export const EXDB=[{"id":"0001","n":"3/4 sit-up","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0001-2gPfomN.jpg","gif":"0001-2gPfomN.gif"},{"id":"0002","n":"45° side bend","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Stand with your feet shoulder-width apart and your arms extended straight down by your sides.","Keeping your back straight and your core engaged, slowly bend your torso to one side, lowering your hand towards your knee.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."],"img":"0002-Hy9D21L.jpg","gif":"0002-Hy9D21L.gif"},{"id":"0003","n":"air bike","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Lie flat on your back with your hands placed behind your head.","Lift your legs off the ground and bend your knees at a 90-degree angle.","Bring your right elbow towards your left knee while simultaneously straightening your right leg.","Return to the starting position and repeat the movement on the opposite side, bringing your left elbow towards your right knee while straightening your left leg.","Continue alternating sides in a pedaling motion for the desired number of repetitions."],"img":"0003-1ZFqTDN.jpg","gif":"0003-1ZFqTDN.gif"},{"id":"1512","n":"all fours squad stretch","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Start on all fours with your hands directly under your shoulders and your knees directly under your hips.","Extend one leg straight back, keeping your knee bent and your foot flexed.","Slowly lower your hips towards the ground, feeling a stretch in your quads.","Hold this position for 20-30 seconds.","Switch legs and repeat the stretch on the other side."],"img":"1512-qBcKorM.jpg","gif":"1512-qBcKorM.gif","ty":"stretch","kind":"time"},{"id":"0006","n":"alternate heel touchers","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms straight out to the sides, parallel to the ground.","Engaging your abs, lift your shoulders off the ground and reach your right hand towards your right heel.","Return to the starting position and repeat on the left side, reaching your left hand towards your left heel.","Continue alternating sides for the desired number of repetitions."],"img":"0006-qaZVsGk.jpg","gif":"0006-qaZVsGk.gif"},{"id":"0007","n":"alternate lateral pulldown","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","rhomboids"],"st":["Sit on the cable machine with your back straight and feet flat on the ground.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Lean back slightly and pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."],"img":"0007-4IKbhHV.jpg","gif":"0007-4IKbhHV.gif"},{"id":"1368","n":"ankle circles","bp":"lower legs","eq":"body weight","tg":"calves","mg":"ankle stabilizers","sm":["ankle stabilizers"],"st":["Sit on the ground with your legs extended in front of you.","Lift one leg off the ground and rotate your ankle in a circular motion.","Perform the desired number of circles in one direction, then switch to the other direction.","Repeat with the other leg."],"img":"1368-uL9CsKm.jpg","gif":"1368-uL9CsKm.gif","ty":"mob"},{"id":"3293","n":"archer pull up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Start by hanging from a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","As you pull yourself up, bend one arm and bring your elbow towards your side, while keeping the other arm straight.","Continue pulling until your chin is above the bar and your bent arm is fully flexed.","Lower yourself back down with control, straightening the bent arm and repeating the movement on the other side.","Alternate sides with each repetition."],"img":"3293-72BC5Za.jpg","gif":"3293-72BC5Za.gif"},{"id":"3294","n":"archer push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Start in a push-up position with your hands slightly wider than shoulder-width apart.","Extend one arm straight out to the side, parallel to the ground.","Lower your body by bending your elbows, keeping your back straight and core engaged.","Push back up to the starting position.","Repeat on the other side, extending the opposite arm out to the side.","Continue alternating sides for the desired number of repetitions."],"img":"3294-A9qxk2F.jpg","gif":"3294-A9qxk2F.gif"},{"id":"2355","n":"arm slingers hanging bent knee legs","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","back"],"st":["Hang from a pull-up bar with your arms fully extended and your knees bent at a 90-degree angle.","Engage your core and lift your knees towards your chest, bringing them as close to your elbows as possible.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"2355-uWpxD4v.jpg","gif":"2355-uWpxD4v.gif"},{"id":"2333","n":"arm slingers hanging straight legs","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","back"],"st":["Hang from a pull-up bar with your arms fully extended and your legs straight down.","Engage your core and lift your legs up in front of you until they are parallel to the ground.","Hold for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"2333-PXTIwgu.jpg","gif":"2333-PXTIwgu.gif"},{"id":"3214","n":"arms apart circular toe touch (male)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","calves"],"st":["Stand with your feet shoulder-width apart and arms extended to the sides.","Keeping your legs straight, bend forward at the waist and reach down towards your toes with your right hand.","As you reach down, simultaneously lift your left leg straight up behind you, maintaining balance.","Return to the starting position and repeat the movement with your left hand reaching towards your toes and your right leg lifting up behind you.","Continue alternating sides for the desired number of repetitions."],"img":"3214-RtyAsy1.jpg","gif":"3214-RtyAsy1.gif"},{"id":"3204","n":"arms overhead full sit-up (male)","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms overhead, keeping them straight.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is upright.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"3204-NAkmgdx.jpg","gif":"3204-NAkmgdx.gif"},{"id":"0009","n":"assisted chest dip (kneeling)","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Adjust the machine to your desired height and secure your knees on the pad.","Grasp the handles with your palms facing down and your arms fully extended.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Pause for a moment, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0009-PAgTVaK.jpg","gif":"0009-PAgTVaK.gif"},{"id":"0011","n":"assisted hanging knee raise","bp":"waist","eq":"assisted","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core muscles and lift your knees towards your chest, bending at the hips and knees.","Pause for a moment at the top of the movement, squeezing your abs.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0011-03lzqwk.jpg","gif":"0011-03lzqwk.gif"},{"id":"0010","n":"assisted hanging knee raise with throw down","bp":"waist","eq":"assisted","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your knees towards your chest, keeping your legs together.","Once your knees are at chest level, explosively throw your legs down towards the ground, extending them fully.","Allow your legs to swing back up and repeat the movement for the desired number of repetitions."],"img":"0010-8K0w2yA.jpg","gif":"0010-8K0w2yA.gif"},{"id":"1708","n":"assisted lying calves stretch","bp":"lower legs","eq":"assisted","tg":"calves","mg":"hamstrings","sm":["hamstrings"],"st":["Lie on your back with your legs extended.","Bend one knee and place your foot flat on the ground.","Using your hands or a towel, gently pull your toes towards your body, feeling a stretch in your calf.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat on the other leg."],"img":"1708-GxDwDX0.jpg","gif":"1708-GxDwDX0.gif","ty":"stretch","kind":"time"},{"id":"1709","n":"assisted lying glutes stretch","bp":"upper legs","eq":"assisted","tg":"glutes","mg":"hamstrings","sm":["hamstrings"],"st":["Lie on your back with your legs extended.","Bend your right knee and place your right ankle on your left thigh, just above the knee.","Grasp your left thigh with both hands and gently pull it towards your chest.","Hold the stretch for 20-30 seconds.","Release and repeat on the other side."],"img":"1709-yn0LjwL.jpg","gif":"1709-yn0LjwL.gif","ty":"stretch","kind":"time"},{"id":"1710","n":"assisted lying gluteus and piriformis stretch","bp":"upper legs","eq":"assisted","tg":"glutes","mg":"hamstrings","sm":["hamstrings"],"st":["Lie on your back with your legs extended.","Bend your right knee and place your right ankle on your left thigh, just above the knee.","Grasp your left thigh with both hands and gently pull it towards your chest.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat on the other side."],"img":"1710-RQNVT10.jpg","gif":"1710-RQNVT10.gif","ty":"stretch","kind":"time"},{"id":"0012","n":"assisted lying leg raise with lateral throw down","bp":"waist","eq":"assisted","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques"],"st":["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your abs and lift your legs off the ground, keeping them straight.","While keeping your legs together, lower them to one side until they are a few inches above the ground.","Pause for a moment, then lift your legs back to the starting position.","Repeat the movement to the other side.","Continue alternating sides for the desired number of repetitions."],"img":"0012-UGhRD1A.jpg","gif":"0012-UGhRD1A.gif"},{"id":"0013","n":"assisted lying leg raise with throw down","bp":"waist","eq":"assisted","tg":"abs","mg":"hip flexors","sm":["hip flexors","quadriceps"],"st":["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your core and lift your legs off the ground, keeping them straight.","Raise your legs until they are perpendicular to the ground.","Lower your legs back down to the starting position.","Simultaneously, throw your legs down towards the ground, keeping them straight.","Raise your legs back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0013-VX5YKR5.jpg","gif":"0013-VX5YKR5.gif"},{"id":"0014","n":"assisted motion russian twist","bp":"waist","eq":"medicine ball","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Sit on the ground with your knees bent and feet flat on the floor.","Hold the medicine ball with both hands in front of your chest.","Lean back slightly, engaging your abs and keeping your back straight.","Slowly twist your torso to the right, bringing the medicine ball towards the right side of your body.","Pause for a moment, then twist your torso to the left, bringing the medicine ball towards the left side of your body.","Continue alternating sides for the desired number of repetitions."],"img":"0014-r7cT9YD.jpg","gif":"0014-r7cT9YD.gif"},{"id":"0015","n":"assisted parallel close grip pull-up","bp":"back","eq":"leverage machine","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Adjust the machine to your desired weight and height.","Place your hands on the parallel bars with a close grip, palms facing each other.","Hang from the bars with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your body.","Continue pulling until your chin is above the bars.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0015-vrhHa6D.jpg","gif":"0015-vrhHa6D.gif"},{"id":"0016","n":"assisted prone hamstring","bp":"upper legs","eq":"assisted","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back"],"st":["Lie face down on a mat or bench with your legs fully extended.","Have a partner or use a resistance band to secure your ankles.","Engage your hamstrings and lift your legs towards your glutes, keeping your knees straight.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0016-VedGSby.jpg","gif":"0016-VedGSby.gif"},{"id":"1713","n":"assisted prone lying quads stretch","bp":"upper legs","eq":"assisted","tg":"quads","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Lie face down on the ground with your legs extended.","Bend your left knee and reach back with your left hand to grab your left foot or ankle.","Gently pull your left foot towards your glutes, feeling a stretch in your left quad.","Hold the stretch for 20-30 seconds, then release.","Repeat with your right leg."],"img":"1713-YUYAMEj.jpg","gif":"1713-YUYAMEj.gif","ty":"stretch","kind":"time"},{"id":"1714","n":"assisted prone rectus femoris stretch","bp":"waist","eq":"assisted","tg":"abs","mg":"quadriceps","sm":["quadriceps"],"st":["Lie face down on the ground with your legs straight.","Bend your right knee and reach back with your right hand to grab your right foot or ankle.","Gently pull your right foot or ankle towards your glutes, feeling a stretch in the front of your right thigh.","Hold the stretch for 20-30 seconds.","Release and repeat on the other side."],"img":"1714-2Ryn564.jpg","gif":"1714-2Ryn564.gif","ty":"stretch","kind":"time"},{"id":"0017","n":"assisted pull-up","bp":"back","eq":"leverage machine","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Adjust the machine to your desired weight and height settings.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Hang with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the handles, keeping your elbows close to your body.","Continue pulling until your chin is above the handles.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0017-kiJ4Z2K.jpg","gif":"0017-kiJ4Z2K.gif"},{"id":"1716","n":"assisted seated pectoralis major stretch with stability ball","bp":"chest","eq":"assisted","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a stability ball with both hands and extend your arms straight out in front of you.","Slowly lower the stability ball towards your chest, feeling a stretch in your pectoral muscles.","Hold the stretch for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"1716-RoV1Rfa.jpg","gif":"1716-RoV1Rfa.gif","ty":"stretch","kind":"time"},{"id":"1712","n":"assisted side lying adductor stretch","bp":"upper legs","eq":"assisted","tg":"adductors","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Lie on your side with your legs straight and stacked on top of each other.","Bend your bottom leg slightly for stability.","Place your top foot on a stable surface, such as a bench or step.","Keeping your top leg straight, slowly lower it towards the ground, feeling a stretch in your inner thigh.","Hold the stretch for 20-30 seconds.","Return to the starting position and repeat on the other side."],"img":"1712-hC6oYY5.jpg","gif":"1712-hC6oYY5.gif","ty":"stretch","kind":"time"},{"id":"1758","n":"assisted sit-up","bp":"waist","eq":"assisted","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Sit on the edge of a bench or have someone hold your feet down.","Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1758-aumB2IV.jpg","gif":"1758-aumB2IV.gif"},{"id":"1431","n":"assisted standing chin-up","bp":"back","eq":"leverage machine","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Adjust the machine to your desired assistance level.","Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your chest up and shoulders back, engage your core, and slightly bend your knees.","Pull your body up by flexing your elbows and driving your elbows down towards your sides.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1431-7OeHptV.jpg","gif":"1431-7OeHptV.gif"},{"id":"1432","n":"assisted standing pull-up","bp":"back","eq":"leverage machine","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Adjust the machine to your desired weight and height settings.","Stand facing the machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Engage your lats and biceps, and pull yourself up towards the handles.","Pause for a moment at the top, squeezing your back muscles.","Slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1432-f4xtKBj.jpg","gif":"1432-f4xtKBj.gif"},{"id":"0018","n":"assisted standing triceps extension (with towel)","bp":"upper arms","eq":"assisted","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Stand with your feet shoulder-width apart and hold a towel with both hands behind your head.","Keep your elbows close to your ears and your upper arms stationary.","Slowly extend your forearms upward, squeezing your triceps at the top.","Pause for a moment, then slowly lower the towel back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0018-7HcfMBP.jpg","gif":"0018-7HcfMBP.gif"},{"id":"0019","n":"assisted triceps dip (kneeling)","bp":"upper arms","eq":"leverage machine","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Adjust the machine to your desired weight and height.","Kneel down on the pad facing the machine, with your hands gripping the handles.","Lower your body by bending your elbows, keeping your back straight and close to the machine.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0019-J60bN17.jpg","gif":"0019-J60bN17.gif"},{"id":"2364","n":"assisted wide-grip chest dip (kneeling)","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Adjust the machine to your desired height and secure your knees on the pad.","Grasp the handles with a wide grip and keep your elbows slightly bent.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."],"img":"2364-PnZJIrk.jpg","gif":"2364-PnZJIrk.gif"},{"id":"3220","n":"astride jumps (male)","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position.","Jump explosively upwards, extending your legs and arms.","While in the air, spread your legs apart and bring your arms out to the sides.","Land softly with your feet shoulder-width apart, bending your knees to absorb the impact.","Repeat for the desired number of repetitions."],"img":"3220-f9lVSSI.jpg","gif":"3220-f9lVSSI.gif","ty":"atl"},{"id":"3672","n":"back and forth step","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","glutes","calves"],"st":["Stand with your feet shoulder-width apart.","Step forward with your right foot, bending your knee and lowering your body into a lunge position.","Push off with your right foot and step back to the starting position.","Repeat the movement with your left foot, alternating legs with each step.","Continue stepping back and forth, maintaining a steady pace.","Repeat for the desired duration or number of repetitions."],"img":"3672-fNGumX0.jpg","gif":"3672-fNGumX0.gif"},{"id":"1314","n":"back extension on exercise ball","bp":"back","eq":"stability ball","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall or other stable surface.","Position your hands behind your head or crossed over your chest.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1314-qLpO4vV.jpg","gif":"1314-qLpO4vV.gif"},{"id":"3297","n":"back lever","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","forearms","core"],"st":["Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","Bend your knees and tuck them towards your chest.","Slowly lift your legs up, keeping them straight, until your body is parallel to the ground.","Hold this position for a few seconds, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"3297-GaSzzuh.jpg","gif":"3297-GaSzzuh.gif"},{"id":"1405","n":"back pec stretch","bp":"back","eq":"body weight","tg":"lats","mg":"shoulders","sm":["shoulders","chest"],"st":["Stand tall with your feet shoulder-width apart.","Extend your arms straight out in front of you, parallel to the ground.","Cross your arms in front of your body, with your right arm over your left arm.","Interlock your fingers and rotate your palms away from your body.","Slowly raise your arms up and away from your body, feeling a stretch in your back and chest.","Hold the stretch for 15-30 seconds, then release.","Repeat on the opposite side."],"img":"1405-chfnQnM.jpg","gif":"1405-chfnQnM.gif","ty":"stretch","kind":"time"},{"id":"1473","n":"backward jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hamstrings","sm":["hamstrings","glutes","calves"],"st":["Stand with your feet shoulder-width apart.","Bend your knees slightly and jump backwards, pushing off with both feet.","Land softly on the balls of your feet, bending your knees to absorb the impact.","Repeat for the desired number of repetitions."],"img":"1473-SaDOwk7.jpg","gif":"1473-SaDOwk7.gif","ty":"atl"},{"id":"0020","n":"balance board","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","hamstrings","glutes"],"st":["Place the balance board on a flat surface.","Step onto the balance board with one foot, ensuring it is centered.","Slowly shift your weight onto the foot on the balance board, keeping your core engaged.","Maintain your balance and stability as you hold the position for a desired amount of time.","Repeat the exercise with the other foot."],"img":"0020-xAySMB0.jpg","gif":"0020-xAySMB0.gif"},{"id":"0968","n":"band alternating biceps curl","bp":"upper arms","eq":"band","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand with your feet shoulder-width apart and hold the band with an underhand grip, palms facing up.","Keep your elbows close to your sides and slowly curl one arm up towards your shoulder, squeezing your biceps at the top.","Lower the arm back down to the starting position and repeat with the other arm.","Continue alternating arms for the desired number of repetitions."],"img":"0968-3omWx6P.jpg","gif":"0968-3omWx6P.gif"},{"id":"0969","n":"band alternating v-up","bp":"waist","eq":"band","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Lie flat on your back with your legs straight and your arms extended overhead, holding the band.","Engage your abs and lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.","As you lower your legs and upper body back down, switch the position of your legs, crossing one over the other.","Repeat the movement, alternating the position of your legs with each repetition.","Continue for the desired number of repetitions."],"img":"0969-ztAa1RK.jpg","gif":"0969-ztAa1RK.gif"},{"id":"0970","n":"band assisted pull-up","bp":"back","eq":"band","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Attach the band to a pull-up bar or sturdy anchor point.","Step onto the band and grip the bar with your palms facing away from you, hands slightly wider than shoulder-width apart.","Hang with your arms fully extended, keeping your core engaged and your shoulders down and back.","Pull your body up towards the bar by squeezing your shoulder blades together and driving your elbows down towards your hips.","Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0970-r1XNRYB.jpg","gif":"0970-r1XNRYB.gif"},{"id":"0971","n":"band assisted wheel rollerout","bp":"waist","eq":"band","tg":"abs","mg":"lower back","sm":["lower back"],"st":["Kneel on the floor and hold the handles of the band with both hands, palms facing down.","Place the band on the ground in front of you and position your hands shoulder-width apart.","Engage your core and slowly roll the wheel forward, extending your body as far as you can while maintaining control.","Pause for a moment at the furthest point, then slowly roll the wheel back towards your knees to return to the starting position.","Repeat for the desired number of repetitions."],"img":"0971-zhF9lW4.jpg","gif":"0971-zhF9lW4.gif"},{"id":"1254","n":"band bench press","bp":"chest","eq":"band","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the band handles with an overhand grip, slightly wider than shoulder-width apart.","Extend your arms fully, pushing the bands away from your chest.","Slowly lower the bands back down to your chest, keeping your elbows at a 90-degree angle.","Repeat for the desired number of repetitions."],"img":"1254-khlHMqs.jpg","gif":"1254-khlHMqs.gif"},{"id":"0980","n":"band bent-over hip extension","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Attach the band to a sturdy anchor point at ankle height.","Stand facing away from the anchor point with your feet shoulder-width apart.","Step back to create tension in the band, keeping your knees slightly bent.","Hinge at the hips and lean forward, maintaining a neutral spine.","Extend your right leg straight back, squeezing your glutes at the top.","Lower your right leg back down and repeat with the left leg.","Continue alternating legs for the desired number of repetitions."],"img":"0980-wSScovH.jpg","gif":"0980-wSScovH.gif"},{"id":"0972","n":"band bicycle crunch","bp":"waist","eq":"band","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques"],"st":["Lie flat on your back with your hands behind your head and your knees bent.","Lift your feet off the ground and bring your right knee towards your chest while simultaneously twisting your torso to bring your left elbow towards your right knee.","Straighten your right leg while bringing your left knee towards your chest and twisting your torso to bring your right elbow towards your left knee.","Continue alternating the twisting motion, as if you are pedaling a bicycle, while keeping your core engaged throughout the movement.","Repeat for the desired number of repetitions."],"img":"0972-tZkGYZ9.jpg","gif":"0972-tZkGYZ9.gif"},{"id":"0974","n":"band close-grip pulldown","bp":"back","eq":"band","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.","Stand facing the anchor point and grab the band with an underhand grip, hands shoulder-width apart.","Step back to create tension in the band, keeping your feet hip-width apart.","Engage your core and keep your back straight as you pull the band down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the band back to the starting position.","Repeat for the desired number of repetitions."],"img":"0974-DptumMx.jpg","gif":"0974-DptumMx.gif"},{"id":"0975","n":"band close-grip push-up","bp":"upper arms","eq":"band","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Place a band around your upper arms, just above the elbows.","Assume a push-up position with your hands directly under your shoulders and your body in a straight line from head to heels.","Bend your elbows and lower your chest towards the ground, keeping your elbows close to your sides.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."],"img":"0975-ufaxB52.jpg","gif":"0975-ufaxB52.gif"},{"id":"0976","n":"band concentration curl","bp":"upper arms","eq":"band","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a bench or chair with your legs spread apart and your feet flat on the ground.","Hold one end of the band in your hand and step on the other end with your foot on the same side.","Lean forward slightly and rest your elbow on the inside of your thigh, just above the knee.","With your palm facing up, slowly curl your hand towards your shoulder, keeping your upper arm stationary.","Pause for a moment at the top, then slowly lower your hand back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"0976-kmVVAfu.jpg","gif":"0976-kmVVAfu.gif"},{"id":"3117","n":"band fixed back close grip pulldown","bp":"back","eq":"band","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Attach the band to a fixed point above you, such as a pull-up bar or sturdy beam.","Sit down on a bench or chair facing the band, with your feet flat on the ground and your knees bent.","Grasp the band with a close grip, palms facing towards you.","Keep your back straight and engage your core.","Pull the band down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, feeling the contraction in your lats.","Slowly release the band back to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions."],"img":"3117-4LoWllp.jpg","gif":"3117-4LoWllp.gif"},{"id":"3116","n":"band fixed back underhand pulldown","bp":"back","eq":"band","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Attach the band to a sturdy anchor point above your head.","Stand facing the anchor point with your feet shoulder-width apart.","Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart.","Step back to create tension in the band, keeping your arms fully extended.","Engage your core and squeeze your shoulder blades together.","Pull the band down towards your chest, leading with your elbows.","Pause for a moment at the bottom of the movement, feeling the contraction in your lats.","Slowly release the tension in the band and return to the starting position.","Repeat for the desired number of repetitions."],"img":"3116-ZH68exZ.jpg","gif":"3116-ZH68exZ.gif"},{"id":"0977","n":"band front lateral raise","bp":"shoulders","eq":"band","tg":"delts","mg":"traps","sm":["traps","upper back"],"st":["Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down.","Keep your arms straight and lift the band up in front of you until your arms are parallel to the ground.","Pause for a moment at the top, then slowly lower the band back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0977-sTg7iys.jpg","gif":"0977-sTg7iys.gif"},{"id":"0978","n":"band front raise","bp":"shoulders","eq":"band","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down.","Keep your arms straight and slowly raise them forward until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0978-TFA88iB.jpg","gif":"0978-TFA88iB.gif"},{"id":"1408","n":"band hip lift","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Lie on your back with your knees bent and feet flat on the ground.","Place a resistance band just above your knees.","Engage your glutes and core muscles.","Press your heels into the ground and lift your hips off the floor, squeezing your glutes at the top.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1408-E4R8Hz1.jpg","gif":"1408-E4R8Hz1.gif"},{"id":"0979","n":"band horizontal pallof press","bp":"waist","eq":"band","tg":"abs","mg":"obliques","sm":["obliques","glutes"],"st":["Attach the band to a sturdy anchor point at waist height.","Stand perpendicular to the anchor point with your feet shoulder-width apart.","Grasp the band handle with both hands and step away from the anchor point to create tension in the band.","Bring your hands to your chest, keeping your elbows bent and close to your body.","Engage your core and maintain a stable stance.","Extend your arms straight out in front of you, pushing the band away from your body.","Hold the extended position for a few seconds, focusing on maintaining tension in your core.","Slowly bring your hands back to your chest, resisting the pull of the band.","Repeat for the desired number of repetitions."],"img":"0979-9pa4H5m.jpg","gif":"0979-9pa4H5m.gif","ty":"rin"},{"id":"0981","n":"band jack knife sit-up","bp":"waist","eq":"band","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Lie flat on your back with your legs straight and your arms extended overhead, holding the band.","Engage your abs and lift your legs and upper body simultaneously, bringing your hands towards your feet.","Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0981-KCBKjma.jpg","gif":"0981-KCBKjma.gif"},{"id":"0983","n":"band kneeling one arm pulldown","bp":"back","eq":"band","tg":"lats","mg":"biceps","sm":["biceps","rhomboids"],"st":["Attach the band to a sturdy anchor point above your head.","Kneel down and hold the band with one hand, palm facing down.","Extend your arm fully overhead, keeping your elbow slightly bent.","Engage your lat muscles and pull the band down towards your side, bringing your elbow towards your ribcage.","Pause for a moment at the bottom, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"0983-pmnrOp0.jpg","gif":"0983-pmnrOp0.gif"},{"id":"0985","n":"band kneeling twisting crunch","bp":"waist","eq":"band","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Attach the band to a sturdy anchor point at waist height.","Kneel down facing away from the anchor point and hold the band with both hands, keeping your elbows bent and close to your sides.","Engage your abs and slowly twist your torso to one side, bringing your hands towards your opposite hip.","Pause for a moment, then slowly return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."],"img":"0985-225x2Vd.jpg","gif":"0985-225x2Vd.gif"},{"id":"0984","n":"band lying hip internal rotation","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Lie on your back with your legs straight and a resistance band looped around your feet.","Bend your knees and bring them towards your chest, keeping your feet together.","Slowly rotate your knees outwards, away from each other, while keeping your feet together.","Pause for a moment at the end of the rotation, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"0984-vIICElP.jpg","gif":"0984-vIICElP.gif","ty":"rin"},{"id":"1002","n":"band lying straight leg raise","bp":"waist","eq":"band","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Lie flat on your back with your legs straight and your feet together.","Place the band around the arches of your feet and hold the ends of the band with your hands.","Engaging your abs, lift both legs off the ground until they are perpendicular to the floor.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1002-bbLR7fB.jpg","gif":"1002-bbLR7fB.gif"},{"id":"0986","n":"band one arm overhead biceps curl","bp":"upper arms","eq":"band","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Stand with your feet shoulder-width apart and place one end of the band under your foot.","Hold the other end of the band with your arm fully extended overhead, palm facing forward.","Keeping your upper arm stationary, curl your forearm towards your shoulder, squeezing your biceps.","Pause for a moment at the top, then slowly lower your forearm back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"0986-UNAB8ak.jpg","gif":"0986-UNAB8ak.gif"},{"id":"0987","n":"band one arm single leg split squat","bp":"upper legs","eq":"band","tg":"quads","mg":"glutes","sm":["glutes","hamstrings"],"st":["Stand with your feet hip-width apart and place a resistance band around your ankles.","Extend one leg forward and rest the top of your foot on a bench or step behind you.","Hold onto a support with one hand for balance.","Bend your standing leg and lower your body down into a squat position, keeping your knee in line with your toes.","Push through your heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"img":"0987-arsYEd3.jpg","gif":"0987-arsYEd3.gif"},{"id":"0988","n":"band one arm standing low row","bp":"back","eq":"band","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Attach the band to a stable anchor point at waist height.","Stand facing the anchor point with your feet shoulder-width apart.","Hold the band with one hand, palm facing inward, and step back to create tension in the band.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Pull the band towards your waist, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the band back to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"0988-km0sQC0.jpg","gif":"0988-km0sQC0.gif"},{"id":"0989","n":"band one arm twisting chest press","bp":"chest","eq":"band","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Attach the band to a sturdy anchor point at chest height.","Stand with your side facing the anchor point and grab the band with one hand.","Step away from the anchor point to create tension in the band.","Position your feet shoulder-width apart and slightly bend your knees.","Bring your hand holding the band across your body, towards the opposite shoulder.","While maintaining tension in the band, push your hand forward and away from your body, extending your arm.","Slowly return to the starting position and repeat for the desired number of repetitions.","Switch sides and repeat the exercise with the other hand."],"img":"0989-c16nYGA.jpg","gif":"0989-c16nYGA.gif"},{"id":"0990","n":"band one arm twisting seated row","bp":"back","eq":"band","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Sit on a bench or chair with your feet flat on the ground and your back straight.","Hold the band with one hand and extend your arm fully in front of you.","Keeping your back straight, pull the band towards your body by bending your elbow and squeezing your shoulder blades together.","At the same time, twist your torso towards the side of the pulling arm.","Pause for a moment at the top, then slowly release the tension in the band and return to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"img":"0990-DKBwJrL.jpg","gif":"0990-DKBwJrL.gif"},{"id":"0991","n":"band pull through","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Attach a resistance band to a sturdy anchor point at ground level.","Stand facing away from the anchor point with your feet shoulder-width apart.","Step forward to create tension in the band, keeping your knees slightly bent.","Hinge at the hips and push your glutes back, maintaining a slight bend in your knees.","Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Drive your hips forward and squeeze your glutes to return to the starting position.","Repeat for the desired number of repetitions."],"img":"0991-VtTbiP3.jpg","gif":"0991-VtTbiP3.gif"},{"id":"0992","n":"band push sit-up","bp":"waist","eq":"band","tg":"abs","mg":"shoulders","sm":["shoulders","chest"],"st":["Attach the band securely to a stable anchor point.","Lie flat on your back with your knees bent and feet flat on the ground.","Hold the band with both hands and extend your arms straight up towards the ceiling.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0992-zFzbBfL.jpg","gif":"0992-zFzbBfL.gif"},{"id":"0993","n":"band reverse fly","bp":"shoulders","eq":"band","tg":"delts","mg":"upper back","sm":["upper back","trapezius"],"st":["Attach the band to a stationary object at chest height.","Stand with your feet shoulder-width apart and hold the band with both hands in front of you.","Keep your arms straight and lift them out to the sides until they are parallel to the ground.","Squeeze your shoulder blades together at the top of the movement.","Slowly lower your arms back to the starting position.","Repeat for the desired number of repetitions."],"img":"0993-sTfvVsG.jpg","gif":"0993-sTfvVsG.gif"},{"id":"0994","n":"band reverse wrist curl","bp":"lower arms","eq":"band","tg":"forearms","mg":"forearms","sm":["forearms"],"st":["Sit on a bench or chair with your feet flat on the ground.","Hold the band with an overhand grip, palms facing down, and wrap it around your fingers.","Rest your forearms on your thighs, with your wrists hanging off the edge.","Slowly curl your wrists upward, squeezing your forearms.","Pause for a moment at the top, then slowly lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0994-Ezpnw9d.jpg","gif":"0994-Ezpnw9d.gif"},{"id":"0996","n":"band seated hip internal rotation","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Sit on a chair or bench with your back straight and feet flat on the ground.","Place a resistance band around your thighs, just above your knees.","Keep your knees bent at a 90-degree angle and your feet shoulder-width apart.","Engage your glutes and slowly rotate your knees outward, pushing against the resistance of the band.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"0996-9gbyYKk.jpg","gif":"0996-9gbyYKk.gif","ty":"rin"},{"id":"1011","n":"band seated twist","bp":"waist","eq":"band","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Sit on the ground with your legs extended in front of you and your back straight.","Wrap the band around your waist and hold the ends with both hands.","Engage your abs and slowly twist your torso to one side, keeping your back straight and your feet on the ground.","Pause for a moment at the end of the twist, then slowly return to the starting position.","Repeat the twist to the other side.","Continue alternating sides for the desired number of repetitions."],"img":"1011-S1JXDAG.jpg","gif":"1011-S1JXDAG.gif"},{"id":"0997","n":"band shoulder press","bp":"shoulders","eq":"band","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Stand with your feet shoulder-width apart and place the band under your feet.","Hold the band with your palms facing forward and raise your hands to shoulder height, elbows bent.","Press the band overhead, fully extending your arms.","Pause for a moment at the top, then slowly lower the band back to shoulder height.","Repeat for the desired number of repetitions."],"img":"0997-peAeMR3.jpg","gif":"0997-peAeMR3.gif"},{"id":"1018","n":"band shrug","bp":"back","eq":"band","tg":"traps","mg":"shoulders","sm":["shoulders"],"st":["Stand with your feet shoulder-width apart and place the band under your feet, holding the ends with your hands.","Keep your arms straight and relaxed, and let the band hang in front of your thighs.","Engage your traps by shrugging your shoulders upward, lifting the band as high as possible.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1018-trmte8s.jpg","gif":"1018-trmte8s.gif"},{"id":"0998","n":"band side triceps extension","bp":"upper arms","eq":"band","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Stand with your feet shoulder-width apart and hold the band with both hands, palms facing down.","Extend your arms straight out to the sides, keeping them parallel to the ground.","Slowly bend your elbows and bring your hands towards your shoulders, keeping your upper arms still.","Pause for a moment, then slowly extend your arms back out to the starting position.","Repeat for the desired number of repetitions."],"img":"0998-obe5LMq.jpg","gif":"0998-obe5LMq.gif"},{"id":"0999","n":"band single leg calf raise","bp":"lower legs","eq":"band","tg":"calves","mg":"ankles","sm":["ankles","feet"],"st":["Stand with your feet hip-width apart and place the band around the ball of your left foot.","Hold onto a stable object for balance if needed.","Slowly raise your left heel off the ground, lifting your body weight onto the ball of your foot.","Pause for a moment at the top, then slowly lower your left heel back down to the starting position.","Repeat for the desired number of repetitions, then switch to the right leg."],"img":"0999-9JprnPh.jpg","gif":"0999-9JprnPh.gif"},{"id":"1000","n":"band single leg reverse calf raise","bp":"lower legs","eq":"band","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Stand with your feet hip-width apart and place the band around the ball of your foot.","Hold onto a stable object for balance.","Slowly raise your heel off the ground, lifting your body weight onto the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other leg."],"img":"1000-QsSQWbf.jpg","gif":"1000-QsSQWbf.gif"},{"id":"1001","n":"band single leg split squat","bp":"upper legs","eq":"band","tg":"quads","mg":"glutes","sm":["glutes","hamstrings"],"st":["Stand with your feet hip-width apart and place a resistance band around your ankles.","Take a big step forward with your right foot and a smaller step back with your left foot.","Bend your knees and lower your body until your right thigh is parallel to the ground, keeping your left knee slightly above the ground.","Push through your right heel to return to the starting position.","Repeat on the other side."],"img":"1001-y8bYM8w.jpg","gif":"1001-y8bYM8w.gif"},{"id":"1004","n":"band squat","bp":"upper legs","eq":"band","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart, with the band placed just above your knees.","Keeping your chest up and core engaged, push your hips back and bend your knees to lower into a squat position.","Make sure your knees are tracking over your toes and your weight is in your heels.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"1004-TUZLh71.jpg","gif":"1004-TUZLh71.gif"},{"id":"1003","n":"band squat row","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","back"],"st":["Attach the band to a sturdy anchor point at waist height.","Stand facing the anchor point with your feet shoulder-width apart.","Hold the band handles with your palms facing each other and your arms extended in front of you.","Bend your knees and lower into a squat position, keeping your back straight and chest lifted.","From the squat position, pull the band handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"img":"1003-w1NOByi.jpg","gif":"1003-w1NOByi.gif"},{"id":"1005","n":"band standing crunch","bp":"waist","eq":"band","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Attach the band to a sturdy anchor point at waist height.","Stand facing away from the anchor point with your feet shoulder-width apart.","Hold the band with both hands and bring it up to your chest, keeping your elbows bent and close to your body.","Engage your abs and slowly crunch forward, bringing your chest towards your knees.","Pause for a moment at the top of the crunch, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"1005-Kzg30R7.jpg","gif":"1005-Kzg30R7.gif"},{"id":"1022","n":"band standing rear delt row","bp":"shoulders","eq":"band","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids","biceps"],"st":["Stand with your feet shoulder-width apart and place the band under your feet.","Hold the band handles with your palms facing each other and your arms extended in front of you.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Pull the band towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"img":"1022-tc5dYrf.jpg","gif":"1022-tc5dYrf.gif"},{"id":"1007","n":"band standing twisting crunch","bp":"waist","eq":"band","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Stand with your feet shoulder-width apart and place the band around your upper back, crossing it in front of your chest.","Hold the ends of the band with your hands, keeping your elbows bent and close to your sides.","Engage your abs and twist your torso to one side, bringing your elbow towards the opposite knee.","Pause for a moment, then return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."],"img":"1007-euq4pwp.jpg","gif":"1007-euq4pwp.gif"},{"id":"1008","n":"band step-up","bp":"upper legs","eq":"band","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Place a band around your thighs, just above your knees.","Stand facing a step or platform with your feet hip-width apart.","Step up onto the platform with your right foot, pushing through your heel.","Extend your left leg behind you, keeping it straight.","Lower your left foot back down to the ground.","Repeat with your left foot stepping up onto the platform.","Continue alternating legs for the desired number of repetitions."],"img":"1008-d5bTEPV.jpg","gif":"1008-d5bTEPV.gif"},{"id":"1009","n":"band stiff leg deadlift","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Stand with your feet shoulder-width apart and place the band around your ankles.","Hold the band with both hands in front of your thighs, palms facing your body.","Keeping your back straight and your core engaged, hinge at the hips and slowly lower your upper body towards the ground.","As you lower, push your hips back and allow your knees to bend slightly.","Lower the band towards the ground, feeling a stretch in your hamstrings.","Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your upper body back up to the starting position.","Repeat for the desired number of repetitions."],"img":"1009-kuMiR2T.jpg","gif":"1009-kuMiR2T.gif"},{"id":"1023","n":"band straight back stiff leg deadlift","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Stand with your feet shoulder-width apart and place the band around your upper legs.","Hold the band with both hands in front of your thighs, palms facing your body.","Keeping your back straight and your knees slightly bent, hinge at the hips and lower the band towards the ground.","Feel the stretch in your hamstrings as you lower the band.","Engage your glutes and hamstrings to lift your body back up to the starting position.","Repeat for the desired number of repetitions."],"img":"1023-lHeUULr.jpg","gif":"1023-lHeUULr.gif"},{"id":"1010","n":"band straight leg deadlift","bp":"back","eq":"band","tg":"spine","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Stand with your feet shoulder-width apart and place the band around your feet.","Hold the band with both hands, palms facing your body, and keep your arms straight.","Engage your core and maintain a slight bend in your knees.","Slowly hinge forward at your hips, keeping your back straight and chest lifted.","Lower the band towards the ground while keeping your legs straight.","Pause for a moment at the bottom, then squeeze your glutes and hamstrings to return to the starting position.","Repeat for the desired number of repetitions."],"img":"1010-KUaoUV8.jpg","gif":"1010-KUaoUV8.gif"},{"id":"1012","n":"band twisting overhead press","bp":"shoulders","eq":"band","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Stand with your feet shoulder-width apart and place the band under your feet.","Hold the band handles at shoulder height with your palms facing forward.","Engage your core and press the band overhead, fully extending your arms.","As you press, twist your torso to one side, keeping your hips stable.","Pause for a moment at the top, then return to the starting position.","Repeat the press and twist on the opposite side.","Continue alternating sides for the desired number of repetitions."],"img":"1012-u4bAmKp.jpg","gif":"1012-u4bAmKp.gif"},{"id":"1369","n":"band two legs calf raise - (band under both legs) v. 2","bp":"lower legs","eq":"band","tg":"calves","mg":"ankles","sm":["ankles","feet"],"st":["Stand with your feet shoulder-width apart and place a resistance band under both feet.","Hold the ends of the band with your hands for stability.","Raise your heels off the ground as high as possible, using your calves.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1369-jl6uxZV.jpg","gif":"1369-jl6uxZV.gif"},{"id":"1013","n":"band underhand pulldown","bp":"back","eq":"band","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.","Stand facing the anchor point with your feet shoulder-width apart.","Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart.","Extend your arms fully overhead, keeping your elbows slightly bent.","Engage your lats and pull the band down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"img":"1013-k6tUeqS.jpg","gif":"1013-k6tUeqS.gif"},{"id":"1014","n":"band v-up","bp":"waist","eq":"band","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Lie flat on your back with your legs straight and your arms extended overhead, holding the band.","Engaging your abs, lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.","Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1014-H6ETwO9.jpg","gif":"1014-H6ETwO9.gif"},{"id":"1015","n":"band vertical pallof press","bp":"waist","eq":"band","tg":"abs","mg":"obliques","sm":["obliques","glutes"],"st":["Stand with your feet shoulder-width apart and wrap the band around a sturdy object at chest height.","Hold the band with both hands and step away from the anchor point, creating tension in the band.","Position yourself perpendicular to the anchor point, with your side facing the band.","Extend your arms straight out in front of you, keeping your hands at chest height.","Engage your core and press the band away from your chest, fully extending your arms.","Hold the position for a few seconds, then slowly bring the band back towards your chest.","Repeat for the desired number of repetitions, then switch sides."],"img":"1015-G7PXMlT.jpg","gif":"1015-G7PXMlT.gif","ty":"rin"},{"id":"1016","n":"band wrist curl","bp":"lower arms","eq":"band","tg":"forearms","mg":"biceps","sm":["biceps","triceps"],"st":["Sit on a bench or chair with your feet flat on the ground.","Hold the band with both hands, palms facing up, and rest your forearms on your thighs.","Slowly curl your wrists upward, squeezing your forearms.","Pause for a moment at the top, then slowly lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1016-vUTfFHw.jpg","gif":"1016-vUTfFHw.gif"},{"id":"1017","n":"band y-raise","bp":"shoulders","eq":"band","tg":"delts","mg":"traps","sm":["traps","rhomboids"],"st":["Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing inwards.","Keep your arms straight and lift them up and out to the sides, forming a 'Y' shape with your body.","Squeeze your shoulder blades together at the top of the movement.","Slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1017-aHDy5O5.jpg","gif":"1017-aHDy5O5.gif","ty":"rin"},{"id":"0023","n":"barbell alternate biceps curl","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with your feet shoulder-width apart and hold a barbell in each hand, palms facing forward.","Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps.","Continue to raise the barbells until your biceps are fully contracted and the barbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale as you slowly begin to lower the barbells back to the starting position.","Repeat for the desired number of repetitions, alternating arms."],"img":"0023-Yza7XrQ.jpg","gif":"0023-Yza7XrQ.gif"},{"id":"0024","n":"barbell bench front squat","bp":"upper legs","eq":"barbell","tg":"quads","mg":"hamstrings","sm":["hamstrings","glutes","calves"],"st":["Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, just below your collarbone.","Hold the barbell with an overhand grip, keeping your elbows up and your upper arms parallel to the ground.","Lower your body down into a squat position by bending at the knees and hips, keeping your back straight and your chest up.","Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"0024-Y7YcmIJ.jpg","gif":"0024-Y7YcmIJ.gif"},{"id":"0025","n":"barbell bench press","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Lower the barbell slowly towards your chest, keeping your elbows tucked in.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."],"img":"0025-EIeI8Vf.jpg","gif":"0025-EIeI8Vf.gif"},{"id":"0026","n":"barbell bench squat","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Set up a barbell on a squat rack at chest height.","Stand facing away from the rack, with your feet shoulder-width apart.","Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and step back, ensuring your feet are still shoulder-width apart.","Lower your body down into a squat, keeping your knees in line with your toes.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"0026-W9pFVv1.jpg","gif":"0026-W9pFVv1.gif"},{"id":"1316","n":"barbell bent arm pullover","bp":"back","eq":"barbell","tg":"lats","mg":"triceps","sm":["triceps","chest"],"st":["Lie flat on a bench with your head at one end and your feet on the floor.","Hold a barbell with a shoulder-width grip and extend your arms straight above your chest.","Lower the barbell behind your head while keeping your arms slightly bent.","Pause for a moment, then raise the barbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"1316-cA9FuWG.jpg","gif":"1316-cA9FuWG.gif"},{"id":"0027","n":"barbell bent over row","bp":"back","eq":"barbell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Stand with your feet shoulder-width apart and knees slightly bent.","Bend forward at the hips while keeping your back straight and chest up.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Pull the barbell towards your lower chest by retracting your shoulder blades and squeezing your back muscles.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"0027-eZyBC3j.jpg","gif":"0027-eZyBC3j.gif"},{"id":"2407","n":"barbell biceps curl (with arm blaster)","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.","Place your upper arms against the arm blaster, keeping your elbows close to your torso.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"2407-aee2Fcj.jpg","gif":"2407-aee2Fcj.gif"},{"id":"0028","n":"barbell clean and press","bp":"upper legs","eq":"barbell","tg":"quads","mg":"hamstrings","sm":["hamstrings","glutes","shoulders","triceps"],"st":["Stand with your feet shoulder-width apart and the barbell on the floor in front of you.","Bend your knees and hinge at the hips to lower down and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Drive through your heels and extend your hips and knees to lift the barbell off the floor, keeping it close to your body.","As the barbell reaches your thighs, explosively extend your hips, shrug your shoulders, and pull the barbell up towards your chest.","As the barbell reaches chest height, quickly drop under it and catch it at shoulder level, with your elbows pointing forward and your palms facing up.","From the catch position, press the barbell overhead by extending your arms and pushing the barbell straight up.","Lower the barbell back down to the starting position and repeat for the desired number of repetitions."],"img":"0028-SGY8Zui.jpg","gif":"0028-SGY8Zui.gif"},{"id":"0029","n":"barbell clean-grip front squat","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, with your elbows pointing forward.","Lower your body by bending your knees and pushing your hips back, as if you are sitting back into a chair.","Keep your chest up and your back straight as you lower down, making sure your knees do not go past your toes.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."],"img":"0029-qi996YS.jpg","gif":"0029-qi996YS.gif"},{"id":"0030","n":"barbell close-grip bench press","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"0030-J6Dx1Mu.jpg","gif":"0030-J6Dx1Mu.gif"},{"id":"0031","n":"barbell curl","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing forward.","Keep your elbows close to your torso and exhale as you curl the weights while contracting your biceps.","Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale as you slowly begin to lower the bar back to the starting position.","Repeat for the desired number of repetitions."],"img":"0031-25GPyDY.jpg","gif":"0031-25GPyDY.gif"},{"id":"0032","n":"barbell deadlift","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Stand with your feet shoulder-width apart and the barbell on the ground in front of you.","Bend your knees and hinge at the hips to lower your torso and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your back straight and chest lifted as you drive through your heels to lift the barbell off the ground, extending your hips and knees.","As you stand up straight, squeeze your glutes and keep your core engaged.","Lower the barbell back down to the ground by bending at the hips and knees, keeping your back straight.","Repeat for the desired number of repetitions."],"img":"0032-ila4NZS.jpg","gif":"0032-ila4NZS.gif"},{"id":"0033","n":"barbell decline bench press","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Lie on a decline bench with your feet secured and your head lower than your hips.","Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0033-GrO65fd.jpg","gif":"0033-GrO65fd.gif"},{"id":"0034","n":"barbell decline bent arm pullover","bp":"back","eq":"barbell","tg":"lats","mg":"triceps","sm":["triceps","chest"],"st":["Lie down on a decline bench with your head lower than your hips and your feet secured.","Hold a barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.","Lower the barbell behind your head in a controlled manner, keeping your arms slightly bent.","Pause for a moment, then raise the barbell back to the starting position by contracting your lats.","Repeat for the desired number of repetitions."],"img":"0034-hMEptv0.jpg","gif":"0034-hMEptv0.gif"},{"id":"0035","n":"barbell decline close grip to skull press","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Lie on a decline bench with your head lower than your feet and hold a barbell with a close grip.","Lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary.","Pause for a moment, then extend your arms to press the barbell back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0035-LMGXZn8.jpg","gif":"0035-LMGXZn8.gif"},{"id":"1255","n":"barbell decline pullover","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Lie down on a decline bench with your head lower than your hips and your feet secured.","Hold the barbell with a pronated grip (palms facing away from you) and your hands slightly wider than shoulder-width apart.","Extend your arms above your chest, keeping a slight bend in your elbows.","Lower the barbell in an arc motion behind your head, feeling a stretch in your chest and shoulders.","Pause for a moment, then return the barbell to the starting position by reversing the motion.","Repeat for the desired number of repetitions."],"img":"1255-9sgNE2O.jpg","gif":"1255-9sgNE2O.gif"},{"id":"0036","n":"barbell decline wide-grip press","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Lie on a decline bench with your feet secured and your head lower than your hips.","Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Lower the barbell to your chest, keeping your elbows out to the sides.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"0036-hl8DUh8.jpg","gif":"0036-hl8DUh8.gif"},{"id":"0037","n":"barbell decline wide-grip pullover","bp":"back","eq":"barbell","tg":"lats","mg":"triceps","sm":["triceps","chest"],"st":["Lie on a decline bench with your head lower than your hips and your feet secured.","Hold a barbell with a wide grip and extend your arms straight above your chest.","Lower the barbell behind your head in a controlled manner, keeping your arms straight.","Pause for a moment, then raise the barbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"0037-Hj4FOCd.jpg","gif":"0037-Hj4FOCd.gif"},{"id":"0038","n":"barbell drag curl","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.","Let the barbell hang at arm's length in front of your thighs.","Keeping your upper arms stationary, curl the barbell up towards your chest by contracting your biceps.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0038-IENzBdA.jpg","gif":"0038-IENzBdA.gif"},{"id":"1370","n":"barbell floor calf raise","bp":"lower legs","eq":"barbell","tg":"calves","mg":"hamstrings","sm":["hamstrings"],"st":["Place a barbell on the floor in front of you.","Stand with the balls of your feet on the edge of the barbell, with your heels hanging off.","Hold onto a stable object for balance if needed.","Raise your heels as high as possible, using your calves to lift your body.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1370-2IHEa2T.jpg","gif":"1370-2IHEa2T.gif"},{"id":"0039","n":"barbell front chest squat","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Start by standing with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell in front of your chest with your hands shoulder-width apart, elbows pointing forward.","Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"0039-IeTIEqg.jpg","gif":"0039-IeTIEqg.gif"},{"id":"0041","n":"barbell front raise","bp":"shoulders","eq":"barbell","tg":"delts","mg":"biceps","sm":["biceps","triceps"],"st":["Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.","Keep your arms straight and lift the barbell forward and upward until it reaches shoulder level.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0041-b2Uoz54.jpg","gif":"0041-b2Uoz54.gif"},{"id":"0040","n":"barbell front raise and pullover","bp":"chest","eq":"barbell","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.","Keep your arms straight and raise the barbell in front of you until it reaches shoulder height.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Next, lower the barbell behind your head, keeping your arms straight.","Pause for a moment at the bottom, then raise the barbell back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0040-33AzZeV.jpg","gif":"0040-33AzZeV.gif"},{"id":"0042","n":"barbell front squat","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Start by standing with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell in front of your shoulders, resting it on your collarbone and shoulders.","Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"0042-zG0zs85.jpg","gif":"0042-zG0zs85.gif"},{"id":"0043","n":"barbell full squat","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you begin to lower your body down.","Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.","Lower yourself until your thighs are parallel to the ground or slightly below.","Keep your knees in line with your toes and your weight in your heels.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."],"img":"0043-qXTaZnJ.jpg","gif":"0043-qXTaZnJ.gif"},{"id":"1461","n":"barbell full squat (back pov)","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you begin to lower your body down.","Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.","Lower your body until your thighs are parallel to the ground or slightly below.","Keep your knees in line with your toes and your weight in your heels.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."],"img":"1461-DhMl549.jpg","gif":"1461-DhMl549.gif"},{"id":"1462","n":"barbell full squat (side pov)","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you begin to lower your body down.","Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.","Lower your body until your thighs are parallel to the ground or slightly below.","Keep your knees in line with your toes and your weight in your heels.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."],"img":"1462-iYzB0Cz.jpg","gif":"1462-iYzB0Cz.gif"},{"id":"1545","n":"barbell full zercher squat","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Stand with your feet shoulder-width apart and toes slightly turned out.","Hold the barbell in the crooks of your elbows, with your hands gripping the barbell for stability.","Engage your core and keep your chest lifted as you lower your hips back and down into a squat position.","Keep your knees in line with your toes and your weight in your heels.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Drive through your heels to stand back up, squeezing your glutes at the top of the movement.","Repeat for the desired number of repetitions."],"img":"1545-vR1vold.jpg","gif":"1545-vR1vold.gif"},{"id":"1409","n":"barbell glute bridge","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Start by lying flat on your back on the ground with your knees bent and feet flat on the floor.","Place a barbell across your hips, holding it securely with both hands.","Engage your glutes and core muscles, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, squeezing your glutes.","Slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1409-qKBpF7I.jpg","gif":"1409-qKBpF7I.gif","ty":"rin"},{"id":"3562","n":"barbell glute bridge two legs on bench (male)","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Start by sitting on the edge of a bench with your upper back resting against it and your feet flat on the ground, hip-width apart.","Place a barbell across your hips, holding it securely with both hands.","Engage your glutes and core muscles, then press through your heels to lift your hips off the bench, creating a straight line from your knees to your shoulders.","Pause for a moment at the top, squeezing your glutes.","Slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"img":"3562-qg2PGl6.jpg","gif":"3562-qg2PGl6.gif","ty":"rin"},{"id":"0044","n":"barbell good morning","bp":"upper legs","eq":"barbell","tg":"hamstrings","mg":"lower back","sm":["lower back"],"st":["Start by standing with your feet shoulder-width apart and the barbell resting on your upper back.","Keeping your back straight and your core engaged, hinge forward at the hips, pushing your buttocks back as if you were trying to touch the wall behind you with your glutes.","Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Pause for a moment, then return to the starting position by squeezing your glutes and pushing your hips forward.","Repeat for the desired number of repetitions."],"img":"0044-XlZ4lAC.jpg","gif":"0044-XlZ4lAC.gif"},{"id":"0045","n":"barbell guillotine bench press","bp":"chest","eq":"barbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lower the barbell slowly towards your neck, keeping your elbows pointed outwards.","Pause for a moment when the barbell is just above your neck.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"0045-GXoaSgn.jpg","gif":"0045-GXoaSgn.gif"},{"id":"0046","n":"barbell hack squat","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Start by standing with your feet shoulder-width apart and your toes slightly turned out.","Hold the barbell behind your legs, resting it on your upper thighs.","Lower your body by bending at the knees and hips, keeping your back straight and your chest up.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"0046-5VCj6iH.jpg","gif":"0046-5VCj6iH.gif"},{"id":"1436","n":"barbell high bar squat","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Stand with your feet shoulder-width apart, toes slightly turned out.","Place the barbell on your upper back, resting it on your traps.","Engage your core and keep your chest up as you begin to squat down, pushing your hips back and bending your knees.","Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."],"img":"1436-Gnfo4FM.jpg","gif":"1436-Gnfo4FM.gif"},{"id":"0047","n":"barbell incline bench press","bp":"chest","eq":"barbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows at a 45-degree angle.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0047-3TZduzM.jpg","gif":"0047-3TZduzM.gif"},{"id":"1719","n":"barbell incline close grip bench press","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"1719-gx7s7uF.jpg","gif":"1719-gx7s7uF.gif"},{"id":"0048","n":"barbell incline reverse-grip press","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Set up an incline bench at a 45-degree angle.","Lie back on the bench and grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.","Unrack the barbell and lower it towards your upper chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0048-641mIfk.jpg","gif":"0048-641mIfk.gif"},{"id":"0049","n":"barbell incline row","bp":"back","eq":"barbell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Set up an incline bench at a 45-degree angle.","Lie face down on the bench with your chest against the pad and your feet flat on the ground.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and your core engaged.","Pull the barbell towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"0049-dmgMp3n.jpg","gif":"0049-dmgMp3n.gif"},{"id":"0050","n":"barbell incline shoulder raise","bp":"chest","eq":"barbell","tg":"serratus anterior","mg":"deltoids","sm":["deltoids","trapezius"],"st":["Set up an incline bench at a 45-degree angle.","Sit on the bench with your back against the pad and feet flat on the ground.","Hold a barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell up to shoulder height, keeping your elbows slightly bent.","Slowly raise the barbell overhead, extending your arms fully.","Pause for a moment at the top, then slowly lower the barbell back to shoulder height.","Repeat for the desired number of repetitions."],"img":"0050-xi0yckC.jpg","gif":"0050-xi0yckC.gif"},{"id":"0051","n":"barbell jefferson squat","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart and toes slightly turned out.","Hold the barbell with an overhand grip, resting it on the front of your body, just below your waist.","Step your left foot forward and your right foot back, keeping your feet shoulder-width apart.","Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.","Push through your heels to stand back up to the starting position.","Repeat the movement, alternating your forward and back foot with each repetition."],"img":"0051-pkSoCW9.jpg","gif":"0051-pkSoCW9.gif"},{"id":"0052","n":"barbell jm bench press","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lower the barbell to your chest, keeping your elbows tucked in close to your body.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"0052-ZsiqXYa.jpg","gif":"0052-ZsiqXYa.gif"},{"id":"0053","n":"barbell jump squat","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.","Lower your body into a squat position by bending your knees and pushing your hips back.","Once you reach the bottom of the squat, explode upwards by jumping off the ground.","As you jump, extend your hips, knees, and ankles, pushing through your toes.","Land softly back into the squat position and immediately repeat the movement for the desired number of repetitions."],"img":"0053-1gFNTZV.jpg","gif":"0053-1gFNTZV.gif","ty":"atl"},{"id":"1410","n":"barbell lateral lunge","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart, holding a barbell across your upper back.","Take a big step to the side with your right foot, keeping your left foot planted.","Bend your right knee and lower your body down into a lunge position, keeping your left leg straight.","Push off with your right foot and return to the starting position.","Repeat on the other side, stepping with your left foot."],"img":"1410-py1HSzx.jpg","gif":"1410-py1HSzx.gif"},{"id":"1435","n":"barbell low bar squat","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart and the barbell resting on your upper back.","Keeping your chest up and core engaged, slowly lower your body by bending your knees and pushing your hips back.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"1435-bTpEUcm.jpg","gif":"1435-bTpEUcm.gif"},{"id":"0054","n":"barbell lunge","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.","Take a step forward with your right foot, keeping your torso upright.","Lower your body by bending your right knee until your thigh is parallel to the ground.","Push through your right heel to return to the starting position.","Repeat with your left leg, alternating legs for the desired number of repetitions."],"img":"0054-t8iSghb.jpg","gif":"0054-t8iSghb.gif"},{"id":"1720","n":"barbell lying back of the head tricep extension","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold a barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"img":"1720-yg8Totb.jpg","gif":"1720-yg8Totb.gif"},{"id":"0055","n":"barbell lying close-grip press","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a close grip, hands shoulder-width apart, palms facing towards your feet.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Slowly lower the barbell towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest, then push it back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0055-EcaV7aL.jpg","gif":"0055-EcaV7aL.gif"},{"id":"0056","n":"barbell lying close-grip triceps extension","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Grasp the barbell with a close grip, hands shoulder-width apart, palms facing up.","Extend your arms fully, lifting the barbell above your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment at the bottom, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"img":"0056-HJ63mSO.jpg","gif":"0056-HJ63mSO.gif"},{"id":"0057","n":"barbell lying extension","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0057-EMpUwRI.jpg","gif":"0057-EMpUwRI.gif"},{"id":"0058","n":"barbell lying lifting (on hip)","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Lie flat on your back on a bench with your feet flat on the ground and your knees bent.","Hold the barbell with an overhand grip and position it on your hips.","Engaging your glutes, lift your hips off the bench until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0058-SNFfUff.jpg","gif":"0058-SNFfUff.gif"},{"id":"0059","n":"barbell lying preacher curl","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a preacher bench with your chest against the pad and your arms extended over the edge, holding a barbell with an underhand grip.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"0059-SYJ4Bkt.jpg","gif":"0059-SYJ4Bkt.gif"},{"id":"0061","n":"barbell lying triceps extension","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment at the bottom, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0061-iZop9xO.jpg","gif":"0061-iZop9xO.gif"},{"id":"0060","n":"barbell lying triceps extension skull crusher","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment when the barbell is just above your forehead, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0060-h8LFzo9.jpg","gif":"0060-h8LFzo9.gif"},{"id":"0063","n":"barbell narrow stance squat","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart and toes pointing slightly outward.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you slowly lower your body by bending your knees and pushing your hips back.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"0063-elhhVgj.jpg","gif":"0063-elhhVgj.gif"},{"id":"0064","n":"barbell one arm bent over row","bp":"back","eq":"barbell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with one hand using an overhand grip.","Bend forward at the hips, keeping your back straight and your head in a neutral position.","Pull the barbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Lower the barbell back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions, then switch to the other arm."],"img":"0064-Jsgsc27.jpg","gif":"0064-Jsgsc27.gif"},{"id":"0065","n":"barbell one arm floor press","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Lie flat on your back on the floor with your knees bent and feet flat on the ground.","Hold the barbell with one hand, palm facing up, and extend your arm straight up over your chest.","Slowly lower the barbell towards your chest, keeping your elbow close to your body.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"0065-vtusOWT.jpg","gif":"0065-vtusOWT.gif"},{"id":"0066","n":"barbell one arm side deadlift","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","lower back"],"st":["Stand with your feet shoulder-width apart, holding a barbell in one hand with an overhand grip.","Keep your back straight and your core engaged.","Bend at the hips and lower the barbell towards the outside of your leg, keeping your arm straight and your chest up.","Lower the barbell as far as you can while maintaining good form.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"0066-2DxtqHL.jpg","gif":"0066-2DxtqHL.gif"},{"id":"0067","n":"barbell one arm snatch","bp":"shoulders","eq":"barbell","tg":"delts","mg":"traps","sm":["traps","forearms","core"],"st":["Stand with your feet shoulder-width apart, toes pointing slightly outwards.","Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend your knees and lower your hips into a squat position, keeping your back straight and chest up.","Explosively extend your hips, knees, and ankles, driving the barbell upwards.","As the barbell reaches chest level, pull it upwards with your arm, keeping it close to your body.","Rotate your elbow under the barbell and extend your arm fully overhead, locking out your elbow.","Lower the barbell back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions, then switch arms."],"img":"0067-xHKN2s8.jpg","gif":"0067-xHKN2s8.gif"},{"id":"0068","n":"barbell one leg squat","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart and hold a barbell across your upper back.","Lift one foot off the ground and extend it forward, keeping it parallel to the ground.","Bend your standing leg and lower your body down as if sitting back into a chair, keeping your chest up and your back straight.","Lower yourself until your thigh is parallel to the ground, then push through your heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."],"img":"0068-uKyN64F.jpg","gif":"0068-uKyN64F.gif"},{"id":"0069","n":"barbell overhead squat","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","core"],"st":["Stand with your feet shoulder-width apart and toes slightly turned out.","Hold the barbell with a wide grip, positioning it overhead with your arms fully extended.","Engage your core and lower your body down into a squat position, keeping your chest up and knees tracking over your toes.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"0069-gfk9kD4.jpg","gif":"0069-gfk9kD4.gif"},{"id":"1411","n":"barbell palms down wrist curl over a bench","bp":"lower arms","eq":"barbell","tg":"forearms","mg":"biceps","sm":["biceps","brachialis"],"st":["Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, palms facing down.","Hold a barbell with an overhand grip, hands shoulder-width apart.","Lower the barbell towards the ground by flexing your wrists, keeping your forearms stationary.","Pause for a moment at the bottom, then slowly raise the barbell back up by extending your wrists.","Repeat for the desired number of repetitions."],"img":"1411-yzYH9pI.jpg","gif":"1411-yzYH9pI.gif"},{"id":"1412","n":"barbell palms up wrist curl over a bench","bp":"lower arms","eq":"barbell","tg":"forearms","mg":"biceps","sm":["biceps","shoulders"],"st":["Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up.","Rest your forearms on the bench, allowing your wrists to hang off the edge.","Keeping your forearms stationary, exhale and curl your wrists upwards as far as possible.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"1412-SJAA2IQ.jpg","gif":"1412-SJAA2IQ.gif"},{"id":"3017","n":"barbell pendlay row","bp":"back","eq":"barbell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Stand with your feet shoulder-width apart and your knees slightly bent.","Bend forward at the hips, keeping your back straight and your chest up.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Pull the barbell towards your upper abdomen, squeezing your shoulder blades together.","Lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"img":"3017-r0z6xzQ.jpg","gif":"3017-r0z6xzQ.gif"},{"id":"1751","n":"barbell pin presses","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Set up a barbell on a power rack at chest height.","Stand facing the barbell and position yourself underneath it, with your feet shoulder-width apart.","Grip the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest, with your arms fully extended.","Lower the barbell down towards your chest, keeping your elbows tucked in close to your body.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"1751-bndCa3Q.jpg","gif":"1751-bndCa3Q.gif"},{"id":"0070","n":"barbell preacher curl","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a preacher bench with your upper arms resting on the pad and your chest against the support.","Grasp the barbell with an underhand grip, slightly wider than shoulder-width apart.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0070-qOgPVf6.jpg","gif":"0070-qOgPVf6.gif"},{"id":"0071","n":"barbell press sit-up","bp":"waist","eq":"barbell","tg":"abs","mg":"shoulders","sm":["shoulders","chest"],"st":["Lie flat on your back on a mat with your knees bent and feet flat on the ground.","Hold the barbell with an overhand grip, resting it on your chest.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0071-wnEscH8.jpg","gif":"0071-wnEscH8.gif"},{"id":"0072","n":"barbell prone incline curl","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Set up an incline bench at a 45-degree angle.","Lie face down on the bench with your chest and stomach resting against it.","Hold a barbell with an underhand grip, shoulder-width apart.","Extend your arms fully, allowing the barbell to hang down towards the floor.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"0072-WLvTAv5.jpg","gif":"0072-WLvTAv5.gif"},{"id":"0073","n":"barbell pullover","bp":"back","eq":"barbell","tg":"lats","mg":"chest","sm":["chest","triceps"],"st":["Lie flat on a bench with your head at one end and your feet on the floor.","Hold a barbell with a shoulder-width grip and extend your arms straight above your chest.","Keeping your arms straight, lower the barbell behind your head in a controlled manner until you feel a stretch in your lats.","Pause for a moment, then raise the barbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"0073-i6LWjok.jpg","gif":"0073-i6LWjok.gif"},{"id":"0022","n":"barbell pullover to press","bp":"back","eq":"barbell","tg":"lats","mg":"triceps","sm":["triceps","chest","shoulders"],"st":["Lie flat on a bench with your head at one end and your feet on the ground.","Hold the barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.","Keeping your arms straight, lower the barbell behind your head in an arc-like motion until you feel a stretch in your lats.","Pause for a moment, then reverse the motion and press the barbell back to the starting position above your chest.","Repeat for the desired number of repetitions."],"img":"0022-znLogoF.jpg","gif":"0022-znLogoF.gif"},{"id":"0074","n":"barbell rack pull","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Set up a barbell on a rack at knee height.","Stand with your feet shoulder-width apart, toes pointing slightly outwards.","Bend at the hips and knees to lower yourself down and grip the barbell with an overhand grip, hands shoulder-width apart.","Engage your core and lift the barbell by extending your hips and knees, pulling your shoulders back and squeezing your glutes at the top.","Lower the barbell back down to the starting position by bending at the hips and knees.","Repeat for the desired number of repetitions."],"img":"0074-za9Ni4z.jpg","gif":"0074-za9Ni4z.gif"},{"id":"0075","n":"barbell rear delt raise","bp":"shoulders","eq":"barbell","tg":"delts","mg":"traps","sm":["traps","rhomboids"],"st":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise the barbell out to the sides, keeping your arms straight, until they are parallel to the ground.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"0075-Ln9iTbU.jpg","gif":"0075-Ln9iTbU.gif"},{"id":"0076","n":"barbell rear delt row","bp":"shoulders","eq":"barbell","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids","biceps"],"st":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend forward at the hips, keeping your back straight and chest up.","Pull the barbell towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"0076-S9zHIvU.jpg","gif":"0076-S9zHIvU.gif"},{"id":"0078","n":"barbell rear lunge","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.","Take a step backward with your right foot, landing on the ball of your foot.","Bend both knees to lower your body until your left thigh is parallel to the ground.","Push through your left heel to return to the starting position.","Repeat with the other leg."],"img":"0078-VaP75jl.jpg","gif":"0078-VaP75jl.gif"},{"id":"0077","n":"barbell rear lunge v. 2","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart and hold a barbell across your upper back.","Take a step backward with your right foot, landing on the ball of your foot.","Bend both knees to lower your body until your left thigh is parallel to the ground.","Push through your left heel to return to the starting position.","Repeat with the other leg."],"img":"0077-62Nw60O.jpg","gif":"0077-62Nw60O.gif"},{"id":"0079","n":"barbell revers wrist curl v. 2","bp":"lower arms","eq":"barbell","tg":"forearms","mg":"biceps","sm":["biceps","brachialis"],"st":["Sit on a bench with your feet flat on the ground and your knees bent.","Hold a barbell with an overhand grip, palms facing down, and your hands shoulder-width apart.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"0079-qDnGfDb.jpg","gif":"0079-qDnGfDb.gif"},{"id":"2187","n":"barbell reverse close-grip bench press","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a reverse grip, hands shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Slowly lower the barbell down towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell is just above your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"2187-YqJw82s.jpg","gif":"2187-YqJw82s.gif"},{"id":"0080","n":"barbell reverse curl","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.","Keep your upper arms stationary and exhale as you curl the barbell upward, contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale as you slowly lower the barbell back to the starting position, keeping your upper arms stationary.","Repeat for the desired number of repetitions."],"img":"0080-xNrS20v.jpg","gif":"0080-xNrS20v.gif"},{"id":"0118","n":"barbell reverse grip bent over row","bp":"back","eq":"barbell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold a barbell with an overhand grip, palms facing down, and hands slightly wider than shoulder-width apart.","Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor.","Pull the barbell towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"0118-SzX3uzM.jpg","gif":"0118-SzX3uzM.gif"},{"id":"1256","n":"barbell reverse grip decline bench press","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Lie on a decline bench with your feet secured and your head lower than your hips.","Grasp the barbell with a reverse grip, slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."],"img":"1256-DotAgEF.jpg","gif":"1256-DotAgEF.gif"},{"id":"1257","n":"barbell reverse grip incline bench press","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"1257-DU7I633.jpg","gif":"1257-DU7I633.gif"},{"id":"1317","n":"barbell reverse grip incline bench row","bp":"back","eq":"barbell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Set up an incline bench at a 45-degree angle.","Sit on the bench facing the backrest with your chest against it.","Grab the barbell with a reverse grip (palms facing down) and hands slightly wider than shoulder-width apart.","Keep your back straight and core engaged.","Pull the barbell towards your upper abdomen, squeezing your shoulder blades together.","Pause for a moment at the top of the movement.","Slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"1317-8d8qJQI.jpg","gif":"1317-8d8qJQI.gif"},{"id":"1721","n":"barbell reverse grip skullcrusher","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"forearms","sm":["forearms"],"st":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with a reverse grip, palms facing towards your face, and your hands shoulder-width apart.","Extend your arms straight up over your chest, keeping your elbows in and your wrists straight.","Slowly lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary.","Pause for a moment at the bottom, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"img":"1721-yRLPCLu.jpg","gif":"1721-yRLPCLu.gif"},{"id":"0081","n":"barbell reverse preacher curl","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a preacher bench with your chest against the pad and your arms extended straight down, holding a barbell with an overhand grip.","Keeping your upper arms stationary, exhale and curl the barbell upward while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"0081-4LIG9xr.jpg","gif":"0081-4LIG9xr.gif"},{"id":"0082","n":"barbell reverse wrist curl","bp":"lower arms","eq":"barbell","tg":"forearms","mg":"biceps","sm":["biceps","brachialis"],"st":["Sit on a bench with your feet flat on the ground and hold a barbell with an overhand grip, palms facing down.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, bringing the barbell towards your body.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0082-LsZkfU6.jpg","gif":"0082-LsZkfU6.gif"},{"id":"0084","n":"barbell rollerout","bp":"waist","eq":"barbell","tg":"abs","mg":"lower back","sm":["lower back"],"st":["Kneel on the floor and hold a barbell with both hands, shoulder-width apart.","Roll the barbell forward, extending your arms and keeping your core engaged.","Continue rolling forward until your body is fully extended and your arms are overhead.","Pause for a moment, then slowly roll the barbell back towards your knees, maintaining control.","Repeat for the desired number of repetitions."],"img":"0084-7M66AVi.jpg","gif":"0084-7M66AVi.gif"},{"id":"0083","n":"barbell rollerout from bench","bp":"waist","eq":"barbell","tg":"abs","mg":"shoulders","sm":["shoulders","triceps"],"st":["Start by kneeling on the floor with a barbell placed on a bench in front of you.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Keeping your core engaged and your back straight, slowly roll the barbell forward, extending your arms in front of you.","Continue rolling the barbell forward until your body is fully extended and your arms are overhead.","Pause for a moment at the fully extended position, then slowly roll the barbell back towards your body, returning to the starting position.","Repeat for the desired number of repetitions."],"img":"0083-Gxg9lDc.jpg","gif":"0083-Gxg9lDc.gif"},{"id":"0085","n":"barbell romanian deadlift","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Stand with your feet shoulder-width apart and your toes pointing forward.","Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend at the hips, keeping your back straight and your knees slightly bent.","Lower the barbell towards the ground, keeping it close to your body.","Feel the stretch in your hamstrings as you lower the barbell.","Once you feel a stretch in your hamstrings, push your hips forward and stand up straight.","Squeeze your glutes at the top of the movement.","Lower the barbell back down to the starting position and repeat for the desired number of repetitions."],"img":"0085-wQ2c4XD.jpg","gif":"0085-wQ2c4XD.gif"},{"id":"0086","n":"barbell seated behind head military press","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and bring it down to shoulder level, behind your head.","Press the barbell upward until your arms are fully extended.","Lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0086-ngPpyRS.jpg","gif":"0086-ngPpyRS.gif"},{"id":"0087","n":"barbell seated bradford rocky press","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell to shoulder height, keeping your elbows slightly bent and pointing forward.","Press the barbell overhead, fully extending your arms.","Lower the barbell back to shoulder height and repeat for the desired number of repetitions."],"img":"0087-0dCyly0.jpg","gif":"0087-0dCyly0.gif"},{"id":"0088","n":"barbell seated calf raise","bp":"lower legs","eq":"barbell","tg":"calves","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Sit on a bench with your feet flat on the floor and a barbell resting on your thighs.","Place the balls of your feet on a raised platform, such as a block or step.","Position the barbell across your thighs and hold it securely with your hands.","Keeping your back straight and your core engaged, lift your heels off the ground by extending your ankles.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0088-ktsFQAZ.jpg","gif":"0088-ktsFQAZ.gif"},{"id":"1371","n":"barbell seated calf raise","bp":"lower legs","eq":"barbell","tg":"calves","mg":"hamstrings","sm":["hamstrings"],"st":["Sit on a bench with your feet flat on the floor and a barbell resting on your thighs.","Place the balls of your feet on a raised platform, such as a block or step.","Lower your heels as far as possible, feeling a stretch in your calves.","Raise your heels as high as possible, contracting your calves.","Repeat for the desired number of repetitions."],"img":"1371-ipvgBnC.jpg","gif":"1371-ipvgBnC.gif"},{"id":"1718","n":"barbell seated close grip behind neck triceps extension","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with a close grip behind your neck, palms facing forward.","Keep your elbows close to your head and slowly lower the barbell towards the back of your head.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"img":"1718-4CBIBOM.jpg","gif":"1718-4CBIBOM.gif"},{"id":"0089","n":"barbell seated close-grip concentration curl","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a bench with your feet flat on the floor and hold a barbell with an underhand grip, hands shoulder-width apart.","Rest your upper arms against your inner thighs, just above your knees, and let the barbell hang down in front of you.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders, contracting your biceps.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0089-1V1gj1u.jpg","gif":"0089-1V1gj1u.gif"},{"id":"0090","n":"barbell seated good morning","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Sit on a bench with your feet flat on the ground and a barbell resting on your upper back.","Keep your back straight and your chest up.","Slowly hinge forward at the hips, lowering your torso towards the ground.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"0090-d960PgE.jpg","gif":"0090-d960PgE.gif"},{"id":"0091","n":"barbell seated overhead press","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and bring it to shoulder level, with your elbows bent and palms facing forward.","Press the barbell overhead by extending your arms fully.","Pause for a moment at the top, then slowly lower the barbell back to shoulder level.","Repeat for the desired number of repetitions."],"img":"0091-kTbSH9h.jpg","gif":"0091-kTbSH9h.gif"},{"id":"0092","n":"barbell seated overhead triceps extension","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Sit on a bench with your back straight and feet flat on the ground.","Hold a barbell with an overhand grip, hands shoulder-width apart, and raise it overhead.","Lower the barbell behind your head by bending your elbows, keeping your upper arms close to your head.","Pause for a moment, then extend your arms to raise the barbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"0092-5uFK1xr.jpg","gif":"0092-5uFK1xr.gif"},{"id":"0094","n":"barbell seated twist","bp":"waist","eq":"barbell","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Sit on a flat bench with your feet flat on the ground and your knees bent.","Hold a barbell with both hands in front of your chest, keeping your elbows slightly bent.","Engage your core and slowly twist your torso to one side, keeping your back straight.","Pause for a moment at the end of the twist, then slowly rotate back to the starting position.","Repeat the twist to the other side.","Continue alternating sides for the desired number of repetitions."],"img":"0094-dFSNDOA.jpg","gif":"0094-dFSNDOA.gif"},{"id":"0095","n":"barbell shrug","bp":"back","eq":"barbell","tg":"traps","mg":"shoulders","sm":["shoulders"],"st":["Stand with your feet shoulder-width apart and hold a barbell in front of you with an overhand grip.","Keep your arms straight and your back straight throughout the exercise.","Lift your shoulders up towards your ears as high as possible, squeezing your traps at the top.","Hold for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0095-dG7tG5y.jpg","gif":"0095-dG7tG5y.gif"},{"id":"0096","n":"barbell side bent v. 2","bp":"waist","eq":"barbell","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Stand with your feet shoulder-width apart and hold a barbell with both hands, palms facing down.","Keep your back straight and core engaged throughout the exercise.","Slowly bend your torso to the right side, lowering the barbell towards your right knee.","Pause for a moment, then return to the starting position.","Repeat the movement on the left side.","Continue alternating sides for the desired number of repetitions."],"img":"0096-i4JkUaL.jpg","gif":"0096-i4JkUaL.gif"},{"id":"0098","n":"barbell side split squat","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.","Hold a barbell across your upper back, resting it on your traps.","Engage your core and keep your chest up as you lower your body down into a squat position, bending at the knees and hips.","As you lower, push your knees out to the sides and keep your weight on your heels.","Lower until your thighs are parallel to the ground, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"0098-W31mMjd.jpg","gif":"0098-W31mMjd.gif"},{"id":"0097","n":"barbell side split squat v. 2","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand with your feet wider than shoulder-width apart, toes pointing slightly outwards.","Hold a barbell across your upper back, resting it on your shoulders.","Take a big step to the side with your right foot, keeping your left foot planted.","Bend your right knee and lower your body down into a squat position, keeping your chest up and your back straight.","Push through your right heel to return to the starting position.","Repeat on the other side, stepping out with your left foot.","Continue alternating sides for the desired number of repetitions."],"img":"0097-HUEqZ1y.jpg","gif":"0097-HUEqZ1y.gif"},{"id":"1756","n":"barbell single leg deadlift","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Stand with your feet hip-width apart, holding a barbell in front of your thighs with an overhand grip.","Shift your weight onto your left foot and lift your right foot slightly off the ground.","Hinge forward at the hips, keeping your back straight and your right leg extended behind you for balance.","Lower the barbell towards the ground, keeping it close to your body and your left leg slightly bent.","Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"1756-gEyURal.jpg","gif":"1756-gEyURal.gif"},{"id":"0099","n":"barbell single leg split squat","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart, holding a barbell across your upper back.","Take a large step forward with one leg, keeping your torso upright.","Lower your body by bending your front knee and hip, while keeping your back leg straight.","Continue lowering until your front thigh is parallel to the ground.","Pause for a moment, then push through your front heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"img":"0099-gGNQmVt.jpg","gif":"0099-gGNQmVt.gif"},{"id":"2799","n":"barbell sitted alternate leg raise","bp":"waist","eq":"barbell","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Sit on a bench with your back straight and hold a barbell across your thighs.","Keeping your legs straight, lift one leg up as high as possible while keeping the other leg on the ground.","Lower the raised leg back down and repeat with the other leg.","Continue alternating legs for the desired number of repetitions."],"img":"2799-G7xoEzr.jpg","gif":"2799-G7xoEzr.gif"},{"id":"2800","n":"barbell sitted alternate leg raise (female)","bp":"waist","eq":"barbell","tg":"abs","mg":"hip flexors","sm":["hip flexors","quadriceps"],"st":["Sit on a bench with your back straight and hold a barbell across your thighs.","Place your hands on the sides of the bench for support.","Keeping your legs straight, lift one leg up as high as possible while keeping it parallel to the ground.","Lower the leg back down and repeat with the other leg.","Continue alternating legs for the desired number of repetitions."],"img":"2800-BCs0G2F.jpg","gif":"2800-BCs0G2F.gif"},{"id":"0100","n":"barbell skier","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Simultaneously lift the barbell up towards your shoulders while jumping slightly off the ground.","As you reach the top of the movement, quickly reverse the motion and lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0100-4Leypho.jpg","gif":"0100-4Leypho.gif"},{"id":"0101","n":"barbell speed squat","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you lower your hips back and down, as if sitting into a chair.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Drive through your heels to stand back up, squeezing your glutes at the top.","Repeat for the desired number of repetitions."],"img":"0101-euI1BwR.jpg","gif":"0101-euI1BwR.gif"},{"id":"2810","n":"barbell split squat v. 2","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.","Take a large step forward with your right foot, keeping your torso upright.","Lower your body by bending your knees and hips until your right thigh is parallel to the ground.","Pause for a moment, then push through your right heel to return to the starting position.","Repeat with your left leg forward for the desired number of repetitions."],"img":"2810-HBYyX94.jpg","gif":"2810-HBYyX94.gif"},{"id":"0102","n":"barbell squat (on knees)","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Start by kneeling on the ground with your knees hip-width apart and your toes pointing forward.","Place a barbell across your shoulders, gripping it with an overhand grip and your hands slightly wider than shoulder-width apart.","Engage your core and keep your chest lifted as you slowly lower your body down by bending your knees, keeping your back straight.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"0102-oR7O9LW.jpg","gif":"0102-oR7O9LW.gif"},{"id":"2798","n":"barbell squat jump step rear lunge","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.","Lower your body into a squat position by bending your knees and pushing your hips back.","Explode upwards, jumping off the ground as high as you can.","Land softly on your feet and immediately step back with one leg into a reverse lunge.","Lower your body down until your front thigh is parallel to the ground, keeping your back straight.","Push through your front heel to return to the starting position.","Repeat the jump and lunge sequence on the other leg.","Continue alternating legs for the desired number of repetitions."],"img":"2798-RYcV1kH.jpg","gif":"2798-RYcV1kH.gif","ty":"atl"},{"id":"0103","n":"barbell standing ab rollerout","bp":"waist","eq":"barbell","tg":"abs","mg":"shoulders","sm":["shoulders","lower back"],"st":["Stand upright with your feet shoulder-width apart and hold the barbell with both hands in front of your thighs.","Engage your core and slowly roll the barbell down towards the ground, keeping your back straight and your arms extended.","Continue rolling the barbell forward until your body is fully extended and your hands are directly above your head.","Pause for a moment, then slowly roll the barbell back towards your thighs, maintaining control and keeping your core engaged.","Repeat for the desired number of repetitions."],"img":"0103-xnInPfE.jpg","gif":"0103-xnInPfE.gif"},{"id":"0104","n":"barbell standing back wrist curl","bp":"lower arms","eq":"barbell","tg":"forearms","mg":"biceps","sm":["biceps","shoulders"],"st":["Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip.","Rest the barbell on the back of your hands with your palms facing down and your fingers pointing towards your body.","Keeping your upper arms stationary, exhale and curl your wrists upwards as far as possible.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"0104-2qTvJAZ.jpg","gif":"0104-2qTvJAZ.gif"},{"id":"0105","n":"barbell standing bradford press","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Stand with your feet shoulder-width apart and hold the barbell in front of your shoulders with an overhand grip.","Press the barbell overhead, fully extending your arms.","Lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0105-dCPESfR.jpg","gif":"0105-dCPESfR.gif"},{"id":"1372","n":"barbell standing calf raise","bp":"lower legs","eq":"barbell","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Stand with your feet shoulder-width apart and place a barbell across your upper back.","Raise your heels off the ground as high as possible, using only your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1372-8ozhUIZ.jpg","gif":"1372-8ozhUIZ.gif"},{"id":"0106","n":"barbell standing close grip curl","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, hands close together.","Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Exhale as you curl the weights while contracting your biceps. Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale as you slowly begin to bring the barbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"0106-4dUn2iv.jpg","gif":"0106-4dUn2iv.gif"},{"id":"1456","n":"barbell standing close grip military press","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, hands slightly closer than shoulder-width apart.","Lift the barbell to shoulder height, keeping your elbows close to your body.","Press the barbell overhead, extending your arms fully.","Lower the barbell back to shoulder height.","Repeat for the desired number of repetitions."],"img":"1456-wdRZISl.jpg","gif":"1456-wdRZISl.gif"},{"id":"2414","n":"barbell standing concentration curl","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand with your feet shoulder-width apart and hold a barbell in one hand, palm facing up.","Rest your opposite hand on your thigh for support.","Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the weight back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"2414-vsMcDi9.jpg","gif":"2414-vsMcDi9.gif"},{"id":"0107","n":"barbell standing front raise over head","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Stand with your feet shoulder-width apart, holding a barbell in front of your thighs with an overhand grip.","Keep your back straight and engage your core.","Slowly raise the barbell in front of you, keeping your arms straight and your palms facing down.","Continue lifting until the barbell is slightly above shoulder level.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0107-S8mo30S.jpg","gif":"0107-S8mo30S.gif"},{"id":"0108","n":"barbell standing leg calf raise","bp":"lower legs","eq":"barbell","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Stand with your feet shoulder-width apart and place a barbell across your upper back.","Raise your heels off the ground as high as possible, using your calves.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0108-rGwhJ5o.jpg","gif":"0108-rGwhJ5o.gif"},{"id":"0109","n":"barbell standing overhead triceps extension","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip.","Raise the barbell overhead, fully extending your arms.","Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then raise the barbell back to the starting position by extending your arms.","Repeat for the desired number of repetitions."],"img":"0109-dZl9Q27.jpg","gif":"0109-dZl9Q27.gif"},{"id":"0110","n":"barbell standing reverse grip curl","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps, bringing the barbell as close to your shoulders as possible.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"0110-LWuA3aZ.jpg","gif":"0110-LWuA3aZ.gif"},{"id":"0111","n":"barbell standing rocking leg calf raise","bp":"lower legs","eq":"barbell","tg":"calves","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Stand with your feet shoulder-width apart and hold a barbell across your upper back.","Raise your heels off the ground as high as possible, balancing on the balls of your feet.","Slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0111-6HiHHe0.jpg","gif":"0111-6HiHHe0.gif"},{"id":"0112","n":"barbell standing twist","bp":"waist","eq":"barbell","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Stand with your feet shoulder-width apart and hold a barbell in front of your chest with both hands, palms facing down.","Engage your core and keep your back straight throughout the exercise.","Slowly twist your torso to the right, pivoting on your feet and hips, while keeping your lower body stable.","Pause for a moment at the end of the twist, then slowly return to the starting position.","Repeat the twist to the left side.","Continue alternating twists for the desired number of repetitions."],"img":"0112-yQe5HpE.jpg","gif":"0112-yQe5HpE.gif"},{"id":"1629","n":"barbell standing wide grip biceps curl","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, hands wider than shoulder-width apart.","Keep your back straight and your elbows close to your torso.","Exhale and curl the barbell up towards your shoulders, keeping your upper arms stationary.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"1629-faHKVkK.jpg","gif":"1629-faHKVkK.gif"},{"id":"1457","n":"barbell standing wide military press","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, slightly wider than shoulder-width.","Lift the barbell to shoulder height, keeping your elbows slightly in front of the bar.","Press the barbell overhead, extending your arms fully.","Lower the barbell back to shoulder height and repeat for the desired number of repetitions."],"img":"1457-Kyd9Rz5.jpg","gif":"1457-Kyd9Rz5.gif"},{"id":"0113","n":"barbell standing wide-grip curl","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart.","Let the barbell hang at arm's length in front of your thighs, with your palms facing away from your body.","Keeping your upper arms stationary, exhale and curl the barbell upward by contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"0113-NdIb5Z1.jpg","gif":"0113-NdIb5Z1.gif"},{"id":"0114","n":"barbell step-up","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand in front of a bench or step with a barbell resting on your upper back.","Place one foot on the bench or step, ensuring your entire foot is in contact with the surface.","Push through your heel and step up onto the bench or step, fully extending your hip and knee.","Pause briefly at the top, then lower yourself back down to the starting position.","Repeat with the opposite leg.","Continue alternating legs for the desired number of repetitions."],"img":"0114-Kxquu2E.jpg","gif":"0114-Kxquu2E.gif"},{"id":"0115","n":"barbell stiff leg good morning","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Stand with your feet shoulder-width apart and your knees slightly bent.","Hold the barbell across your upper back, resting it on your traps.","Keeping your back straight, hinge forward at the hips, pushing your glutes back.","Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Engage your glutes and hamstrings to return to the starting position.","Repeat for the desired number of repetitions."],"img":"0115-JrOHAZc.jpg","gif":"0115-JrOHAZc.gif"},{"id":"0116","n":"barbell straight leg deadlift","bp":"upper legs","eq":"barbell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back"],"st":["Stand with your feet shoulder-width apart and your toes pointing forward.","Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend at your hips and lower the barbell towards the ground, keeping your back straight and your knees slightly bent.","Lower the barbell until you feel a stretch in your hamstrings.","Engage your hamstrings and glutes to lift the barbell back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0116-hrVQWvE.jpg","gif":"0116-hrVQWvE.gif"},{"id":"0117","n":"barbell sumo deadlift","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","lower back"],"st":["Stand with your feet wider than shoulder-width apart, toes pointing outwards.","Place a barbell on the ground in front of you, centered between your feet.","Bend your knees and lower your hips, keeping your back straight and chest up, to grip the barbell with an overhand grip.","Engage your core and drive through your heels to lift the barbell off the ground, extending your hips and knees simultaneously.","As you lift, keep your chest up and back straight, and push your hips forward to fully engage your glutes.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions."],"img":"0117-KgI0tqW.jpg","gif":"0117-KgI0tqW.gif"},{"id":"3305","n":"barbell thruster","bp":"shoulders","eq":"barbell","tg":"delts","mg":"quadriceps","sm":["quadriceps","glutes","hamstrings","core"],"st":["Start by standing with your feet shoulder-width apart, holding a barbell at shoulder height with an overhand grip.","Lower into a squat position by bending your knees and pushing your hips back.","As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the barbell overhead.","Lower the barbell back to shoulder height as you lower back into the squat position.","Repeat for the desired number of repetitions."],"img":"3305-f7Y9eDZ.jpg","gif":"3305-f7Y9eDZ.gif"},{"id":"0120","n":"barbell upright row","bp":"shoulders","eq":"barbell","tg":"delts","mg":"traps","sm":["traps","biceps"],"st":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Let the barbell hang in front of your thighs, arms fully extended.","Keeping your back straight and core engaged, exhale and lift the barbell straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0120-UDlhcO8.jpg","gif":"0120-UDlhcO8.gif"},{"id":"0119","n":"barbell upright row v. 2","bp":"shoulders","eq":"barbell","tg":"delts","mg":"traps","sm":["traps","biceps"],"st":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Let the barbell hang in front of your thighs, arms fully extended.","Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0119-83HoW9X.jpg","gif":"0119-83HoW9X.gif"},{"id":"0121","n":"barbell upright row v. 3","bp":"shoulders","eq":"barbell","tg":"delts","mg":"traps","sm":["traps","biceps"],"st":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Let the barbell hang in front of your thighs, arms fully extended.","Keeping your core engaged and back straight, exhale as you lift the barbell straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale as you slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0121-fI18Rbc.jpg","gif":"0121-fI18Rbc.gif"},{"id":"0122","n":"barbell wide bench press","bp":"chest","eq":"barbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Lower the barbell slowly towards your chest, keeping your elbows slightly flared out.","Pause for a moment when the barbell touches your chest, then push it back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0122-JsKq9so.jpg","gif":"0122-JsKq9so.gif"},{"id":"1258","n":"barbell wide reverse grip bench press","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a wide reverse grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Lower the barbell slowly towards your chest, keeping your elbows tucked in and your wrists straight.","Pause for a moment when the barbell touches your chest, then push it back up to the starting position.","Repeat for the desired number of repetitions."],"img":"1258-945zpRg.jpg","gif":"1258-945zpRg.gif"},{"id":"0124","n":"barbell wide squat","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you lower your body down into a squat, pushing your hips back and bending your knees.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"0124-s7HX1BY.jpg","gif":"0124-s7HX1BY.gif"},{"id":"0123","n":"barbell wide-grip upright row","bp":"shoulders","eq":"barbell","tg":"delts","mg":"traps","sm":["traps","biceps"],"st":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart.","Let the barbell hang in front of your thighs, arms fully extended.","Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0123-RgJDRR1.jpg","gif":"0123-RgJDRR1.gif"},{"id":"0126","n":"barbell wrist curl","bp":"lower arms","eq":"barbell","tg":"forearms","mg":"biceps","sm":["biceps","brachialis"],"st":["Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, holding a barbell with an underhand grip.","Allow the barbell to roll down to your fingertips, keeping your wrists straight.","Slowly curl the barbell up towards your forearms by flexing your wrists.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0126-82LxxkW.jpg","gif":"0126-82LxxkW.gif"},{"id":"0125","n":"barbell wrist curl v. 2","bp":"lower arms","eq":"barbell","tg":"forearms","mg":"biceps","sm":["biceps","brachialis"],"st":["Sit on a bench with your feet flat on the ground and your knees bent.","Hold a barbell with an underhand grip, palms facing up, and your hands shoulder-width apart.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, bringing the barbell towards your forearms.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0125-6kSxYnw.jpg","gif":"0125-6kSxYnw.gif"},{"id":"0127","n":"barbell zercher squat","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Stand with your feet shoulder-width apart and toes slightly turned out.","Hold the barbell in the crooks of your elbows, with your hands gripping the bar for stability.","Engage your core and keep your chest lifted as you lower your hips back and down into a squat position.","Keep your knees in line with your toes and your weight in your heels.","Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"0127-LSTChY9.jpg","gif":"0127-LSTChY9.gif"},{"id":"3212","n":"basic toe touch (male)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","calves"],"st":["Stand with your feet shoulder-width apart and your arms by your sides.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Reach down towards your toes with your hands, keeping your legs as straight as possible.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"3212-BbfB8Gb.jpg","gif":"3212-BbfB8Gb.gif"},{"id":"0128","n":"battling ropes","bp":"shoulders","eq":"rope","tg":"delts","mg":"forearms","sm":["forearms","core"],"st":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold one end of the rope in each hand, with your palms facing each other.","Raise your arms to shoulder height, keeping your elbows slightly bent.","Begin making alternating waves with the ropes by rapidly raising and lowering each arm.","Continue for the desired duration or number of repetitions."],"img":"0128-RJa4tCo.jpg","gif":"0128-RJa4tCo.gif"},{"id":"3360","n":"bear crawl","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"core","sm":["core","shoulders","triceps"],"st":["Start on all fours with your hands directly under your shoulders and your knees directly under your hips.","Lift your knees slightly off the ground, keeping your back flat and your core engaged.","Move your right hand and left foot forward simultaneously, followed by your left hand and right foot.","Continue crawling forward, alternating your hand and foot movements.","Maintain a steady pace and keep your core tight throughout the exercise.","Continue for the desired distance or time."],"img":"3360-0Yz8WdV.jpg","gif":"3360-0Yz8WdV.gif","ty":"atl"},{"id":"1259","n":"behind head chest stretch","bp":"chest","eq":"assisted","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Stand tall with your feet shoulder-width apart.","Interlace your fingers behind your head with your elbows pointing outwards.","Slowly squeeze your shoulder blades together and push your chest forward.","Hold the stretch for 15-30 seconds.","Release the stretch and repeat as desired."],"img":"1259-QoHIhPl.jpg","gif":"1259-QoHIhPl.gif","ty":"stretch","kind":"time"},{"id":"0129","n":"bench dip (knees bent)","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.","Slide your butt off the bench and straighten your legs in front of you, keeping your heels on the ground.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0129-RrLske5.jpg","gif":"0129-RrLske5.gif"},{"id":"1399","n":"bench dip on floor","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"img":"1399-9RT8oQW.jpg","gif":"1399-9RT8oQW.gif"},{"id":"0130","n":"bench hip extension","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings"],"st":["Sit on a bench with your back against the bench and your feet flat on the ground.","Place your hands on the bench for support.","Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0130-u27Kcdz.jpg","gif":"0130-u27Kcdz.gif"},{"id":"3019","n":"bench pull-ups","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Position yourself under a bar or a sturdy horizontal surface that is at chest height.","Grab the bar or surface with an overhand grip, slightly wider than shoulder-width apart.","Hang with your arms fully extended and your body straight.","Pull your chest towards the bar or surface by squeezing your shoulder blades together and bending your elbows.","Continue pulling until your chin is above the bar or surface.","Lower yourself back down to the starting position with control.","Repeat for the desired number of repetitions."],"img":"3019-mExgrF9.jpg","gif":"3019-mExgrF9.gif"},{"id":"3639","n":"bent knee lying twist (male)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"obliques","sm":["obliques","hip flexors"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms out to the sides, perpendicular to your body.","Keeping your knees together, slowly lower them to one side, aiming to touch the ground with your knees.","Pause for a moment, then engage your core and slowly lift your knees back to the starting position.","Repeat the movement to the other side.","Continue alternating sides for the desired number of repetitions."],"img":"3639-6sYyrRX.jpg","gif":"3639-6sYyrRX.gif"},{"id":"1770","n":"biceps leg concentration curl","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a bench with your legs spread apart and your feet flat on the ground.","Hold a dumbbell in one hand and place your elbow on the inside of your thigh, just above the knee.","With your palm facing up, curl the dumbbell towards your shoulder while keeping your upper arm stationary.","Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1770-sJFIDIp.jpg","gif":"1770-sJFIDIp.gif"},{"id":"0139","n":"biceps narrow pull-ups","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.","Engage your core and pull yourself up towards the bar, focusing on using your biceps to lift your body.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0139-50BETrz.jpg","gif":"0139-50BETrz.gif"},{"id":"0140","n":"biceps pull-up","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Hang from a pull-up bar with your palms facing away from you and your hands shoulder-width apart.","Engage your core and pull yourself up by bending your elbows, bringing your chest towards the bar.","Pause at the top of the movement, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0140-guT8YnS.jpg","gif":"0140-guT8YnS.gif"},{"id":"0137","n":"body-up","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Start by placing your hands on a raised surface, such as a bench or parallel bars, with your palms facing down and fingers pointing forward.","Extend your legs out in front of you, keeping your heels on the ground and your body straight.","Lower your body by bending your elbows, keeping them close to your sides, until your upper arms are parallel to the ground.","Pause for a moment, then push through your palms to straighten your arms and lift your body back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0137-U6G2gk9.jpg","gif":"0137-U6G2gk9.gif"},{"id":"3543","n":"bodyweight drop jump squat","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and pushing your hips back.","Jump up explosively, extending your hips, knees, and ankles.","While in mid-air, quickly bring your feet together.","Land softly on the balls of your feet and immediately drop back into a squat position.","Repeat for the desired number of repetitions."],"img":"3543-wfotm7S.jpg","gif":"3543-wfotm7S.gif","ty":"atl"},{"id":"3544","n":"bodyweight incline side plank","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","shoulders"],"st":["Start by lying on your side with your legs extended and stacked on top of each other.","Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","Hold this position for the desired amount of time.","Lower your hips back down to the ground and repeat on the other side."],"img":"3544-5VXmnV5.jpg","gif":"3544-5VXmnV5.gif","ty":"rin","kind":"time"},{"id":"1771","n":"bodyweight kneeling triceps extension","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders","chest"],"st":["Kneel down on the ground with your knees hip-width apart.","Place your hands on the ground in front of you, shoulder-width apart, fingers pointing forward.","Extend your legs straight behind you, balancing on your toes and hands, forming a straight line from head to heels.","Bend your elbows and lower your upper body towards the ground, keeping your elbows close to your sides.","Pause for a moment at the bottom, then push through your hands to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."],"img":"1771-s0HKO2I.jpg","gif":"1771-s0HKO2I.gif"},{"id":"1769","n":"bodyweight side lying biceps curl","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Lie on your side with your legs extended and your head supported by your arm.","Hold your upper arm against your side and bend your elbow to curl your forearm towards your shoulder.","Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1769-gscGLOU.jpg","gif":"1769-gscGLOU.gif"},{"id":"3168","n":"bodyweight squatting row","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Stand with your feet shoulder-width apart, holding onto a sturdy object or suspension trainer with your arms extended.","Lower your body into a squat position, keeping your back straight and your knees behind your toes.","From the squat position, pull your body up towards the object or suspension trainer, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"3168-3xK09Sk.jpg","gif":"3168-3xK09Sk.gif"},{"id":"3167","n":"bodyweight squatting row (with towel)","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Stand with your feet shoulder-width apart, holding a towel in front of you with your palms facing down.","Bend your knees and lower your body into a squat position, keeping your back straight and your chest up.","As you lower into the squat, simultaneously pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the squat, then slowly return to the starting position while extending your arms.","Repeat for the desired number of repetitions."],"img":"3167-BReCuOn.jpg","gif":"3167-BReCuOn.gif"},{"id":"1373","n":"bodyweight standing calf raise","bp":"lower legs","eq":"body weight","tg":"calves","mg":"ankles","sm":["ankles","feet"],"st":["Stand with your feet shoulder-width apart, toes pointing forward.","Place your hands on a wall or stable surface for balance.","Slowly raise your heels off the ground, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1373-bJYHBIN.jpg","gif":"1373-bJYHBIN.gif"},{"id":"3156","n":"bodyweight standing close-grip one arm row","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand with a neutral grip.","Bend forward at the hips, keeping your back straight and your core engaged.","Pull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"3156-v2DfH14.jpg","gif":"3156-v2DfH14.gif"},{"id":"3158","n":"bodyweight standing close-grip row","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Stand with your feet shoulder-width apart and knees slightly bent.","Bend forward at the waist, keeping your back straight and your core engaged.","Extend your arms straight in front of you, gripping the bar or handles with a close grip.","Pull the bar or handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release and return to the starting position.","Repeat for the desired number of repetitions."],"img":"3158-tig3PXb.jpg","gif":"3158-tig3PXb.gif"},{"id":"3162","n":"bodyweight standing one arm row","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand.","Bend forward at the hips, keeping your back straight and your core engaged.","Let the dumbbell hang straight down in front of you, with your arm fully extended.","Pull the dumbbell up towards your chest, keeping your elbow close to your body.","Squeeze your shoulder blades together at the top of the movement.","Lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"3162-xbkPfaw.jpg","gif":"3162-xbkPfaw.gif"},{"id":"3161","n":"bodyweight standing one arm row (with towel)","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand.","Bend forward at the hips, keeping your back straight and your core engaged.","Pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the towel back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"img":"3161-O4oIqQD.jpg","gif":"3161-O4oIqQD.gif"},{"id":"3166","n":"bodyweight standing row","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Stand with your feet shoulder-width apart and knees slightly bent.","Grasp a bar or handles with an overhand grip, palms facing down.","Keep your back straight and core engaged.","Pull the bar or handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the top of the movement.","Slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"img":"3166-wd4ds3s.jpg","gif":"3166-wd4ds3s.gif"},{"id":"3165","n":"bodyweight standing row (with towel)","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Stand with your feet shoulder-width apart and hold a towel in front of you with both hands.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"img":"3165-uTv34oq.jpg","gif":"3165-uTv34oq.gif"},{"id":"0138","n":"bottoms-up","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Lie flat on your back with your legs extended and your arms by your sides.","Bend your knees and bring them towards your chest, keeping your feet off the ground.","Engaging your abs, lift your hips off the ground, bringing your knees towards your head.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0138-CI6baTY.jpg","gif":"0138-CI6baTY.gif"},{"id":"1374","n":"box jump down with one leg stabilization","bp":"lower legs","eq":"body weight","tg":"calves","mg":"quadriceps","sm":["quadriceps","hamstrings","glutes"],"st":["Stand in front of a box or platform with your feet shoulder-width apart.","Bend your knees and jump onto the box, landing softly with one foot on the box and the other foot hanging off the edge.","Stabilize yourself on the box with the foot that is on it, while keeping the other foot off the ground.","Hold this position for a few seconds, engaging your calf muscles to maintain balance.","Slowly step down with the foot that is on the box, returning to the starting position.","Repeat the exercise with the other leg."],"img":"1374-iPm26QU.jpg","gif":"1374-iPm26QU.gif","ty":"atl"},{"id":"2466","n":"bridge - mountain climber (cross body)","bp":"waist","eq":"body weight","tg":"abs","mg":"glutes","sm":["glutes","quadriceps","hamstrings","shoulders","triceps"],"st":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Engage your core and lift your right foot off the ground, bringing your right knee towards your left elbow.","Return your right foot to the starting position and repeat the movement with your left foot towards your right elbow.","Continue alternating sides, moving at a controlled pace.","Keep your hips level and avoid lifting your hips too high or sagging them too low.","Maintain a steady breathing pattern throughout the exercise.","Repeat for the desired number of repetitions."],"img":"2466-9c6T1YX.jpg","gif":"2466-9c6T1YX.gif","ty":"rin"},{"id":"1160","n":"burpee","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","shoulders","chest"],"st":["Start in a standing position with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and placing your hands on the floor in front of you.","Kick your feet back into a push-up position.","Perform a push-up, keeping your body in a straight line.","Jump your feet back into the squat position.","Jump up explosively, reaching your arms overhead.","Land softly and immediately lower back into a squat position to begin the next repetition."],"img":"1160-dK9394r.jpg","gif":"1160-dK9394r.gif","ty":"atl"},{"id":"0870","n":"butt-ups","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands by your sides, palms facing down.","Engaging your abs, lift your legs off the ground, bringing your knees towards your chest.","At the top of the movement, squeeze your abs and pause for a moment.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0870-qcNN2FN.jpg","gif":"0870-qcNN2FN.gif"},{"id":"1494","n":"butterfly yoga pose","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"hamstrings","sm":["hamstrings","groin"],"st":["Sit on the floor with your legs extended in front of you.","Bend your knees and bring the soles of your feet together, allowing your knees to fall out to the sides.","Hold onto your ankles or feet with your hands.","Sit up tall and lengthen your spine.","Gently press your knees down towards the floor, feeling a stretch in your inner thighs.","Hold this position for a few breaths.","To release, slowly bring your knees back up and extend your legs."],"img":"1494-bWlZvXh.jpg","gif":"1494-bWlZvXh.gif"},{"id":"0148","n":"cable alternate shoulder press","bp":"shoulders","eq":"cable","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Stand with your feet shoulder-width apart and grasp the handles of the cable machine with an overhand grip.","Position your hands at shoulder height, with your palms facing forward.","Keep your core engaged and your back straight.","Press one handle up and forward until your arm is fully extended.","Pause for a moment at the top, then slowly lower the handle back to the starting position.","Repeat with the other arm.","Alternate between arms for the desired number of repetitions."],"img":"0148-KHPZL0b.jpg","gif":"0148-KHPZL0b.gif"},{"id":"0149","n":"cable alternate triceps extension","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Stand facing the cable machine with your feet shoulder-width apart.","Hold the cable handle with your right hand and bring your arm up so that your upper arm is parallel to the ground and your elbow is bent at a 90-degree angle.","Keep your upper arm stationary and extend your forearm backward, fully straightening your arm.","Pause for a moment, then slowly return to the starting position.","Repeat with your left arm.","Continue alternating arms for the desired number of repetitions."],"img":"0149-Gchi5Tr.jpg","gif":"0149-Gchi5Tr.gif"},{"id":"3235","n":"cable assisted inverse leg curl","bp":"upper legs","eq":"cable","tg":"hamstrings","mg":"glutes","sm":["glutes","calves"],"st":["Adjust the cable machine so that the ankle attachment is at the lowest setting.","Lie face down on the bench with your legs straight and the ankle attachment secured to your ankles.","Hold onto the handles of the bench for stability.","Keeping your upper body stationary, exhale and curl your legs up towards your glutes by flexing your knees.","Pause for a moment at the top of the movement, squeezing your hamstrings.","Inhale and slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."],"img":"3235-zHEpuuc.jpg","gif":"3235-zHEpuuc.gif"},{"id":"0150","n":"cable bar lateral pulldown","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Adjust the cable pulley to a high position and attach a straight bar.","Sit facing the cable machine with your feet flat on the ground and your knees slightly bent.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Lean back slightly and keep your chest up, maintaining a slight arch in your lower back.","Pull the bar down towards your chest, leading with your elbows and squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."],"img":"0150-eYnzaCm.jpg","gif":"0150-eYnzaCm.gif"},{"id":"0151","n":"cable bench press","bp":"chest","eq":"cable","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Adjust the cable machine to chest height and attach the handles.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip and step forward to create tension in the cables.","Position your feet firmly on the ground and engage your core.","Bend your elbows and bring your hands to shoulder level, keeping your elbows at a 90-degree angle.","Push the handles forward, extending your arms fully in front of you.","Pause for a moment, then slowly reverse the movement, bringing your hands back to shoulder level.","Repeat for the desired number of repetitions."],"img":"0151-7xI5MXA.jpg","gif":"0151-7xI5MXA.gif"},{"id":"1630","n":"cable close grip curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Attach a straight bar to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Exhale and curl the bar up towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the bar back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"1630-BCGQ6J5.jpg","gif":"1630-BCGQ6J5.gif"},{"id":"1631","n":"cable concentration curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a bench or chair with your feet flat on the floor and your knees slightly bent.","Hold the cable handle with an underhand grip and rest your elbow against the inside of your thigh.","Keeping your upper arm stationary, exhale and curl the cable handle towards your shoulder while contracting your biceps.","Pause for a moment at the top of the movement, then inhale and slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1631-NvfE43H.jpg","gif":"1631-NvfE43H.gif"},{"id":"0152","n":"cable concentration extension (on knee)","bp":"upper arms","eq":"cable","tg":"triceps","mg":"forearms","sm":["forearms"],"st":["Sit on a bench or chair with your knees bent and feet flat on the ground.","Hold the cable handle with your right hand and place your elbow on the inside of your right knee.","Extend your arm fully, keeping your elbow stationary and close to your knee.","Pause for a moment at the top, then slowly lower your arm back to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"0152-Db7eEgw.jpg","gif":"0152-Db7eEgw.gif"},{"id":"0153","n":"cable cross-over lateral pulldown","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Attach a cable handle to each side of a cable machine at shoulder height.","Stand in the middle of the machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip and step back to create tension in the cables.","Lean forward slightly from the hips, keeping your back straight and your chest up.","Pull the handles down and across your body, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"0153-OQ1otBN.jpg","gif":"0153-OQ1otBN.gif"},{"id":"0154","n":"cable cross-over revers fly","bp":"shoulders","eq":"cable","tg":"delts","mg":"rhomboids","sm":["rhomboids","trapezius"],"st":["Attach a D-handle to each low pulley cable and stand in the middle of the cable crossover machine.","Grasp the handles with a pronated grip (palms facing down) and take a step forward, positioning your feet shoulder-width apart.","Bend your knees slightly and lean forward at the waist, keeping your back straight and your abs engaged.","With your arms extended out to the sides and slightly bent at the elbows, exhale and squeeze your shoulder blades together as you pull the cables back and upward in a reverse fly motion.","Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"0154-aqvSOQE.jpg","gif":"0154-aqvSOQE.gif"},{"id":"0155","n":"cable cross-over variation","bp":"chest","eq":"cable","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Adjust the cable pulleys to chest height.","Stand in the center of the cable machine with one foot in front of the other.","Grasp the handles with your palms facing down and your arms extended out to the sides.","Take a step forward, keeping your arms slightly bent.","With a slight bend in your elbows, bring your hands together in front of your chest.","Pause for a moment, then slowly return your arms back to the starting position.","Repeat for the desired number of repetitions."],"img":"0155-0CXGHya.jpg","gif":"0155-0CXGHya.gif"},{"id":"0868","n":"cable curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable attachment with an underhand grip, palms facing up.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and curl the cable attachment towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable attachment back to the starting position.","Repeat for the desired number of repetitions."],"img":"0868-G08RZcQ.jpg","gif":"0868-G08RZcQ.gif"},{"id":"0157","n":"cable deadlift","bp":"upper legs","eq":"cable","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","lower back"],"st":["Stand facing the cable machine with your feet shoulder-width apart.","Bend at the hips and knees, lowering your torso until your back is parallel to the ground.","Grasp the cable handles with an overhand grip, keeping your arms straight and your shoulders back.","Engage your glutes and hamstrings to lift the cable handles, extending your hips and standing up straight.","Pause for a moment at the top, then slowly lower the cable handles back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0157-eGDudUV.jpg","gif":"0157-eGDudUV.gif"},{"id":"0158","n":"cable decline fly","bp":"chest","eq":"cable","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Adjust the cable machine to a decline position.","Stand facing away from the machine with your feet shoulder-width apart.","Hold the handles with your palms facing forward and your arms extended straight out in front of you.","Keeping a slight bend in your elbows, open your arms out to the sides in a controlled motion.","Pause for a moment at the fully extended position, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"0158-7saC5zz.jpg","gif":"0158-7saC5zz.gif"},{"id":"1260","n":"cable decline one arm press","bp":"chest","eq":"cable","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Adjust the cable machine to a decline position.","Stand facing away from the machine and grab the handle with one hand.","Position yourself with your back against the decline bench and your arm extended straight in front of you.","Bend your elbow and lower the handle towards your chest while keeping your upper arm stationary.","Pause for a moment at the bottom, then push the handle back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1260-KHGNa16.jpg","gif":"1260-KHGNa16.gif"},{"id":"1261","n":"cable decline press","bp":"chest","eq":"cable","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Adjust the cable machine to a decline position.","Sit on the decline bench facing the cable machine.","Grasp the handles with an overhand grip and position them at chest level.","Keep your feet flat on the ground and your back firmly against the bench.","Exhale and push the handles away from your body, extending your arms fully.","Pause for a moment at the end of the movement, squeezing your chest muscles.","Inhale and slowly return the handles back to the starting position.","Repeat for the desired number of repetitions."],"img":"1261-2Pya1cP.jpg","gif":"1261-2Pya1cP.gif"},{"id":"0159","n":"cable decline seated wide-grip row","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Sit on the decline bench facing the cable machine with your feet securely placed on the footrests.","Grasp the cable attachment with a wide overhand grip, palms facing down.","Lean back slightly, keeping your back straight and your core engaged.","Pull the cable towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the peak of the contraction, then slowly release the cable back to the starting position.","Repeat for the desired number of repetitions."],"img":"0159-kesXOpB.jpg","gif":"0159-kesXOpB.gif"},{"id":"1632","n":"cable drag curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand facing a cable machine with your feet shoulder-width apart.","Grasp the cable attachment with an underhand grip, palms facing up, and arms fully extended.","Keeping your upper arms stationary, exhale and curl the cable attachment towards your shoulders by contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"1632-dXz8zjF.jpg","gif":"1632-dXz8zjF.gif"},{"id":"0160","n":"cable floor seated wide-grip row","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Sit on the floor with your legs extended and your back straight.","Attach a cable handle to a low pulley and position the cable machine behind you.","Grasp the handle with a wide overhand grip, palms facing down.","Lean back slightly, keeping your back straight and your chest lifted.","Pull the handle towards your waist, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the handle back to the starting position.","Repeat for the desired number of repetitions."],"img":"0160-veXwo0D.jpg","gif":"0160-veXwo0D.gif"},{"id":"0161","n":"cable forward raise","bp":"shoulders","eq":"cable","tg":"delts","mg":"triceps","sm":["triceps","forearms"],"st":["Stand with your feet shoulder-width apart and your knees slightly bent.","Hold the cable handle with an overhand grip, palms facing down, and your arms fully extended in front of you.","Keeping your arms straight, raise the cable handle up to shoulder level.","Pause for a moment at the top, then slowly lower the cable handle back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0161-hvHhCv8.jpg","gif":"0161-hvHhCv8.gif"},{"id":"0162","n":"cable front raise","bp":"shoulders","eq":"cable","tg":"delts","mg":"triceps","sm":["triceps","forearms"],"st":["Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip.","Keep your back straight and your core engaged.","Raise the cable handle in front of you, keeping your arms straight and your palms facing down.","Continue lifting until your arms are parallel to the floor.","Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions."],"img":"0162-u2X71Np.jpg","gif":"0162-u2X71Np.gif"},{"id":"0164","n":"cable front shoulder raise","bp":"shoulders","eq":"cable","tg":"delts","mg":"trapezius","sm":["trapezius","biceps"],"st":["Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip.","Keep your back straight and your core engaged.","Raise the cable handle in front of you, keeping your arms straight and your palms facing down.","Continue lifting until your arms are parallel to the floor.","Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions."],"img":"0164-mTT3KLn.jpg","gif":"0164-mTT3KLn.gif"},{"id":"0165","n":"cable hammer curl (with rope)","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand upright with your feet shoulder-width apart and a slight bend in your knees.","Hold the cable rope attachment with an underhand grip, palms facing each other, and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the cable rope attachment until your biceps are fully contracted and the rope is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the cable rope attachment back to the starting position.","Repeat for the desired number of repetitions."],"img":"0165-HPlPoQA.jpg","gif":"0165-HPlPoQA.gif"},{"id":"1722","n":"cable high pulley overhead tricep extension","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Attach a rope to a high pulley and stand facing away from the machine.","Grasp the rope with both hands and extend your arms overhead.","Keep your elbows close to your head and your upper arms stationary.","Slowly lower the rope behind your head by bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"img":"1722-1xHyxys.jpg","gif":"1722-1xHyxys.gif"},{"id":"0167","n":"cable high row (kneeling)","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Attach a straight bar to a cable machine at chest height.","Kneel down in front of the cable machine and grab the bar with an overhand grip, hands shoulder-width apart.","Sit back on your heels, keeping your back straight and your core engaged.","Pull the bar towards your upper abdomen, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the bar back to the starting position.","Repeat for the desired number of repetitions."],"img":"0167-ZSJNetl.jpg","gif":"0167-ZSJNetl.gif"},{"id":"0168","n":"cable hip adduction","bp":"upper legs","eq":"cable","tg":"adductors","mg":"glutes","sm":["glutes","quadriceps"],"st":["Attach the ankle cuff to your ankle and stand facing the cable machine.","Position yourself far enough away from the machine so that there is tension on the cable.","Place your hands on the machine for support.","Keeping your leg straight, slowly move your leg across your body towards the midline.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"0168-hBGWILP.jpg","gif":"0168-hBGWILP.gif"},{"id":"0169","n":"cable incline bench press","bp":"chest","eq":"cable","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Adjust the bench to a 45-degree incline.","Attach the cable handles to the high pulleys.","Sit on the bench facing the cable machine with your feet flat on the ground.","Grasp the handles with an overhand grip and bring them to shoulder height.","Push the handles forward and upward until your arms are fully extended.","Pause for a moment, then slowly lower the handles back to the starting position.","Repeat for the desired number of repetitions."],"img":"0169-Vh0GsK4.jpg","gif":"0169-Vh0GsK4.gif"},{"id":"1318","n":"cable incline bench row","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","rear deltoids"],"st":["Set up an incline bench at a 45-degree angle and attach a cable handle to the low pulley.","Sit on the bench facing the cable machine with your feet flat on the floor and your knees slightly bent.","Grasp the cable handle with an overhand grip and extend your arms fully in front of you.","Lean forward from your hips while keeping your back straight and your core engaged.","Pull the cable handle towards your chest by retracting your shoulder blades and bending your elbows.","Squeeze your back muscles at the top of the movement, then slowly extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"img":"1318-yaMIo4D.jpg","gif":"1318-yaMIo4D.gif"},{"id":"0171","n":"cable incline fly","bp":"chest","eq":"cable","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Adjust the cable machine to a low position and attach the handles.","Sit on an incline bench with your back against the pad and feet flat on the floor.","Grasp the handles with an overhand grip and extend your arms straight out in front of you.","Keeping a slight bend in your elbows, open your arms out to the sides in a controlled motion.","Pause for a moment at the fully extended position, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"0171-tBWXbIT.jpg","gif":"0171-tBWXbIT.gif"},{"id":"0170","n":"cable incline fly (on stability ball)","bp":"chest","eq":"cable","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Set up a stability ball at an incline angle.","Attach the cable handles to the high pulleys of a cable machine.","Sit on the stability ball facing away from the machine, with your feet firmly planted on the ground.","Grasp the cable handles with an overhand grip, palms facing forward.","Lean forward slightly, keeping your back straight and core engaged.","With a controlled motion, bring your arms out to the sides, keeping a slight bend in your elbows.","Continue the motion until your arms are parallel to the ground.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"0170-27NNGFr.jpg","gif":"0170-27NNGFr.gif"},{"id":"0172","n":"cable incline pushdown","bp":"back","eq":"cable","tg":"lats","mg":"triceps","sm":["triceps","shoulders"],"st":["Attach a straight bar to a high pulley cable machine.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Lean forward slightly and keep your back straight.","Pull the bar down towards your thighs by extending your elbows.","Pause for a moment at the bottom, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."],"img":"0172-1PK5Uo3.jpg","gif":"0172-1PK5Uo3.gif"},{"id":"0173","n":"cable incline triceps extension","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Adjust the cable machine to a low pulley position.","Attach a straight bar to the cable.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip and extend your arms straight overhead.","Lean forward slightly, keeping your back straight and core engaged.","Bend your elbows and lower the bar behind your head, keeping your upper arms close to your ears.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"img":"0173-Hx1WC8I.jpg","gif":"0173-Hx1WC8I.gif"},{"id":"0174","n":"cable judo flip","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques","shoulders"],"st":["Stand facing the cable machine with your feet shoulder-width apart.","Hold the cable handle with both hands at chest level, palms facing down.","Engage your core and rotate your torso to the right, pulling the cable across your body.","As you rotate, pivot your back foot and allow your hips to rotate naturally.","Extend your arms fully and finish the movement by flipping the cable handle over your shoulder.","Return to the starting position by reversing the movement, rotating your torso back to the center.","Repeat the movement on the opposite side.","Continue alternating sides for the desired number of repetitions."],"img":"0174-MvQPqVW.jpg","gif":"0174-MvQPqVW.gif"},{"id":"0860","n":"cable kickback","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Stand facing a cable machine with your feet shoulder-width apart.","Hold the cable handle with your right hand and step back to create tension in the cable.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Keep your upper arm close to your body and your elbow bent at a 90-degree angle.","Extend your forearm backward, straightening your arm fully.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"0860-HEJ6DIX.jpg","gif":"0860-HEJ6DIX.gif"},{"id":"0175","n":"cable kneeling crunch","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Attach a rope handle to a high pulley and kneel down facing away from the machine.","Hold the rope handle with both hands and place it behind your head, keeping your elbows out to the sides.","Keeping your hips stationary, flex your waist and crunch your torso down towards your thighs.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"0175-WW95auq.jpg","gif":"0175-WW95auq.gif"},{"id":"3697","n":"cable kneeling rear delt row (with rope) (male)","bp":"shoulders","eq":"cable","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids","biceps"],"st":["Attach a rope handle to a low cable pulley and kneel down facing the machine.","Grasp the rope with a neutral grip (palms facing each other) and extend your arms fully in front of you.","Keeping your back straight and core engaged, pull the rope towards your body by retracting your shoulder blades.","Squeeze your shoulder blades together at the end of the movement and hold for a brief pause.","Slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"img":"3697-G61cXLk.jpg","gif":"3697-G61cXLk.gif"},{"id":"0176","n":"cable kneeling triceps extension","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Attach a rope handle to a high pulley and kneel down facing the cable machine.","Grasp the rope with a neutral grip (palms facing each other) and bring your hands to the sides of your head.","Keep your elbows close to your head and your upper arms stationary throughout the exercise.","Extend your forearms by contracting your triceps until your arms are fully extended.","Pause for a moment, then slowly return to the starting position by bending your elbows.","Repeat for the desired number of repetitions."],"img":"0176-KWdF2JI.jpg","gif":"0176-KWdF2JI.gif"},{"id":"2330","n":"cable lat pulldown full range of motion","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Sit on the lat pulldown machine with your knees positioned under the pads.","Grasp the cable bar with an overhand grip, slightly wider than shoulder-width apart.","Lean back slightly and keep your chest up, maintaining a slight arch in your lower back.","Pull the bar down towards your upper chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back to the starting position.","Repeat for the desired number of repetitions."],"img":"2330-LEprlgG.jpg","gif":"2330-LEprlgG.gif"},{"id":"0177","n":"cable lateral pulldown (with rope attachment)","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Attach a rope attachment to the cable machine at a high position.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope with an overhand grip, palms facing each other.","Keep your back straight and lean slightly back.","Pull the rope down towards your sides, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement.","Slowly release the tension and allow the rope to return to the starting position.","Repeat for the desired number of repetitions."],"img":"0177-CuaWCmC.jpg","gif":"0177-CuaWCmC.gif"},{"id":"2616","n":"cable lateral pulldown with v-bar","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Sit down on the cable pulldown machine and grab the v-bar attachment with an overhand grip.","Adjust the knee pad so that your thighs are secured under it.","Keep your back straight and lean back slightly.","Pull the v-bar down towards your upper chest while keeping your elbows close to your body.","Squeeze your back muscles at the bottom of the movement.","Slowly return the v-bar to the starting position and repeat for the desired number of repetitions."],"img":"2616-4c9BhzB.jpg","gif":"2616-4c9BhzB.gif"},{"id":"0178","n":"cable lateral raise","bp":"shoulders","eq":"cable","tg":"delts","mg":"traps","sm":["traps","triceps"],"st":["Stand with your feet shoulder-width apart and grasp the cable handles with an overhand grip.","Keep your arms straight and your core engaged.","Raise your arms out to the sides until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0178-goJ6ezq.jpg","gif":"0178-goJ6ezq.gif"},{"id":"0179","n":"cable low fly","bp":"chest","eq":"cable","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Attach the handles to the low pulleys of a cable machine and select an appropriate weight.","Stand in the middle of the machine with your feet shoulder-width apart and a slight bend in your knees.","Grasp the handles with an overhand grip and extend your arms out to the sides, keeping a slight bend in your elbows.","Maintaining control, slowly bring your arms forward in a sweeping motion, crossing them in front of your body.","Pause for a moment at the peak of the movement, feeling the stretch in your chest muscles.","Reverse the motion and slowly return your arms to the starting position, keeping tension on your chest muscles throughout.","Repeat for the desired number of repetitions."],"img":"0179-FVmZVhk.jpg","gif":"0179-FVmZVhk.gif"},{"id":"0180","n":"cable low seated row","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Sit on the machine with your feet flat on the footrests and your knees slightly bent.","Grasp the handles with an overhand grip, palms facing down.","Keep your back straight and lean slightly forward, maintaining a slight bend in your elbows.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."],"img":"0180-hvV79Si.jpg","gif":"0180-hvV79Si.gif"},{"id":"1634","n":"cable lying bicep curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Attach a straight bar to a low pulley cable machine.","Lie face up on a flat bench with your feet flat on the ground.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Extend your arms fully, keeping your elbows close to your sides.","Keeping your upper arms stationary, exhale and curl the bar up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the bar back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"1634-otqIxU4.jpg","gif":"1634-otqIxU4.gif"},{"id":"0182","n":"cable lying close-grip curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Attach a straight bar to a low pulley cable machine.","Lie face up on a flat bench with your feet flat on the ground.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Extend your arms fully, keeping your elbows close to your sides.","Keeping your upper arms stationary, curl the bar towards your chest by contracting your biceps.","Pause for a moment at the top, squeezing your biceps.","Slowly lower the bar back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"0182-61GrD55.jpg","gif":"0182-61GrD55.gif"},{"id":"0184","n":"cable lying extension pullover (with rope attachment)","bp":"back","eq":"cable","tg":"lats","mg":"triceps","sm":["triceps","shoulders"],"st":["Attach a rope to a cable machine and set the pulley at the highest position.","Lie down on a bench with your head towards the cable machine.","Hold the rope with both hands and extend your arms straight up above your chest.","Keeping your arms straight, slowly lower the rope behind your head while maintaining control.","Pause for a moment at the bottom, then slowly raise the rope back to the starting position.","Repeat for the desired number of repetitions."],"img":"0184-Q2Eu1Ax.jpg","gif":"0184-Q2Eu1Ax.gif"},{"id":"0185","n":"cable lying fly","bp":"chest","eq":"cable","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Attach the handles to the cables and lie flat on a bench with your feet flat on the ground.","Hold the handles with your palms facing each other and your arms extended straight above your chest.","Keeping a slight bend in your elbows, lower your arms out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring your arms back to the starting position.","Repeat for the desired number of repetitions."],"img":"0185-lJJ7Yq8.jpg","gif":"0185-lJJ7Yq8.gif"},{"id":"0186","n":"cable lying triceps extension v. 2","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Attach a rope handle to a low pulley cable machine.","Lie down on a flat bench facing up, with your head towards the cable machine.","Grasp the rope handle with both hands, palms facing each other, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the rope handle towards your forehead by bending your elbows.","Pause for a moment at the bottom, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0186-uxJcFUU.jpg","gif":"0186-uxJcFUU.gif"},{"id":"0188","n":"cable middle fly","bp":"chest","eq":"cable","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Attach cables to both sides of a cable machine at chest height.","Stand in the center of the machine with one foot slightly in front of the other.","Grasp the handles with an overhand grip and extend your arms out to the sides.","Keep a slight bend in your elbows and maintain a slight forward lean.","Engage your chest muscles and bring your arms forward in a sweeping motion.","Pause for a moment at the center, then slowly return your arms back to the starting position.","Repeat for the desired number of repetitions."],"img":"0188-xLYSdtg.jpg","gif":"0188-xLYSdtg.gif"},{"id":"0189","n":"cable one arm bent over row","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Stand facing a cable machine with your feet shoulder-width apart.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Grasp the cable handle with one hand, palm facing inward, and extend your arm fully.","Pull the cable handle towards your body, keeping your elbow close to your side, until your hand reaches your lower chest.","Pause for a moment, then slowly extend your arm back to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"0189-EIsE3u8.jpg","gif":"0189-EIsE3u8.gif"},{"id":"0190","n":"cable one arm curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip, palm facing up.","Keep your elbow close to your side and slowly curl your forearm up towards your shoulder.","Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0190-YTur5nR.jpg","gif":"0190-YTur5nR.gif"},{"id":"1262","n":"cable one arm decline chest fly","bp":"chest","eq":"cable","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Attach a D-handle to a low pulley cable machine and set the bench to a decline angle.","Lie down on the bench with your head towards the machine and grab the handle with your right hand.","Extend your arm straight up above your chest, keeping a slight bend in your elbow.","With a controlled motion, lower your arm out to the side until your hand is in line with your shoulder.","Pause for a moment, then reverse the motion and bring your arm back to the starting position.","Repeat for the desired number of repetitions, then switch to your left arm and repeat the exercise."],"img":"1262-w4dLzSx.jpg","gif":"1262-w4dLzSx.gif"},{"id":"1263","n":"cable one arm fly on exercise ball","bp":"chest","eq":"cable","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a cable handle in one hand and extend your arm out to the side, parallel to the ground.","Keep your elbow slightly bent and your palm facing forward.","Slowly bring your arm across your body, squeezing your chest muscles.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"1263-hHy8tQG.jpg","gif":"1263-hHy8tQG.gif"},{"id":"1264","n":"cable one arm incline fly on exercise ball","bp":"chest","eq":"cable","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Sit on an exercise ball with your feet flat on the ground and your back against an incline bench.","Hold a cable handle in one hand with your arm extended and palm facing inward.","Keeping a slight bend in your elbow, slowly lower your arm out to the side until your hand is in line with your shoulder.","Pause for a moment, then squeeze your chest muscles to bring your arm back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1264-P14Dz9D.jpg","gif":"1264-P14Dz9D.gif"},{"id":"1265","n":"cable one arm incline press","bp":"chest","eq":"cable","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Adjust the cable machine to a low pulley position.","Sit on an incline bench facing away from the cable machine.","Grasp the handle with one hand and bring it up to shoulder height.","Position your feet firmly on the ground and maintain a stable position.","Press the handle forward and upward, extending your arm fully.","Pause for a moment at the top, then slowly lower the handle back to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"1265-GKEH6jj.jpg","gif":"1265-GKEH6jj.gif"},{"id":"1266","n":"cable one arm incline press on exercise ball","bp":"chest","eq":"cable","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Sit on an exercise ball with your feet flat on the ground and your back resting against an incline bench.","Hold a cable handle in one hand and position your arm at a 90-degree angle with your elbow bent.","Press the cable handle forward and upward, extending your arm fully.","Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"img":"1266-6t00BsF.jpg","gif":"1266-6t00BsF.gif"},{"id":"0191","n":"cable one arm lateral bent-over","bp":"chest","eq":"cable","tg":"pectorals","mg":"deltoids","sm":["deltoids","trapezius"],"st":["Stand with your feet shoulder-width apart, facing a cable machine.","Grasp the handle with one hand and step back to create tension on the cable.","Bend forward at the waist, keeping your back straight and your core engaged.","Extend your arm out to the side, parallel to the ground, with a slight bend in your elbow.","Slowly bring your arm back to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions, then switch sides."],"img":"0191-dB07vDu.jpg","gif":"0191-dB07vDu.gif"},{"id":"0192","n":"cable one arm lateral raise","bp":"shoulders","eq":"cable","tg":"delts","mg":"traps","sm":["traps","triceps"],"st":["Stand with your feet shoulder-width apart, facing the cable machine.","Hold the cable handle with one hand, palm facing down, and stand far enough away from the machine so that there is tension on the cable.","Keep your arm straight and slowly raise it out to the side until it is parallel to the ground.","Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"0192-wEulIzp.jpg","gif":"0192-wEulIzp.gif"},{"id":"1633","n":"cable one arm preacher curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Adjust the cable machine so that the preacher curl pad is at chest height.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip and position your upper arm against the preacher curl pad.","Keep your back straight and your core engaged.","Slowly curl the cable handle towards your shoulder, keeping your upper arm against the pad.","Pause for a moment at the top of the movement, squeezing your biceps.","Slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions.","Switch arms and repeat the exercise."],"img":"1633-eHBlPsa.jpg","gif":"1633-eHBlPsa.gif"},{"id":"1267","n":"cable one arm press on exercise ball","bp":"chest","eq":"cable","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a cable handle in one hand and position your arm at chest height, elbow bent.","Place your other hand on your hip for stability.","Press the cable handle forward, extending your arm fully.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1267-MKIelrR.jpg","gif":"1267-MKIelrR.gif"},{"id":"3563","n":"cable one arm pulldown","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Attach a single handle to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the handle with an overhand grip and extend your arm fully.","Keep your back straight and your core engaged.","Pull the handle down towards your side while keeping your elbow close to your body.","Pause for a moment at the bottom of the movement, squeezing your lat muscle.","Slowly release the handle back to the starting position.","Repeat for the desired number of repetitions.","Switch sides and repeat the exercise with the other arm."],"img":"3563-U5INZY6.jpg","gif":"3563-U5INZY6.gif"},{"id":"1635","n":"cable one arm reverse preacher curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Adjust the cable machine so that the pulley is at the lowest position.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip and position your upper arm against the preacher bench pad.","Keep your back straight and your core engaged throughout the exercise.","Slowly curl your forearm towards your bicep, keeping your upper arm stationary against the pad.","Pause for a moment at the top of the movement, squeezing your bicep.","Slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions.","Switch arms and repeat the exercise."],"img":"1635-ZXnjcOQ.jpg","gif":"1635-ZXnjcOQ.gif"},{"id":"0193","n":"cable one arm straight back high row (kneeling)","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Attach a handle to a cable machine at waist height.","Kneel down facing the cable machine and grab the handle with one hand.","Keep your back straight and your core engaged.","Pull the handle towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement.","Slowly release the handle back to the starting position.","Repeat for the desired number of repetitions.","Switch sides and repeat the exercise with the other arm."],"img":"0193-WrYPP2g.jpg","gif":"0193-WrYPP2g.gif"},{"id":"1723","n":"cable one arm tricep pushdown","bp":"upper arms","eq":"cable","tg":"triceps","mg":"forearms","sm":["forearms"],"st":["Stand facing a cable machine with a straight bar attachment at chest height.","Grasp the bar with an overhand grip and step back to create tension in the cable.","Position your feet shoulder-width apart and slightly bend your knees.","Keep your back straight and core engaged throughout the exercise.","Start with your arm fully extended and perpendicular to the floor.","Keeping your upper arm stationary, exhale and push the bar down until your arm is fully extended.","Pause for a moment, then inhale and slowly return to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1723-qRZ5S1N.jpg","gif":"1723-qRZ5S1N.gif"},{"id":"1636","n":"cable overhead curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Attach a straight bar to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and curl the bar down towards your forehead, keeping your upper arms stationary.","Pause for a moment at the bottom of the movement, squeezing your biceps.","Inhale and slowly return the bar to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"1636-wDUqY2u.jpg","gif":"1636-wDUqY2u.gif"},{"id":"1637","n":"cable overhead curl on exercise ball","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Sit on an exercise ball and hold the cable handle with an underhand grip.","Extend your arms fully overhead, keeping your elbows close to your ears.","Slowly curl the cable down towards your forehead, keeping your upper arms stationary.","Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"1637-ioTf098.jpg","gif":"1637-ioTf098.gif"},{"id":"0194","n":"cable overhead triceps extension (rope attachment)","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Attach a rope to a cable machine at a high position.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the rope with both hands, palms facing each other, and bring your hands above your head.","Keep your upper arms close to your head and your elbows pointing forward.","Slowly lower the rope behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0194-2IxROQ1.jpg","gif":"0194-2IxROQ1.gif"},{"id":"1319","n":"cable palm rotational row","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Attach a handle to a cable machine at waist height.","Stand facing the machine with your feet shoulder-width apart.","Grasp the handle with an overhand grip, palms facing down.","Step back to create tension on the cable, keeping your back straight and knees slightly bent.","Pull the handle towards your body, rotating your palms to face upwards as you do so.","Squeeze your shoulder blades together at the end of the movement.","Slowly release the handle back to the starting position.","Repeat for the desired number of repetitions."],"img":"1319-OmQ8w0p.jpg","gif":"1319-OmQ8w0p.gif","ty":"mob"},{"id":"0195","n":"cable preacher curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Adjust the cable machine so that the preacher curl pad is at chest height.","Sit on the preacher curl bench and place your upper arms on the pad, gripping the cable attachment with an underhand grip.","Keep your back straight and your elbows tucked in at your sides.","Slowly curl the cable attachment up towards your shoulders, squeezing your biceps at the top of the movement.","Pause for a moment, then slowly lower the cable attachment back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0195-P2lNrGL.jpg","gif":"0195-P2lNrGL.gif"},{"id":"1268","n":"cable press on exercise ball","bp":"chest","eq":"cable","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Sit on an exercise ball with your feet flat on the ground and your knees at a 90-degree angle.","Hold the cable handles at chest height with your palms facing down and your elbows bent.","Engage your core and press the cable handles forward until your arms are fully extended.","Pause for a moment, then slowly release the tension and bring the cable handles back to the starting position.","Repeat for the desired number of repetitions."],"img":"1268-vAwm6rK.jpg","gif":"1268-vAwm6rK.gif"},{"id":"0196","n":"cable pull through (with rope)","bp":"upper legs","eq":"cable","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Stand facing away from the cable machine with your feet shoulder-width apart.","Grab the rope attachment with both hands and step forward, creating tension in the cable.","Bend at the hips and lower your upper body until it is parallel to the ground, keeping your back straight.","Engage your glutes and hamstrings to pull your body back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0196-OM46QHm.jpg","gif":"0196-OM46QHm.gif"},{"id":"0198","n":"cable pulldown","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Adjust the cable pulldown machine so that the seat is at a comfortable height and the knee pad is secured.","Sit on the seat with your back straight and your feet flat on the ground.","Grasp the cable bar with an overhand grip, slightly wider than shoulder-width apart.","Lean back slightly and engage your core.","Pull the cable bar down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back to the starting position.","Repeat for the desired number of repetitions."],"img":"0198-RVwzP10.jpg","gif":"0198-RVwzP10.gif"},{"id":"0197","n":"cable pulldown (pro lat bar)","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Adjust the seat height so that your thighs are parallel to the ground and your feet are flat on the floor.","Grasp the lat bar with an overhand grip, slightly wider than shoulder-width apart.","Sit down and lean back slightly, keeping your chest up and your back straight.","Pull the bar down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0197-qdRxqCj.jpg","gif":"0197-qdRxqCj.gif"},{"id":"1638","n":"cable pulldown bicep curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Attach a straight bar to the cable machine at the highest setting.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and slowly curl the bar down towards your thighs, keeping your wrists straight.","Pause for a moment at the bottom of the movement, squeezing your biceps.","Inhale and slowly return the bar to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"1638-QTXKWPh.jpg","gif":"1638-QTXKWPh.gif"},{"id":"0201","n":"cable pushdown","bp":"upper arms","eq":"cable","tg":"triceps","mg":"forearms","sm":["forearms"],"st":["Attach a straight bar to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.","Grasp the bar with an overhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and push the bar down until your elbows are fully extended.","Pause for a moment, then inhale and slowly return the bar to the starting position.","Repeat for the desired number of repetitions."],"img":"0201-3ZflifB.jpg","gif":"0201-3ZflifB.gif"},{"id":"0199","n":"cable pushdown (straight arm) v. 2","bp":"back","eq":"cable","tg":"lats","mg":"triceps","sm":["triceps","shoulders"],"st":["Attach a straight bar to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.","Grasp the bar with an overhand grip, keeping your arms straight and your palms facing down.","Engage your core and keep your back straight as you exhale and push the bar down towards your thighs.","Pause for a moment at the bottom, then slowly return the bar to the starting position while inhaling.","Repeat for the desired number of repetitions."],"img":"0199-PskORrA.jpg","gif":"0199-PskORrA.gif"},{"id":"0200","n":"cable pushdown (with rope attachment)","bp":"upper arms","eq":"cable","tg":"triceps","mg":"forearms","sm":["forearms"],"st":["Attach a rope attachment to a high pulley on a cable machine.","Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.","Grasp the rope with an overhand grip, palms facing each other.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Exhale and push the rope downward by extending your elbows until your arms are fully extended.","Pause for a moment, then inhale and slowly return to the starting position by allowing your elbows to flex.","Repeat for the desired number of repetitions."],"img":"0200-dU605di.jpg","gif":"0200-dU605di.gif"},{"id":"0202","n":"cable rear delt row (stirrups)","bp":"shoulders","eq":"cable","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids","biceps"],"st":["Attach a stirrup handle to a low cable pulley and stand facing the machine.","Grasp the handle with your left hand and take a step back with your right foot, positioning your body at a slight angle.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.","With your left arm extended and your palm facing down, pull the handle towards your chest by retracting your shoulder blade.","Pause for a moment at the top of the movement, squeezing your shoulder blade.","Slowly release the handle back to the starting position and repeat for the desired number of repetitions.","Switch sides and repeat the exercise with your right arm."],"img":"0202-yUdIGNs.jpg","gif":"0202-yUdIGNs.gif"},{"id":"0203","n":"cable rear delt row (with rope)","bp":"shoulders","eq":"cable","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids","biceps"],"st":["Attach a rope handle to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope handle with an overhand grip, palms facing each other.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Keep your elbows slightly bent and pull the rope towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"img":"0203-wqNPGCg.jpg","gif":"0203-wqNPGCg.gif"},{"id":"0204","n":"cable rear drive","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders","back"],"st":["Attach a handle to a low pulley cable machine and stand facing away from the machine.","Grasp the handle with an overhand grip and extend your arms straight out in front of you.","Keeping your elbows stationary, pull the handle back towards your body, squeezing your triceps at the end of the movement.","Slowly return the handle to the starting position and repeat for the desired number of repetitions."],"img":"0204-c3QQLPi.jpg","gif":"0204-c3QQLPi.gif"},{"id":"0205","n":"cable rear pulldown","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Adjust the cable machine so that the pulley is at the highest position.","Sit facing the machine with your feet flat on the ground and your knees slightly bent.","Grasp the cable attachment with an overhand grip, hands slightly wider than shoulder-width apart.","Lean back slightly, keeping your back straight and your chest up.","Pull the cable attachment down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the cable back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0205-SpsOSXk.jpg","gif":"0205-SpsOSXk.gif"},{"id":"0873","n":"cable reverse crunch","bp":"waist","eq":"cable","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Attach a cable to a low pulley and lie down facing up on a mat.","Hold the cable with both hands and extend your arms straight up towards the ceiling.","Bend your knees and lift your legs up, bringing your thighs towards your chest.","While keeping your upper body stable, curl your pelvis up towards your chest, lifting your hips off the mat.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0873-RqOtqD7.jpg","gif":"0873-RqOtqD7.gif"},{"id":"0206","n":"cable reverse curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Attach a straight bar to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Exhale and curl the bar up towards your shoulders, contracting your biceps.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the bar back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"0206-eOG0r6v.jpg","gif":"0206-eOG0r6v.gif"},{"id":"2406","n":"cable reverse grip triceps pushdown (sz-bar) (with arm blaster)","bp":"upper arms","eq":"cable","tg":"triceps","mg":"forearms","sm":["forearms"],"st":["Attach a straight bar to the cable machine at the highest setting.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Engage your triceps and slowly push the bar down until your arms are fully extended.","Pause for a moment at the bottom, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."],"img":"2406-ThKP69G.jpg","gif":"2406-ThKP69G.gif"},{"id":"1413","n":"cable reverse one arm curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand facing a cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip, palm facing down.","Keep your elbow close to your side and slowly curl your forearm up towards your shoulder.","Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1413-gVlnLIJ.jpg","gif":"1413-gVlnLIJ.gif"},{"id":"0209","n":"cable reverse preacher curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Adjust the cable machine so that the preacher curl pad is at chest height.","Sit on the preacher curl bench and place your upper arms on the pad, with your palms facing down and your elbows fully extended.","Grab the cable handles with an underhand grip, shoulder-width apart.","Keeping your upper arms stationary, exhale and curl the handles towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position, fully extending your elbows.","Repeat for the desired number of repetitions."],"img":"0209-IwX5NqK.jpg","gif":"0209-IwX5NqK.gif"},{"id":"0210","n":"cable reverse wrist curl","bp":"lower arms","eq":"cable","tg":"forearms","mg":"forearms","sm":["forearms","wrists"],"st":["Attach a cable to a low pulley and sit on a bench facing the cable machine.","Grasp the cable handle with an overhand grip, palms facing down.","Rest your forearms on your thighs, with your wrists hanging off the edge.","Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.","Pause for a moment at the top, then inhale and slowly lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0210-eYmsEPR.jpg","gif":"0210-eYmsEPR.gif"},{"id":"0207","n":"cable reverse-grip pushdown","bp":"upper arms","eq":"cable","tg":"triceps","mg":"forearms","sm":["forearms"],"st":["Attach a straight bar to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Using your triceps, push the bar down until your arms are fully extended and your triceps are contracted.","Pause for a moment, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."],"img":"0207-VjYliFZ.jpg","gif":"0207-VjYliFZ.gif"},{"id":"0208","n":"cable reverse-grip straight back seated high row","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Sit on the seat facing the cable machine with your feet flat on the floor.","Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart.","Keep your back straight and lean slightly forward from your hips.","Pull the cable towards your torso by retracting your shoulder blades and squeezing your back muscles.","Pause for a moment at the peak of the contraction, then slowly release the cable back to the starting position.","Repeat for the desired number of repetitions."],"img":"0208-PNtsX17.jpg","gif":"0208-PNtsX17.gif"},{"id":"1320","n":"cable rope crossover seated row","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Sit on the rowing machine with your feet flat on the footrests and your knees slightly bent.","Grasp the cable ropes with an overhand grip, palms facing each other.","Lean back slightly, keeping your back straight and your core engaged.","Pull the cable ropes towards your chest, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"img":"1320-UFGF6gk.jpg","gif":"1320-UFGF6gk.gif"},{"id":"1321","n":"cable rope elevated seated row","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Sit on the elevated seat facing the cable machine.","Grab the cable rope handles with an overhand grip, palms facing each other.","Keep your back straight and lean slightly back, maintaining a slight bend in your knees.","Pull the cable towards your body by retracting your shoulder blades and squeezing your back muscles.","Pause for a moment at the fully contracted position.","Slowly release the tension and extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"img":"1321-c8oybX6.jpg","gif":"1321-c8oybX6.gif"},{"id":"1322","n":"cable rope extension incline bench row","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Set up an incline bench at a 45-degree angle and attach a cable machine to the low pulley.","Attach a rope handle to the cable machine and sit on the incline bench facing the machine.","Grab the rope handle with an overhand grip and lean forward, keeping your back straight.","Extend your arms fully, pulling the rope towards your upper chest while keeping your elbows close to your body.","Squeeze your shoulder blades together at the end of the movement.","Slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"img":"1322-MgKwAAo.jpg","gif":"1322-MgKwAAo.gif"},{"id":"1639","n":"cable rope hammer preacher curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Attach a rope attachment to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope with a neutral grip (palms facing each other).","Position your upper arms against the preacher bench pad, keeping your elbows slightly bent.","Keeping your upper arms stationary, exhale and curl the rope towards your shoulders by contracting your biceps.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the rope back to the starting position.","Repeat for the desired number of repetitions."],"img":"1639-PcPe0P5.jpg","gif":"1639-PcPe0P5.gif"},{"id":"1724","n":"cable rope high pulley overhead tricep extension","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Attach a rope to a high pulley and adjust the weight accordingly.","Stand facing away from the pulley machine with your feet shoulder-width apart.","Grasp the rope with both hands, palms facing down, and bring your hands above your head.","Keep your upper arms close to your head and perpendicular to the floor.","Slowly lower the rope behind your head by bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"img":"1724-NN8nSNT.jpg","gif":"1724-NN8nSNT.gif"},{"id":"1725","n":"cable rope incline tricep extension","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Attach a rope to a high pulley and adjust the incline bench to a comfortable angle.","Stand facing away from the pulley with your feet shoulder-width apart.","Grasp the rope with an overhand grip and extend your arms straight overhead.","Keep your elbows close to your head and your upper arms stationary throughout the exercise.","Lower the rope behind your head by bending your elbows until your forearms touch your biceps.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"img":"1725-ZujAdR9.jpg","gif":"1725-ZujAdR9.gif"},{"id":"1726","n":"cable rope lying on floor tricep extension","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Attach a rope to a cable machine and set it to the lowest position.","Lie on the floor facing up, with your head towards the cable machine.","Hold the rope with both hands, palms facing each other, and extend your arms straight up towards the ceiling.","Keep your upper arms stationary and slowly lower the rope towards your forehead, bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"img":"1726-U3ffHlY.jpg","gif":"1726-U3ffHlY.gif"},{"id":"1640","n":"cable rope one arm hammer preacher curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Attach a rope handle to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope handle with an underhand grip, palms facing up.","Position your upper arm against the preacher bench pad, keeping your elbow slightly bent.","Keep your back straight and your core engaged throughout the exercise.","Slowly curl the rope handle towards your shoulder, keeping your upper arm stationary.","Squeeze your biceps at the top of the movement, then slowly lower the rope handle back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1640-4hATdoB.jpg","gif":"1640-4hATdoB.gif"},{"id":"1323","n":"cable rope seated row","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Sit on the rowing machine with your feet flat on the footrests and knees slightly bent.","Grasp the cable ropes with an overhand grip, palms facing each other.","Keep your back straight and lean slightly forward, maintaining a slight bend in your elbows.","Pull the cable ropes towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"img":"1323-SJqRxOt.jpg","gif":"1323-SJqRxOt.gif"},{"id":"0211","n":"cable russian twists (on stability ball)","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold the cable handle with both hands and extend your arms straight out in front of you.","Lean back slightly while keeping your back straight and your core engaged.","Twist your torso to the right, bringing the cable handle towards your right hip.","Pause for a moment, then twist your torso to the left, bringing the cable handle towards your left hip.","Continue alternating twists for the desired number of repetitions."],"img":"0211-d9Xaxq6.jpg","gif":"0211-d9Xaxq6.gif"},{"id":"2144","n":"cable seated chest press","bp":"chest","eq":"cable","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Adjust the seat height and cable handles to a comfortable position.","Sit on the bench with your back straight and feet flat on the floor.","Grasp the cable handles with an overhand grip at shoulder height.","Push the handles forward and away from your body, extending your arms fully.","Pause for a moment, then slowly bring the handles back to the starting position.","Repeat for the desired number of repetitions."],"img":"2144-nIR4Rwl.jpg","gif":"2144-nIR4Rwl.gif"},{"id":"0212","n":"cable seated crunch","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Sit on a cable machine with your feet flat on the ground and your knees bent.","Hold the cable handle with both hands and position it behind your head.","Engage your abs and slowly curl your upper body forward, bringing your chest towards your knees.","Pause for a moment at the top, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"0212-8xUv4J7.jpg","gif":"0212-8xUv4J7.gif"},{"id":"1641","n":"cable seated curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a cable machine with your feet flat on the ground and your back straight.","Grasp the cable attachment with an underhand grip, palms facing up, and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the cable attachment towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"1641-8oYqOt9.jpg","gif":"1641-8oYqOt9.gif"},{"id":"0213","n":"cable seated high row (v-bar)","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Sit on the cable machine with your feet flat on the floor and your knees slightly bent.","Grasp the v-bar attachment with an overhand grip, palms facing each other, and your hands shoulder-width apart.","Keep your back straight and lean slightly forward from the hips.","Pull the v-bar towards your torso by retracting your shoulder blades and squeezing your back muscles.","Pause for a moment at the peak of the contraction, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"img":"0213-pwt0pnM.jpg","gif":"0213-pwt0pnM.gif"},{"id":"0214","n":"cable seated one arm alternate row","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Sit on a bench facing a cable machine with your feet flat on the ground and knees slightly bent.","Grasp the handle with one hand and keep your arm fully extended in front of you.","Pull the handle towards your body, retracting your shoulder blade and keeping your elbow close to your side.","Pause for a moment at the top of the movement, squeezing your back muscles.","Slowly release the handle back to the starting position.","Repeat with the other arm.","Alternate between arms for the desired number of repetitions."],"img":"0214-vpp9Ku2.jpg","gif":"0214-vpp9Ku2.gif"},{"id":"1642","n":"cable seated one arm concentration curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a bench with your feet flat on the floor and your back straight.","Hold a cable handle with one hand and place your elbow on the inside of your thigh, just above the knee.","Keep your upper arm stationary and curl the cable handle towards your shoulder while exhaling.","Pause for a moment at the top of the movement, squeezing your biceps.","Slowly lower the cable handle back to the starting position while inhaling.","Repeat for the desired number of repetitions, then switch arms."],"img":"1642-rZ80Gbp.jpg","gif":"1642-rZ80Gbp.gif"},{"id":"1643","n":"cable seated overhead curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Sit on a bench facing the cable machine with your feet flat on the ground.","Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart.","Keep your upper arms stationary and your elbows close to your sides.","Exhale and curl the cable attachment towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"1643-DpWMFP5.jpg","gif":"1643-DpWMFP5.gif"},{"id":"0215","n":"cable seated rear lateral raise","bp":"shoulders","eq":"cable","tg":"delts","mg":"traps","sm":["traps","rhomboids"],"st":["Sit on a bench facing the cable machine with your feet flat on the ground.","Grasp the cable handles with an overhand grip and extend your arms straight in front of you.","Keeping your arms straight, slowly raise them out to the sides until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back to the starting position.","Repeat for the desired number of repetitions."],"img":"0215-x825CZm.jpg","gif":"0215-x825CZm.gif"},{"id":"0861","n":"cable seated row","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.","Grasp the handles with an overhand grip, keeping your back straight and your shoulders relaxed.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."],"img":"0861-fUBheHs.jpg","gif":"0861-fUBheHs.gif"},{"id":"0216","n":"cable seated shoulder internal rotation","bp":"shoulders","eq":"cable","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","triceps"],"st":["Sit on a bench or chair facing the cable machine with your feet flat on the ground.","Hold the cable handle with your arm extended straight out in front of you, parallel to the ground.","Keep your elbow slightly bent and your shoulder blades pulled back and down.","Slowly rotate your arm inward, bringing the cable handle towards the center of your body.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"0216-YPoVrBi.jpg","gif":"0216-YPoVrBi.gif","ty":"rin"},{"id":"2399","n":"cable seated twist","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Sit on a cable machine with your feet flat on the ground and your knees slightly bent.","Hold the cable handle with both hands and extend your arms straight in front of you.","Keeping your core engaged, slowly rotate your torso to one side, pulling the cable across your body.","Pause for a moment at the end of the range of motion, then slowly rotate back to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."],"img":"2399-UEjSrKI.jpg","gif":"2399-UEjSrKI.gif"},{"id":"0218","n":"cable seated wide-grip row","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.","Grasp the handle with a wide overhand grip, palms facing down.","Keep your back straight and lean slightly forward from the hips.","Pull the handle towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the peak of the contraction.","Slowly release the handle back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"0218-qcY50ZD.jpg","gif":"0218-qcY50ZD.gif"},{"id":"0219","n":"cable shoulder press","bp":"shoulders","eq":"cable","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Adjust the cable machine so that the handles are at shoulder height.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip and bring them up to shoulder level, with your elbows bent and pointing outwards.","Press the handles upwards until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the handles back down to shoulder level.","Repeat for the desired number of repetitions."],"img":"0219-PzQanLE.jpg","gif":"0219-PzQanLE.gif"},{"id":"0220","n":"cable shrug","bp":"back","eq":"cable","tg":"traps","mg":"shoulders","sm":["shoulders"],"st":["Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable handles with an overhand grip and let your arms hang down in front of you.","Keeping your arms straight, shrug your shoulders up towards your ears.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0220-Eg98Ft9.jpg","gif":"0220-Eg98Ft9.gif"},{"id":"0222","n":"cable side bend","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Stand with your feet shoulder-width apart and grasp the cable handle with one hand.","Keep your back straight and your core engaged.","Slowly bend sideways at the waist, lowering the cable handle towards your knee.","Pause for a moment, then return to the starting position.","Repeat on the other side.","Alternate sides for the desired number of repetitions."],"img":"0222-wPypxFY.jpg","gif":"0222-wPypxFY.gif"},{"id":"0221","n":"cable side bend crunch (bosu ball)","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Stand with your feet shoulder-width apart, holding a cable handle in one hand.","Place the other hand on your hip.","Engage your core and slowly bend sideways towards the hand holding the cable, keeping your back straight.","Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"0221-qatbkEd.jpg","gif":"0221-qatbkEd.gif"},{"id":"0223","n":"cable side crunch","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Attach a cable handle to a low pulley and stand sideways to the machine.","Grasp the handle with the hand furthest from the machine and place your other hand on your hip.","Keep your feet shoulder-width apart and your knees slightly bent.","With your abs engaged, bend sideways at the waist, bringing your elbow down towards your hip.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"0223-q2ADGqV.jpg","gif":"0223-q2ADGqV.gif"},{"id":"1717","n":"cable squat row (with rope attachment)","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Attach a rope to a cable machine at waist height.","Stand facing the cable machine with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position, keeping your back straight and chest up.","Grasp the rope with an overhand grip, with your hands shoulder-width apart.","Engage your core and pull the rope towards your body, squeezing your shoulder blades together.","Keep your elbows close to your body and continue pulling until your hands reach your chest.","Pause for a moment at the top of the movement, then slowly release the rope and extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"img":"1717-f7fnAIB.jpg","gif":"1717-f7fnAIB.gif"},{"id":"1644","n":"cable squatting curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Attach a cable handle to the lowest setting on a cable machine.","Stand facing the machine with your feet shoulder-width apart.","Hold the cable handle with an underhand grip, palms facing up, and arms fully extended.","Lower your body into a squat position, keeping your back straight and knees behind your toes.","As you squat down, curl the cable handle towards your shoulders, keeping your elbows close to your sides.","Pause for a moment at the top of the curl, squeezing your biceps.","Slowly lower the cable handle back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"1644-3XFdb1Z.jpg","gif":"1644-3XFdb1Z.gif"},{"id":"0224","n":"cable standing back wrist curl","bp":"lower arms","eq":"cable","tg":"forearms","mg":"biceps","sm":["biceps","brachialis"],"st":["Stand facing a cable machine with your feet shoulder-width apart.","Hold the cable handle with an overhand grip, palms facing down.","Keep your arms straight and your elbows close to your sides.","Slowly curl your wrists upward, bringing the cable handle towards your body.","Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions."],"img":"0224-VhX2JdE.jpg","gif":"0224-VhX2JdE.gif"},{"id":"1375","n":"cable standing calf raise","bp":"lower legs","eq":"cable","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Stand facing a cable machine with your feet shoulder-width apart.","Hold onto the cable machine handles or attach a cable ankle strap to your ankles.","Raise your heels off the ground by extending your ankles as high as possible.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1375-yl2IYyy.jpg","gif":"1375-yl2IYyy.gif"},{"id":"0225","n":"cable standing cross-over high reverse fly","bp":"shoulders","eq":"cable","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids","rear deltoids"],"st":["Attach a D-handle to each side of a cable machine at shoulder height.","Stand in the middle of the cable machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip and extend your arms out to the sides, palms facing forward.","Keep a slight bend in your elbows and maintain a straight back throughout the exercise.","Engage your shoulder muscles and squeeze your shoulder blades together as you pull the handles towards the front of your body.","Pause for a moment at the peak of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"0225-P5p0j8B.jpg","gif":"0225-P5p0j8B.gif"},{"id":"0226","n":"cable standing crunch","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Attach a cable handle to a high pulley and stand facing away from the machine.","Hold the handle with both hands and place it behind your head, keeping your elbows bent.","Stand with your feet shoulder-width apart and your knees slightly bent.","Keeping your abs engaged, exhale and crunch your torso down towards your knees, bringing your elbows towards your thighs.","Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"0226-jpgqxiS.jpg","gif":"0226-jpgqxiS.gif"},{"id":"0874","n":"cable standing crunch (with rope attachment)","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Attach a rope to a cable machine at chest height.","Stand facing away from the machine with your feet shoulder-width apart.","Hold the rope with both hands and bring it behind your head, keeping your elbows bent.","Engage your abs and slowly crunch your torso forward, bringing your elbows towards your knees.","Pause for a moment at the top of the crunch, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"0874-XU3ePuv.jpg","gif":"0874-XU3ePuv.gif"},{"id":"0227","n":"cable standing fly","bp":"chest","eq":"cable","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Attach the handles to the cables at chest height.","Stand with your feet shoulder-width apart, facing away from the cable machine.","Grasp the handles with an overhand grip, palms facing forward.","Step forward slightly to create tension in the cables.","Keep your core engaged and your back straight throughout the exercise.","With a slight bend in your elbows, slowly bring your arms forward and together in front of your chest.","Squeeze your chest muscles at the peak of the movement.","Slowly reverse the movement, returning your arms to the starting position.","Repeat for the desired number of repetitions."],"img":"0227-Pr9Rhf4.jpg","gif":"0227-Pr9Rhf4.gif"},{"id":"0228","n":"cable standing hip extension","bp":"upper legs","eq":"cable","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Attach a cable to a low pulley and stand facing away from the machine.","Place the cable around your ankle and stand with your feet shoulder-width apart.","Keep your core engaged and your back straight throughout the exercise.","Slowly extend your leg straight back, squeezing your glutes at the top of the movement.","Pause for a moment, then return to the starting position.","Repeat for the desired number of repetitions.","Switch sides and repeat with the other leg."],"img":"0228-Kpajagk.jpg","gif":"0228-Kpajagk.gif"},{"id":"0229","n":"cable standing inner curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand facing a cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip, palms facing up.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and curl the cable handle towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions."],"img":"0229-YwnI4ja.jpg","gif":"0229-YwnI4ja.gif"},{"id":"0230","n":"cable standing lift","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Stand facing the cable machine with your feet shoulder-width apart.","Hold the cable handle with both hands and position it at waist height.","Engage your core and maintain a straight back throughout the exercise.","Keeping your arms straight, exhale and lift the cable handle up towards your opposite shoulder, rotating your torso.","Pause for a moment at the top, then inhale and slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"0230-qFpAkpP.jpg","gif":"0230-qFpAkpP.gif"},{"id":"0231","n":"cable standing one arm triceps extension","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Stand with your feet shoulder-width apart, facing the cable machine.","Hold the cable handle with your right hand, palm facing down, and position your arm so that it is fully extended and parallel to the ground.","Keep your elbow stationary and close to your body.","Slowly bend your elbow, lowering the cable handle towards the back of your head.","Pause for a moment at the bottom of the movement, then extend your arm back to the starting position.","Repeat for the desired number of repetitions, then switch sides and perform the exercise with your left arm."],"img":"0231-sYCcnon.jpg","gif":"0231-sYCcnon.gif"},{"id":"1376","n":"cable standing one leg calf raise","bp":"lower legs","eq":"cable","tg":"calves","mg":"ankles","sm":["ankles","feet"],"st":["Stand facing a cable machine with your feet shoulder-width apart.","Hold onto the cable machine for support.","Lift one leg off the ground and balance on the other leg.","Slowly raise your heel off the ground, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"img":"1376-fgc9Xdl.jpg","gif":"1376-fgc9Xdl.gif"},{"id":"0232","n":"cable standing pulldown (with rope)","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Attach a rope to the cable machine at the highest setting.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope with an overhand grip, palms facing down.","Keep your back straight and core engaged throughout the exercise.","Pull the rope down towards your thighs, squeezing your biceps.","Pause for a moment at the bottom, then slowly release the rope back up.","Repeat for the desired number of repetitions."],"img":"0232-CvPn9WV.jpg","gif":"0232-CvPn9WV.gif"},{"id":"0233","n":"cable standing rear delt row (with rope)","bp":"shoulders","eq":"cable","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids","biceps"],"st":["Stand facing a cable machine with your feet shoulder-width apart.","Hold the cable attachment with both hands, palms facing each other, and step back to create tension in the cable.","Keep your back straight and your core engaged.","Pull the cable towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the cable back to the starting position.","Repeat for the desired number of repetitions."],"img":"0233-ZfyAGhK.jpg","gif":"0233-ZfyAGhK.gif"},{"id":"1727","n":"cable standing reverse grip one arm overhead tricep extension","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Stand facing away from the cable machine with your feet shoulder-width apart.","Hold the cable handle with an underhand grip and extend your arm overhead, keeping your elbow close to your head.","Keep your upper arm stationary and slowly lower the cable handle behind your head by bending your elbow.","Pause for a moment at the bottom, then extend your arm back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1727-i11JWU7.jpg","gif":"1727-i11JWU7.gif"},{"id":"0234","n":"cable standing row (v-bar)","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Stand facing the cable machine with your feet shoulder-width apart.","Grasp the v-bar attachment with an overhand grip, palms facing down.","Keep your back straight and your core engaged.","Pull the v-bar towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"img":"0234-4f8RXP8.jpg","gif":"0234-4f8RXP8.gif"},{"id":"0235","n":"cable standing shoulder external rotation","bp":"shoulders","eq":"cable","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","trapezius"],"st":["Stand with your feet shoulder-width apart and your knees slightly bent.","Hold the cable handle with your arm extended in front of you, parallel to the ground.","Keep your elbow slightly bent and your shoulder blades pulled back.","Slowly rotate your arm outward, away from your body, while keeping your elbow in the same position.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"0235-FWdVhcW.jpg","gif":"0235-FWdVhcW.gif","ty":"rin"},{"id":"0236","n":"cable standing twist row (v-bar)","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Attach a v-bar attachment to a cable machine at chest height.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the v-bar with an overhand grip, palms facing down.","Take a step back to create tension in the cable.","Keep your back straight and core engaged throughout the exercise.","Pull the v-bar towards your torso by retracting your shoulder blades and bending your elbows.","As you pull, twist your torso to one side, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, feeling the contraction in your upper back.","Slowly release the tension and return to the starting position, untwisting your torso.","Repeat the movement for the desired number of repetitions, alternating the twisting direction with each rep."],"img":"0236-JOZhu2h.jpg","gif":"0236-JOZhu2h.gif"},{"id":"1269","n":"cable standing up straight crossovers","bp":"chest","eq":"cable","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Stand in the middle of a cable machine with your feet shoulder-width apart.","Hold the handles of the cables with your palms facing down and your arms extended straight out to the sides.","Keeping your arms straight, bring your hands together in front of your body, crossing them over each other.","Pause for a moment, then slowly return to the starting position, keeping your arms extended.","Repeat for the desired number of repetitions."],"img":"1269-UKWTJWR.jpg","gif":"1269-UKWTJWR.gif"},{"id":"0238","n":"cable straight arm pulldown","bp":"back","eq":"cable","tg":"lats","mg":"shoulders","sm":["shoulders","biceps"],"st":["Attach a straight bar to the high pulley of a cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, keeping your arms straight and your palms facing down.","Engage your lats and pull the bar down towards your thighs, keeping your arms straight throughout the movement.","Pause for a moment at the bottom, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."],"img":"0238-x69MAlq.jpg","gif":"0238-x69MAlq.gif"},{"id":"0237","n":"cable straight arm pulldown (with rope)","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Attach a rope to the cable machine at the highest setting.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope with both hands, palms facing down.","Extend your arms fully in front of you, keeping your elbows slightly bent.","Engage your lats and slowly pull the rope down towards your thighs, keeping your arms straight.","Pause for a moment at the bottom, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"img":"0237-DT14T9T.jpg","gif":"0237-DT14T9T.gif"},{"id":"0239","n":"cable straight back seated row","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","forearms","shoulders"],"st":["Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.","Grasp the cable handles with an overhand grip, palms facing down.","Keep your back straight and lean slightly forward from the hips.","Pull the cable handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."],"img":"0239-Tq6gbK6.jpg","gif":"0239-Tq6gbK6.gif"},{"id":"0240","n":"cable supine reverse fly","bp":"shoulders","eq":"cable","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids"],"st":["Attach a D-handle to a low pulley cable machine and lie face down on a flat bench.","Grasp the D-handle with each hand, palms facing down, and extend your arms straight out in front of you.","Keeping your arms straight, raise them out to the sides until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0240-PQcUlDi.jpg","gif":"0240-PQcUlDi.gif"},{"id":"2464","n":"cable thibaudeau kayak row","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Attach a cable handle to a low pulley and sit facing the machine with your feet flat on the floor.","Grasp the handle with your right hand and extend your arm fully, keeping a slight bend in your elbow.","Lean forward from your hips, keeping your back straight and your abs engaged.","Pull the handle towards your torso by retracting your shoulder blade and bending your elbow, keeping your arm close to your body.","Squeeze your back muscles at the top of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides and perform with your left arm."],"img":"2464-ZgwWBoC.jpg","gif":"2464-ZgwWBoC.gif"},{"id":"0241","n":"cable triceps pushdown (v-bar)","bp":"upper arms","eq":"cable","tg":"triceps","mg":"forearms","sm":["forearms"],"st":["Attach a v-bar attachment to the cable machine at the highest setting.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Engage your triceps and exhale as you push the v-bar down until your arms are fully extended.","Pause for a moment at the bottom of the movement, squeezing your triceps.","Inhale as you slowly return the v-bar to the starting position, maintaining control.","Repeat for the desired number of repetitions."],"img":"0241-gAwDzB3.jpg","gif":"0241-gAwDzB3.gif"},{"id":"2405","n":"cable triceps pushdown (v-bar) (with arm blaster)","bp":"upper arms","eq":"cable","tg":"triceps","mg":"forearms","sm":["forearms"],"st":["Attach a v-bar attachment to the cable machine at the highest setting.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Engage your triceps and exhale as you push the v-bar down until your arms are fully extended.","Pause for a moment at the bottom of the movement, squeezing your triceps.","Inhale as you slowly return the v-bar to the starting position, maintaining control.","Repeat for the desired number of repetitions."],"img":"2405-OxJk1fg.jpg","gif":"2405-OxJk1fg.gif"},{"id":"0242","n":"cable tuck reverse crunch","bp":"waist","eq":"cable","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Attach a cable to a low pulley and lie down on a mat facing up.","Hold the cable with both hands and extend your arms straight up above your chest.","Bend your knees and lift your legs up, bringing your knees towards your chest.","At the same time, curl your pelvis up towards your chest, lifting your hips off the ground.","Pause for a moment at the top, then slowly lower your legs and hips back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0242-TXtXc84.jpg","gif":"0242-TXtXc84.gif"},{"id":"0243","n":"cable twist","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Stand with your feet shoulder-width apart, facing the cable machine.","Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent.","Engage your core and twist your torso to the right, pulling the cable across your body.","Pause for a moment at the end of the movement, feeling the contraction in your abs and obliques.","Slowly return to the starting position, resisting the cable's pull.","Repeat the movement to the left side.","Continue alternating sides for the desired number of repetitions."],"img":"0243-aVs3BR3.jpg","gif":"0243-aVs3BR3.gif"},{"id":"0862","n":"cable twist (up-down)","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Stand with your feet shoulder-width apart, facing the cable machine.","Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent.","Engage your core and slowly rotate your torso to one side, keeping your hips and legs stable.","Pause for a moment at the end of the rotation, then slowly return to the starting position.","Repeat the rotation to the opposite side.","Continue alternating sides for the desired number of repetitions."],"img":"0862-fhZQPlV.jpg","gif":"0862-fhZQPlV.gif"},{"id":"0244","n":"cable twisting pull","bp":"back","eq":"cable","tg":"lats","mg":"shoulders","sm":["shoulders","biceps"],"st":["Attach a cable handle to a low pulley and stand facing the machine.","Grasp the handle with your left hand and step away from the machine, extending your arm fully.","Position your feet shoulder-width apart, with your knees slightly bent.","Keep your back straight and your core engaged throughout the exercise.","Pull the handle towards your body, rotating your torso to the right as you do so.","Squeeze your back muscles at the end of the movement.","Slowly return to the starting position, keeping tension on the cable.","Repeat for the desired number of repetitions, then switch sides and perform with your right hand."],"img":"0244-zCgxPbV.jpg","gif":"0244-zCgxPbV.gif"},{"id":"1645","n":"cable two arm curl on incline bench","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on an incline bench with your back against the pad and your feet flat on the ground.","Grasp the cable handles with an underhand grip, palms facing up, and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the handles towards your shoulders while contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"1645-H9y3Dkr.jpg","gif":"1645-H9y3Dkr.gif"},{"id":"1728","n":"cable two arm tricep kickback","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold the cable handle in each hand with your palms facing inwards and your arms bent at a 90-degree angle.","Keeping your upper arms stationary, extend your forearms backwards until your arms are fully extended.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"1728-vvNjDJS.jpg","gif":"1728-vvNjDJS.gif"},{"id":"0245","n":"cable underhand pulldown","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Adjust the cable machine so that the pulldown bar is at a height above your head.","Sit down on the seat and grab the pulldown bar with an underhand grip, hands slightly wider than shoulder-width apart.","Keep your back straight and lean back slightly.","Pull the bar down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0245-xBYcQHj.jpg","gif":"0245-xBYcQHj.gif"},{"id":"1270","n":"cable upper chest crossovers","bp":"chest","eq":"cable","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Attach the handles to the cables at chest height.","Stand in the center of the cable machine with one foot slightly in front of the other.","Grasp the handles with your palms facing down and your arms extended out to the sides.","Keep a slight bend in your elbows and engage your core.","Pull the cables together in front of your chest, crossing them over each other.","Squeeze your chest muscles at the peak of the movement.","Slowly release the cables back to the starting position.","Repeat for the desired number of repetitions."],"img":"1270-j7XMAyn.jpg","gif":"1270-j7XMAyn.gif"},{"id":"1324","n":"cable upper row","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Attach a straight bar to a cable machine at chest height.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your back straight and your core engaged.","Pull the bar towards your upper chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement.","Slowly release the bar back to the starting position.","Repeat for the desired number of repetitions."],"img":"1324-PQStVXH.jpg","gif":"1324-PQStVXH.gif"},{"id":"0246","n":"cable upright row","bp":"shoulders","eq":"cable","tg":"delts","mg":"traps","sm":["traps","biceps"],"st":["Stand with your feet shoulder-width apart, knees slightly bent, and hold the cable attachment with an overhand grip.","Keep your back straight and your core engaged throughout the exercise.","Pull the cable attachment straight up towards your chin, leading with your elbows.","Pause for a moment at the top, squeezing your shoulder blades together.","Slowly lower the cable attachment back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0246-cALKspW.jpg","gif":"0246-cALKspW.gif"},{"id":"1325","n":"cable wide grip rear pulldown behind neck","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Adjust the cable machine so that the pulldown bar is at a height above your head.","Sit down on the seat and grab the pulldown bar with a wide overhand grip.","Keep your back straight and your chest up as you lean back slightly.","Pull the bar down towards your upper chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.","Repeat for the desired number of repetitions."],"img":"1325-CmEr4pM.jpg","gif":"1325-CmEr4pM.gif"},{"id":"0247","n":"cable wrist curl","bp":"lower arms","eq":"cable","tg":"forearms","mg":"biceps","sm":["biceps","brachialis"],"st":["Attach a straight bar to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.","Rest your forearms on a bench or pad, with your wrists hanging off the edge.","Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.","Pause for a moment at the top, then inhale and slowly lower the bar back to the starting position.","Repeat for the desired number of repetitions."],"img":"0247-LrV4s90.jpg","gif":"0247-LrV4s90.gif"},{"id":"1407","n":"calf push stretch with hands against wall","bp":"lower legs","eq":"body weight","tg":"calves","mg":"hamstrings","sm":["hamstrings"],"st":["Stand facing a wall with your feet hip-width apart.","Place your hands against the wall at shoulder height.","Step back with one foot, keeping your heel on the ground and your leg straight.","Bend your front knee slightly and lean forward, feeling a stretch in your calf.","Hold the stretch for 20-30 seconds.","Switch legs and repeat the stretch."],"img":"1407-PzNxakt.jpg","gif":"1407-PzNxakt.gif","ty":"stretch","kind":"time"},{"id":"1377","n":"calf stretch with hands against wall","bp":"lower legs","eq":"body weight","tg":"calves","mg":"hamstrings","sm":["hamstrings"],"st":["Stand facing a wall with your feet hip-width apart.","Place your hands against the wall at shoulder height.","Step your right foot back, keeping your heel on the ground and your leg straight.","Bend your left knee and lean forward, keeping your back leg straight and your heel on the ground.","Hold the stretch for 20-30 seconds.","Switch legs and repeat the stretch."],"img":"1377-m0tCHqc.jpg","gif":"1377-m0tCHqc.gif","ty":"stretch","kind":"time"},{"id":"1378","n":"calf stretch with rope","bp":"lower legs","eq":"rope","tg":"calves","mg":"hamstrings","sm":["hamstrings"],"st":["Stand facing a wall or sturdy object with your feet hip-width apart.","Hold the ends of the rope in each hand and place the middle of the rope around the ball of your right foot.","Step back with your left foot, keeping your heel on the ground and your leg straight.","Lean forward, keeping your back straight, and gently pull on the rope to stretch your calf.","Hold the stretch for 20-30 seconds, then release.","Repeat on the other leg."],"img":"1378-1LVFcEn.jpg","gif":"1378-1LVFcEn.gif","ty":"stretch","kind":"time"},{"id":"0248","n":"cambered bar lying row","bp":"back","eq":"barbell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Set up a barbell on the floor and lie face down on a bench with your chest just off the edge.","Reach down and grab the barbell with an overhand grip, slightly wider than shoulder-width apart.","With your legs straight and feet on the ground, lift the barbell off the floor by extending your arms.","Pull the barbell towards your chest, squeezing your shoulder blades together.","Lower the barbell back down to the starting position and repeat for the desired number of repetitions."],"img":"0248-R5swFnc.jpg","gif":"0248-R5swFnc.gif"},{"id":"2963","n":"captains chair straight leg raise","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Sit on the captain's chair with your back against the backrest and your forearms resting on the arm pads.","Keep your upper body stable and your back straight.","Engage your abs and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"2963-weoDEpH.jpg","gif":"2963-weoDEpH.gif"},{"id":"1548","n":"chair leg extended stretch","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hamstrings","sm":["hamstrings","calves"],"st":["Sit on the edge of a chair with your back straight and feet flat on the ground.","Extend one leg straight out in front of you, keeping your heel on the ground.","Lean forward slightly, feeling a stretch in your quadriceps.","Hold this position for 20-30 seconds.","Switch legs and repeat the stretch."],"img":"1548-xGgAGPm.jpg","gif":"1548-xGgAGPm.gif","ty":"stretch","kind":"time"},{"id":"1271","n":"chest and front of shoulder stretch","bp":"chest","eq":"body weight","tg":"pectorals","mg":"deltoids","sm":["deltoids"],"st":["Stand tall with your feet shoulder-width apart.","Extend your arms straight out in front of you at shoulder height.","Cross your arms in front of your body, with your right arm on top of your left arm.","Interlace your fingers and press your palms together.","Gently squeeze your shoulder blades together and push your hands forward, feeling a stretch in your chest and front of your shoulders.","Hold the stretch for 20-30 seconds, then release.","Repeat for the desired number of repetitions."],"img":"1271-Uto7l43.jpg","gif":"1271-Uto7l43.gif","ty":"stretch","kind":"time"},{"id":"0251","n":"chest dip","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Position yourself on parallel bars with your arms fully extended and your body straight.","Lower your body by bending your elbows until your shoulders are below your elbows.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"img":"0251-9WTm7dq.jpg","gif":"0251-9WTm7dq.gif"},{"id":"1430","n":"chest dip (on dip-pull-up cage)","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Adjust the dip bars to a height that allows you to comfortably grip them.","Stand between the bars and place your hands on each bar, slightly wider than shoulder-width apart.","Jump up and straighten your arms, supporting your body weight on the bars.","Bend your knees and cross your ankles behind you.","Lower your body by bending your elbows, keeping your chest up and your shoulders down.","Continue lowering until your shoulders are below your elbows or until you feel a stretch in your chest.","Push through your palms and extend your elbows to raise your body back up to the starting position.","Repeat for the desired number of repetitions."],"img":"1430-XgWyAiA.jpg","gif":"1430-XgWyAiA.gif"},{"id":"2462","n":"chest dip on straight bar","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Grab the parallel bars with your palms facing down and your arms fully extended.","Bend your knees and cross your ankles.","Lower your body by bending your arms until your shoulders are below your elbows.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"img":"2462-LQFOrMn.jpg","gif":"2462-LQFOrMn.gif"},{"id":"1272","n":"chest stretch with exercise ball","bp":"chest","eq":"stability ball","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Sit on the stability ball with your feet flat on the ground and your back straight.","Hold the exercise ball with both hands and extend your arms straight out in front of you.","Slowly bring the exercise ball towards your chest, feeling a stretch in your chest muscles.","Hold the stretch for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"1272-ykA5tU7.jpg","gif":"1272-ykA5tU7.gif","ty":"stretch","kind":"time"},{"id":"3216","n":"chest tap push-up (male)","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","As you lower yourself, tap your chest with your right hand.","Push yourself back up to the starting position.","Repeat the movement, this time tapping your chest with your left hand.","Continue alternating sides for the desired number of repetitions."],"img":"3216-7E06s6d.jpg","gif":"3216-7E06s6d.gif"},{"id":"1326","n":"chin-up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.","Engage your core and pull your body up towards the bar, leading with your chest.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1326-T2mxWqc.jpg","gif":"1326-T2mxWqc.gif"},{"id":"0253","n":"chin-ups (narrow parallel grip)","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Hang from a pull-up bar with a narrow parallel grip, palms facing towards you.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0253-G70mEAJ.jpg","gif":"0253-G70mEAJ.gif"},{"id":"0257","n":"circles knee stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Stand with your feet shoulder-width apart and your hands on your hips.","Bend your knees slightly and lift your heels off the ground, balancing on the balls of your feet.","Keeping your knees bent, rotate your knees in a circular motion, first clockwise and then counterclockwise.","Perform the movement for the desired number of repetitions."],"img":"0257-X7jbxra.jpg","gif":"0257-X7jbxra.gif","ty":"mob"},{"id":"1273","n":"clap push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Start in a high plank position with your hands slightly wider than shoulder-width apart.","Lower your body towards the ground by bending your elbows, keeping your core engaged.","Push through your palms explosively to propel your body off the ground.","While in mid-air, clap your hands together before landing back in the starting position.","Repeat for the desired number of repetitions."],"img":"1273-wigSg76.jpg","gif":"1273-wigSg76.gif"},{"id":"0258","n":"clock push-up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","As you lower, rotate your body to the left, extending your left arm straight out to the side.","Push back up to the starting position, while rotating your body to the center.","Repeat the push-up, this time rotating your body to the right and extending your right arm out to the side.","Continue alternating sides with each repetition."],"img":"0258-CMAxnsG.jpg","gif":"0258-CMAxnsG.gif"},{"id":"1327","n":"close grip chin-up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Grab the pull-up bar with your palms facing towards you and your hands shoulder-width apart.","Hang from the bar with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1327-VnfUNW7.jpg","gif":"1327-VnfUNW7.gif"},{"id":"0259","n":"close-grip push-up","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Start in a high plank position with your hands placed close together, directly under your shoulders.","Engage your core and lower your body towards the ground, keeping your elbows close to your sides.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."],"img":"0259-x6KpKpq.jpg","gif":"0259-x6KpKpq.gif"},{"id":"2398","n":"close-grip push-up (on knees)","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Start by getting on your hands and knees, with your hands shoulder-width apart and your knees hip-width apart.","Lower your upper body towards the ground by bending your elbows, keeping them close to your sides.","Pause for a moment when your chest is just above the ground.","Push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."],"img":"2398-v3vLFW0.jpg","gif":"2398-v3vLFW0.gif"},{"id":"0260","n":"cocoons","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0260-SLKj2pX.jpg","gif":"0260-SLKj2pX.gif"},{"id":"1468","n":"crab twist toe touch","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Start by sitting on the ground with your knees bent and feet flat on the floor.","Place your hands behind you, fingers pointing towards your feet, and lift your hips off the ground.","Extend one leg straight out in front of you while simultaneously reaching your opposite hand towards your toes.","Return to the starting position and repeat on the other side.","Continue alternating sides for the desired number of repetitions."],"img":"1468-xgsGFVM.jpg","gif":"1468-xgsGFVM.gif"},{"id":"0262","n":"cross body crunch","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your upper body off the ground and twist to bring your right elbow towards your left knee.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat on the other side, bringing your left elbow towards your right knee.","Repeat for the desired number of repetitions."],"img":"0262-rbu5UUb.jpg","gif":"0262-rbu5UUb.gif"},{"id":"0267","n":"crunch (hands overhead)","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms straight above your head.","Engaging your abs, lift your upper body off the ground, curling forward towards your knees.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0267-kjJ3VoQ.jpg","gif":"0267-kjJ3VoQ.gif"},{"id":"0271","n":"crunch (on stability ball)","bp":"waist","eq":"stability ball","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Lie back on the ball until your lower back is supported and your upper body is parallel to the floor.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body towards your knees, curling your torso forward.","Pause for a moment at the top of the movement, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0271-MCUhf1F.jpg","gif":"0271-MCUhf1F.gif"},{"id":"0272","n":"crunch (on stability ball, arms straight)","bp":"waist","eq":"stability ball","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Lie back on the ball until your lower back is supported and your upper body is parallel to the floor.","Place your hands behind your head or cross them over your chest.","Engage your abs and lift your upper body off the ball, curling your shoulders towards your hips.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0272-Sn8wxAI.jpg","gif":"0272-Sn8wxAI.gif"},{"id":"0274","n":"crunch floor","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and lift your shoulders off the ground, curling forward towards your knees.","Pause for a moment at the top, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0274-TFqbd8t.jpg","gif":"0274-TFqbd8t.gif"},{"id":"3016","n":"curl-up","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"3016-g2oKspu.jpg","gif":"3016-g2oKspu.gif","ty":"rin"},{"id":"3769","n":"curtsey squat","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart.","Take a step diagonally behind and across your body with your right foot, crossing it behind your left leg.","Bend both knees as if you were curtsying, lowering your body towards the ground.","Keep your torso upright and your weight on your front foot.","Push through your front foot to return to the starting position.","Repeat on the other side, stepping diagonally behind and across your body with your left foot."],"img":"3769-gUjqdei.jpg","gif":"3769-gUjqdei.gif"},{"id":"2331","n":"cycle cross trainer","bp":"cardio","eq":"leverage machine","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","glutes"],"st":["Adjust the seat height and position yourself on the cycle cross trainer.","Place your feet on the pedals and grip the handlebars.","Start pedaling in a smooth and controlled motion.","Maintain a steady pace and increase the resistance if desired.","Continue pedaling for the desired duration of your cardio workout."],"img":"2331-XSCHmiI.jpg","gif":"2331-XSCHmiI.gif"},{"id":"0276","n":"dead bug","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Lie flat on your back with your arms extended towards the ceiling.","Bend your knees and lift your legs off the ground, creating a 90-degree angle at your hips and knees.","Engage your core and lower back to press your lower back into the ground.","Slowly lower your right arm and left leg towards the ground, keeping them straight and hovering just above the floor.","Pause for a moment, then return to the starting position.","Repeat the movement with your left arm and right leg.","Continue alternating sides for the desired number of repetitions."],"img":"0276-iny3m5y.jpg","gif":"0276-iny3m5y.gif","ty":"rin"},{"id":"0277","n":"decline crunch","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Lie on a decline bench with your feet secured and your knees bent at a 90-degree angle.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body towards your knees, curling your torso.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0277-9Ap7miY.jpg","gif":"0277-9Ap7miY.gif"},{"id":"0279","n":"decline push-up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Place your hands on the ground slightly wider than shoulder-width apart, with your feet elevated on a stable surface.","Keep your body in a straight line from head to toe, engaging your core muscles.","Lower your chest towards the ground by bending your elbows, keeping them close to your body.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."],"img":"0279-i5cEhka.jpg","gif":"0279-i5cEhka.gif"},{"id":"0282","n":"decline sit-up","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Lie on a decline bench with your feet secured and your knees bent.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body off the bench, curling forward towards your knees.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0282-QLL2gdc.jpg","gif":"0282-QLL2gdc.gif"},{"id":"1274","n":"deep push up","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line.","Lower your chest towards the ground by bending your elbows, keeping them close to your body.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."],"img":"1274-vptOQ4N.jpg","gif":"1274-vptOQ4N.gif"},{"id":"0283","n":"diamond push-up","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Start in a high plank position with your hands close together, forming a diamond shape with your thumbs and index fingers.","Keep your body in a straight line from head to toe, engaging your core and glutes.","Lower your chest towards the diamond shape formed by your hands, keeping your elbows close to your body.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0283-soIB2rj.jpg","gif":"0283-soIB2rj.gif"},{"id":"0284","n":"donkey calf raise","bp":"lower legs","eq":"body weight","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Stand with your toes on an elevated surface, such as a step or block.","Place your hands on a stable support, such as a wall or railing, for balance.","Raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0284-u5ESqzH.jpg","gif":"0284-u5ESqzH.gif"},{"id":"1275","n":"drop push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Start in a high plank position with your hands slightly wider than shoulder-width apart.","Lower your chest towards the ground, keeping your elbows close to your body.","Once your chest is just above the ground, quickly drop your knees to the ground.","Push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."],"img":"1275-Q497lAE.jpg","gif":"1275-Q497lAE.gif"},{"id":"0285","n":"dumbbell alternate biceps curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions, alternating arms."],"img":"0285-BU15nH4.jpg","gif":"0285-BU15nH4.gif"},{"id":"2403","n":"dumbbell alternate biceps curl (with arm blaster)","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Place the arm blaster on your upper arms, ensuring a secure fit.","Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the movement with the opposite arm.","Continue alternating arms for the desired number of repetitions."],"img":"2403-CfKsRbG.jpg","gif":"2403-CfKsRbG.gif"},{"id":"1646","n":"dumbbell alternate hammer preacher curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a preacher bench with a dumbbell in each hand, palms facing your torso and arms fully extended.","Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."],"img":"1646-fy7Tgy4.jpg","gif":"1646-fy7Tgy4.gif"},{"id":"1647","n":"dumbbell alternate preacher curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a preacher bench with a dumbbell in each hand, palms facing up.","Rest your upper arms on the pad of the preacher bench, allowing your arms to fully extend.","Keeping your upper arms stationary, exhale and curl the dumbbell in your right hand as you contract your biceps.","Continue to curl the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Pause for a moment, then inhale and slowly lower the dumbbell back to the starting position.","Repeat the movement with your left arm.","Continue alternating arms for the desired number of repetitions."],"img":"1647-NlfIbzq.jpg","gif":"1647-NlfIbzq.gif"},{"id":"1648","n":"dumbbell alternate seated hammer curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended down.","Keep your back straight and your elbows close to your torso.","Exhale and curl the dumbbell in your right hand towards your shoulder, keeping your upper arm stationary.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Pause for a brief moment, then inhale and slowly lower the dumbbell back to the starting position.","Repeat the movement with your left arm.","Continue alternating arms for the desired number of repetitions."],"img":"1648-6em2Dxj.jpg","gif":"1648-6em2Dxj.gif"},{"id":"0286","n":"dumbbell alternate side press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height.","Press one dumbbell overhead while keeping the other dumbbell at shoulder height.","Lower the pressed dumbbell back to shoulder height while pressing the other dumbbell overhead.","Continue alternating sides for the desired number of repetitions."],"img":"0286-izMnLqz.jpg","gif":"0286-izMnLqz.gif"},{"id":"1649","n":"dumbbell alternating bicep curl with leg raised on exercise ball","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Place an exercise ball behind you and position one foot on top of it, keeping your balance.","With your arms fully extended and elbows close to your sides, curl one dumbbell towards your shoulder while keeping your upper arm stationary.","Lower the dumbbell back down to the starting position and repeat with the other arm.","Continue alternating arms for the desired number of repetitions."],"img":"1649-Zwiw7XR.jpg","gif":"1649-Zwiw7XR.gif"},{"id":"1650","n":"dumbbell alternating seated bicep curl on exercise ball","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.","Keeping your upper arms stationary, exhale and curl one dumbbell while rotating your forearm until your palm is facing your shoulder.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the curl with the other arm.","Continue alternating curls for the desired number of repetitions."],"img":"1650-J74XlNf.jpg","gif":"1650-J74XlNf.gif"},{"id":"2137","n":"dumbbell arnold press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest"],"st":["Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent.","Press the dumbbells upward until your arms are fully extended and your palms are facing forward.","Rotate your wrists as you lift, so that your palms are facing forward at the top of the movement.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"2137-Xy4jlWA.jpg","gif":"2137-Xy4jlWA.gif"},{"id":"0287","n":"dumbbell arnold press v. 2","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest"],"st":["Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent.","Press the dumbbells upward until your arms are fully extended and your palms are facing forward.","Rotate your wrists as you lift, so that your palms end up facing forward at the top of the movement.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0287-eOrFCnx.jpg","gif":"0287-eOrFCnx.gif"},{"id":"0288","n":"dumbbell around pullover","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","latissimus dorsi"],"st":["Lie flat on a bench with your head at one end and your feet firmly on the ground.","Hold a dumbbell with both hands and extend your arms straight above your chest.","Keeping your arms straight, slowly lower the dumbbell behind your head in an arc motion.","Pause for a moment at the bottom, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"0288-vi8EhoE.jpg","gif":"0288-vi8EhoE.gif"},{"id":"0289","n":"dumbbell bench press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Hold a dumbbell in each hand, with your palms facing forward and your arms extended above your chest.","Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.","Pause for a moment, then push the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"0289-SpYC0Kp.jpg","gif":"0289-SpYC0Kp.gif"},{"id":"0290","n":"dumbbell bench seated press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","chest"],"st":["Sit on a bench with a dumbbell in each hand, resting on your thighs.","Lean back and position the dumbbells to the sides of your chest, palms facing forward.","Press the dumbbells upward until your arms are fully extended.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0290-3d7wHyd.jpg","gif":"0290-3d7wHyd.gif"},{"id":"0291","n":"dumbbell bench squat","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Place a dumbbell on the ground in front of a bench.","Stand facing away from the bench with your feet shoulder-width apart.","Bend at the knees and hips to lower yourself down towards the bench, keeping your chest up and back straight.","Once your glutes touch the bench, push through your heels to stand back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0291-mnzcrIB.jpg","gif":"0291-mnzcrIB.gif"},{"id":"0293","n":"dumbbell bent over row","bp":"back","eq":"dumbbell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in each hand with your palms facing your body.","Bend forward at the hips, keeping your back straight and your core engaged.","Let your arms hang straight down towards the floor, with your elbows slightly bent.","Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0293-BJ0Hz5L.jpg","gif":"0293-BJ0Hz5L.gif"},{"id":"1651","n":"dumbbell bicep curl lunge with bowling motion","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.","Take a step forward with your right foot, bending your right knee and lowering your body into a lunge position.","As you lunge forward, curl the dumbbells up towards your shoulders, keeping your elbows close to your body.","At the bottom of the lunge, rotate your torso to the right, as if you were bowling a ball.","Reverse the motion, stepping back with your right foot and returning to the starting position while lowering the dumbbells back down.","Repeat the lunge and curl motion, this time rotating your torso to the left.","Continue alternating sides for the desired number of repetitions."],"img":"1651-1VpF8db.jpg","gif":"1651-1VpF8db.gif"},{"id":"1652","n":"dumbbell bicep curl on exercise ball with leg raised","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.","Slowly curl the dumbbells towards your shoulders, keeping your elbows close to your sides.","Pause for a moment at the top of the movement, then slowly lower the dumbbells back to the starting position.","While performing the bicep curl, raise one leg off the ground and hold it in the air for the duration of the exercise.","Repeat for the desired number of repetitions, then switch legs and repeat."],"img":"1652-2NImIAG.jpg","gif":"1652-2NImIAG.gif"},{"id":"1653","n":"dumbbell bicep curl with stork stance","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Extend one leg behind you, balancing on the toes of that foot.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."],"img":"1653-uSkDMYl.jpg","gif":"1653-uSkDMYl.gif"},{"id":"0294","n":"dumbbell biceps curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0294-NbVPDMW.jpg","gif":"0294-NbVPDMW.gif"},{"id":"2401","n":"dumbbell biceps curl (with arm blaster)","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with a dumbbell in each hand, palms facing forward.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"2401-nlJsbkW.jpg","gif":"2401-nlJsbkW.gif"},{"id":"1654","n":"dumbbell biceps curl reverse","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with a dumbbell in each hand, palms facing down and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"1654-nFc4FyV.jpg","gif":"1654-nFc4FyV.gif"},{"id":"1655","n":"dumbbell biceps curl squat","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.","Keeping your back straight and your elbows close to your sides, exhale and curl the dumbbells up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1655-niXESDw.jpg","gif":"1655-niXESDw.gif"},{"id":"1656","n":"dumbbell biceps curl v sit on bosu ball","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Sit on a bosu ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell in each hand with your palms facing forward and your arms fully extended down by your sides.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"1656-H1XAdpk.jpg","gif":"1656-H1XAdpk.gif"},{"id":"1201","n":"dumbbell burpee","bp":"cardio","eq":"dumbbell","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","shoulders","triceps","core"],"st":["Start in a standing position with your feet shoulder-width apart and a dumbbell in each hand.","Lower your body into a squat position, placing the dumbbells on the ground in front of you.","Kick your feet back into a push-up position, keeping your body in a straight line.","Perform a push-up, bending your elbows and lowering your chest towards the ground.","Jump your feet back towards your hands, landing in a squat position.","Stand up explosively, lifting the dumbbells off the ground and bringing them to your shoulders.","Press the dumbbells overhead, fully extending your arms.","Lower the dumbbells back to your shoulders and repeat the entire sequence for the desired number of repetitions."],"img":"1201-0JtKWum.jpg","gif":"1201-0JtKWum.gif","ty":"atl"},{"id":"0295","n":"dumbbell clean","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","calves"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Bend your knees and lower your hips into a squat position, keeping your back straight and chest up.","Explosively extend your hips and knees, driving through your heels to jump off the ground.","As you jump, shrug your shoulders and pull the dumbbells up towards your shoulders, keeping them close to your body.","Catch the dumbbells at shoulder height, with your elbows pointing forward and your palms facing up.","Lower the dumbbells back down to the starting position by reversing the movement.","Repeat for the desired number of repetitions."],"img":"0295-7Hg55JG.jpg","gif":"0295-7Hg55JG.gif"},{"id":"1731","n":"dumbbell close grip press","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Sit on a flat bench with a dumbbell in each hand, resting on your thighs.","Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.","Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.","As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest.","As you exhale, use your triceps to lift the dumbbells back to the starting position. Make sure to use only your triceps and do not use your forearms or biceps to help lift the dumbbells.","After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."],"img":"1731-7jGOBF3.jpg","gif":"1731-7jGOBF3.gif"},{"id":"0296","n":"dumbbell close-grip press","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Sit on a flat bench with a dumbbell in each hand, resting on your thighs.","Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.","Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.","As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest.","As you exhale, use your triceps to lift the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0296-RxayqAZ.jpg","gif":"0296-RxayqAZ.gif"},{"id":"0297","n":"dumbbell concentration curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a bench with your legs spread apart and a dumbbell in one hand, resting your elbow on the inside of your thigh.","Fully extend your arm and hold the dumbbell with an underhand grip.","Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder while contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"0297-gvsWLQw.jpg","gif":"0297-gvsWLQw.gif"},{"id":"3635","n":"dumbbell contralateral forward lunge","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step forward with your right foot, keeping your back straight and core engaged.","Lower your body by bending both knees until your right thigh is parallel to the ground.","Push through your right heel to return to the starting position.","Repeat with your left leg.","Alternate legs for the desired number of repetitions."],"img":"3635-ecl28tP.jpg","gif":"3635-ecl28tP.gif"},{"id":"0298","n":"dumbbell cross body hammer curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with a dumbbell in each hand, palms facing your body.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps, bringing the dumbbells across your body towards your opposite shoulder.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0298-Qyk5J3p.jpg","gif":"0298-Qyk5J3p.gif"},{"id":"1657","n":"dumbbell cross body hammer curl v. 2","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with a dumbbell in each hand, palms facing your body.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps, bringing the dumbbells as close to your opposite shoulder as possible.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"1657-HDYiZcY.jpg","gif":"1657-HDYiZcY.gif"},{"id":"0299","n":"dumbbell cuban press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing down.","Keeping your core engaged and your elbows slightly bent, press the dumbbells up and overhead until your arms are fully extended.","Rotate your wrists so that your palms are facing forward.","Slowly lower the dumbbells back to the starting position, rotating your wrists back to the starting position as you do so.","Repeat for the desired number of repetitions."],"img":"0299-QfAKy1G.jpg","gif":"0299-QfAKy1G.gif","ty":"rin"},{"id":"2136","n":"dumbbell cuban press v. 2","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing down.","Keeping your core engaged and your back straight, press the dumbbells straight up overhead until your arms are fully extended.","Rotate your wrists so that your palms are facing forward.","Lower the dumbbells back down to shoulder height, rotating your wrists back to the starting position.","Repeat for the desired number of repetitions."],"img":"2136-BqgCRif.jpg","gif":"2136-BqgCRif.gif","ty":"rin"},{"id":"0300","n":"dumbbell deadlift","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Stand with your feet shoulder-width apart, toes pointing forward.","Hold a dumbbell in each hand, palms facing your body, arms extended downwards.","Bend at your hips and knees, lowering the dumbbells towards the ground while keeping your back straight.","Push through your heels and extend your hips and knees, lifting the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0300-nUwVh7b.jpg","gif":"0300-nUwVh7b.gif"},{"id":"0301","n":"dumbbell decline bench press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Lie down on a decline bench with your feet secured and your head lower than your hips.","Hold a dumbbell in each hand and extend your arms straight up above your chest, palms facing forward.","Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.","Push the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"0301-DwhEmmE.jpg","gif":"0301-DwhEmmE.gif"},{"id":"0302","n":"dumbbell decline fly","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders"],"st":["Lie on a decline bench with your feet secured and your head lower than your hips.","Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0302-xXm4nYq.jpg","gif":"0302-xXm4nYq.gif"},{"id":"0303","n":"dumbbell decline hammer press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Lie on a decline bench with your feet secured and your head lower than your hips.","Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.","Lower the dumbbells to the sides of your chest, keeping your elbows slightly bent.","Press the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"0303-1qrWgZ2.jpg","gif":"0303-1qrWgZ2.gif"},{"id":"1276","n":"dumbbell decline one arm fly","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders"],"st":["Lie down on a decline bench with a dumbbell in one hand, resting it on your thigh.","Using your thigh to help raise the dumbbell, lift it up to shoulder width with your palm facing your torso.","Rotate your wrist so that the palm of your hand is facing forward.","As you breathe in, lower the dumbbell slowly to the side until you feel a stretch in your chest.","Exhale and use your chest muscles to bring the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1276-NL6YBwN.jpg","gif":"1276-NL6YBwN.gif"},{"id":"1617","n":"dumbbell decline one arm hammer press","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Lie on a decline bench with a dumbbell in one hand, resting on your chest.","Extend your arm straight up, keeping your elbow slightly bent.","Lower the dumbbell down towards your shoulder, keeping your elbow close to your body.","Press the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1617-SHUMp5H.jpg","gif":"1617-SHUMp5H.gif"},{"id":"0305","n":"dumbbell decline shrug","bp":"back","eq":"dumbbell","tg":"traps","mg":"shoulders","sm":["shoulders","rhomboids"],"st":["Set up a decline bench at a 45-degree angle.","Lie face down on the bench with your chest and stomach resting against it.","Hold a dumbbell in each hand with your arms fully extended towards the floor.","Keeping your arms straight, raise your shoulders towards your ears as high as possible.","Hold the contraction for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0305-cwsAI4G.jpg","gif":"0305-cwsAI4G.gif"},{"id":"0304","n":"dumbbell decline shrug v. 2","bp":"back","eq":"dumbbell","tg":"traps","mg":"shoulders","sm":["shoulders","rhomboids"],"st":["Set up a decline bench at a 45-degree angle.","Lie face down on the bench with your chest and stomach resting on it.","Hold a dumbbell in each hand with your palms facing each other and your arms fully extended.","Keeping your arms straight, raise your shoulders as high as possible while squeezing your shoulder blades together.","Hold the contraction for a brief pause, then lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0304-bRlbdjK.jpg","gif":"0304-bRlbdjK.gif"},{"id":"0306","n":"dumbbell decline triceps extension","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Lie on a decline bench with your head lower than your feet and hold a dumbbell in each hand, palms facing each other.","Extend your arms fully, keeping your elbows close to your head.","Lower the dumbbells slowly behind your head, bending your elbows.","Pause for a moment, then raise the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0306-OTgkHwR.jpg","gif":"0306-OTgkHwR.gif"},{"id":"0307","n":"dumbbell decline twist fly","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Lie down on a decline bench with your head lower than your hips.","Hold a dumbbell in each hand with your palms facing each other and your arms extended straight up over your chest.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","As you lower the dumbbells, twist your wrists so that your palms face forward at the bottom of the movement.","Reverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles at the top.","Repeat for the desired number of repetitions."],"img":"0307-reFHapa.jpg","gif":"0307-reFHapa.gif"},{"id":"1437","n":"dumbbell finger curls","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","wrist extensors"],"st":["Sit on a bench or chair with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with an underhand grip, resting your forearm on your thigh, palm facing up.","Allow the dumbbell to roll down to your fingertips, then curl it back up by flexing your fingers.","Repeat for the desired number of repetitions, then switch to the other hand."],"img":"1437-mtXengz.jpg","gif":"1437-mtXengz.gif"},{"id":"0308","n":"dumbbell fly","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders"],"st":["Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight up over your chest, with a slight bend in your elbows.","Keeping a slight bend in your elbows, lower your arms out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then reverse the movement and bring the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0308-yz9nUhF.jpg","gif":"0308-yz9nUhF.gif"},{"id":"1277","n":"dumbbell fly on exercise ball","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Sit on an exercise ball and hold a dumbbell in each hand.","Walk your feet forward and roll your body down until your head, neck, and upper back are supported by the ball.","Extend your arms straight up above your chest, palms facing each other.","Bend your elbows slightly and lower your arms out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then reverse the movement and squeeze your chest muscles as you bring the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"1277-Lt3iWnf.jpg","gif":"1277-Lt3iWnf.gif"},{"id":"1732","n":"dumbbell forward lunge triceps extension","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step forward with your right foot, lowering your body into a lunge position.","Keep your back straight and your chest up.","Extend your arms straight overhead, keeping your elbows close to your ears.","Lower the dumbbells behind your head by bending your elbows.","Pause for a moment, then straighten your arms to return to the starting position.","Repeat the movement for the desired number of repetitions, then switch legs and repeat."],"img":"1732-XalXcvM.jpg","gif":"1732-XalXcvM.gif"},{"id":"0310","n":"dumbbell front raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"biceps","sm":["biceps","trapezius"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.","Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0310-3eGE2JC.jpg","gif":"0310-3eGE2JC.gif"},{"id":"0309","n":"dumbbell front raise v. 2","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","biceps"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.","Keep your back straight and engage your core.","Slowly lift the dumbbells in front of you, with your arms straight, until they are at shoulder level.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0309-Rr7S3yg.jpg","gif":"0309-Rr7S3yg.gif"},{"id":"0311","n":"dumbbell full can lateral raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps","rotator cuff"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.","Keep your back straight and engage your core.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0311-AQ0mC4Y.jpg","gif":"0311-AQ0mC4Y.gif"},{"id":"1760","n":"dumbbell goblet squat","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell vertically against your chest with both hands.","Keeping your chest up and core engaged, lower your body down into a squat position by pushing your hips back and bending your knees.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"1760-yn8yg1r.jpg","gif":"1760-yn8yg1r.gif"},{"id":"0313","n":"dumbbell hammer curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","This will be your starting position.","Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."],"img":"0313-slDvUAU.jpg","gif":"0313-slDvUAU.gif"},{"id":"1659","n":"dumbbell hammer curl on exercise ball","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing your body and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"1659-fY68AyX.jpg","gif":"1659-fY68AyX.gif"},{"id":"0312","n":"dumbbell hammer curl v. 2","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","This will be your starting position.","Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."],"img":"0312-2NpxjC1.jpg","gif":"0312-2NpxjC1.gif"},{"id":"2402","n":"dumbbell hammer curls (with arm blaster)","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","This will be your starting position.","Now, while holding your upper arm stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."],"img":"2402-GNhAeJ0.jpg","gif":"2402-GNhAeJ0.gif"},{"id":"1664","n":"dumbbell high curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with a dumbbell in each hand, palms facing forward.","Keep your upper arms stationary and curl the dumbbells as high as possible while contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"1664-qAmNMJY.jpg","gif":"1664-qAmNMJY.gif"},{"id":"3545","n":"dumbbell incline alternate press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Sit on an incline bench with a dumbbell in each hand, resting on your thighs.","Lean back on the bench and use your thighs to help raise the dumbbells to shoulder height, palms facing forward.","Once at shoulder height, rotate your wrists so that the palms of your hands are facing forward.","Push the dumbbells up with your chest and shoulders, extending your arms fully.","Lower the dumbbells back down to the starting position, keeping your elbows slightly bent.","Repeat for the desired number of repetitions, alternating arms."],"img":"3545-TVdivgY.jpg","gif":"3545-TVdivgY.gif"},{"id":"0314","n":"dumbbell incline bench press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Set up an incline bench at a 45-degree angle.","Sit on the bench with your feet flat on the ground and your back pressed firmly against the bench.","Hold a dumbbell in each hand, palms facing forward, and lift them to shoulder height.","Slowly lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle.","Push the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"0314-ns0SIbU.jpg","gif":"0314-ns0SIbU.gif"},{"id":"0315","n":"dumbbell incline biceps curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on an incline bench with a dumbbell in each hand, palms facing forward, and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0315-F3xgbjF.jpg","gif":"0315-F3xgbjF.gif"},{"id":"0316","n":"dumbbell incline breeding","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Set up an incline bench at a 45-degree angle.","Sit on the bench with your back against the pad and feet flat on the ground.","Hold a dumbbell in each hand with an overhand grip, palms facing forward.","Start with your arms fully extended, perpendicular to the ground.","Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.","Pause for a moment at the bottom, then push the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0316-B3Rxp6L.jpg","gif":"0316-B3Rxp6L.gif"},{"id":"0318","n":"dumbbell incline curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing forward.","Rest your upper arms on the incline bench and let your elbows hang down, fully extending your arms.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0318-ae9UoXQ.jpg","gif":"0318-ae9UoXQ.gif"},{"id":"0317","n":"dumbbell incline curl v. 2","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on an incline bench with a dumbbell in each hand, palms facing forward and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0317-RaflbWD.jpg","gif":"0317-RaflbWD.gif"},{"id":"0319","n":"dumbbell incline fly","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders"],"st":["Set an incline bench to a 45-degree angle.","Sit on the bench with a dumbbell in each hand, palms facing each other.","Lie back on the bench and press the dumbbells up to the starting position, directly above your chest.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0319-ESOd5Pl.jpg","gif":"0319-ESOd5Pl.gif"},{"id":"1278","n":"dumbbell incline fly on exercise ball","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders"],"st":["Set up an incline bench at a 45-degree angle.","Sit on an exercise ball and roll forward until your upper back is resting on the incline bench.","Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"1278-HYe1ZqR.jpg","gif":"1278-HYe1ZqR.gif"},{"id":"0320","n":"dumbbell incline hammer curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on an incline bench with a dumbbell in each hand, palms facing your torso and arms fully extended.","Keep your back against the bench and your feet flat on the floor.","While keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0320-ByX0WxV.jpg","gif":"0320-ByX0WxV.gif"},{"id":"0321","n":"dumbbell incline hammer press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, resting on your thighs.","Lie back on the bench and position the dumbbells at shoulder level with your palms facing each other.","Press the dumbbells up and away from your body until your arms are fully extended.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0321-PG1kcIb.jpg","gif":"0321-PG1kcIb.gif"},{"id":"1618","n":"dumbbell incline hammer press on exercise ball","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Sit on an exercise ball with a dumbbell in each hand, palms facing each other.","Walk your feet forward and roll your body down the ball until your head, neck, and upper back are supported on the ball.","Hold the dumbbells at shoulder level, elbows bent and pointing out to the sides.","Press the dumbbells up and slightly inward, keeping your palms facing each other.","Extend your arms fully, squeezing your triceps at the top of the movement.","Slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"1618-wkgnGfb.jpg","gif":"1618-wkgnGfb.gif"},{"id":"0322","n":"dumbbell incline inner biceps curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on an incline bench with a dumbbell in each hand, palms facing each other.","Rest your upper arms on the bench, allowing your elbows to hang down and your palms to face forward.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0322-LCtQPn8.jpg","gif":"0322-LCtQPn8.gif"},{"id":"1279","n":"dumbbell incline one arm fly","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Adjust the incline bench to a 30-45 degree angle.","Sit on the bench with a dumbbell in one hand, resting it on your thigh.","Lie back on the bench, keeping your feet flat on the ground.","Hold the dumbbell with your arm extended straight up over your chest.","Lower the dumbbell out to the side in a wide arc, keeping a slight bend in your elbow.","Pause when your arm is parallel to the ground, then reverse the motion to bring the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1279-Gw2HFvW.jpg","gif":"1279-Gw2HFvW.gif"},{"id":"1280","n":"dumbbell incline one arm fly on exercise ball","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders"],"st":["Sit on an exercise ball with a dumbbell in one hand.","Walk your feet forward and roll your body down until your head, neck, and upper back are supported on the ball.","Hold the dumbbell with your arm extended straight up over your chest, palm facing inwards.","Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.","Pause for a moment when your arm is parallel to the ground.","Engage your chest muscles to bring the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1280-LLNh6q5.jpg","gif":"1280-LLNh6q5.gif"},{"id":"1619","n":"dumbbell incline one arm hammer press","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","chest"],"st":["Sit on an incline bench with a dumbbell in one hand, resting on your thigh.","Lean back on the bench and use your thigh to help raise the dumbbell to shoulder height.","Rotate your wrist so that your palm is facing inward, towards your body.","Press the dumbbell up and away from your body, extending your arm fully.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1619-LL1UiTX.jpg","gif":"1619-LL1UiTX.gif"},{"id":"1620","n":"dumbbell incline one arm hammer press on exercise ball","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","chest"],"st":["Sit on an exercise ball with a dumbbell in one hand.","Walk your feet forward and roll your body down until your head, neck, and upper back are supported on the ball.","Hold the dumbbell with your palm facing inward and your elbow bent at a 90-degree angle.","Press the dumbbell up towards the ceiling, straightening your arm.","Lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1620-jDnrkar.jpg","gif":"1620-jDnrkar.gif"},{"id":"0323","n":"dumbbell incline one arm lateral raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","triceps"],"st":["Sit on an incline bench with a dumbbell in one hand, resting it on your thigh.","Lean forward and position your upper arm against the inside of your thigh.","Raise the dumbbell to the side, keeping your arm slightly bent and your palm facing down.","Continue lifting until your arm is parallel to the floor.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"img":"0323-aTNKZiC.jpg","gif":"0323-aTNKZiC.gif"},{"id":"1281","n":"dumbbell incline one arm press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Sit on an incline bench with a dumbbell in one hand, resting on your thigh.","Lie back on the bench and position the dumbbell at shoulder level, palm facing forward.","Press the dumbbell upward and slightly inward, extending your arm fully.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"img":"1281-rDAiRf9.jpg","gif":"1281-rDAiRf9.gif"},{"id":"1282","n":"dumbbell incline one arm press on exercise ball","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Sit on an exercise ball with a dumbbell in one hand, feet flat on the ground.","Slowly walk your feet forward, rolling the ball until your head, neck, and upper back are supported on the ball.","Hold the dumbbell at shoulder height with your palm facing forward.","Press the dumbbell upward until your arm is fully extended.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"img":"1282-Bg5JKSH.jpg","gif":"1282-Bg5JKSH.gif"},{"id":"0324","n":"dumbbell incline palm-in press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Set up an incline bench at a 45-degree angle.","Sit on the bench with a dumbbell in each hand, palms facing each other.","Plant your feet firmly on the ground and keep your back straight against the bench.","Start with the dumbbells at shoulder level, elbows bent and palms facing each other.","Press the dumbbells up and away from your body, extending your arms fully.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0324-OVLmUuL.jpg","gif":"0324-OVLmUuL.gif"},{"id":"1283","n":"dumbbell incline press on exercise ball","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Sit on an exercise ball with a dumbbell in each hand, palms facing forward.","Slowly walk your feet forward, rolling your body down the ball until your head, neck, and upper back are supported on the ball.","Hold the dumbbells at shoulder level, elbows bent and pointing out to the sides.","Press the dumbbells upward, extending your arms fully.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"1283-bfiHMpI.jpg","gif":"1283-bfiHMpI.gif"},{"id":"0325","n":"dumbbell incline raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","triceps"],"st":["Sit on an incline bench with a dumbbell in each hand, resting on your thighs.","Lean back on the bench and raise the dumbbells to shoulder height, palms facing forward.","Keeping your back against the bench, exhale and raise the dumbbells above your head, fully extending your arms.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."],"img":"0325-nxW6BkN.jpg","gif":"0325-nxW6BkN.gif"},{"id":"0326","n":"dumbbell incline rear lateral raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps","rhomboids"],"st":["Set up an incline bench at a 45-degree angle.","Sit on the bench with your chest against the backrest and hold a dumbbell in each hand.","Extend your arms straight down with your palms facing each other.","Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0326-vYk8lqw.jpg","gif":"0326-vYk8lqw.gif"},{"id":"0327","n":"dumbbell incline row","bp":"back","eq":"dumbbell","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Set up an incline bench at a 45-degree angle.","Grab a dumbbell in each hand and sit on the bench with your chest against the incline.","Extend your arms fully, allowing the dumbbells to hang straight down from your shoulders.","Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0327-7vG5o25.jpg","gif":"0327-7vG5o25.gif"},{"id":"0328","n":"dumbbell incline shoulder raise","bp":"chest","eq":"dumbbell","tg":"serratus anterior","mg":"deltoids","sm":["deltoids","trapezius"],"st":["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing down.","Rest the dumbbells on your thighs and lean back onto the bench.","Use your thighs to help raise the dumbbells to shoulder height, then rotate your wrists so that your palms are facing forward.","Exhale and slowly raise the dumbbells above your head, keeping a slight bend in your elbows.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."],"img":"0328-6e2DcYX.jpg","gif":"0328-6e2DcYX.gif"},{"id":"0329","n":"dumbbell incline shrug","bp":"back","eq":"dumbbell","tg":"traps","mg":"shoulders","sm":["shoulders"],"st":["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand.","Place your feet flat on the ground and let your arms hang straight down with your palms facing your body.","Keeping your arms straight, shrug your shoulders up towards your ears as high as possible.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0329-JymLInS.jpg","gif":"0329-JymLInS.gif"},{"id":"3542","n":"dumbbell incline t-raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps","rhomboids"],"st":["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.","Lean forward and let your arms hang straight down, perpendicular to the floor.","Keeping your arms straight, raise them out to the sides until they are parallel to the floor, forming a 'T' shape with your body.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"img":"3542-jgbvVJ0.jpg","gif":"3542-jgbvVJ0.gif"},{"id":"0330","n":"dumbbell incline triceps extension","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Sit on an incline bench with a dumbbell in each hand, palms facing inwards.","Extend your arms fully overhead, keeping your elbows close to your head.","Lower the dumbbells behind your head by bending your elbows, keeping your upper arms stationary.","Pause for a moment, then raise the dumbbells back to the starting position by extending your arms.","Repeat for the desired number of repetitions."],"img":"0330-OVIKwsd.jpg","gif":"0330-OVIKwsd.gif"},{"id":"0331","n":"dumbbell incline twisted flyes","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing each other.","Lie back on the bench and press the dumbbells up to the starting position, directly above your chest, with your arms extended.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","As you lower the dumbbells, rotate your wrists so that your palms face forward at the bottom of the movement.","Reverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles together at the top.","Repeat for the desired number of repetitions."],"img":"0331-1PLE8e9.jpg","gif":"0331-1PLE8e9.gif"},{"id":"1733","n":"dumbbell incline two arm extension","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Sit on an incline bench with a dumbbell in each hand, resting on your thighs.","Slowly lie back on the bench, keeping the dumbbells close to your chest.","Once you are fully lying down, extend your arms straight up towards the ceiling, keeping your elbows slightly bent.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1733-U7D9Fx3.jpg","gif":"1733-U7D9Fx3.gif"},{"id":"3541","n":"dumbbell incline y-raise","bp":"back","eq":"dumbbell","tg":"upper back","mg":"shoulders","sm":["shoulders","rear deltoids"],"st":["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.","Lean forward slightly and let your arms hang straight down, keeping a slight bend in your elbows.","Raise your arms out to the sides and up in a Y shape until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"img":"3541-PbzNu7c.jpg","gif":"3541-PbzNu7c.gif","ty":"rin"},{"id":"0332","n":"dumbbell iron cross","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","chest"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Raise your arms out to the sides until they are parallel to the ground, forming a T shape with your body.","Pause for a moment, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0332-cALkHHX.jpg","gif":"0332-cALkHHX.gif"},{"id":"0333","n":"dumbbell kickback","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Bring your upper arms close to your sides, with your elbows bent at a 90-degree angle.","Extend your arms straight back, squeezing your triceps at the top of the movement.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0333-W6PxUkg.jpg","gif":"0333-W6PxUkg.gif"},{"id":"1734","n":"dumbbell kickbacks on exercise ball","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","back"],"st":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing inwards and your arms bent at a 90-degree angle.","Extend your arms straight back, squeezing your triceps at the top of the movement.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"1734-cAvTaSg.jpg","gif":"1734-cAvTaSg.gif"},{"id":"1660","n":"dumbbell kneeling bicep curl exercise ball","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Kneel on the floor with an exercise ball in front of you.","Place your elbows on top of the exercise ball, holding a dumbbell in each hand with your palms facing up.","Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"1660-2JCuFTU.jpg","gif":"1660-2JCuFTU.gif"},{"id":"0334","n":"dumbbell lateral raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps"],"st":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Keep your back straight and engage your core.","Raise your arms out to the sides until they are parallel to the floor, keeping a slight bend in your elbows.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0334-DsgkuIt.jpg","gif":"0334-DsgkuIt.gif"},{"id":"0335","n":"dumbbell lateral to front raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","biceps"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.","Keep your back straight and engage your core.","Raise your arms out to the sides until they are parallel to the ground, keeping a slight bend in your elbows.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Next, raise your arms in front of you until they are parallel to the ground, again keeping a slight bend in your elbows.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0335-xMjBKwn.jpg","gif":"0335-xMjBKwn.gif"},{"id":"0336","n":"dumbbell lunge","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step forward with your right foot, lowering your body into a lunge position.","Keep your back straight and your chest up as you lower your body.","Push through your right heel to return to the starting position.","Repeat with your left leg.","Alternate legs for the desired number of repetitions."],"img":"0336-RRWFUcw.jpg","gif":"0336-RRWFUcw.gif"},{"id":"1658","n":"dumbbell lunge with bicep curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"quadriceps","sm":["quadriceps","hamstrings"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.","Take a step forward with your right foot, lowering your body into a lunge position. Your right knee should be bent at a 90-degree angle and your left knee should be hovering just above the ground.","As you lunge forward, simultaneously curl the dumbbells towards your shoulders, keeping your elbows close to your body.","Pause for a moment at the bottom of the lunge, then push through your right heel to return to the starting position, lowering the dumbbells back down to your sides.","Repeat the lunge and bicep curl on the opposite side, stepping forward with your left foot.","Continue alternating sides for the desired number of repetitions."],"img":"1658-Mz6lLcW.jpg","gif":"1658-Mz6lLcW.gif"},{"id":"0337","n":"dumbbell lying extension (across face)","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold a dumbbell with both hands and extend your arms straight up above your chest, palms facing each other.","Keeping your upper arms stationary, slowly lower the dumbbell in an arc behind your head until your forearms are parallel to the ground.","Pause for a moment, then contract your triceps to bring the dumbbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"0337-L2V5Nan.jpg","gif":"0337-L2V5Nan.gif"},{"id":"1729","n":"dumbbell lying alternate extension","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight up over your chest, keeping a slight bend in your elbows.","Lower one dumbbell down towards your head, bending at the elbow, while keeping the other arm extended.","Pause for a moment at the bottom, then raise the dumbbell back up to the starting position.","Repeat with the other arm, alternating sides for the desired number of repetitions."],"img":"1729-NfP83rA.jpg","gif":"1729-NfP83rA.gif"},{"id":"0338","n":"dumbbell lying elbow press","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up over your chest.","Lower the dumbbells towards your shoulders by bending your elbows, keeping your upper arms stationary.","Pause for a moment at the bottom, then press the dumbbells back up to the starting position by extending your elbows.","Repeat for the desired number of repetitions."],"img":"0338-eOCOwIR.jpg","gif":"0338-eOCOwIR.gif"},{"id":"0863","n":"dumbbell lying external shoulder rotation","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","triceps"],"st":["Lie on your side on a flat bench with your upper arm against your side and your elbow bent 90 degrees.","Hold a dumbbell in your hand with your palm facing down.","Keeping your upper arm against your side, slowly rotate your forearm upward as far as possible.","Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"0863-bmBf7LN.jpg","gif":"0863-bmBf7LN.gif","ty":"mob"},{"id":"0339","n":"dumbbell lying femoral","bp":"upper legs","eq":"dumbbell","tg":"hamstrings","mg":"glutes","sm":["glutes"],"st":["Lie flat on your back with your legs extended and a dumbbell resting on your lower abdomen.","Bend your knees and bring the dumbbell towards your glutes, keeping your feet flat on the ground.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"0339-FkBIE6a.jpg","gif":"0339-FkBIE6a.gif"},{"id":"0340","n":"dumbbell lying hammer press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up.","Lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle.","Press the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"0340-7gdLIXa.jpg","gif":"0340-7gdLIXa.gif"},{"id":"2470","n":"dumbbell lying on floor rear delt raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids"],"st":["Lie face down on the floor with a dumbbell in each hand, palms facing each other.","Extend your arms straight out in front of you, keeping a slight bend in your elbows.","Engaging your shoulder muscles, lift your arms up and out to the sides, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"img":"2470-Ion0XWz.jpg","gif":"2470-Ion0XWz.gif"},{"id":"0341","n":"dumbbell lying one arm deltoid rear","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids"],"st":["Lie face down on a flat bench with a dumbbell in one hand, palm facing inwards.","Extend your arm straight down towards the floor, keeping it close to your body.","Raise your arm up and back, squeezing your shoulder blade towards your spine.","Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"0341-gSw59a4.jpg","gif":"0341-gSw59a4.gif"},{"id":"0343","n":"dumbbell lying one arm press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Lie flat on a bench with a dumbbell in one hand and your feet flat on the ground.","Hold the dumbbell at shoulder level with your palm facing forward.","Press the dumbbell upward until your arm is fully extended.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"img":"0343-zGSIWQi.jpg","gif":"0343-zGSIWQi.gif"},{"id":"0342","n":"dumbbell lying one arm press v. 2","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Lie flat on a bench with your back supported and feet flat on the ground.","Hold a dumbbell in one hand with your palm facing towards your feet.","Extend your arm straight up towards the ceiling, keeping your elbow slightly bent.","Slowly lower the dumbbell down towards your chest, keeping your elbow close to your body.","Pause for a moment at the bottom, then push the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"img":"0342-K3dIO25.jpg","gif":"0342-K3dIO25.gif"},{"id":"0344","n":"dumbbell lying one arm pronated triceps extension","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Lie flat on a bench with your back and head supported, and your feet flat on the ground.","Hold a dumbbell in one hand with your palm facing down, and extend your arm straight up above your shoulder.","Keeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow.","Pause for a moment at the bottom, then extend your arm back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"0344-wyaqzOS.jpg","gif":"0344-wyaqzOS.gif"},{"id":"0345","n":"dumbbell lying one arm rear lateral raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps","rhomboids"],"st":["Lie face down on a flat bench with a dumbbell in one hand, hanging towards the floor.","Keep your arm straight and lift the dumbbell out to the side, away from your body.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"img":"0345-KwFGiEP.jpg","gif":"0345-KwFGiEP.gif"},{"id":"0346","n":"dumbbell lying one arm supinated triceps extension","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"forearms","sm":["forearms"],"st":["Lie flat on a bench with your back and head supported, and your feet flat on the ground.","Hold a dumbbell in one hand with an underhand grip, and extend your arm straight up above your shoulder.","Keeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow.","Pause for a moment at the bottom, then extend your arm back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"0346-zZlORz6.jpg","gif":"0346-zZlORz6.gif"},{"id":"0347","n":"dumbbell lying pronation","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"biceps","sm":["biceps","shoulders"],"st":["Lie flat on a bench with your chest facing down and your arms extended straight down, holding a dumbbell in each hand.","Rotate your palms so they are facing up.","Keeping your upper arms stationary, exhale and curl the dumbbells as you rotate your palms to face down.","Inhale and slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0347-mym4hJo.jpg","gif":"0347-mym4hJo.gif","ty":"rin"},{"id":"2705","n":"dumbbell lying pronation on floor","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"biceps","sm":["biceps","triceps"],"st":["Lie flat on the floor with your face down and your arms extended straight out in front of you, holding a dumbbell in each hand.","Rotate your palms so they are facing down towards the floor.","Keeping your arms straight, lift the dumbbells off the floor by contracting your forearms.","Continue lifting until your forearms are fully contracted and the dumbbells are at shoulder level.","Hold for a moment, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"img":"2705-7RWNjiB.jpg","gif":"2705-7RWNjiB.gif","ty":"rin"},{"id":"1284","n":"dumbbell lying pullover on exercise ball","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","back"],"st":["Sit on an exercise ball and roll forward until your upper back is resting on the ball.","Hold a dumbbell with both hands and extend your arms straight up over your chest.","Slowly lower the dumbbell behind your head while keeping your arms straight.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"1284-iK59oEA.jpg","gif":"1284-iK59oEA.gif"},{"id":"1328","n":"dumbbell lying rear delt row","bp":"back","eq":"dumbbell","tg":"upper back","mg":"shoulders","sm":["shoulders","biceps"],"st":["Lie face down on a flat bench with a dumbbell in each hand, palms facing inwards.","Extend your arms straight down towards the floor, keeping a slight bend in your elbows.","Engaging your back muscles, lift the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1328-XUUD0Fs.jpg","gif":"1328-XUUD0Fs.gif"},{"id":"0348","n":"dumbbell lying rear lateral raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps","rhomboids"],"st":["Lie face down on a flat bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight down towards the floor, keeping a slight bend in your elbows.","Engaging your shoulder muscles, lift your arms out to the sides until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0348-53Ttlck.jpg","gif":"0348-53Ttlck.gif"},{"id":"1735","n":"dumbbell lying single extension","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Lie flat on a bench with a dumbbell in one hand and your arm fully extended above your chest.","Lower the dumbbell in a controlled manner towards your forehead, keeping your upper arm stationary.","Pause briefly at the bottom of the movement, then extend your arm back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1735-6MfS53i.jpg","gif":"1735-6MfS53i.gif"},{"id":"0349","n":"dumbbell lying supination","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"biceps","sm":["biceps","shoulders"],"st":["Lie flat on a bench with your feet flat on the ground.","Hold a dumbbell in each hand with your palms facing up and your arms fully extended.","Keeping your upper arms stationary, curl the dumbbells towards your shoulders by contracting your forearms.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0349-M2Pm3zj.jpg","gif":"0349-M2Pm3zj.gif","ty":"rin"},{"id":"2706","n":"dumbbell lying supination on floor","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"biceps","sm":["biceps","shoulders"],"st":["Lie flat on your back on the floor with your legs extended and your arms by your sides, holding a dumbbell in each hand.","Rotate your palms to face up, keeping your elbows close to your sides.","Slowly curl the dumbbells towards your shoulders, squeezing your forearms.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"img":"2706-rEhi2o5.jpg","gif":"2706-rEhi2o5.gif","ty":"rin"},{"id":"1661","n":"dumbbell lying supine biceps curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Lie flat on a bench with your back and head supported, and your feet flat on the ground.","Hold a dumbbell in each hand with your palms facing up and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"1661-XVzF3iZ.jpg","gif":"1661-XVzF3iZ.gif"},{"id":"0350","n":"dumbbell lying supine curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Lie flat on a bench with a dumbbell in each hand, palms facing up and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0350-KUaZst7.jpg","gif":"0350-KUaZst7.gif"},{"id":"0351","n":"dumbbell lying triceps extension","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight up over your chest, keeping your elbows close to your body.","Lower the dumbbells down towards your forehead, bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0351-mpKZGWz.jpg","gif":"0351-mpKZGWz.gif"},{"id":"1662","n":"dumbbell lying wide curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Lie flat on a bench with a dumbbell in each hand, palms facing up and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"1662-qm9veZw.jpg","gif":"1662-qm9veZw.gif"},{"id":"0352","n":"dumbbell neutral grip bench press","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Hold a dumbbell in each hand with a neutral grip (palms facing each other) and your arms extended straight up over your chest.","Slowly lower the dumbbells down towards your chest, keeping your elbows close to your body.","Pause for a moment at the bottom, then push the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"0352-pP8wP2P.jpg","gif":"0352-pP8wP2P.gif"},{"id":"1285","n":"dumbbell one arm bench fly","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders"],"st":["Sit on a flat bench with a dumbbell in one hand, resting it on top of your thigh.","Lie back on the bench, keeping the dumbbell pressed against your thigh.","Using your free hand, help lift the dumbbell up to the starting position.","Hold the dumbbell directly above your shoulder with your arm extended and palm facing inward.","Lower the dumbbell out to the side in a wide arc, keeping a slight bend in your elbow.","Pause when your arm is parallel to the ground, then reverse the movement and bring the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms and repeat."],"img":"1285-o5Jsk92.jpg","gif":"1285-o5Jsk92.gif"},{"id":"0292","n":"dumbbell one arm bent-over row","bp":"back","eq":"dumbbell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing your body.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.","Let the dumbbell hang straight down towards the floor, with your arm fully extended.","Pull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"0292-C0MA9bC.jpg","gif":"0292-C0MA9bC.gif"},{"id":"1286","n":"dumbbell one arm chest fly on exercise ball","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground.","Walk your feet forward, rolling the ball until your upper back is supported on the ball and your head, neck, and shoulders are off the ball.","Extend your arm with the dumbbell straight up above your chest, palm facing inward.","Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.","Pause for a moment when your arm is parallel to the ground.","Engage your chest muscles to bring the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1286-Bpkf41o.jpg","gif":"1286-Bpkf41o.gif"},{"id":"0353","n":"dumbbell one arm concentration curl (on stability ball)","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell in one hand with your palm facing up and your arm extended down towards the floor.","Rest your elbow on the inside of your thigh, just above the knee.","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder while contracting your biceps.","Pause for a moment at the top of the movement, then inhale and slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms and repeat."],"img":"0353-k5IpyHg.jpg","gif":"0353-k5IpyHg.gif"},{"id":"1287","n":"dumbbell one arm decline chest press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Lie on a decline bench with a dumbbell in one hand, resting on your chest.","Place your feet flat on the ground and keep your back pressed against the bench.","Extend your arm and push the dumbbell up towards the ceiling, fully extending your elbow.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"img":"1287-REGM1dE.jpg","gif":"1287-REGM1dE.gif"},{"id":"1288","n":"dumbbell one arm fly on exercise ball","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground.","Walk your feet forward and roll your body down until your upper back is resting on the exercise ball.","Extend your arm with the dumbbell straight up above your chest, palm facing inwards.","Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.","Pause for a moment, then squeeze your chest muscles to bring the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1288-Am02iPd.jpg","gif":"1288-Am02iPd.gif"},{"id":"1736","n":"dumbbell one arm french press on exercise ball","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing up and your elbow bent at a 90-degree angle.","Extend your arm straight up towards the ceiling, keeping your elbow stationary.","Slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1736-ziFKQXP.jpg","gif":"1736-ziFKQXP.gif"},{"id":"1663","n":"dumbbell one arm hammer preacher curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a preacher bench with a dumbbell in one hand and your upper arm resting on the pad.","Hold the dumbbell with a neutral grip (palms facing your body).","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1663-4dF3maG.jpg","gif":"1663-4dF3maG.gif"},{"id":"1621","n":"dumbbell one arm hammer press on exercise ball","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","chest"],"st":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing inwards and your elbow bent at a 90-degree angle.","Place your other hand on your hip for stability.","Press the dumbbell upwards, extending your arm fully.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1621-VYmYxK5.jpg","gif":"1621-VYmYxK5.gif"},{"id":"1289","n":"dumbbell one arm incline chest press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Adjust the incline bench to a 45-degree angle.","Sit on the bench with your back against the pad and feet flat on the ground.","Hold a dumbbell in one hand with an overhand grip, resting it on your shoulder.","Push the dumbbell up and away from your body, extending your arm fully.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"img":"1289-PDaMuyV.jpg","gif":"1289-PDaMuyV.gif"},{"id":"0354","n":"dumbbell one arm kickback","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Stand with your feet shoulder-width apart and hold a dumbbell in your right hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Bring your right elbow up to your side, keeping it bent at a 90-degree angle.","Extend your right arm straight back, squeezing your triceps at the top of the movement.","Slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"0354-bQy2Eni.jpg","gif":"0354-bQy2Eni.gif"},{"id":"0355","n":"dumbbell one arm lateral raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","triceps"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing your body.","Keep your back straight and your core engaged throughout the exercise.","Raise the dumbbell to the side, keeping your arm straight and your palm facing down.","Continue lifting until your arm is parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"img":"0355-n5cWCsI.jpg","gif":"0355-n5cWCsI.gif"},{"id":"0356","n":"dumbbell one arm lateral raise with support","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rotator cuff"],"st":["Stand with your feet shoulder-width apart and hold a dumbbell in one hand, with your palm facing your body.","Place your other hand on a stable surface, such as a bench or wall, for support.","Keep your back straight and engage your core.","Raise the dumbbell out to the side, keeping your arm straight and your palm facing down.","Continue lifting until your arm is parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"0356-Yg7MJAT.jpg","gif":"0356-Yg7MJAT.gif"},{"id":"1290","n":"dumbbell one arm press on exercise ball","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps","core"],"st":["Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell in one hand and position it at shoulder height, with your elbow bent and palm facing forward.","Slowly press the dumbbell upward until your arm is fully extended, while keeping your core engaged and maintaining balance on the exercise ball.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"img":"1290-QZFv5ui.jpg","gif":"1290-QZFv5ui.gif"},{"id":"1665","n":"dumbbell one arm prone curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Lie face down on a flat bench with a dumbbell in one hand, palm facing down.","Extend your arm fully, letting it hang straight down towards the floor.","Keeping your upper arm stationary, curl the dumbbell up towards your shoulder by contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1665-JWjujiY.jpg","gif":"1665-JWjujiY.gif"},{"id":"1666","n":"dumbbell one arm prone hammer curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Lie face down on a flat bench with a dumbbell in one hand, palm facing your body and arm fully extended.","Keep your upper arm stationary and curl the dumbbell towards your shoulder, contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1666-LIGZSTA.jpg","gif":"1666-LIGZSTA.gif"},{"id":"1291","n":"dumbbell one arm pullover on exercise ball","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","latissimus dorsi","rhomboids"],"st":["Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell with one hand and extend your arm straight up above your chest.","Slowly lower the dumbbell behind your head while keeping your arm straight.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1291-bQHPBU3.jpg","gif":"1291-bQHPBU3.gif"},{"id":"0358","n":"dumbbell one arm reverse wrist curl","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"wrist extensors","sm":["wrist extensors"],"st":["Sit on a bench or chair with your feet flat on the ground.","Hold a dumbbell in one hand with an overhand grip, palm facing down.","Rest your forearm on your thigh, with your wrist hanging off the edge.","Slowly lower the dumbbell towards the ground by flexing your wrist.","Pause for a moment at the bottom, then slowly curl your wrist back up towards your body.","Repeat for the desired number of repetitions, then switch to the other arm."],"img":"0358-BwSNDGt.jpg","gif":"0358-BwSNDGt.gif"},{"id":"0359","n":"dumbbell one arm reverse fly (with support)","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids"],"st":["Sit on a bench with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing inwards.","Lean forward and place your free hand on the bench for support.","Keep your arm slightly bent and raise it out to the side until it is parallel to the ground.","Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"0359-e25F58f.jpg","gif":"0359-e25F58f.gif"},{"id":"1622","n":"dumbbell one arm reverse grip press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Sit on a flat bench with a dumbbell in one hand, palm facing towards your body.","Place your feet flat on the ground and keep your back straight.","Raise the dumbbell to shoulder height, keeping your elbow close to your body.","Press the dumbbell upwards until your arm is fully extended.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"img":"1622-Ze7MoIb.jpg","gif":"1622-Ze7MoIb.gif"},{"id":"1414","n":"dumbbell one arm reverse preacher curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a preacher bench with your chest against the pad and your arm extended over the edge of the bench, holding a dumbbell with an underhand grip.","Lower the dumbbell slowly until your arm is fully extended.","Curl the dumbbell back up towards your shoulder, keeping your upper arm stationary.","Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1414-bWxq4op.jpg","gif":"1414-bWxq4op.gif"},{"id":"1667","n":"dumbbell one arm reverse spider curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with a dumbbell in one hand, palm facing down and arm fully extended.","Keeping your upper arm stationary, curl the dumbbell towards your shoulder by flexing your elbow.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1667-VdLZ3nB.jpg","gif":"1667-VdLZ3nB.gif"},{"id":"1668","n":"dumbbell one arm seated bicep curl on exercise ball","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing up and your arm fully extended.","Keeping your upper arm stationary, curl the dumbbell towards your shoulder by contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1668-s999Hdo.jpg","gif":"1668-s999Hdo.gif"},{"id":"1669","n":"dumbbell one arm seated hammer curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in one hand with a neutral grip (palms facing each other).","Rest your elbow on the inside of your thigh, just above the knee.","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1669-jK2hZ6n.jpg","gif":"1669-jK2hZ6n.gif"},{"id":"1415","n":"dumbbell one arm seated neutral wrist curl","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"biceps","sm":["biceps","brachialis"],"st":["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up.","Rest your forearm on your thigh, allowing your wrist to hang off the edge.","Keeping your forearm stationary, curl your wrist upward as far as possible.","Pause for a moment at the top, then slowly lower your wrist back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other hand."],"img":"1415-YtaCTYl.jpg","gif":"1415-YtaCTYl.gif"},{"id":"0361","n":"dumbbell one arm shoulder press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Stand with your feet shoulder-width apart and hold a dumbbell in one hand at shoulder level, palm facing forward.","Press the dumbbell upward until your arm is fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"img":"0361-84RyJf8.jpg","gif":"0361-84RyJf8.gif"},{"id":"0360","n":"dumbbell one arm shoulder press v. 2","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Stand with your feet shoulder-width apart and hold a dumbbell in one hand at shoulder level, palm facing forward.","Engage your core and press the dumbbell straight up overhead, fully extending your arm.","Pause for a moment at the top, then slowly lower the dumbbell back to shoulder level.","Repeat for the desired number of repetitions, then switch to the other arm."],"img":"0360-1TkiAFK.jpg","gif":"0360-1TkiAFK.gif"},{"id":"3888","n":"dumbbell one arm snatch","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","core"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Lower the dumbbell towards the ground, keeping it close to your body.","Explosively extend your hips, knees, and ankles, driving the dumbbell upwards in a straight line.","As the dumbbell reaches shoulder height, quickly rotate your hand and punch it overhead, fully extending your arm.","Catch the dumbbell overhead with a slight bend in your knees and hips.","Lower the dumbbell back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions, then switch to the other arm."],"img":"3888-6pTkI99.jpg","gif":"3888-6pTkI99.gif"},{"id":"1670","n":"dumbbell one arm standing curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with a dumbbell in one hand, palm facing forward and arm fully extended.","Keeping your upper arm stationary, exhale and curl the weight upward while contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1670-ffQsyBj.jpg","gif":"1670-ffQsyBj.gif"},{"id":"1671","n":"dumbbell one arm standing hammer curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"1671-2sQGZ5b.jpg","gif":"1671-2sQGZ5b.gif"},{"id":"0362","n":"dumbbell one arm triceps extension (on bench)","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in one hand and place your other hand on the bench for support.","Raise the dumbbell overhead, keeping your upper arm close to your head and your elbow pointing forward.","Lower the dumbbell behind your head by bending your elbow, keeping your upper arm stationary.","Extend your arm back up to the starting position, fully straightening your elbow.","Repeat for the desired number of repetitions, then switch arms."],"img":"0362-nAuHPcD.jpg","gif":"0362-nAuHPcD.gif"},{"id":"0363","n":"dumbbell one arm upright row","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps","biceps"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with an overhand grip.","Let the dumbbell hang at arm's length in front of your thighs, with your palm facing your body.","Keeping your back straight and your core engaged, exhale and lift the dumbbell straight up towards your chin, leading with your elbow.","Pause for a moment at the top, then inhale and slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"img":"0363-6cKQC5E.jpg","gif":"0363-6cKQC5E.gif"},{"id":"0364","n":"dumbbell one arm wrist curl","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"biceps","sm":["biceps","brachialis"],"st":["Sit on a bench or chair with your feet flat on the ground.","Hold a dumbbell in one hand with an underhand grip, resting your forearm on your thigh.","Allow your wrist to extend, letting the dumbbell roll down towards your fingers.","Slowly curl your wrist back up, bringing the dumbbell towards your forearm.","Repeat for the desired number of repetitions, then switch to the other hand."],"img":"0364-q8aHNoF.jpg","gif":"0364-q8aHNoF.gif"},{"id":"1672","n":"dumbbell one arm zottman preacher curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a preacher curl bench and hold a dumbbell in one hand with an underhand grip.","Rest your upper arm on the preacher bench pad, allowing your arm to fully extend.","Curl the dumbbell up towards your shoulder, keeping your upper arm stationary.","At the top of the curl, rotate your wrist so that your palm faces up.","Slowly lower the dumbbell back down to the starting position, rotating your wrist back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1672-sxY5Biu.jpg","gif":"1672-sxY5Biu.gif"},{"id":"1292","n":"dumbbell one leg fly on exercise ball","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Sit on an exercise ball with a dumbbell in each hand, palms facing each other.","Place one foot on the ground and extend the other leg straight out in front of you.","Lean forward slightly and bring your arms out to the sides, keeping a slight bend in your elbows.","Slowly lower the dumbbells down and out to the sides, feeling a stretch in your chest.","Pause for a moment at the bottom, then squeeze your chest muscles to bring the dumbbells back up to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."],"img":"1292-pH2x2jj.jpg","gif":"1292-pH2x2jj.gif"},{"id":"0365","n":"dumbbell over bench neutral wrist curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Rest your forearms on the bench, allowing your wrists to hang off the edge.","Keeping your upper arms stationary, exhale and curl the dumbbells up towards your shoulders.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0365-BKa8dmT.jpg","gif":"0365-BKa8dmT.gif"},{"id":"0366","n":"dumbbell over bench one arm neutral wrist curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a bench with a dumbbell in one hand and your arm extended over the bench, palm facing up.","Keep your upper arm stationary and curl the dumbbell towards your shoulder, keeping your wrist in a neutral position.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"0366-IvV6C9M.jpg","gif":"0366-IvV6C9M.gif"},{"id":"1441","n":"dumbbell over bench one arm reverse wrist curl","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"biceps","sm":["biceps","brachialis"],"st":["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down.","Rest your forearm on the bench with your wrist hanging off the edge.","Slowly curl your wrist upwards, bringing the dumbbell towards your forearm.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"img":"1441-4Jc36XM.jpg","gif":"1441-4Jc36XM.gif"},{"id":"0367","n":"dumbbell over bench one arm wrist curl","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"biceps","sm":["biceps","shoulders"],"st":["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down.","Rest your forearm on the bench with your wrist hanging off the edge.","Slowly curl your wrist upwards, bringing the dumbbell towards your forearm.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"img":"0367-KI1DjNN.jpg","gif":"0367-KI1DjNN.gif"},{"id":"0368","n":"dumbbell over bench revers wrist curl","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"biceps","sm":["biceps","brachialis"],"st":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing down.","Rest your forearms on the bench, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, bringing the dumbbells towards your body.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0368-3tAXPQ6.jpg","gif":"0368-3tAXPQ6.gif"},{"id":"0369","n":"dumbbell over bench wrist curl","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"biceps","sm":["biceps","brachialis"],"st":["Sit on a bench with your forearms resting on the bench and your palms facing up, holding a dumbbell in each hand.","Allow your wrists to hang over the edge of the bench.","Slowly curl your wrists upward, squeezing your forearms at the top of the movement.","Pause for a moment, then slowly lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0369-D1xYJAU.jpg","gif":"0369-D1xYJAU.gif"},{"id":"1329","n":"dumbbell palm rotational bent over row","bp":"back","eq":"dumbbell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Bend forward at the hips, keeping your back straight and your knees slightly bent.","Let your arms hang straight down, palms facing your body.","Engage your core and pull the dumbbells up towards your chest, keeping your elbows close to your body.","As you pull the dumbbells up, rotate your palms so they face away from your body.","Squeeze your shoulder blades together at the top of the movement.","Slowly lower the dumbbells back down to the starting position, rotating your palms back to the starting position.","Repeat for the desired number of repetitions."],"img":"1329-wt6rwjk.jpg","gif":"1329-wt6rwjk.gif","ty":"mob"},{"id":"1623","n":"dumbbell palms in incline bench press","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Set up an incline bench at a 45-degree angle.","Sit on the bench with your back against the backrest and feet flat on the ground.","Hold a dumbbell in each hand with an overhand grip, palms facing inwards.","Extend your arms straight up above your chest, keeping a slight bend in your elbows.","Lower the dumbbells slowly towards your shoulders, keeping your elbows close to your body.","Pause for a moment at the bottom, then press the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."],"img":"1623-8eqjhOl.jpg","gif":"1623-8eqjhOl.gif"},{"id":"0370","n":"dumbbell peacher hammer curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","This will be your starting position.","Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."],"img":"0370-F1KxjBa.jpg","gif":"0370-F1KxjBa.gif"},{"id":"0371","n":"dumbbell plyo squat","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Lower your body into a squat position by bending your knees and pushing your hips back.","As you reach the bottom of the squat, explode upward, jumping off the ground.","While in the air, quickly switch the position of your feet, landing with your opposite foot forward.","Immediately lower your body back into a squat position and repeat the jump, switching your feet again.","Continue alternating the position of your feet with each jump for the desired number of repetitions."],"img":"0371-S4pwGlc.jpg","gif":"0371-S4pwGlc.gif"},{"id":"0372","n":"dumbbell preacher curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a preacher curl bench with your upper arms resting on the pad and your chest against it.","Hold a dumbbell in each hand with your palms facing up and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0372-jivWf8n.jpg","gif":"0372-jivWf8n.gif"},{"id":"1673","n":"dumbbell preacher curl over exercise ball","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with an underhand grip, resting your elbow on the exercise ball.","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1673-hwygydB.jpg","gif":"1673-hwygydB.gif"},{"id":"1293","n":"dumbbell press on exercise ball","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Sit on an exercise ball with your feet flat on the ground and dumbbells in each hand, resting on your thighs.","Slowly walk your feet forward, rolling the exercise ball until your lower back is supported on the ball and your knees are at a 90-degree angle.","Raise the dumbbells to shoulder height, palms facing forward.","Press the dumbbells upward until your arms are fully extended.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"1293-O8o7q4d.jpg","gif":"1293-O8o7q4d.gif"},{"id":"0373","n":"dumbbell pronate-grip triceps extension","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"forearms","sm":["forearms"],"st":["Sit on a bench or chair with your back straight and feet flat on the ground.","Hold a dumbbell with both hands, palms facing down, and extend your arms straight up overhead.","Keeping your upper arms close to your head and elbows pointing forward, slowly lower the dumbbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0373-bpJL2Qs.jpg","gif":"0373-bpJL2Qs.gif"},{"id":"0374","n":"dumbbell prone incline curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Adjust the bench to a 45-degree incline.","Lie face down on the bench with your chest and stomach resting against it.","Hold a dumbbell in each hand with your palms facing down and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0374-mwpPcr1.jpg","gif":"0374-mwpPcr1.gif"},{"id":"1674","n":"dumbbell prone incline hammer curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Adjust the bench to a 45-degree incline.","Lie face down on the bench with a dumbbell in each hand, palms facing each other.","Allow your arms to hang straight down towards the floor, keeping your elbows slightly bent.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"1674-cWemPG8.jpg","gif":"1674-cWemPG8.gif"},{"id":"0375","n":"dumbbell pullover","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"latissimus dorsi","sm":["latissimus dorsi","triceps"],"st":["Lie flat on a bench with your head at one end and your feet on the floor.","Hold a dumbbell with both hands and extend your arms straight above your chest.","Keeping a slight bend in your elbows, slowly lower the dumbbell behind your head until you feel a stretch in your chest and shoulders.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"0375-9XjtHvS.jpg","gif":"0375-9XjtHvS.gif"},{"id":"1294","n":"dumbbell pullover hip extension on exercise ball","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Sit on an exercise ball with your feet flat on the ground and the dumbbell resting on your thighs.","Slowly walk your feet forward, rolling the exercise ball down your back until your head, neck, and upper back are supported on the ball.","Hold the dumbbell with both hands and extend your arms straight up over your chest, keeping a slight bend in your elbows.","Lower the dumbbell behind your head, keeping your arms straight and maintaining control.","Pause for a moment, then raise the dumbbell back to the starting position.","While keeping your arms extended, lift your hips off the ground, squeezing your glutes and engaging your core.","Lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1294-lI7easp.jpg","gif":"1294-lI7easp.gif"},{"id":"1295","n":"dumbbell pullover on exercise ball","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","latissimus dorsi"],"st":["Sit on an exercise ball and hold a dumbbell with both hands above your chest, arms extended.","Slowly lower the dumbbell behind your head while keeping your arms straight.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"1295-FSD6PGL.jpg","gif":"1295-FSD6PGL.gif"},{"id":"1700","n":"dumbbell push press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level.","Bend your knees slightly and dip your body down, then explosively extend your legs and press the dumbbells overhead.","Lock out your arms at the top of the movement, then lower the dumbbells back to shoulder level.","Repeat for the desired number of repetitions."],"img":"1700-FS63wTN.jpg","gif":"1700-FS63wTN.gif"},{"id":"0376","n":"dumbbell raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps","rhomboids"],"st":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Keep your back straight and engage your core.","Raise your arms out to the sides until they are parallel to the floor, keeping a slight bend in your elbows.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0376-c9MnDRp.jpg","gif":"0376-c9MnDRp.gif"},{"id":"2292","n":"dumbbell rear delt raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids"],"st":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"img":"2292-mu5Guxt.jpg","gif":"2292-mu5Guxt.gif"},{"id":"0377","n":"dumbbell rear delt row_shoulder","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids"],"st":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold a dumbbell in each hand with your palms facing your body.","Bend forward at the waist, keeping your back straight and your core engaged.","Extend your arms straight down towards the floor, with a slight bend in your elbows.","Raise the dumbbells out to the sides, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0377-EKXOMEh.jpg","gif":"0377-EKXOMEh.gif"},{"id":"0378","n":"dumbbell rear fly","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids"],"st":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms straight down towards the ground, palms facing each other.","Keeping a slight bend in your elbows, lift your arms out to the sides and squeeze your shoulder blades together.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0378-8DiFDVA.jpg","gif":"0378-8DiFDVA.gif"},{"id":"0380","n":"dumbbell rear lateral raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps","rhomboids"],"st":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and core engaged.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0380-v1qBec9.jpg","gif":"0380-v1qBec9.gif"},{"id":"0379","n":"dumbbell rear lateral raise (support head)","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps","rhomboids"],"st":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0379-UzkLrem.jpg","gif":"0379-UzkLrem.gif"},{"id":"0381","n":"dumbbell rear lunge","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step backward with your right foot, lowering your body into a lunge position.","Bend your left knee and lower your body until your left thigh is parallel to the ground.","Pause for a moment, then push through your left heel to return to the starting position.","Repeat on the other side, stepping back with your left foot."],"img":"0381-SSsBDwB.jpg","gif":"0381-SSsBDwB.gif"},{"id":"0382","n":"dumbbell revers grip biceps curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with a dumbbell in each hand, palms facing down and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0382-e4ojVhP.jpg","gif":"0382-e4ojVhP.gif"},{"id":"1624","n":"dumbbell reverse bench press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Lie flat on a bench with your feet flat on the ground and your knees bent.","Hold a dumbbell in each hand with an overhand grip, palms facing towards your feet.","Extend your arms straight up towards the ceiling, keeping a slight bend in your elbows.","Slowly lower the dumbbells towards your chest, allowing your elbows to flare out to the sides.","Pause for a moment at the bottom, then push the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."],"img":"1624-UIbGx6H.jpg","gif":"1624-UIbGx6H.gif"},{"id":"0383","n":"dumbbell reverse fly","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids"],"st":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms straight down in front of you, palms facing each other.","Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0383-EAs3xL9.jpg","gif":"0383-EAs3xL9.gif"},{"id":"1330","n":"dumbbell reverse grip incline bench one arm row","bp":"back","eq":"dumbbell","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Set up an incline bench at a 45-degree angle.","Place a dumbbell on the floor next to the bench.","Stand facing the bench with your feet shoulder-width apart.","Bend at the waist and place your left knee and left hand on the bench for support.","Pick up the dumbbell with your right hand using a reverse grip (palm facing down).","Keep your back straight and your core engaged.","Pull the dumbbell up towards your chest, keeping your elbow close to your body.","Squeeze your back muscles at the top of the movement.","Lower the dumbbell back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions.","Switch sides and repeat the exercise with your left arm."],"img":"1330-ZIViNh1.jpg","gif":"1330-ZIViNh1.gif"},{"id":"1331","n":"dumbbell reverse grip incline bench two arm row","bp":"back","eq":"dumbbell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Set up an incline bench at a 45-degree angle.","Sit on the bench with your chest against the backrest and your feet flat on the ground.","Hold a dumbbell in each hand with an underhand grip.","Lean forward and let your arms hang straight down, fully extended.","Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1331-9pQSkH8.jpg","gif":"1331-9pQSkH8.gif"},{"id":"2327","n":"dumbbell reverse grip row (female)","bp":"back","eq":"dumbbell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold a dumbbell in each hand with an overhand grip, palms facing your body.","Bend forward at the waist, keeping your back straight and your core engaged.","Let your arms hang straight down, fully extended, with a slight bend in your elbows.","Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"img":"2327-Nh3mvOO.jpg","gif":"2327-Nh3mvOO.gif"},{"id":"0384","n":"dumbbell reverse preacher curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a preacher bench with your upper arms resting on the pad and your chest against the support.","Hold a dumbbell in each hand with an underhand grip, palms facing up.","Keeping your upper arms stationary, exhale and curl the dumbbells as you contract your biceps.","Continue to curl the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0384-O8Aq69u.jpg","gif":"0384-O8Aq69u.gif"},{"id":"1675","n":"dumbbell reverse spider curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with a dumbbell in each hand, palms facing your body and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"1675-6sMAmNv.jpg","gif":"1675-6sMAmNv.gif"},{"id":"0385","n":"dumbbell reverse wrist curl","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"biceps","sm":["biceps","brachialis"],"st":["Sit on a bench or chair with your feet flat on the ground.","Hold a dumbbell in each hand with an overhand grip, palms facing down.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, bringing the dumbbells towards your body.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0385-BLCvwr2.jpg","gif":"0385-BLCvwr2.gif"},{"id":"1459","n":"dumbbell romanian deadlift","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your knees to bend slightly.","Lower the dumbbells until you feel a stretch in your hamstrings, then push through your heels and engage your glutes to return to the starting position.","Repeat for the desired number of repetitions."],"img":"1459-rR0LJzx.jpg","gif":"1459-rR0LJzx.gif"},{"id":"0386","n":"dumbbell rotation reverse fly","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids"],"st":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing inwards.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.","Rotate your arms so that your palms are facing downwards.","Slowly lower your arms back to the starting position.","Repeat for the desired number of repetitions."],"img":"0386-prbWx1D.jpg","gif":"0386-prbWx1D.gif"},{"id":"2397","n":"dumbbell scott press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","chest"],"st":["Sit on a bench with a dumbbell in each hand, palms facing forward.","Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.","Press the dumbbells upward until your arms are fully extended.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"2397-5vfAI0I.jpg","gif":"2397-5vfAI0I.gif"},{"id":"0387","n":"dumbbell seated alternate front raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","biceps"],"st":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in each hand with your palms facing your body and arms extended down by your sides.","Keeping your arms straight, raise one dumbbell in front of you until it is parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat with the other arm.","Alternate between arms for the desired number of repetitions."],"img":"0387-gH5fRsC.jpg","gif":"0387-gH5fRsC.gif"},{"id":"1676","n":"dumbbell seated alternate hammer curl on exercise ball","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing your body and your arms fully extended.","Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while keeping your palm facing your body.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the movement with the opposite arm.","Continue alternating arms for the desired number of repetitions."],"img":"1676-QLRmNeT.jpg","gif":"1676-QLRmNeT.gif"},{"id":"0388","n":"dumbbell seated alternate press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","chest"],"st":["Sit on a bench with a dumbbell in each hand, palms facing forward.","Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.","Press one dumbbell up overhead, fully extending your arm.","Lower the dumbbell back down to shoulder height.","Repeat with the other arm.","Continue alternating arms for the desired number of repetitions."],"img":"0388-QT5Q0nK.jpg","gif":"0388-QT5Q0nK.gif"},{"id":"3546","n":"dumbbell seated alternate shoulder","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in each hand, palms facing inwards, and raise them to shoulder height.","Press one dumbbell up overhead while keeping the other dumbbell at shoulder height.","Lower the raised dumbbell back to shoulder height while simultaneously pressing the other dumbbell up overhead.","Continue alternating between arms for the desired number of repetitions."],"img":"3546-q7qkONO.jpg","gif":"3546-q7qkONO.gif"},{"id":"0389","n":"dumbbell seated bench extension","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell with both hands and extend your arms straight up above your head.","Slowly lower the dumbbell behind your head, keeping your elbows close to your ears.","Pause for a moment, then raise the dumbbell back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0389-JhYSVwT.jpg","gif":"0389-JhYSVwT.gif"},{"id":"2317","n":"dumbbell seated bent arm lateral raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids"],"st":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in each hand with your palms facing your body and your arms bent at a 90-degree angle.","Keeping your elbows bent, raise your arms out to the sides until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"img":"2317-JzQbv7J.jpg","gif":"2317-JzQbv7J.gif"},{"id":"1730","n":"dumbbell seated bent over alternate kickback","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","back"],"st":["Sit on a bench with a dumbbell in each hand, palms facing inwards.","Bend forward at the waist, keeping your back straight and parallel to the ground.","Extend one arm straight back, keeping it close to your body, until your arm is fully extended.","Pause for a moment, then slowly lower the dumbbell back to the starting position.","Repeat with the other arm.","Continue alternating arms for the desired number of repetitions."],"img":"1730-x0lwvfq.jpg","gif":"1730-x0lwvfq.gif"},{"id":"1737","n":"dumbbell seated bent over triceps extension","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","back"],"st":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand.","Bend forward at the waist, keeping your back straight and your head up.","Extend your arms straight back, keeping your elbows close to your head.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"1737-4ievMJ9.jpg","gif":"1737-4ievMJ9.gif"},{"id":"1677","n":"dumbbell seated bicep curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Keep your back straight and your elbows close to your torso.","Exhale and curl the dumbbells up towards your shoulders, contracting your biceps.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1677-xiA6lRr.jpg","gif":"1677-xiA6lRr.gif"},{"id":"0390","n":"dumbbell seated biceps curl (on stability ball)","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0390-WgJnBH5.jpg","gif":"0390-WgJnBH5.gif"},{"id":"3547","n":"dumbbell seated biceps curl to shoulder press","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"shoulders","sm":["shoulders"],"st":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in each hand with your palms facing forward and arms fully extended.","Keeping your elbows close to your sides, curl the dumbbells up towards your shoulders.","Once your forearms are vertical, rotate your wrists so that your palms are facing forward.","Press the dumbbells overhead until your arms are fully extended.","Lower the dumbbells back down to the starting position by reversing the movement.","Repeat for the desired number of repetitions."],"img":"3547-OeL23VY.jpg","gif":"3547-OeL23VY.gif"},{"id":"1379","n":"dumbbell seated calf raise","bp":"lower legs","eq":"dumbbell","tg":"calves","mg":"hamstrings","sm":["hamstrings"],"st":["Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs.","Place the balls of your feet on a raised surface such as a step or block, with your heels hanging off the edge.","Hold onto the dumbbell for stability.","Raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1379-r29jP7S.jpg","gif":"1379-r29jP7S.gif"},{"id":"0391","n":"dumbbell seated curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, palms facing forward.","Keep your back straight and your elbows close to your torso.","Exhale and curl the dumbbells up towards your shoulders, contracting your biceps.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0391-TiaZTxx.jpg","gif":"0391-TiaZTxx.gif"},{"id":"0392","n":"dumbbell seated front raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","biceps"],"st":["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.","Keep your back straight and core engaged.","Raise the dumbbells in front of you, with your palms facing down, until they are at shoulder level.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0392-Ys97II0.jpg","gif":"0392-Ys97II0.gif"},{"id":"1678","n":"dumbbell seated hammer curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended straight down.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"1678-IGtBdNT.jpg","gif":"1678-IGtBdNT.gif"},{"id":"0393","n":"dumbbell seated inner biceps curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Rest your upper arms on your thighs, allowing the dumbbells to hang down.","Keeping your upper arms stationary, curl the dumbbells up towards your shoulders by contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0393-KXyoEtA.jpg","gif":"0393-KXyoEtA.gif"},{"id":"0394","n":"dumbbell seated kickback","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand.","Bend your knees slightly and lean forward from your hips, keeping your back straight.","Bring your upper arms close to your sides and keep your elbows bent at a 90-degree angle.","Extend your arms straight back, squeezing your triceps at the top of the movement.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0394-en550rk.jpg","gif":"0394-en550rk.gif"},{"id":"0396","n":"dumbbell seated lateral raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps","upper back"],"st":["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.","Keep your back straight and core engaged.","Raise the dumbbells to your sides with a slight bend in your elbows, until your arms are parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0396-hxyTtWj.jpg","gif":"0396-hxyTtWj.gif"},{"id":"0395","n":"dumbbell seated lateral raise v. 2","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps","triceps"],"st":["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.","Keep your back straight and core engaged.","Raise the dumbbells to your sides with a slight bend in your elbows, until your arms are parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0395-hrrS0Ed.jpg","gif":"0395-hrrS0Ed.gif"},{"id":"0397","n":"dumbbell seated neutral wrist curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing each other.","Rest your forearms on your thighs, allowing the dumbbells to hang down.","Keeping your wrists in a neutral position, curl the dumbbells up towards your shoulders.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0397-uJmK7Z1.jpg","gif":"0397-uJmK7Z1.gif"},{"id":"1679","n":"dumbbell seated one arm bicep curl on exercise ball with leg raised","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing up and your arm fully extended.","Place your other hand on your hip for stability.","Slowly curl the dumbbell towards your shoulder, keeping your upper arm stationary.","Pause for a moment at the top of the movement, squeezing your bicep.","Slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions.","Switch arms and repeat the exercise."],"img":"1679-84sESNy.jpg","gif":"1679-84sESNy.gif"},{"id":"0398","n":"dumbbell seated one arm kickback","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand.","Bend your torso forward at the waist, keeping your back straight and parallel to the ground.","Extend your arm straight back, keeping your elbow close to your body.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"0398-VQ3sNCn.jpg","gif":"0398-VQ3sNCn.gif"},{"id":"0399","n":"dumbbell seated one arm rotate","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"shoulders","sm":["shoulders","biceps"],"st":["Sit on a bench with your back straight and hold a dumbbell in one hand, resting it on your thigh.","Raise the dumbbell up to shoulder height, keeping your elbow close to your body.","Rotate your forearm outward, away from your body, while keeping your upper arm stationary.","Pause for a moment at the top, then slowly rotate your forearm back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"img":"0399-7f2jsqP.jpg","gif":"0399-7f2jsqP.gif"},{"id":"0400","n":"dumbbell seated one leg calf raise","bp":"lower legs","eq":"dumbbell","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your right thigh.","Extend your left leg straight out in front of you, keeping your foot flexed.","Place the ball of your right foot on an elevated surface, such as a step or weight plate.","Using your calf muscles, raise your right heel as high as possible.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"img":"0400-Ia7tumC.jpg","gif":"0400-Ia7tumC.gif"},{"id":"1380","n":"dumbbell seated one leg calf raise - hammer grip","bp":"lower legs","eq":"dumbbell","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs.","Place one foot on a raised surface, such as a step or block, with your heel hanging off the edge.","Hold the dumbbell with a hammer grip, meaning your palms are facing each other and your fingers are wrapped around the handle.","Keeping your core engaged and your back straight, slowly raise your heel as high as possible by pushing through the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other leg."],"img":"1380-FxhcxUW.jpg","gif":"1380-FxhcxUW.gif"},{"id":"1381","n":"dumbbell seated one leg calf raise - palm up","bp":"lower legs","eq":"dumbbell","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Sit on a bench or chair with your back straight and your feet flat on the ground.","Hold a dumbbell in one hand and place it on top of your thigh, palm facing up.","Lift one leg off the ground and extend it in front of you, keeping your knee slightly bent.","Raise your heel as high as possible by pushing through the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down.","Repeat for the desired number of repetitions, then switch legs and repeat."],"img":"1381-VW88JNd.jpg","gif":"1381-VW88JNd.gif"},{"id":"0401","n":"dumbbell seated palms up wrist curl","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"biceps","sm":["biceps","shoulders"],"st":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, squeezing your forearms at the top of the movement.","Pause for a moment, then lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0401-2dImyQ8.jpg","gif":"0401-2dImyQ8.gif"},{"id":"0402","n":"dumbbell seated preacher curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a preacher curl bench with your feet flat on the floor.","Hold a dumbbell in one hand with an underhand grip, resting your upper arm against the preacher pad.","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Pause for a moment at the top, then inhale and slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"0402-7D5bgLT.jpg","gif":"0402-7D5bgLT.gif"},{"id":"0403","n":"dumbbell seated revers grip concentration curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up.","Rest your elbow on the inside of your thigh, just above the knee.","Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"0403-lyKCLmK.jpg","gif":"0403-lyKCLmK.gif"},{"id":"1738","n":"dumbbell seated reverse grip one arm overhead tricep extension","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell with an underhand grip and extend your arm straight up overhead.","Lower the dumbbell behind your head by bending your elbow, keeping your upper arm stationary.","Pause for a moment, then extend your arm back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1738-5fKX7wi.jpg","gif":"1738-5fKX7wi.gif"},{"id":"0405","n":"dumbbell seated shoulder press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Sit on a bench with a dumbbell in each hand, resting on your thighs.","Raise the dumbbells to shoulder height, palms facing forward.","Press the dumbbells upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."],"img":"0405-znQUdHY.jpg","gif":"0405-znQUdHY.gif"},{"id":"0404","n":"dumbbell seated shoulder press (parallel grip)","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Sit on a bench with a dumbbell in each hand, palms facing inward.","Raise the dumbbells to shoulder height, elbows bent and palms facing forward.","Press the dumbbells upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."],"img":"0404-f1jf47L.jpg","gif":"0404-f1jf47L.gif"},{"id":"2188","n":"dumbbell seated triceps extension","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell with both hands and extend your arms straight up overhead.","Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears.","Pause for a moment, then straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."],"img":"2188-kont8Ut.jpg","gif":"2188-kont8Ut.gif"},{"id":"0406","n":"dumbbell shrug","bp":"back","eq":"dumbbell","tg":"traps","mg":"shoulders","sm":["shoulders"],"st":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body.","Keep your arms straight and let the dumbbells hang by your sides.","Raise your shoulders as high as possible, as if you are trying to touch your ears with your shoulders.","Hold the contraction for a second, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0406-NJzBsGJ.jpg","gif":"0406-NJzBsGJ.gif"},{"id":"0407","n":"dumbbell side bend","bp":"waist","eq":"dumbbell","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, letting it hang down by your side.","Keeping your back straight and your core engaged, slowly bend sideways at the waist towards the opposite side of the dumbbell, lowering the weight as far as you comfortably can.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides and repeat."],"img":"0407-IpONWYv.jpg","gif":"0407-IpONWYv.gif"},{"id":"0408","n":"dumbbell side lying one hand raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids"],"st":["Lie on your side with your legs extended and your head supported by your arm.","Hold a dumbbell in your top hand with your palm facing down.","Keeping your arm straight, raise the dumbbell up to shoulder height.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"0408-fTlkJop.jpg","gif":"0408-fTlkJop.gif"},{"id":"3664","n":"dumbbell side plank with rear fly","bp":"back","eq":"dumbbell","tg":"upper back","mg":"shoulders","sm":["shoulders","core"],"st":["Start by lying on your side with your legs extended and stacked on top of each other.","Place your forearm on the ground directly below your shoulder, keeping your elbow bent at a 90-degree angle.","Hold a dumbbell in your top hand, with your arm extended straight down towards the ground.","Engage your core and lift your hips off the ground, creating a straight line from your head to your heels.","While maintaining the side plank position, lift the dumbbell up towards the ceiling, squeezing your shoulder blades together.","Lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"3664-X6ytgYZ.jpg","gif":"3664-X6ytgYZ.gif","ty":"rin"},{"id":"3548","n":"dumbbell single arm overhead carry","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps","core"],"st":["Stand tall with your feet shoulder-width apart, holding a dumbbell in one hand.","Raise the dumbbell overhead, fully extending your arm.","Engage your core and keep your back straight as you walk forward, maintaining the dumbbell overhead.","Continue walking for the desired distance or time.","Switch hands and repeat the exercise."],"img":"3548-mWBtgmb.jpg","gif":"3548-mWBtgmb.gif"},{"id":"0409","n":"dumbbell single leg calf raise","bp":"lower legs","eq":"dumbbell","tg":"calves","mg":"ankles","sm":["ankles"],"st":["Stand on the edge of a step or platform with your heels hanging off and your toes on the step.","Hold a dumbbell in one hand and place your other hand on a wall or railing for support.","Raise your heel as high as possible, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heel back down below the step.","Repeat for the desired number of repetitions, then switch to the other leg."],"img":"0409-1kB3Wmk.jpg","gif":"0409-1kB3Wmk.gif"},{"id":"1757","n":"dumbbell single leg deadlift","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Stand with your feet hip-width apart, holding a dumbbell in your right hand.","Shift your weight onto your left leg and lift your right foot slightly off the ground.","Keeping your back straight, hinge forward at the hips and lower the dumbbell towards the ground.","At the same time, extend your right leg straight behind you, maintaining a slight bend in your left knee.","Lower the dumbbell until your torso and right leg are parallel to the ground.","Pause for a moment, then engage your glutes and hamstrings to return to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"1757-gKozT8X.jpg","gif":"1757-gKozT8X.gif"},{"id":"2805","n":"dumbbell single leg deadlift with stepbox support","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Stand with your feet hip-width apart, holding a dumbbell in your right hand.","Place your left foot on a stepbox or elevated surface behind you.","Keeping your back straight and core engaged, hinge forward at the hips, lowering the dumbbell towards the ground.","As you lower the dumbbell, simultaneously lift your left leg behind you, maintaining a straight line from head to heel.","Lower the dumbbell until you feel a stretch in your right hamstring, then return to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"2805-daBmy1Y.jpg","gif":"2805-daBmy1Y.gif"},{"id":"0410","n":"dumbbell single leg split squat","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step forward with one foot and position your feet so that your front foot is flat on the ground and your back foot is elevated on a bench or step.","Lower your body by bending your front knee and hip, keeping your back knee slightly bent and your back heel off the ground.","Continue lowering until your front thigh is parallel to the ground, then push through your front heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."],"img":"0410-qx4fgX7.jpg","gif":"0410-qx4fgX7.gif"},{"id":"0411","n":"dumbbell single leg squat","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Extend one leg forward and keep it off the ground throughout the exercise.","Bend your standing leg and lower your body down as if sitting back into a chair.","Keep your chest up and your back straight.","Pause for a moment at the bottom, then push through your heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"img":"0411-H6ybluc.jpg","gif":"0411-H6ybluc.gif"},{"id":"0413","n":"dumbbell squat","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Keeping your chest up and core engaged, lower your body down by bending at the knees and hips, as if sitting back into a chair.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"0413-HsvHqgf.jpg","gif":"0413-HsvHqgf.gif"},{"id":"3560","n":"dumbbell standing alternate hammer curl and press","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Stand up straight with a dumbbell in each hand, palms facing your body.","Keep your elbows close to your torso and your back straight.","Exhale and curl the dumbbell in your right hand towards your shoulder, keeping your upper arm stationary.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the curl with your left hand.","After completing the curl with your left hand, exhale and press the dumbbell in your right hand overhead.","Extend your arm fully and hold for a moment at the top.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the press with your left hand.","Continue alternating between curls and presses for the desired number of repetitions."],"img":"3560-LeaZOIz.jpg","gif":"3560-LeaZOIz.gif"},{"id":"0414","n":"dumbbell standing alternate overhead press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward.","Press one dumbbell overhead, fully extending your arm.","Lower the dumbbell back to shoulder level.","Repeat with the other arm.","Continue alternating arms for the desired number of repetitions."],"img":"0414-bBi35y3.jpg","gif":"0414-bBi35y3.gif"},{"id":"0415","n":"dumbbell standing alternate raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps","forearms"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.","Keep your back straight and your core engaged.","Raise one dumbbell to the side, keeping your arm straight and your palm facing down.","Continue lifting until your arm is parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat with the other arm.","Alternate between arms for the desired number of repetitions."],"img":"0415-SxHteRW.jpg","gif":"0415-SxHteRW.gif"},{"id":"1739","n":"dumbbell standing alternating tricep kickback","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms straight back, keeping your elbows close to your body.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat with the other arm, alternating sides with each repetition."],"img":"1739-Gi2BXfK.jpg","gif":"1739-Gi2BXfK.gif"},{"id":"2143","n":"dumbbell standing around world","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","forearms"],"st":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Extend your arms straight out to the sides at shoulder height, palms facing down.","Keeping your arms straight, slowly rotate your arms in a circular motion, bringing the dumbbells in front of your body and then overhead.","Continue the circular motion, bringing the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"img":"2143-RSOsp5d.jpg","gif":"2143-RSOsp5d.gif"},{"id":"1740","n":"dumbbell standing bent over one arm triceps extension","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","back"],"st":["Stand with your feet shoulder-width apart and hold a dumbbell in one hand.","Bend forward at the waist, keeping your back straight and parallel to the ground.","Extend your arm straight back, keeping your elbow close to your body.","Slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1740-CJwa0vD.jpg","gif":"1740-CJwa0vD.gif"},{"id":"1741","n":"dumbbell standing bent over two arm triceps extension","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","back"],"st":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Extend your arms straight back, keeping your elbows close to your body.","Slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1741-3T12T87.jpg","gif":"1741-3T12T87.gif"},{"id":"0416","n":"dumbbell standing biceps curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0416-3s4NnTh.jpg","gif":"0416-3s4NnTh.gif"},{"id":"0417","n":"dumbbell standing calf raise","bp":"lower legs","eq":"dumbbell","tg":"calves","mg":"ankles","sm":["ankles"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Raise your heels off the ground as high as possible, using your calves.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0417-dPmaUaU.jpg","gif":"0417-dPmaUaU.gif"},{"id":"0418","n":"dumbbell standing concentration curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand with your feet shoulder-width apart and hold a dumbbell in one hand, with your arm fully extended and palm facing inwards.","Place your opposite hand on your thigh for support.","Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"0418-7inpWch.jpg","gif":"0418-7inpWch.gif"},{"id":"0419","n":"dumbbell standing front raise above head","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","biceps"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Keep your arms straight and lift the dumbbells in front of you, raising them above your head.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0419-laVRfDf.jpg","gif":"0419-laVRfDf.gif"},{"id":"2321","n":"dumbbell standing inner biceps curl v. 2","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","While holding your upper arms stationary, curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Slowly begin to bring the dumbbells back to the starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"img":"2321-vKilzz3.jpg","gif":"2321-vKilzz3.gif"},{"id":"0420","n":"dumbbell standing kickback","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms straight back, squeezing your triceps at the top of the movement.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0420-UmpPAAe.jpg","gif":"0420-UmpPAAe.gif"},{"id":"0421","n":"dumbbell standing one arm concentration curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, palm facing up.","Place your free hand on your thigh for support.","Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"0421-8fgqP5a.jpg","gif":"0421-8fgqP5a.gif"},{"id":"0422","n":"dumbbell standing one arm curl (over incline bench)","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing forward.","Place your other hand on an incline bench for support.","Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.","Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"0422-BIb1tGo.jpg","gif":"0422-BIb1tGo.gif"},{"id":"1680","n":"dumbbell standing one arm curl over incline bench","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand.","Place your other hand on an incline bench for support.","Keeping your upper arm stationary, curl the dumbbell towards your shoulder by contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1680-EmlJR2y.jpg","gif":"1680-EmlJR2y.gif"},{"id":"0423","n":"dumbbell standing one arm extension","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand.","Raise the dumbbell overhead, fully extending your arm.","Keep your upper arm close to your head and perpendicular to the ground.","Slowly lower the dumbbell behind your head, bending your elbow.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"0423-BCUR88E.jpg","gif":"0423-BCUR88E.gif"},{"id":"0424","n":"dumbbell standing one arm palm in press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand at shoulder height with your palm facing inwards.","Engage your core and keep your back straight.","Press the dumbbell upwards until your arm is fully extended.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"img":"0424-ocYc6Db.jpg","gif":"0424-ocYc6Db.gif"},{"id":"0425","n":"dumbbell standing one arm reverse curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand with an overhand grip.","Keep your arm fully extended and close to your body, with your palm facing down.","Slowly curl the dumbbell up towards your shoulder, keeping your upper arm stationary.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"img":"0425-DU5Kkj2.jpg","gif":"0425-DU5Kkj2.gif"},{"id":"0426","n":"dumbbell standing overhead press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward.","Press the dumbbells upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbells back down to shoulder level.","Repeat for the desired number of repetitions."],"img":"0426-A6wtbuL.jpg","gif":"0426-A6wtbuL.gif"},{"id":"0427","n":"dumbbell standing palms in press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","chest"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing inwards.","Keeping your core engaged and your back straight, press the dumbbells upwards until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0427-UilDHSs.jpg","gif":"0427-UilDHSs.gif"},{"id":"0428","n":"dumbbell standing preacher curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand upright with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Rest the back of your upper arms against the preacher bench or an incline bench, with your elbows slightly bent.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0428-hq2hyDH.jpg","gif":"0428-hq2hyDH.gif"},{"id":"0429","n":"dumbbell standing reverse curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0429-0IgNjSM.jpg","gif":"0429-0IgNjSM.gif"},{"id":"0430","n":"dumbbell standing triceps extension","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Stand with your feet shoulder-width apart and hold a dumbbell in one hand.","Raise the dumbbell overhead, keeping your arm straight.","Bend your elbow and lower the dumbbell behind your head, keeping your upper arm stationary.","Extend your arm back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0430-PdmaD0N.jpg","gif":"0430-PdmaD0N.gif"},{"id":"2293","n":"dumbbell standing zottman preacher curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with a dumbbell in each hand, palms facing forward.","Place your upper arms against the preacher bench and keep your elbows slightly bent.","Curl the dumbbells up towards your shoulders while keeping your upper arms stationary.","At the top of the movement, rotate your wrists so that your palms are facing downward.","Slowly lower the dumbbells back to the starting position, rotating your wrists back to the starting position as well.","Repeat for the desired number of repetitions."],"img":"2293-P2nRiUa.jpg","gif":"2293-P2nRiUa.gif"},{"id":"1684","n":"dumbbell step up single leg balance with bicep curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"quadriceps","sm":["quadriceps","glutes","hamstrings"],"st":["Stand in front of a step or platform with a dumbbell in each hand, palms facing your body.","Place your right foot on the step, ensuring your entire foot is in contact with the surface.","Engage your core and push through your right heel to lift your body up onto the step, bringing your left knee up towards your chest.","At the top of the movement, perform a bicep curl by bending your elbows and bringing the dumbbells towards your shoulders.","Lower the dumbbells back down and simultaneously lower your left foot back to the ground.","Repeat the movement on the opposite side, stepping up with your left foot and curling the dumbbells.","Continue alternating sides for the desired number of repetitions."],"img":"1684-76vfTdU.jpg","gif":"1684-76vfTdU.gif"},{"id":"0431","n":"dumbbell step-up","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand in front of a bench or step with a dumbbell in each hand, palms facing your body.","Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface.","Push through your right heel and lift your body up onto the bench or step, straightening your right leg.","Bring your left foot up onto the bench or step, standing fully upright.","Step back down with your left foot, followed by your right foot, returning to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"img":"0431-aXtJhlg.jpg","gif":"0431-aXtJhlg.gif"},{"id":"2796","n":"dumbbell step-up lunge","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand in front of a step or platform with a dumbbell in each hand, palms facing your sides.","Place your right foot on the step, ensuring your entire foot is on the surface.","Push through your right heel and lift your body up onto the step, bringing your left foot up as well.","Once both feet are on the step, lower your left foot back down to the starting position, keeping your right foot on the step.","Repeat the movement, alternating which foot you step up with each time.","Continue for the desired number of repetitions."],"img":"2796-gFyFj9z.jpg","gif":"2796-gFyFj9z.gif"},{"id":"2812","n":"dumbbell step-up split squat","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand in front of a bench or step with a dumbbell in each hand, palms facing your body.","Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface.","Step up onto the bench or step with your right foot, pushing through your heel to lift your body up.","As you step up, simultaneously lift your left knee towards your chest.","Pause at the top of the movement, then slowly lower your left foot back to the ground while keeping your right foot on the bench or step.","Repeat the movement with your left foot on the bench or step.","Continue alternating between your right and left foot for the desired number of repetitions."],"img":"2812-QjE2DcA.jpg","gif":"2812-QjE2DcA.gif"},{"id":"0432","n":"dumbbell stiff leg deadlift","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing a slight bend in your knees.","Lower the dumbbells until you feel a stretch in your hamstrings, then squeeze your glutes and push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"0432-5eLRITT.jpg","gif":"0432-5eLRITT.gif"},{"id":"0433","n":"dumbbell straight arm pullover","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"latissimus dorsi","sm":["latissimus dorsi","triceps"],"st":["Lie flat on a bench with your head at one end and your feet planted firmly on the ground.","Hold a dumbbell with both hands and extend your arms straight above your chest.","Keeping your arms straight, slowly lower the dumbbell behind your head in an arc-like motion.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"0433-i8BdLTK.jpg","gif":"0433-i8BdLTK.gif"},{"id":"0434","n":"dumbbell straight leg deadlift","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your torso to lean forward.","Continue lowering the dumbbells until you feel a stretch in your hamstrings, keeping your knees slightly bent.","Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0434-oom75KC.jpg","gif":"0434-oom75KC.gif"},{"id":"2808","n":"dumbbell sumo pull through","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","core"],"st":["Stand with your feet wider than shoulder-width apart, toes pointed outwards.","Hold a dumbbell with both hands in front of your body, arms extended.","Bend your knees and lower your hips down into a squat position, keeping your back straight.","Lower the dumbbell down between your legs, keeping your arms straight.","Drive through your heels and extend your hips forward, pulling the dumbbell up and in front of your body.","Squeeze your glutes at the top of the movement, then lower the dumbbell back down between your legs.","Repeat for the desired number of repetitions."],"img":"2808-BmrwWzo.jpg","gif":"2808-BmrwWzo.gif"},{"id":"2803","n":"dumbbell supported squat","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Keeping your chest up and core engaged, slowly lower your body down by bending your knees and pushing your hips back.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"2803-r5DgrW9.jpg","gif":"2803-r5DgrW9.gif"},{"id":"0436","n":"dumbbell tate press","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Sit on a flat bench with a dumbbell in each hand, palms facing each other.","Raise the dumbbells to shoulder height, then rotate your wrists so that your palms are facing away from you.","Press the dumbbells up until your arms are fully extended, then lower them back down to shoulder height.","Rotate your wrists back to the starting position and repeat for the desired number of repetitions."],"img":"0436-s5PdDyY.jpg","gif":"0436-s5PdDyY.gif"},{"id":"1742","n":"dumbbell tricep kickback with stork stance","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Stand with your feet shoulder-width apart and hold a dumbbell in your right hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Bring your right elbow up to your side, keeping it bent at a 90-degree angle.","Extend your right arm straight back, squeezing your triceps.","Pause for a moment, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"1742-wOLmCXc.jpg","gif":"1742-wOLmCXc.gif"},{"id":"1743","n":"dumbbell twisting bench press","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Hold a dumbbell in each hand with an overhand grip, palms facing away from you.","Extend your arms straight up over your chest, keeping a slight bend in your elbows.","Lower the dumbbells down towards your chest, keeping your elbows close to your body.","As you lower the dumbbells, twist your wrists so that your palms face towards you at the bottom of the movement.","Pause for a moment at the bottom, then reverse the movement by pressing the dumbbells back up to the starting position.","As you press the dumbbells up, twist your wrists back to the starting position with palms facing away from you.","Repeat for the desired number of repetitions."],"img":"1743-z6TAHoT.jpg","gif":"1743-z6TAHoT.gif"},{"id":"0437","n":"dumbbell upright row","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps","biceps"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Let the dumbbells hang in front of your thighs, with your arms fully extended.","Keeping your back straight and your core engaged, exhale and lift the dumbbells straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0437-ainizkb.jpg","gif":"0437-ainizkb.gif"},{"id":"1765","n":"dumbbell upright row (back pov)","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps","biceps"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Let the dumbbells hang in front of your thighs, with your arms fully extended and your palms facing your body.","Keeping your back straight and your core engaged, exhale and lift the dumbbells straight up towards your chin, leading with your elbows.","Continue lifting until the dumbbells are at shoulder height, with your elbows pointing out to the sides.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1765-Iptlv6x.jpg","gif":"1765-Iptlv6x.gif"},{"id":"0864","n":"dumbbell upright shoulder external rotation","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","trapezius"],"st":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body.","Raise your arms out to the sides until they are parallel to the ground, keeping your elbows slightly bent.","Rotate your arms externally, bringing the dumbbells up towards your head while keeping your elbows in the same position.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0864-x306lCW.jpg","gif":"0864-x306lCW.gif","ty":"rin"},{"id":"5201","n":"dumbbell waiter biceps curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Stand up straight with a dumbbell in each hand, palms facing forward.","Keep your upper arms close to your body and your elbows tucked in.","Slowly curl the dumbbells up towards your shoulders, keeping your wrists straight.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"img":"5201-KOpzGBL.jpg","gif":"5201-KOpzGBL.gif"},{"id":"0438","n":"dumbbell w-press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","chest"],"st":["Sit on a bench with a dumbbell in each hand, palms facing forward.","Raise the dumbbells to shoulder height, elbows bent and palms facing forward.","Press the dumbbells upward until your arms are fully extended overhead.","Lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."],"img":"0438-vmwLyCg.jpg","gif":"0438-vmwLyCg.gif"},{"id":"0439","n":"dumbbell zottman curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with a dumbbell in each hand, palms facing your body.","Keep your elbows close to your torso and rotate your palms to face forward.","Curl the dumbbells up to your shoulders while keeping your upper arms stationary.","At the top of the movement, rotate your wrists so that your palms are facing away from your body.","Slowly lower the dumbbells back to the starting position, rotating your palms back to facing your body.","Repeat for the desired number of repetitions."],"img":"0439-kXaIn5A.jpg","gif":"0439-kXaIn5A.gif"},{"id":"2294","n":"dumbbell zottman preacher curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a preacher bench with a dumbbell in each hand, palms facing up and elbows resting on the pad.","Curl the dumbbells up towards your shoulders, keeping your upper arms stationary and your palms facing up.","At the top of the curl, rotate your wrists so that your palms are facing down.","Slowly lower the dumbbells back down to the starting position, rotating your wrists back to the starting position as you do so.","Repeat for the desired number of repetitions."],"img":"2294-y5U5B9Y.jpg","gif":"2294-y5U5B9Y.gif"},{"id":"2189","n":"dumbbells seated triceps extension","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in both hands with an overhand grip, and raise it above your head.","Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears.","Extend your arms and raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"2189-FQXdXzY.jpg","gif":"2189-FQXdXzY.gif"},{"id":"1167","n":"dynamic chest stretch (male)","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Stand tall with your feet shoulder-width apart.","Extend your arms straight out to the sides, parallel to the ground.","Slowly bring your arms forward, crossing them in front of your body.","Feel the stretch in your chest muscles.","Hold the stretch for 10-30 seconds.","Return to the starting position and repeat for the desired number of repetitions."],"img":"1167-3uj0Ozg.jpg","gif":"1167-3uj0Ozg.gif","ty":"mob"},{"id":"3287","n":"elbow dips","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.","Slide your hips forward off the bench and straighten your legs, keeping your heels on the ground.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position.","Repeat for the desired number of repetitions."],"img":"3287-LkoAWAE.jpg","gif":"3287-LkoAWAE.gif"},{"id":"1772","n":"elbow lift - reverse push-up","bp":"back","eq":"body weight","tg":"upper back","mg":"triceps","sm":["triceps","shoulders"],"st":["Start by lying face down on the ground with your legs extended and your hands placed directly under your shoulders.","Engage your core and press through your palms to lift your upper body off the ground, keeping your elbows close to your sides.","Pause at the top for a moment, squeezing your upper back muscles.","Slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1772-wbUYILZ.jpg","gif":"1772-wbUYILZ.gif"},{"id":"0443","n":"elbow-to-knee","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Start by lying flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee.","At the same time, bring your left knee towards your right elbow, creating a twisting motion.","Pause for a moment at the top, then slowly lower your upper body and extend your legs back to the starting position.","Repeat the movement, this time bringing your left elbow towards your right knee and your right knee towards your left elbow.","Continue alternating sides for the desired number of repetitions."],"img":"0443-jvp6DiD.jpg","gif":"0443-jvp6DiD.gif"},{"id":"3292","n":"elevator","bp":"back","eq":"body weight","tg":"upper back","mg":"shoulders","sm":["shoulders","trapezius"],"st":["Stand with your feet shoulder-width apart and your knees slightly bent.","Place your hands on your hips or cross them in front of your chest.","Keeping your back straight, slowly bend forward at the waist, lowering your upper body towards the ground.","Pause for a moment at the bottom, then slowly raise your upper body back up to the starting position.","Repeat for the desired number of repetitions."],"img":"3292-zYmNaoY.jpg","gif":"3292-zYmNaoY.gif"},{"id":"1332","n":"exercise ball alternating arm ups","bp":"back","eq":"stability ball","tg":"lats","mg":"shoulders","sm":["shoulders","core"],"st":["Sit on the stability ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing inwards and your arms extended down by your sides.","Engage your core and slowly lift one arm up towards your shoulder, keeping your elbow slightly bent.","Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Repeat the movement with the other arm.","Continue alternating arms for the desired number of repetitions."],"img":"1332-EyLrNC2.jpg","gif":"1332-EyLrNC2.gif"},{"id":"1333","n":"exercise ball back extension with arms extended","bp":"back","eq":"stability ball","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability.","Extend your arms straight out in front of you, with your palms facing down.","Engage your core and slowly lift your upper body off the ball, keeping your back straight and your neck in line with your spine.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1333-PERjVm8.jpg","gif":"1333-PERjVm8.gif"},{"id":"1334","n":"exercise ball back extension with hands behind head","bp":"back","eq":"stability ball","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Place the stability ball on the ground and lie face down on top of it with your hips resting on the ball.","Position your feet against a wall or other stable surface for support.","Cross your arms behind your head, with your hands touching the back of your head.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your hips.","Pause for a moment at the top of the movement, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1334-o1HGDSq.jpg","gif":"1334-o1HGDSq.gif"},{"id":"1335","n":"exercise ball back extension with knees off ground","bp":"back","eq":"stability ball","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability.","Position your hands behind your head or crossed over your chest.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1335-WME869U.jpg","gif":"1335-WME869U.gif"},{"id":"1336","n":"exercise ball back extension with rotation","bp":"back","eq":"stability ball","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Start by lying face down on the stability ball with your hips resting on the ball and your feet firmly planted on the ground.","Place your hands behind your head or cross them over your chest.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.","Pause for a moment at the top, then slowly rotate your torso to one side, keeping your hips and legs stable.","Return to the center and repeat the rotation to the other side.","Lower your upper body back down to the starting position and repeat for the desired number of repetitions."],"img":"1336-WVD66ff.jpg","gif":"1336-WVD66ff.gif","ty":"mob"},{"id":"1744","n":"exercise ball dip","bp":"upper arms","eq":"stability ball","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Place your hands on the ball beside your hips, fingers pointing forward.","Engage your triceps and push through your hands to lift your body off the ball, straightening your arms.","Lower your body back down by bending your elbows, keeping them close to your sides.","Repeat for the desired number of repetitions."],"img":"1744-kprile3.jpg","gif":"1744-kprile3.gif"},{"id":"1559","n":"exercise ball hip flexor stretch","bp":"upper legs","eq":"stability ball","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings"],"st":["Place the stability ball on the ground and kneel in front of it.","Place your right foot on top of the stability ball, with your knee bent at a 90-degree angle.","Extend your left leg behind you, keeping it straight.","Lean forward, pushing your hips towards the stability ball, until you feel a stretch in your right hip flexor.","Hold the stretch for 20-30 seconds, then switch sides and repeat."],"img":"1559-2LQkNPW.jpg","gif":"1559-2LQkNPW.gif","ty":"stretch","kind":"time"},{"id":"1338","n":"exercise ball hug","bp":"back","eq":"stability ball","tg":"spine","mg":"shoulders","sm":["shoulders","chest"],"st":["Sit on the stability ball with your feet flat on the ground and your back straight.","Hold the stability ball with both hands, hugging it close to your chest.","Engage your core muscles and slowly lean back, keeping your back straight and your feet planted on the ground.","Continue leaning back until you feel a stretch in your back muscles.","Hold the position for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"1338-d7z1Y7V.jpg","gif":"1338-d7z1Y7V.gif"},{"id":"1339","n":"exercise ball lat stretch","bp":"back","eq":"stability ball","tg":"lats","mg":"shoulders","sm":["shoulders","triceps"],"st":["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand and extend your arm straight up overhead.","Slowly lean to the opposite side, feeling a stretch in your lat muscle.","Hold the stretch for 20-30 seconds, then return to the starting position.","Repeat on the other side."],"img":"1339-sM84pE4.jpg","gif":"1339-sM84pE4.gif","ty":"stretch","kind":"time"},{"id":"1341","n":"exercise ball lower back stretch (pyramid)","bp":"back","eq":"stability ball","tg":"lats","mg":"glutes","sm":["glutes","hamstrings"],"st":["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Slowly walk your feet forward, rolling the ball down your back until your lower back is resting on the ball.","Place your hands behind your head or cross them over your chest.","Engage your core and slowly lower your upper body towards the ground, allowing your lower back to stretch over the ball.","Hold the stretch for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"1341-yU7w7CA.jpg","gif":"1341-yU7w7CA.gif","ty":"stretch","kind":"time"},{"id":"1342","n":"exercise ball lying side lat stretch","bp":"back","eq":"stability ball","tg":"lats","mg":"shoulders","sm":["shoulders","triceps"],"st":["Lie on your side with your legs extended and your head supported by the stability ball.","Place your top arm on the ball for stability.","Reach your top arm overhead and allow your torso to rotate slightly.","Feel the stretch in your lat muscles on the side of your body.","Hold the stretch for 20-30 seconds, then switch sides and repeat."],"img":"1342-rTbyBYV.jpg","gif":"1342-rTbyBYV.gif","ty":"stretch","kind":"time"},{"id":"1382","n":"exercise ball on the wall calf raise","bp":"lower legs","eq":"dumbbell","tg":"calves","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Stand with your back against a wall and place an exercise ball between your lower back and the wall.","Position your feet shoulder-width apart, with your toes pointing forward.","Hold a dumbbell in each hand, with your arms extended by your sides.","Raise your heels off the ground, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1382-xo6sENf.jpg","gif":"1382-xo6sENf.gif"},{"id":"3241","n":"exercise ball on the wall calf raise (tennis ball between ankles)","bp":"lower legs","eq":"dumbbell","tg":"calves","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Stand facing a wall with your feet shoulder-width apart.","Place an exercise ball between the wall and your lower back.","Hold a dumbbell in each hand, with your arms extended by your sides.","Place a tennis ball between your ankles.","Raise your heels off the ground, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"img":"3241-FY3UdNT.jpg","gif":"3241-FY3UdNT.gif"},{"id":"3240","n":"exercise ball on the wall calf raise (tennis ball between knees)","bp":"lower legs","eq":"dumbbell","tg":"calves","mg":"quadriceps","sm":["quadriceps","hamstrings"],"st":["Stand with your back against a wall and place an exercise ball between your lower back and the wall.","Position your feet shoulder-width apart and slightly in front of you.","Hold a dumbbell in each hand, with your arms extended by your sides.","Place a tennis ball between your knees.","Raise your heels off the ground, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"img":"3240-j74M6Zn.jpg","gif":"3240-j74M6Zn.gif"},{"id":"1416","n":"exercise ball one leg prone lower body rotation","bp":"upper legs","eq":"stability ball","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","core"],"st":["Lie face down on the stability ball with your hips resting on the ball and your legs extended straight behind you.","Place your hands on the ground in front of you for support.","Engage your glutes and core muscles to stabilize your body.","Slowly lift one leg off the ground, keeping it straight and parallel to the floor.","Rotate your leg outward, away from your body, while keeping your hips and upper body stable.","Pause for a moment at the end of the rotation, then slowly return your leg to the starting position.","Repeat the rotation with the other leg.","Continue alternating legs for the desired number of repetitions."],"img":"1416-M72BExt.jpg","gif":"1416-M72BExt.gif","ty":"mob"},{"id":"1417","n":"exercise ball one legged diagonal kick hamstring curl","bp":"upper legs","eq":"stability ball","tg":"glutes","mg":"hamstrings","sm":["hamstrings","calves"],"st":["Start by lying on your back with your legs extended and your heels resting on top of the stability ball.","Place your arms by your sides for stability.","Engage your glutes and core muscles to lift your hips off the ground, creating a straight line from your shoulders to your heels.","Bend your right knee and bring it towards your chest, keeping your left leg extended and your foot flexed.","Kick your right leg diagonally across your body, extending it fully and engaging your hamstrings.","Slowly return your right leg to the starting position, maintaining control and stability.","Repeat the movement with your left leg, alternating sides for the desired number of repetitions."],"img":"1417-GOJKFfO.jpg","gif":"1417-GOJKFfO.gif"},{"id":"1296","n":"exercise ball pike push up","bp":"chest","eq":"stability ball","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps","core"],"st":["Start in a push-up position with your hands on the floor and your shins resting on the stability ball.","Engage your core and lift your hips up towards the ceiling, rolling the ball towards your hands.","Keep your legs straight and your body in a pike position, forming an inverted V shape.","Bend your elbows and lower your upper body towards the floor, keeping your head in line with your hands.","Push through your hands and extend your arms to return to the starting position.","Repeat for the desired number of repetitions."],"img":"1296-sVvXT5J.jpg","gif":"1296-sVvXT5J.gif"},{"id":"1343","n":"exercise ball prone leg raise","bp":"back","eq":"stability ball","tg":"spine","mg":"abdominals","sm":["abdominals","glutes"],"st":["Lie face down on a mat with your legs extended and your toes resting on top of the stability ball.","Place your hands on the ground, shoulder-width apart, and engage your core muscles.","Keeping your legs straight, slowly lift them off the ground, using your lower back and glutes to raise them as high as possible.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1343-lCKm4Rs.jpg","gif":"1343-lCKm4Rs.gif"},{"id":"1560","n":"exercise ball seated hamstring stretch","bp":"upper legs","eq":"stability ball","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back"],"st":["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Slowly roll the ball forward, walking your feet out until your upper back is resting on the ball and your legs are extended straight in front of you.","Place your hands on your hips for support.","Engage your core and slowly lower your upper body towards the ground, keeping your back straight and your chest lifted.","Stop when you feel a stretch in your hamstrings, and hold the position for 20-30 seconds.","Slowly return to the starting position by pushing through your heels and using your hamstrings to pull yourself back up.","Repeat for the desired number of repetitions."],"img":"1560-yRYyfdA.jpg","gif":"1560-yRYyfdA.gif","ty":"stretch","kind":"time"},{"id":"1745","n":"exercise ball seated triceps stretch","bp":"upper arms","eq":"stability ball","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand and extend your arm straight up above your head.","Bend your elbow and lower the dumbbell behind your head, keeping your upper arm close to your ear.","Hold the stretch for a few seconds, then return to the starting position.","Repeat with the other arm."],"img":"1745-7ePTw4B.jpg","gif":"1745-7ePTw4B.gif","ty":"stretch","kind":"time"},{"id":"1746","n":"exercise ball supine triceps extension","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell with both hands and extend your arms straight up towards the ceiling.","Slowly lower the dumbbell behind your head, keeping your elbows close to your ears.","Pause for a moment, then raise the dumbbell back up to the starting position.","Repeat for the desired number of repetitions."],"img":"1746-Gm2Uv1z.jpg","gif":"1746-Gm2Uv1z.gif"},{"id":"1747","n":"ez bar french press on exercise ball","bp":"upper arms","eq":"ez barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Sit on an exercise ball and hold an EZ barbell with an overhand grip.","Extend your arms straight up, keeping your elbows close to your head.","Slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"img":"1747-CFN9P8G.jpg","gif":"1747-CFN9P8G.gif"},{"id":"3010","n":"ez bar lying bent arms pullover","bp":"back","eq":"ez barbell","tg":"lats","mg":"triceps","sm":["triceps","chest"],"st":["Lie flat on a bench with your head at one end and your feet on the floor.","Hold the EZ barbell with a pronated grip (palms facing away from you) and your hands shoulder-width apart.","Extend your arms straight above your chest, keeping a slight bend in your elbows.","Lower the barbell in an arc motion behind your head, maintaining the slight bend in your elbows.","Pause for a moment, then return the barbell to the starting position by reversing the arc motion.","Repeat for the desired number of repetitions."],"img":"3010-nDK1HJ0.jpg","gif":"3010-nDK1HJ0.gif"},{"id":"1748","n":"ez bar lying close grip triceps extension behind head","bp":"upper arms","eq":"ez barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the ez barbell with a close grip, palms facing up, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"img":"1748-6CKUx7o.jpg","gif":"1748-6CKUx7o.gif"},{"id":"1344","n":"ez bar reverse grip bent over row","bp":"back","eq":"ez barbell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold the ez barbell with an underhand grip, palms facing up, and hands shoulder-width apart.","Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor.","Pull the ez barbell towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the ez barbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"1344-G8dXpNG.jpg","gif":"1344-G8dXpNG.gif"},{"id":"1682","n":"ez bar seated close grip concentration curl","bp":"upper arms","eq":"ez barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a bench with your feet flat on the ground and hold an EZ barbell with an underhand grip.","Rest your elbow on the inside of your thigh, just above the knee.","Curl the barbell up towards your shoulder while keeping your upper arm stationary.","Squeeze your biceps at the top of the movement, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1682-Dsfz0Id.jpg","gif":"1682-Dsfz0Id.gif"},{"id":"1749","n":"ez bar standing french press","bp":"upper arms","eq":"ez barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Stand with your feet shoulder-width apart and hold the ez barbell with an overhand grip.","Raise the barbell above your head, fully extending your arms.","Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"img":"1749-1cTf2Ux.jpg","gif":"1749-1cTf2Ux.gif"},{"id":"0445","n":"ez barbell anti gravity press","bp":"shoulders","eq":"ez barbell","tg":"delts","mg":"triceps","sm":["triceps","chest"],"st":["Start by standing with your feet shoulder-width apart and holding the ez barbell with an overhand grip.","Raise the barbell to shoulder height, keeping your elbows slightly bent and your palms facing forward.","Press the barbell overhead, extending your arms fully.","Lower the barbell back to shoulder height and repeat for the desired number of repetitions."],"img":"0445-fprd84i.jpg","gif":"0445-fprd84i.gif"},{"id":"1627","n":"ez barbell close grip preacher curl","bp":"upper arms","eq":"ez barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a preacher curl bench and place your upper arms on the pad, gripping the ez barbell with an underhand grip.","Rest your triceps on the pad and fully extend your arms, keeping your back straight.","Slowly curl the barbell towards your shoulders, contracting your biceps.","Pause for a moment at the top, squeezing your biceps.","Lower the barbell back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"1627-hacCyUv.jpg","gif":"1627-hacCyUv.gif"},{"id":"0446","n":"ez barbell close-grip curl","bp":"upper arms","eq":"ez barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Curl the barbell up towards your shoulders, contracting your biceps.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0446-V4ryaZa.jpg","gif":"0446-V4ryaZa.gif"},{"id":"0447","n":"ez barbell curl","bp":"upper arms","eq":"ez barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.","Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Exhale as you curl the barbell up towards your shoulders, contracting your biceps.","Pause for a moment at the top, then inhale as you slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0447-6TG6x2w.jpg","gif":"0447-6TG6x2w.gif"},{"id":"0448","n":"ez barbell decline close grip face press","bp":"upper arms","eq":"ez barbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Lie on a decline bench with your head lower than your feet.","Grasp the ez barbell with a close grip, palms facing each other.","Extend your arms straight up above your chest, keeping your elbows close to your body.","Lower the barbell towards your forehead by bending your elbows.","Pause for a moment, then press the barbell back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0448-DgZQ11d.jpg","gif":"0448-DgZQ11d.gif"},{"id":"2186","n":"ez barbell decline triceps extension","bp":"upper arms","eq":"ez barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Lie on a decline bench with your head lower than your feet and your feet secured.","Hold the ez barbell with an overhand grip, hands shoulder-width apart.","Extend your arms fully, keeping your elbows close to your head.","Lower the barbell slowly towards your forehead, bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"img":"2186-CQHoDm0.jpg","gif":"2186-CQHoDm0.gif"},{"id":"0449","n":"ez barbell incline triceps extension","bp":"upper arms","eq":"ez barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Set up an incline bench at a 45-degree angle.","Sit on the bench with your back against the pad and hold the ez barbell with an overhand grip.","Extend your arms fully overhead, keeping your elbows close to your head.","Lower the barbell behind your head by bending your elbows, keeping your upper arms stationary.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"img":"0449-KyLtiLT.jpg","gif":"0449-KyLtiLT.gif"},{"id":"0450","n":"ez barbell jm bench press","bp":"upper arms","eq":"ez barbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the ez barbell with an overhand grip, slightly wider than shoulder-width apart.","Lower the barbell to your chest, keeping your elbows tucked in close to your body.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"0450-hnOYgH3.jpg","gif":"0450-hnOYgH3.gif"},{"id":"0451","n":"ez barbell reverse grip curl","bp":"upper arms","eq":"ez barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip.","Keep your elbows close to your torso and your upper arms stationary throughout the exercise.","Curl the barbell upwards by contracting your biceps, while exhaling.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Slowly begin to bring the barbell back to the starting position as you inhale.","Repeat for the desired number of repetitions."],"img":"0451-Y5X65IB.jpg","gif":"0451-Y5X65IB.gif"},{"id":"0452","n":"ez barbell reverse grip preacher curl","bp":"upper arms","eq":"ez barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a preacher bench with your chest against the pad and your feet flat on the floor.","Grasp the ez barbell with an underhand grip, hands shoulder-width apart.","Rest your upper arms on the pad, allowing your forearms to hang down.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0452-vBNyir7.jpg","gif":"0452-vBNyir7.gif"},{"id":"1458","n":"ez barbell seated curls","bp":"upper arms","eq":"ez barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a bench with your feet flat on the ground and your back straight.","Hold the ez barbell with an underhand grip, palms facing up, and your hands shoulder-width apart.","Rest your upper arms on your thighs, allowing the ez barbell to hang down in front of you.","Keeping your upper arms stationary, exhale and curl the ez barbell upwards towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the ez barbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"1458-jtFKbt5.jpg","gif":"1458-jtFKbt5.gif"},{"id":"0453","n":"ez barbell seated triceps extension","bp":"upper arms","eq":"ez barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Sit on a bench with your back straight and feet flat on the ground.","Hold the ez barbell with an overhand grip, hands shoulder-width apart.","Raise the barbell overhead, fully extending your arms.","Keeping your upper arms stationary, lower the barbell behind your head by bending your elbows.","Pause for a moment, then raise the barbell back to the starting position by extending your arms.","Repeat for the desired number of repetitions."],"img":"0453-iaapw0g.jpg","gif":"0453-iaapw0g.gif"},{"id":"0454","n":"ez barbell spider curl","bp":"upper arms","eq":"ez barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.","Rest your upper arms on a preacher bench or stability ball, allowing your elbows to hang down.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"0454-Ye5Qxb0.jpg","gif":"0454-Ye5Qxb0.gif"},{"id":"1628","n":"ez barbell spider curl","bp":"upper arms","eq":"ez barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.","Rest your upper arms on a preacher bench or stability ball, allowing your elbows to hang down.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"1628-2kattbR.jpg","gif":"1628-2kattbR.gif"},{"id":"2404","n":"ez-bar biceps curl (with arm blaster)","bp":"upper arms","eq":"ez barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.","Place your upper arms against the arm blaster, keeping them stationary throughout the exercise.","Keeping your elbows close to your body, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"2404-tJ5nYqo.jpg","gif":"2404-tJ5nYqo.gif"},{"id":"2432","n":"ez-bar close-grip bench press","bp":"upper arms","eq":"ez barbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the ez barbell with a close grip, hands shoulder-width apart, palms facing forward.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Slowly lower the barbell towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"2432-da4cXST.jpg","gif":"2432-da4cXST.gif"},{"id":"2741","n":"ez-barbell standing wide grip biceps curl","bp":"upper arms","eq":"ez barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, hands wider than shoulder-width apart.","Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Curl the barbell up towards your shoulders by contracting your biceps.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"2741-OVTZ65k.jpg","gif":"2741-OVTZ65k.gif"},{"id":"2133","n":"farmers walk","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"calves","sm":["calves","forearms","core"],"st":["Stand up straight with a dumbbell in each hand, palms facing your sides.","Keep your back straight and your shoulders back.","Take small, controlled steps forward, maintaining an upright posture.","Continue walking for the desired distance or time.","To finish, stop walking and carefully lower the dumbbells to your sides."],"img":"2133-qPEzJjA.jpg","gif":"2133-qPEzJjA.gif","ty":"atl"},{"id":"0455","n":"finger curls","bp":"lower arms","eq":"barbell","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","grip muscles"],"st":["Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your fingers towards your palms, squeezing the barbell tightly.","Hold the contraction for a moment, then slowly release your fingers back to the starting position.","Repeat for the desired number of repetitions."],"img":"0455-awG04cF.jpg","gif":"0455-awG04cF.gif"},{"id":"3303","n":"flag","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","shoulders"],"st":["Start by gripping a vertical pole with both hands, palms facing each other, and arms fully extended.","Engage your core and lift your legs off the ground, keeping them straight.","Using your core and upper body strength, raise your legs until they are parallel to the ground.","Hold this position for as long as you can, maintaining a straight body line.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"3303-pQ0Mx1Z.jpg","gif":"3303-pQ0Mx1Z.gif"},{"id":"0456","n":"flexion leg sit up (bent knee)","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","At the same time, lift your legs off the ground, bending your knees and bringing them towards your chest.","Pause for a moment at the top, then slowly lower your upper body and legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0456-AR0ig3o.jpg","gif":"0456-AR0ig3o.gif"},{"id":"0457","n":"flexion leg sit up (straight arm)","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","quadriceps"],"st":["Lie flat on your back with your legs extended and arms straight above your head.","Engaging your abs, lift your upper body off the ground while simultaneously lifting your legs towards your chest.","Reach your hands towards your toes as you lift your upper body and legs.","Pause for a moment at the top, then slowly lower your upper body and legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0457-KZn52RC.jpg","gif":"0457-KZn52RC.gif"},{"id":"0458","n":"floor fly (with barbell)","bp":"chest","eq":"barbell","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Lie flat on your back on the floor with your knees bent and feet flat on the ground.","Hold a barbell with an overhand grip, arms extended straight up over your chest.","Slowly lower the barbell out to the sides, keeping a slight bend in your elbows.","Lower the barbell until your arms are parallel to the floor, feeling a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring the barbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"0458-neonEDL.jpg","gif":"0458-neonEDL.gif"},{"id":"0459","n":"flutter kicks","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","lower abs"],"st":["Lie flat on your back with your legs extended and your hands by your sides.","Engage your core and lift your legs off the ground about 6 inches.","Keeping your legs straight, alternate lifting one leg slightly higher than the other.","Continue this fluttering motion for the desired number of repetitions."],"img":"0459-UVo2Qs2.jpg","gif":"0459-UVo2Qs2.gif"},{"id":"1472","n":"forward jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","hamstrings","glutes"],"st":["Stand with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position.","Swing your arms back for momentum.","Jump forward explosively, extending your hips, knees, and ankles.","Land softly on the balls of your feet and immediately go into the next jump.","Repeat for the desired number of repetitions."],"img":"1472-uZKq7lo.jpg","gif":"1472-uZKq7lo.gif","ty":"atl"},{"id":"3470","n":"forward lunge (male)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet hip-width apart and hands on your hips.","Take a big step forward with your right foot, lowering your body into a lunge position.","Bend your right knee to about 90 degrees, keeping your knee aligned with your ankle.","Push off with your right foot and return to the starting position.","Repeat with your left leg, alternating sides for the desired number of repetitions."],"img":"3470-kMzUs9Y.jpg","gif":"3470-kMzUs9Y.gif"},{"id":"3194","n":"frankenstein squat","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart and hold the barbell in front of your body with straight arms.","Keeping your back straight, lower your body by bending at the knees and hips, as if sitting back into a chair.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"3194-bdWcbaU.jpg","gif":"3194-bdWcbaU.gif"},{"id":"2429","n":"frog crunch","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"2429-FFRP97T.jpg","gif":"2429-FFRP97T.gif"},{"id":"3301","n":"frog planche","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","chest","triceps"],"st":["Start in a push-up position with your hands shoulder-width apart and your feet together.","Bend your elbows and lower your body towards the ground, keeping your back straight.","As you lower your body, lift your feet off the ground and bring your knees towards your chest.","Hold this position for a few seconds, then extend your legs back out and push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"img":"3301-rQhGcin.jpg","gif":"3301-rQhGcin.gif"},{"id":"3296","n":"front lever","bp":"waist","eq":"body weight","tg":"abs","mg":"lats","sm":["lats","shoulders","forearms"],"st":["Start by hanging from a pull-up bar with an overhand grip, hands shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","Bend your knees and tuck them towards your chest.","Simultaneously, lift your legs up and extend them straight out in front of you, keeping your body parallel to the ground.","Hold this position for as long as you can, aiming for a full front lever position.","To release, slowly lower your legs back down and return to the starting position.","Repeat for the desired number of repetitions."],"img":"3296-PkCN2lv.jpg","gif":"3296-PkCN2lv.gif"},{"id":"3295","n":"front lever reps","bp":"back","eq":"body weight","tg":"upper back","mg":"core","sm":["core","shoulders"],"st":["Hang from a pull-up bar with an overhand grip, palms facing away from you.","Engage your core and pull your shoulder blades down and back.","Keeping your body straight, lift your legs up until they are parallel to the ground.","Hold this position for as long as you can, aiming for 10-20 seconds.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"3295-hbY9wqG.jpg","gif":"3295-hbY9wqG.gif"},{"id":"0464","n":"front plank with twist","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","shoulders"],"st":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.","Engage your core and glutes to maintain a stable position.","Rotate your torso to the right, lifting your right arm and extending it towards the ceiling.","Keep your hips and legs stable as you twist.","Hold for a moment, then return to the starting position.","Repeat the twist on the left side.","Continue alternating sides for the desired number of repetitions."],"img":"0464-CosupLu.jpg","gif":"0464-CosupLu.gif","ty":"rin"},{"id":"3315","n":"full maltese","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","chest"],"st":["Start by standing with your feet shoulder-width apart and your arms extended straight out to the sides.","Slowly lean forward, keeping your arms straight, until your upper body is parallel to the ground.","Engage your core and hold this position for a few seconds.","Return to the starting position by pushing through your feet and standing back up.","Repeat for the desired number of repetitions."],"img":"3315-YRaCa5Y.jpg","gif":"3315-YRaCa5Y.gif"},{"id":"3299","n":"full planche","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","chest","triceps"],"st":["Start in a push-up position with your hands shoulder-width apart and your fingers pointing forward.","Engage your core and slowly shift your weight forward, lifting your feet off the ground.","Continue shifting your weight forward until your body is parallel to the ground, balancing on your hands.","Hold this position for as long as you can, maintaining a straight body line.","Slowly lower your feet back to the ground and return to the starting position.","Repeat for the desired number of repetitions."],"img":"3299-YZ4961r.jpg","gif":"3299-YZ4961r.gif"},{"id":"3327","n":"full planche push-up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps","core"],"st":["Start in a push-up position with your hands placed slightly wider than shoulder-width apart.","Engage your core and lower your body down towards the ground, keeping your elbows close to your sides.","As you lower yourself, lean your body forward and lift your feet off the ground, balancing on your hands.","Continue to lower your body until your chest is just above the ground.","Push through your hands and extend your arms to lift your body back up to the starting position.","Maintain a straight line from your head to your heels throughout the movement.","Repeat for the desired number of repetitions."],"img":"3327-gw9PqGk.jpg","gif":"3327-gw9PqGk.gif"},{"id":"0466","n":"gironda sternum chin","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Stand facing a high bar with your feet shoulder-width apart.","Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your lats and biceps to pull your chest up towards the bar, leading with your sternum.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0466-IL0JUxR.jpg","gif":"0466-IL0JUxR.gif"},{"id":"3561","n":"glute bridge march","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.","While keeping your hips lifted, lift one foot off the ground and bring your knee towards your chest.","Lower your foot back to the ground and repeat the movement with the other leg.","Continue alternating legs in a marching motion while maintaining the bridge position.","Repeat for the desired number of repetitions."],"img":"3561-GibBPPg.jpg","gif":"3561-GibBPPg.gif","ty":"rin"},{"id":"3523","n":"glute bridge two legs on bench (male)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Sit on the edge of a bench with your back against it and your feet flat on the ground.","Place your hands on the bench beside your hips for support.","Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"img":"3523-aWedzZX.jpg","gif":"3523-aWedzZX.gif","ty":"rin"},{"id":"3193","n":"glute-ham raise","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back"],"st":["Adjust the glute-ham raise machine to fit your body.","Position yourself face down on the machine with your ankles secured.","Place your hands on your chest or cross them over your chest.","Engage your hamstrings and glutes to lift your upper body up towards the ceiling.","Continue lifting until your body is in a straight line from your head to your heels.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"3193-Vvwjz6N.jpg","gif":"3193-Vvwjz6N.gif"},{"id":"0467","n":"gorilla chin","bp":"waist","eq":"body weight","tg":"abs","mg":"forearms","sm":["forearms","biceps"],"st":["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your palms facing away from you.","Engage your core and pull your body up towards the bar, bringing your chin above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0467-bmwlYvD.jpg","gif":"0467-bmwlYvD.gif"},{"id":"0469","n":"groin crunch","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","inner thighs"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your legs off the ground, bringing your knees towards your chest.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0469-mWppALS.jpg","gif":"0469-mWppALS.gif"},{"id":"1383","n":"hack calf raise","bp":"lower legs","eq":"sled machine","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Adjust the sled machine to a comfortable weight.","Stand on the sled machine with your toes on the platform and your heels hanging off.","Hold onto the handles for stability.","Raise your heels as high as possible by pushing through the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1383-2ORFMoR.jpg","gif":"1383-2ORFMoR.gif"},{"id":"1384","n":"hack one leg calf raise","bp":"lower legs","eq":"sled machine","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Adjust the sled machine to an appropriate weight.","Stand on the sled machine with one foot, keeping the other foot off the ground.","Hold onto the handles for stability.","Raise your heel as high as possible, lifting your body up on the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions.","Switch legs and repeat the exercise."],"img":"1384-AxFoqAD.jpg","gif":"1384-AxFoqAD.gif"},{"id":"3221","n":"half knee bends (male)","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","glutes"],"st":["Stand with your feet shoulder-width apart.","Bend your knees and lower your body down as if you were sitting back into a chair.","Keep your chest up and your weight in your heels.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"3221-ia6kIIl.jpg","gif":"3221-ia6kIIl.gif"},{"id":"3202","n":"half sit-up (male)","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"3202-iQ241UP.jpg","gif":"3202-iQ241UP.gif"},{"id":"1511","n":"hamstring stretch","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes"],"st":["Stand with your feet shoulder-width apart.","Step forward with your right foot and shift your weight onto your right leg.","Keeping your back straight, slowly bend forward at the hips, reaching towards your right foot with both hands.","Hold the stretch for 20-30 seconds, then return to the starting position.","Repeat on the other side."],"img":"1511-99rWm7w.jpg","gif":"1511-99rWm7w.gif","ty":"stretch","kind":"time"},{"id":"2139","n":"hands bike","bp":"chest","eq":"upper body ergometer","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Adjust the seat height and handlebar position to a comfortable level.","Sit on the ergometer with your back straight and feet on the pedals.","Grasp the handles with your hands and position your arms at a 90-degree angle.","Start pedaling with your hands, pushing and pulling the handles in a controlled motion.","Continue pedaling for the desired duration or number of repetitions."],"img":"2139-pAIWRGu.jpg","gif":"2139-pAIWRGu.gif"},{"id":"3218","n":"hands clasped circular toe touch (male)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","calves"],"st":["Stand with your feet shoulder-width apart and your hands clasped together in front of your chest.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Lower your hands towards your toes in a circular motion, reaching as far as you can without straining.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"3218-B5xca8s.jpg","gif":"3218-B5xca8s.gif"},{"id":"3215","n":"hands reversed clasped circular toe touch (male)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","calves"],"st":["Stand with your feet shoulder-width apart and your arms extended to the sides.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Reach down with your hands and clasp them together behind your legs.","Slowly raise your hands up and over your head in a circular motion, keeping your legs straight.","Continue the circular motion until your hands touch your toes.","Reverse the motion and bring your hands back down to the starting position.","Repeat for the desired number of repetitions."],"img":"3215-yq3GAJX.jpg","gif":"3215-yq3GAJX.gif"},{"id":"3302","n":"handstand","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Find an open space with enough room to perform a handstand.","Place your hands on the ground shoulder-width apart, fingers pointing forward.","Kick your legs up towards the wall, using your core and shoulders to maintain balance.","Once in a handstand position, engage your triceps to support your body weight.","Hold the handstand for as long as you can maintain balance.","To come down, slowly lower your legs back to the ground.","Repeat for the desired number of repetitions."],"img":"3302-XooAdhl.jpg","gif":"3302-XooAdhl.gif","ty":"atl","kind":"time"},{"id":"0471","n":"handstand push-up","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders","chest","core"],"st":["Find a wall and face away from it, standing a few feet away.","Place your hands on the ground shoulder-width apart and kick your feet up against the wall, coming into a handstand position.","Bend your elbows and lower your head towards the ground, keeping your body in a straight line.","Push through your hands and extend your arms to return to the starting position.","Repeat for the desired number of repetitions."],"img":"0471-rQxwMxO.jpg","gif":"0471-rQxwMxO.gif","ty":"atl"},{"id":"1764","n":"hanging leg hip raise","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up by flexing your hips and knees until your thighs are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1764-VEcJRo2.jpg","gif":"1764-VEcJRo2.gif"},{"id":"0472","n":"hanging leg raise","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0472-I3tsCnC.jpg","gif":"0472-I3tsCnC.gif"},{"id":"1761","n":"hanging oblique knee raise","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your knees towards your chest, twisting your torso to the side as you do so.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat on the other side, twisting your torso in the opposite direction.","Continue alternating sides for the desired number of repetitions."],"img":"1761-BaE7O6U.jpg","gif":"1761-BaE7O6U.gif"},{"id":"0473","n":"hanging pike","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","shoulders"],"st":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up towards the bar, keeping them straight.","Continue lifting until your body forms a 'V' shape, with your legs parallel to the ground.","Hold the position for a moment, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0473-nuBF9MO.jpg","gif":"0473-nuBF9MO.gif"},{"id":"0474","n":"hanging straight leg hip raise","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up in front of you until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0474-pj0X0tF.jpg","gif":"0474-pj0X0tF.gif"},{"id":"0475","n":"hanging straight leg raise","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0475-4Ml7QFO.jpg","gif":"0475-4Ml7QFO.gif"},{"id":"0476","n":"hanging straight twisting leg hip raise","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Hang from a pull-up bar with your arms fully extended and your legs straight.","Engage your core and lift your legs up towards your chest, keeping them straight.","Once your legs are parallel to the ground, twist your hips to one side, bringing your legs towards that side.","Pause for a moment, then return to the starting position.","Repeat the movement, but this time twist your hips to the opposite side.","Continue alternating sides for the desired number of repetitions."],"img":"0476-Q6bvyen.jpg","gif":"0476-Q6bvyen.gif"},{"id":"3636","n":"high knee against wall","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","glutes","calves"],"st":["Stand facing a wall with your feet hip-width apart.","Place your hands on the wall for support.","Engage your core and lift your right knee up towards your chest, while keeping your left foot on the ground.","Quickly switch legs, bringing your left knee up towards your chest and lowering your right foot back down.","Continue alternating legs in a running motion, bringing your knees up as high as possible.","Maintain a fast pace and keep your upper body stable throughout the exercise.","Repeat for the desired duration or number of repetitions."],"img":"3636-ealLwvX.jpg","gif":"3636-ealLwvX.gif"},{"id":"0484","n":"hip raise (bent knee)","bp":"waist","eq":"body weight","tg":"abs","mg":"glutes","sm":["glutes","hamstrings"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands by your sides, palms facing down.","Engage your core and glutes, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0484-196HJGw.jpg","gif":"0484-196HJGw.gif"},{"id":"1418","n":"hug keens to chest","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Start by standing with your feet shoulder-width apart.","Bend your knees and lower your body down into a squat position.","As you squat down, bring your knees up towards your chest and hug them with your arms.","Hold this position for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"1418-znP9SIh.jpg","gif":"1418-znP9SIh.gif"},{"id":"3234","n":"hyght dumbbell fly","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders"],"st":["Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight up over your chest, with a slight bend in your elbows.","Keeping a slight bend in your elbows, lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then reverse the movement and bring the dumbbells back to the starting position.","Repeat for the desired number of repetitions."],"img":"3234-P9ZRyLT.jpg","gif":"3234-P9ZRyLT.gif"},{"id":"0489","n":"hyperextension","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Adjust the hyperextension bench so that your upper thighs are resting on the pad and your feet are secured.","Cross your arms over your chest or place your hands behind your head.","Lower your upper body towards the ground while keeping your back straight.","Pause for a moment at the bottom, then raise your upper body back up until it is in line with your legs.","Repeat for the desired number of repetitions."],"img":"0489-zhMwOwE.jpg","gif":"0489-zhMwOwE.gif"},{"id":"0488","n":"hyperextension (on bench)","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Adjust the hyperextension bench so that your hips are resting comfortably on the pad and your feet are secured.","Cross your arms over your chest or place your hands behind your head.","Slowly lower your upper body towards the ground while keeping your back straight.","Pause for a moment at the bottom, then raise your upper body back up until it is in line with your legs.","Repeat for the desired number of repetitions."],"img":"0488-zkgRrbK.jpg","gif":"0488-zkgRrbK.gif"},{"id":"3289","n":"impossible dips","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Position yourself between two parallel bars with your arms fully extended and your body suspended in the air.","Bend your knees and cross your ankles.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"img":"3289-05Cf2v8.jpg","gif":"3289-05Cf2v8.gif"},{"id":"1471","n":"inchworm","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","hamstrings"],"st":["Start in a standing position with your feet hip-width apart.","Bend forward at the waist and place your hands on the ground in front of you.","Walk your hands forward until you are in a high plank position, with your body in a straight line from head to toe.","Pause for a moment, then walk your hands back towards your feet, keeping your legs as straight as possible.","Once your hands reach your feet, stand back up to the starting position.","Repeat for the desired number of repetitions."],"img":"1471-ZgsNQ6d.jpg","gif":"1471-ZgsNQ6d.gif","ty":"mob"},{"id":"3698","n":"inchworm v. 2","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","hamstrings"],"st":["Start in a standing position with your feet hip-width apart.","Bend forward at the waist and place your hands on the ground in front of you.","Walk your hands forward until you are in a high plank position, with your body in a straight line from head to toe.","Keeping your legs straight, walk your feet towards your hands, bringing your hips up towards the ceiling.","Continue walking your hands forward, repeating the movement for the desired number of repetitions."],"img":"3698-TV87DNB.jpg","gif":"3698-TV87DNB.gif","ty":"mob"},{"id":"0490","n":"incline close-grip push-up","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, with your body forming a straight line from head to heels.","Lower your chest towards the elevated surface by bending your elbows, keeping them close to your sides.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"img":"0490-1YB40kg.jpg","gif":"0490-1YB40kg.gif"},{"id":"0491","n":"incline leg hip raise (leg straight)","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Lie on an incline bench with your back flat against the bench and your legs extended straight out in front of you.","Place your hands on the sides of the bench for support.","Engaging your abs, lift your legs off the bench, raising them as high as you can while keeping them straight.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0491-eVxAzgz.jpg","gif":"0491-eVxAzgz.gif"},{"id":"0492","n":"incline push up depth jump","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Find an elevated surface, such as a bench or step, and place your hands shoulder-width apart on the edge.","Step your feet back, keeping your body in a straight line from head to heels.","Lower your chest towards the edge of the surface, bending your elbows and keeping your body aligned.","Push through your palms to extend your arms and return to the starting position.","Jump off the edge of the surface, landing softly with your knees slightly bent.","Repeat the push-up and depth jump for the desired number of repetitions."],"img":"0492-CB8WET1.jpg","gif":"0492-CB8WET1.gif","ty":"atl"},{"id":"0493","n":"incline push-up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Lower your chest towards the elevated surface by bending your elbows, keeping your body in a straight line.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"img":"0493-B1EVP9F.jpg","gif":"0493-B1EVP9F.gif"},{"id":"3785","n":"incline push-up (on box)","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Place your hands on the edge of a box or elevated surface, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Lower your chest towards the box by bending your elbows, keeping your body in a straight line.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"img":"3785-F7vjXqT.jpg","gif":"3785-F7vjXqT.gif"},{"id":"0494","n":"incline reverse grip push-up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Place your hands on the edge of a bench or elevated surface, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Lower your chest towards the bench by bending your elbows, keeping them close to your sides.","Pause for a moment at the bottom, then push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."],"img":"0494-XaaRnRn.jpg","gif":"0494-XaaRnRn.gif"},{"id":"3011","n":"incline scapula push up","bp":"chest","eq":"body weight","tg":"serratus anterior","mg":"triceps","sm":["triceps","shoulders"],"st":["Set up an incline bench at a 45-degree angle.","Place your hands on the bench slightly wider than shoulder-width apart.","Position your feet on the ground, hip-width apart.","Lower your chest towards the bench, keeping your elbows tucked in.","As you lower, retract your shoulder blades, squeezing your scapulae together.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."],"img":"3011-GdMa1ET.jpg","gif":"3011-GdMa1ET.gif","ty":"rin"},{"id":"0495","n":"incline twisting sit-up","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet secured under the foot pads.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body off the bench, curling forward.","As you curl up, twist your torso to one side, bringing your elbow towards the opposite knee.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat the movement, this time twisting your torso to the other side.","Continue alternating sides for the desired number of repetitions."],"img":"0495-9ZGZuOD.jpg","gif":"0495-9ZGZuOD.gif"},{"id":"1564","n":"intermediate hip flexor and quad stretch","bp":"upper legs","eq":"rope","tg":"quads","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Stand upright with your feet shoulder-width apart.","Hold onto a stable object for support.","Bend your right knee and bring your right foot towards your glutes, grabbing the rope with your right hand.","Slowly pull your right foot towards your glutes, feeling a stretch in your right quad.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat on the left side."],"img":"1564-tFGKm99.jpg","gif":"1564-tFGKm99.gif","ty":"stretch","kind":"time"},{"id":"0496","n":"inverse leg curl (bench support)","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","calves"],"st":["Lie face down on a bench with your hips at the edge and your legs extended straight behind you.","Hold onto the bench for support.","Keeping your upper body still, bend your knees and curl your legs towards your glutes.","Pause for a moment at the top, then slowly extend your legs back to the starting position.","Repeat for the desired number of repetitions."],"img":"0496-ms7tjSG.jpg","gif":"0496-ms7tjSG.gif"},{"id":"2400","n":"inverse leg curl (on pull-up cable machine)","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","calves"],"st":["Adjust the cable machine so that the ankle straps are at the lowest setting.","Lie face down on the bench with your legs extended and the ankle straps attached to your feet.","Hold onto the handles of the bench for stability.","Bend your knees and curl your legs towards your glutes, squeezing your hamstrings.","Pause for a moment at the top of the movement, then slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."],"img":"2400-0rHfvy9.jpg","gif":"2400-0rHfvy9.gif"},{"id":"0499","n":"inverted row","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Set up a bar at waist height or use a suspension trainer.","Stand facing the bar or suspension trainer, with your feet shoulder-width apart.","Grab the bar or handles with an overhand grip, slightly wider than shoulder-width apart.","Lean back, keeping your body straight and your heels on the ground.","Pull your chest towards the bar or handles, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower yourself back to the starting position.","Repeat for the desired number of repetitions."],"img":"0499-bZGHsAZ.jpg","gif":"0499-bZGHsAZ.gif"},{"id":"2300","n":"inverted row bent knees","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Set up a bar at waist height and lie underneath it.","Grab the bar with an overhand grip, slightly wider than shoulder-width apart.","Position your body so that your heels are on the ground and your body is straight.","Pull your chest up towards the bar by squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"2300-VPPtusI.jpg","gif":"2300-VPPtusI.gif"},{"id":"2298","n":"inverted row on bench","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Set up a bench at a height that allows your body to hang freely underneath it.","Lie face up on the ground with your head towards the bench.","Reach up and grab the bench with an overhand grip, slightly wider than shoulder-width apart.","Position your body so that your heels are on the ground and your arms are fully extended.","Engage your core and squeeze your shoulder blades together as you pull your chest up towards the bench.","Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"2298-Mxa7Cr8.jpg","gif":"2298-Mxa7Cr8.gif"},{"id":"0497","n":"inverted row v. 2","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Set up a bar at waist height on a Smith machine or use a suspension trainer.","Stand facing the bar or suspension trainer and grab it with an overhand grip, hands shoulder-width apart.","Walk your feet forward, leaning back until your body is at a slight angle.","Keep your body straight and pull your chest up towards the bar or handles, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0497-uX3sUBz.jpg","gif":"0497-uX3sUBz.gif"},{"id":"0498","n":"inverted row with straps","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Set up a suspension trainer or straps at chest height.","Stand facing the anchor point and grab the handles with an overhand grip.","Walk your feet forward, leaning back until your body is at an angle.","Keep your body straight and engage your core.","Pull your chest towards the handles, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower yourself back to the starting position.","Repeat for the desired number of repetitions."],"img":"0498-jdiExfW.jpg","gif":"0498-jdiExfW.gif"},{"id":"1419","n":"iron cross stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Lie flat on your back with your arms extended out to the sides.","Raise your legs up towards the ceiling, keeping them straight.","Slowly lower your legs to one side, aiming to touch the floor with your feet.","Hold the stretch for a few seconds, then return your legs to the starting position.","Repeat the stretch on the other side.","Continue alternating sides for the desired number of repetitions."],"img":"1419-pZwUsKB.jpg","gif":"1419-pZwUsKB.gif","ty":"stretch","kind":"time"},{"id":"1297","n":"isometric chest squeeze","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Stand with your feet shoulder-width apart and your knees slightly bent.","Extend your arms straight out in front of you, parallel to the ground, with your palms facing each other.","Squeeze your chest muscles together as hard as you can, while keeping your arms straight.","Hold this position for a few seconds, focusing on contracting your chest muscles.","Release the squeeze and relax your chest muscles.","Repeat for the desired number of repetitions."],"img":"1297-HbSG1Pw.jpg","gif":"1297-HbSG1Pw.gif","ty":"rin"},{"id":"0500","n":"isometric wipers","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps","core"],"st":["Start by lying flat on your back on a mat or bench.","Extend your arms straight out to the sides, perpendicular to your body.","Engage your core and lift both legs off the ground, keeping them together and straight.","Slowly lower your legs to one side, aiming to touch the ground with your feet while maintaining control.","Pause for a moment, then use your core to lift your legs back to the starting position.","Repeat the movement, this time lowering your legs to the opposite side.","Continue alternating sides for the desired number of repetitions."],"img":"0500-11wrviz.jpg","gif":"0500-11wrviz.gif","ty":"rin"},{"id":"0501","n":"jack burpee","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","shoulders","triceps","core"],"st":["Start in a standing position with your feet shoulder-width apart.","Lower your body into a squat position, placing your hands on the ground in front of you.","Kick your feet back, landing in a push-up position.","Perform a push-up, lowering your chest to the ground and then pushing back up.","Jump your feet forward, landing in a squat position.","Jump up explosively, reaching your arms overhead.","Land softly and immediately lower back into the squat position to begin the next repetition."],"img":"0501-mr7pkqP.jpg","gif":"0501-mr7pkqP.gif","ty":"atl"},{"id":"3224","n":"jack jump (male)","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","calves"],"st":["Stand with your feet together and your arms by your sides.","Jump up, spreading your feet apart and raising your arms above your head.","As you land, quickly jump back to the starting position.","Repeat for the desired number of repetitions."],"img":"3224-1g5bPpA.jpg","gif":"3224-1g5bPpA.gif","ty":"atl"},{"id":"0507","n":"jackknife sit-up","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Lie flat on your back with your legs extended and your arms overhead.","Engage your core and lift your legs and upper body simultaneously, reaching your hands towards your toes.","Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0507-mbkgB44.jpg","gif":"0507-mbkgB44.gif"},{"id":"0508","n":"janda sit-up","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0508-1GPHRyK.jpg","gif":"0508-1GPHRyK.gif"},{"id":"2612","n":"jump rope","bp":"cardio","eq":"rope","tg":"cardiovascular system","mg":"calves","sm":["calves","quadriceps","hamstrings","glutes"],"st":["Hold the handles of the jump rope with your hands, palms facing inward.","Stand with your feet shoulder-width apart and knees slightly bent.","Swing the rope over your head and jump over it as it comes towards your feet.","Land softly on the balls of your feet and repeat the jump as the rope comes around again.","Continue jumping for the desired duration or number of repetitions."],"img":"2612-e1e76I2.jpg","gif":"2612-e1e76I2.gif","ty":"atl"},{"id":"0514","n":"jump squat","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and pushing your hips back.","Jump explosively off the ground, extending your hips, knees, and ankles.","While in mid-air, quickly bring your arms forward for balance.","Land softly on the balls of your feet and immediately go into the next repetition.","Repeat for the desired number of repetitions."],"img":"0514-LIlE5Tn.jpg","gif":"0514-LIlE5Tn.gif","ty":"atl"},{"id":"0513","n":"jump squat v. 2","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and pushing your hips back.","Jump explosively, extending your hips and knees fully.","Land softly on the balls of your feet and immediately lower your body back into a squat position.","Repeat for the desired number of repetitions."],"img":"0513-TDYiji6.jpg","gif":"0513-TDYiji6.gif","ty":"atl"},{"id":"0517","n":"kettlebell advanced windmill","bp":"waist","eq":"kettlebell","tg":"abs","mg":"obliques","sm":["obliques","shoulders"],"st":["Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.","Hold a kettlebell in your right hand, with your arm extended overhead and your palm facing forward.","Rotate your left foot slightly to the right, and shift your weight onto your left leg.","Bend your left knee and hinge at the hip, lowering your torso towards the left side.","Keep your right arm extended overhead and your eyes on the kettlebell.","As you lower your torso, allow your right leg to straighten and your right foot to pivot slightly.","Lower your torso until you feel a stretch in your left hamstring and your right arm is pointing towards the ground.","Pause for a moment, then engage your core and push through your left heel to return to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"0517-Kal9cQQ.jpg","gif":"0517-Kal9cQQ.gif"},{"id":"0518","n":"kettlebell alternating hang clean","bp":"lower arms","eq":"kettlebell","tg":"forearms","mg":"shoulders","sm":["shoulders","traps","core"],"st":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Allow the kettlebells to hang in front of your body with your arms fully extended.","In one fluid motion, explosively extend your hips, shrug your shoulders, and pull the kettlebells up towards your shoulders.","As the kettlebells reach shoulder height, rotate your wrists and catch the kettlebells in the rack position, with your palms facing inward and the kettlebells resting on the outside of your forearms.","Lower the kettlebells back down to the starting position and repeat the movement with the opposite arm.","Continue alternating arms for the desired number of repetitions."],"img":"0518-I4tibZG.jpg","gif":"0518-I4tibZG.gif"},{"id":"0520","n":"kettlebell alternating press","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Press one kettlebell overhead, fully extending your arm.","Lower the kettlebell back to shoulder height.","Repeat with the other arm.","Continue alternating arms for the desired number of repetitions."],"img":"0520-5KLbZWx.jpg","gif":"0520-5KLbZWx.gif"},{"id":"0519","n":"kettlebell alternating press on floor","bp":"chest","eq":"kettlebell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Start by lying on your back on the floor with your knees bent and feet flat on the ground.","Hold a kettlebell in each hand, with your palms facing towards your feet and your arms extended straight up towards the ceiling.","Lower one kettlebell down towards your shoulder while keeping the other kettlebell extended straight up.","Press the lowered kettlebell back up to the starting position while simultaneously lowering the other kettlebell down towards your shoulder.","Continue alternating the press motion with each kettlebell for the desired number of repetitions."],"img":"0519-7w6i0vE.jpg","gif":"0519-7w6i0vE.gif"},{"id":"0521","n":"kettlebell alternating renegade row","bp":"back","eq":"kettlebell","tg":"upper back","mg":"core","sm":["core","shoulders"],"st":["Start in a high plank position with your hands gripping the kettlebells and your feet hip-width apart.","Engage your core and keep your body in a straight line from head to heels.","Pull one kettlebell up towards your chest, keeping your elbow close to your body.","Lower the kettlebell back down to the starting position and repeat with the other arm.","Continue alternating arms for the desired number of repetitions."],"img":"0521-b9kqlBy.jpg","gif":"0521-b9kqlBy.gif"},{"id":"0522","n":"kettlebell alternating row","bp":"back","eq":"kettlebell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body.","Bend forward at the hips, keeping your back straight and your core engaged.","Pull one kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Lower the kettlebell back down to the starting position and repeat with the other arm.","Continue alternating arms for the desired number of repetitions."],"img":"0522-Ca76jUE.jpg","gif":"0522-Ca76jUE.gif"},{"id":"0523","n":"kettlebell arnold press","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height with your palms facing towards you.","Engage your core and press the kettlebells overhead, rotating your palms to face forward as you extend your arms.","Pause at the top of the movement, then slowly lower the kettlebells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0523-UM8mgyG.jpg","gif":"0523-UM8mgyG.gif"},{"id":"0524","n":"kettlebell bent press","bp":"waist","eq":"kettlebell","tg":"abs","mg":"shoulders","sm":["shoulders","triceps","obliques"],"st":["Stand with your feet shoulder-width apart, holding a kettlebell in your right hand.","Bend your knees slightly and press the kettlebell overhead with your right arm, keeping your elbow locked.","Rotate your torso to the left, shifting your weight onto your left foot.","Bend your left knee and lower your torso towards the ground, keeping your right arm extended overhead.","As you lower, keep your eyes on the kettlebell and your chest lifted.","Once your left hand touches the ground, push through your left foot and straighten your left leg, driving your hips forward.","As you drive your hips forward, use your core and right arm to press the kettlebell back up to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"0524-kjE55n5.jpg","gif":"0524-kjE55n5.gif"},{"id":"0525","n":"kettlebell bottoms up clean from the hang position","bp":"upper arms","eq":"kettlebell","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Allow the kettlebell to hang down between your legs, with your arm fully extended.","In one fluid motion, explosively extend your hips and knees while pulling the kettlebell up towards your shoulder.","As the kettlebell reaches shoulder height, rotate your wrist so that the bottom of the kettlebell is facing up.","Catch the kettlebell at shoulder height with your elbow bent and your palm facing up.","Lower the kettlebell back down to the starting position by reversing the movement.","Repeat for the desired number of repetitions, then switch sides."],"img":"0525-4KJEpzb.jpg","gif":"0525-4KJEpzb.gif"},{"id":"0526","n":"kettlebell double alternating hang clean","bp":"upper arms","eq":"kettlebell","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Allow the kettlebells to hang straight down in front of your body.","In one fluid motion, explosively extend your hips and knees while shrugging your shoulders.","As the kettlebells rise, pull them up towards your shoulders, keeping your elbows high and out to the sides.","Catch the kettlebells at shoulder height, with your palms facing inward and your elbows pointing forward.","Lower the kettlebells back down to the starting position and repeat for the desired number of repetitions."],"img":"0526-a4F9Oyc.jpg","gif":"0526-a4F9Oyc.gif"},{"id":"0527","n":"kettlebell double jerk","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Bend your knees slightly and engage your core.","Press the kettlebells overhead, fully extending your arms.","Bend your knees and quickly drop into a partial squat.","Explosively extend your hips and knees, driving the kettlebells overhead.","Lock out your arms and catch the kettlebells overhead with your knees slightly bent.","Stand up straight and return to the starting position.","Repeat for the desired number of repetitions."],"img":"0527-tznL2Ad.jpg","gif":"0527-tznL2Ad.gif"},{"id":"0528","n":"kettlebell double push press","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Start by standing with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Bend your knees slightly and engage your core.","Initiate the movement by explosively extending your hips, knees, and ankles, driving the kettlebells overhead.","As the kettlebells reach the top, press them fully overhead, locking out your arms.","Lower the kettlebells back to the starting position by bending your elbows and bringing them back down to shoulder height.","Repeat for the desired number of repetitions."],"img":"0528-I4KkPdl.jpg","gif":"0528-I4KkPdl.gif"},{"id":"0529","n":"kettlebell double snatch","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"trapezius","sm":["trapezius","forearms","core"],"st":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at arm's length in front of your thighs.","Bend your knees slightly and hinge forward at the hips, keeping your back flat and chest up.","In one explosive motion, extend your hips, knees, and ankles, and simultaneously pull the kettlebells up towards your shoulders.","As the kettlebells reach shoulder level, rotate your wrists and punch the kettlebells overhead, fully extending your arms.","Lower the kettlebells back down to the starting position and repeat for the desired number of repetitions."],"img":"0529-M74kdvm.jpg","gif":"0529-M74kdvm.gif"},{"id":"0530","n":"kettlebell double windmill","bp":"waist","eq":"kettlebell","tg":"abs","mg":"shoulders","sm":["shoulders","hamstrings"],"st":["Stand with your feet shoulder-width apart, holding a kettlebell in your right hand.","Extend your right arm overhead, keeping your eyes on the kettlebell.","Rotate your left foot 45 degrees to the left and your right foot 90 degrees to the right.","Bend at the waist to the left, keeping your right arm extended overhead.","Lower the kettlebell towards the ground, reaching towards your left foot.","Pause for a moment, then engage your core and push through your right foot to return to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"0530-OaE7CpD.jpg","gif":"0530-OaE7CpD.gif"},{"id":"0531","n":"kettlebell extended range one arm press on floor","bp":"chest","eq":"kettlebell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Start by lying on your back on the floor with your knees bent and feet flat on the ground.","Hold a kettlebell in one hand, with your palm facing towards your feet.","Extend your arm straight up towards the ceiling, keeping your elbow locked and your wrist straight.","Slowly lower the kettlebell back down to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions, then switch to the other arm."],"img":"0531-rseLfH3.jpg","gif":"0531-rseLfH3.gif"},{"id":"0532","n":"kettlebell figure 8","bp":"waist","eq":"kettlebell","tg":"abs","mg":"shoulders","sm":["shoulders","forearms"],"st":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Pass the kettlebell between your legs, switching hands as it reaches the back of your legs.","As the kettlebell comes forward, pass it to the other hand between your legs.","Continue passing the kettlebell between your legs in a figure 8 motion.","Maintain a steady pace and engage your core throughout the exercise.","Repeat for the desired number of repetitions."],"img":"0532-L4ay0PW.jpg","gif":"0532-L4ay0PW.gif"},{"id":"0533","n":"kettlebell front squat","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the kettlebell with both hands in front of your chest, close to your body.","Engage your core and keep your chest up as you lower your hips down and back, as if sitting into a chair.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Drive through your heels to stand back up, squeezing your glutes at the top.","Repeat for the desired number of repetitions."],"img":"0533-DB0n8AG.jpg","gif":"0533-DB0n8AG.gif"},{"id":"0534","n":"kettlebell goblet squat","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart, holding a kettlebell close to your chest with both hands.","Keeping your chest up and core engaged, lower your body down into a squat position by bending at the knees and hips.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"0534-ZA8b5hc.jpg","gif":"0534-ZA8b5hc.gif"},{"id":"0535","n":"kettlebell hang clean","bp":"upper legs","eq":"kettlebell","tg":"hamstrings","mg":"glutes","sm":["glutes","quadriceps","calves"],"st":["Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Lower the kettlebell towards the ground, allowing it to swing between your legs.","Quickly extend your hips and knees, using the momentum to swing the kettlebell up to shoulder height.","As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbow tucked in and the kettlebell resting on your forearm.","Lower the kettlebell back down to the starting position between your legs, and repeat for the desired number of repetitions."],"img":"0535-LHWF7us.jpg","gif":"0535-LHWF7us.gif"},{"id":"0536","n":"kettlebell lunge pass through","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands.","Take a step forward with your right foot, lowering your body into a lunge position.","As you lunge forward, pass the kettlebell under your right thigh and transfer it to your left hand.","Push off with your right foot to return to the starting position, while simultaneously passing the kettlebell back to your right hand.","Repeat the lunge on the opposite side, passing the kettlebell under your left thigh.","Continue alternating lunges and passing the kettlebell between hands for the desired number of repetitions."],"img":"0536-WKMQzCD.jpg","gif":"0536-WKMQzCD.gif"},{"id":"0537","n":"kettlebell one arm clean and jerk","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.","Bend your knees slightly and hinge at the hips, lowering the kettlebell between your legs.","Explosively extend your hips, knees, and ankles, using the momentum to swing the kettlebell up to shoulder height.","As the kettlebell reaches shoulder height, rotate your wrist and punch your hand straight up, locking out your arm overhead.","Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions."],"img":"0537-vzAxBtt.jpg","gif":"0537-vzAxBtt.gif"},{"id":"1298","n":"kettlebell one arm floor press","bp":"chest","eq":"kettlebell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Lie flat on your back on the floor with your knees bent and feet flat on the ground.","Hold the kettlebell in one hand with your palm facing towards your feet and your arm extended straight up towards the ceiling.","Slowly lower the kettlebell towards your chest by bending your elbow, keeping your upper arm close to your body.","Pause for a moment when the kettlebell is just above your chest, then push it back up to the starting position by extending your elbow.","Repeat for the desired number of repetitions, then switch to the other arm."],"img":"1298-rg59QCH.jpg","gif":"1298-rg59QCH.gif"},{"id":"0538","n":"kettlebell one arm jerk","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height.","Bend your knees slightly and engage your core.","Press the kettlebell overhead in a straight line, fully extending your arm.","As you press the kettlebell overhead, simultaneously dip your knees and quickly straighten them to generate momentum.","As the kettlebell reaches its highest point, quickly drop underneath it by bending your knees and hips.","Catch the kettlebell with a slight bend in your knees and hips, and your arm fully extended overhead.","Stand up straight, fully extending your knees and hips, and stabilize the kettlebell overhead.","Lower the kettlebell back to the starting position by bending your knees and hips, and repeat for the desired number of repetitions."],"img":"0538-S37C94C.jpg","gif":"0538-S37C94C.gif"},{"id":"0539","n":"kettlebell one arm military press to the side","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height.","Engage your core and keep your back straight.","Press the kettlebell overhead, extending your arm fully.","Pause for a moment at the top, then slowly lower the kettlebell back to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"0539-yCvYdi7.jpg","gif":"0539-yCvYdi7.gif"},{"id":"0540","n":"kettlebell one arm push press","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder level.","Bend your knees slightly and engage your core.","Press the kettlebell overhead by extending your arm and fully extending your legs.","Lower the kettlebell back to the starting position by bending your knees and bringing the kettlebell back to your shoulder.","Repeat for the desired number of repetitions, then switch sides."],"img":"0540-osdXT3K.jpg","gif":"0540-osdXT3K.gif"},{"id":"0541","n":"kettlebell one arm row","bp":"back","eq":"kettlebell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.","Pull the kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the kettlebell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides and repeat with the other arm."],"img":"0541-g9AsZ8P.jpg","gif":"0541-g9AsZ8P.gif"},{"id":"0542","n":"kettlebell one arm snatch","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"trapezius","sm":["trapezius","forearms","core"],"st":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand between your legs.","Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground.","Explosively extend your hips and knees, using the momentum to swing the kettlebell up towards your shoulder.","As the kettlebell reaches shoulder height, rotate your hand and punch it straight up overhead, fully extending your arm.","Lower the kettlebell back down between your legs and repeat for the desired number of repetitions."],"img":"0542-aXcUyKb.jpg","gif":"0542-aXcUyKb.gif"},{"id":"0543","n":"kettlebell pirate supper legs","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","forearms"],"st":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise the kettlebell up to shoulder height, keeping your elbow close to your body.","Extend your arm fully overhead, straightening your elbow.","Lower the kettlebell back down to shoulder height, then return to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"0543-kuXhl0o.jpg","gif":"0543-kuXhl0o.gif"},{"id":"0544","n":"kettlebell pistol squat","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands.","Lift your left foot off the ground and extend it forward, keeping it parallel to the ground.","Slowly lower your body down into a squat position, keeping your right foot flat on the ground and your left leg extended.","Pause for a moment at the bottom of the squat, then push through your right heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"img":"0544-5bpPTHv.jpg","gif":"0544-5bpPTHv.gif","ty":"atl"},{"id":"0545","n":"kettlebell plyo push-up","bp":"chest","eq":"kettlebell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Start in a high plank position with your hands on the kettlebells, shoulder-width apart.","Lower your chest towards the ground, keeping your elbows close to your body.","Push through your hands explosively, lifting your hands off the kettlebells and extending your arms fully.","Land softly back on the kettlebells and immediately lower your chest back down for the next repetition.","Repeat for the desired number of repetitions."],"img":"0545-ktf3nvW.jpg","gif":"0545-ktf3nvW.gif"},{"id":"0546","n":"kettlebell seated press","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Sit on a bench with your back straight and feet flat on the ground.","Hold a kettlebell in each hand at shoulder height, palms facing forward.","Press the kettlebells overhead, fully extending your arms.","Lower the kettlebells back to shoulder height.","Repeat for the desired number of repetitions."],"img":"0546-BkxB8LW.jpg","gif":"0546-BkxB8LW.gif"},{"id":"1438","n":"kettlebell seated two arm military press","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Sit on a bench with your back straight and feet flat on the ground.","Hold a kettlebell in each hand at shoulder level with your palms facing forward.","Press the kettlebells overhead by extending your arms fully.","Pause for a moment at the top, then slowly lower the kettlebells back to shoulder level.","Repeat for the desired number of repetitions."],"img":"1438-ZEkjZDi.jpg","gif":"1438-ZEkjZDi.gif"},{"id":"0547","n":"kettlebell seesaw press","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Press one kettlebell overhead while keeping the other kettlebell at shoulder height.","Lower the pressed kettlebell back to shoulder height while simultaneously pressing the other kettlebell overhead.","Continue alternating the pressing motion, creating a seesaw-like movement.","Repeat for the desired number of repetitions."],"img":"0547-UDm6cGl.jpg","gif":"0547-UDm6cGl.gif"},{"id":"0548","n":"kettlebell sumo high pull","bp":"back","eq":"kettlebell","tg":"traps","mg":"shoulders","sm":["shoulders","glutes","hamstrings"],"st":["Stand with your feet wider than shoulder-width apart, toes pointing outwards.","Hold a kettlebell with both hands in front of your body, arms extended downwards.","Bend your knees and lower your hips into a squat position, keeping your back straight.","Drive through your heels and explosively extend your hips and knees, pulling the kettlebell up towards your chin.","As you pull the kettlebell up, keep your elbows high and wide, and squeeze your shoulder blades together.","Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions."],"img":"0548-8ARQ9Hw.jpg","gif":"0548-8ARQ9Hw.gif"},{"id":"0549","n":"kettlebell swing","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Stand with your feet shoulder-width apart, toes pointed slightly outward.","Hold the kettlebell with both hands in front of your body, arms extended.","Bend your knees slightly and hinge at the hips, pushing your butt back.","Swing the kettlebell back between your legs, keeping your arms straight and maintaining a flat back.","Drive your hips forward and swing the kettlebell up to shoulder height, using the momentum generated by your hips.","Allow the kettlebell to swing back down between your legs and repeat the movement for the desired number of repetitions."],"img":"0549-UHJlbu3.jpg","gif":"0549-UHJlbu3.gif"},{"id":"0550","n":"kettlebell thruster","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"quadriceps","sm":["quadriceps","glutes","core"],"st":["Start by standing with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands, palms facing each other.","Lower into a squat position by bending your knees and pushing your hips back, keeping your chest up and your back straight.","As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the kettlebell overhead.","Lock out your arms at the top of the movement, fully extending your elbows.","Lower the kettlebell back to the starting position by reversing the movement, bending your elbows and lowering the weight back to your chest.","Repeat for the desired number of repetitions."],"img":"0550-yWxMvB5.jpg","gif":"0550-yWxMvB5.gif"},{"id":"0551","n":"kettlebell turkish get up (squat style)","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Start by lying on your back with your legs extended and the kettlebell held in your right hand, arm fully extended above your shoulder.","Bend your right knee and place your right foot flat on the ground, keeping your left leg extended.","Pressing through your right foot, lift your hips off the ground, coming into a bridge position.","Slide your left leg underneath your body, bending your left knee and placing your left foot flat on the ground.","Rotate your torso to the left, bringing your left hand to the ground for support.","Pressing through your right foot and left hand, lift your torso off the ground, coming into a kneeling position.","From the kneeling position, stand up, keeping the kettlebell extended overhead.","Reverse the movement to return to the starting position.","Repeat the exercise on the other side, starting with the kettlebell in your left hand."],"img":"0551-Ha7SZ3y.jpg","gif":"0551-Ha7SZ3y.gif"},{"id":"0552","n":"kettlebell two arm clean","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"traps","sm":["traps","forearms"],"st":["Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs with both hands, palms facing towards you.","Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground.","Explosively extend your hips and knees, using the momentum to pull the kettlebell up towards your shoulders.","As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbows tucked in and the kettlebell resting on the back of your forearm.","Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions."],"img":"0552-7Ba7bQ2.jpg","gif":"0552-7Ba7bQ2.gif"},{"id":"0553","n":"kettlebell two arm military press","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder level with your palms facing forward.","Engage your core and press the kettlebells overhead, fully extending your arms.","Pause for a moment at the top, then slowly lower the kettlebells back to the starting position.","Repeat for the desired number of repetitions."],"img":"0553-blBXysN.jpg","gif":"0553-blBXysN.gif"},{"id":"1345","n":"kettlebell two arm row","bp":"back","eq":"kettlebell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body.","Bend forward at the hips, keeping your back straight and your core engaged.","Pull the kettlebells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the kettlebells back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1345-wf24o8S.jpg","gif":"1345-wf24o8S.gif"},{"id":"0554","n":"kettlebell windmill","bp":"waist","eq":"kettlebell","tg":"abs","mg":"obliques","sm":["obliques","shoulders"],"st":["Stand with your feet shoulder-width apart, holding a kettlebell in your right hand overhead.","Rotate your left foot outwards about 45 degrees and keep your right foot pointing forward.","Bend your torso to the left side, keeping your right arm extended overhead and your eyes on the kettlebell.","Lower your torso as far as you can while keeping your right arm straight and your left arm extended to the side.","Pause for a moment, then return to the starting position by pushing through your right foot and engaging your obliques.","Repeat for the desired number of repetitions, then switch sides."],"img":"0554-9Tkqa9O.jpg","gif":"0554-9Tkqa9O.gif"},{"id":"0555","n":"kick out sit","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"quadriceps","sm":["quadriceps","glutes"],"st":["Sit on the edge of a bench or chair with your feet flat on the ground and your knees bent at a 90-degree angle.","Lean back slightly and place your hands on the edge of the bench or chair for support.","Engaging your hamstrings, lift your feet off the ground and extend your legs straight out in front of you.","Pause for a moment at the top, then slowly bend your knees and bring your feet back towards your body.","Repeat for the desired number of repetitions."],"img":"0555-v7p5bYl.jpg","gif":"0555-v7p5bYl.gif"},{"id":"0558","n":"kipping muscle up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","triceps","shoulders","core"],"st":["Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.","Engage your core and use a swinging motion to generate momentum.","As you swing forward, pull your chest towards the bar, using your lats and biceps to initiate the movement.","Continue the upward motion until your chest reaches the bar, then transition into a dip position by pushing down on the bar and extending your arms.","Lower yourself back down to the starting position by bending your arms and controlling the descent.","Repeat for the desired number of repetitions."],"img":"0558-pM07UxU.jpg","gif":"0558-pM07UxU.gif","ty":"atl"},{"id":"3640","n":"knee touch crunch","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your shoulder blades off the ground and reach your right hand towards your left knee.","Return to the starting position and repeat, this time reaching your left hand towards your right knee.","Continue alternating sides for the desired number of repetitions."],"img":"3640-dTg95eZ.jpg","gif":"3640-dTg95eZ.gif"},{"id":"1420","n":"kneeling jump squat","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Start by kneeling on the ground with your feet hip-width apart and your toes pointing forward.","Hold a barbell across your upper back, resting it on your shoulders.","Engage your core and glutes, then explosively jump up into the air, extending your hips and knees.","As you jump, push through your toes and fully extend your ankles, knees, and hips.","Land softly back on the ground, bending your knees to absorb the impact.","Immediately go into the next repetition, repeating the jump squat motion."],"img":"1420-UgDm3oy.jpg","gif":"1420-UgDm3oy.gif","ty":"atl"},{"id":"1346","n":"kneeling lat stretch","bp":"back","eq":"body weight","tg":"lats","mg":"shoulders","sm":["shoulders","triceps"],"st":["Kneel on the ground with your knees hip-width apart and your toes pointing back.","Extend your arms overhead and interlace your fingers.","Keeping your back straight, slowly lean to the right side, feeling a stretch in your left lat muscle.","Hold the stretch for 20-30 seconds, then return to the starting position.","Repeat the stretch on the left side, leaning to the left and feeling a stretch in your right lat muscle.","Continue alternating sides for the desired number of repetitions."],"img":"1346-f38OEuO.jpg","gif":"1346-f38OEuO.gif","ty":"stretch","kind":"time"},{"id":"3239","n":"kneeling plank tap shoulder (male)","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","triceps"],"st":["Start in a kneeling position with your hands on the ground, shoulder-width apart.","Extend your legs behind you, resting on your toes, and lift your body into a plank position.","Keeping your core engaged and your hips stable, lift one hand off the ground and tap the opposite shoulder.","Return the hand to the ground and repeat with the other hand.","Continue alternating sides for the desired number of repetitions."],"img":"3239-h1ezqSu.jpg","gif":"3239-h1ezqSu.gif","ty":"rin"},{"id":"3211","n":"kneeling push-up (male)","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Start by kneeling on the ground with your hands shoulder-width apart, fingers pointing forward.","Extend your legs behind you, resting on the balls of your feet, so that your body forms a straight line from head to heels.","Engage your core and lower your body towards the ground by bending your elbows, keeping them close to your sides.","Continue lowering until your chest is just above the ground, then push back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"img":"3211-ZOuKWir.jpg","gif":"3211-ZOuKWir.gif"},{"id":"3288","n":"korean dips","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Position yourself between two parallel bars with your arms extended and supporting your body weight.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"img":"3288-rWoBmi5.jpg","gif":"3288-rWoBmi5.gif"},{"id":"3418","n":"l-pull-up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang with your arms fully extended and your body straight.","Engage your lats and biceps to pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"3418-d1GgzTU.jpg","gif":"3418-d1GgzTU.gif"},{"id":"3419","n":"l-sit on floor","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Sit on the floor with your legs extended in front of you.","Place your hands on the floor beside your hips, fingers pointing forward.","Engage your core and lift your legs off the ground, keeping them straight.","Try to bring your legs parallel to the floor, forming an 'L' shape with your body.","Hold this position for as long as you can.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"3419-UpWmA5E.jpg","gif":"3419-UpWmA5E.gif","ty":"atl","kind":"time"},{"id":"0562","n":"landmine 180","bp":"waist","eq":"barbell","tg":"abs","mg":"obliques","sm":["obliques","quadriceps"],"st":["Stand with your feet shoulder-width apart and hold the barbell with both hands in front of your chest.","Bend your knees slightly and rotate your torso to the right, swinging the barbell down towards your right hip.","As you reach the bottom of the movement, quickly reverse the motion and rotate your torso to the left, swinging the barbell up and across your body towards your left shoulder.","Continue this twisting motion, alternating sides, for the desired number of repetitions."],"img":"0562-QYysSLV.jpg","gif":"0562-QYysSLV.gif"},{"id":"3237","n":"landmine lateral raise","bp":"shoulders","eq":"barbell","tg":"delts","mg":"traps","sm":["traps","upper back"],"st":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold the barbell with an overhand grip, resting it on the front of your shoulders.","Keeping your core engaged and back straight, lift the barbell up and away from your body, raising it to shoulder height.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"img":"3237-eXMFHww.jpg","gif":"3237-eXMFHww.gif"},{"id":"3300","n":"lean planche","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","chest","triceps"],"st":["Start in a push-up position with your hands shoulder-width apart and your body straight.","Engage your core and slowly shift your weight forward, bringing your shoulders past your hands.","Keep your elbows slightly bent and your body straight as you lean forward.","Hold this position for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"3300-LYJodFS.jpg","gif":"3300-LYJodFS.gif"},{"id":"2271","n":"left hook. boxing","bp":"shoulders","eq":"body weight","tg":"delts","mg":"biceps","sm":["biceps","triceps","forearms"],"st":["Stand with your feet shoulder-width apart and your knees slightly bent.","Keep your left hand up to protect your face and your right hand by your chin.","Rotate your hips and pivot on your left foot as you extend your left arm forward in a punching motion.","Twist your torso and engage your core muscles to generate power in the punch.","Snap your arm back to the starting position and repeat for the desired number of repetitions."],"img":"2271-hoXt6wv.jpg","gif":"2271-hoXt6wv.gif"},{"id":"0570","n":"leg pull in flat bench","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Sit on a flat bench with your legs extended straight out in front of you.","Place your hands on the bench beside your hips for support.","Engage your abs and lift your legs off the ground, bringing your knees towards your chest.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0570-OyoZ3Pu.jpg","gif":"0570-OyoZ3Pu.gif"},{"id":"1576","n":"leg up hamstring stretch","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes"],"st":["Lie flat on your back with your legs extended.","Bend one knee and bring it towards your chest, holding onto your thigh or shin.","Straighten your leg as much as possible while keeping it elevated.","Hold the stretch for 20-30 seconds.","Repeat with the other leg."],"img":"1576-sU5BrfP.jpg","gif":"1576-sU5BrfP.gif","ty":"stretch","kind":"time"},{"id":"2287","n":"lever alternate leg press","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Adjust the seat and foot platform of the leverage machine to your desired position.","Sit on the machine with your back against the backrest and your feet on the foot platform.","Place your hands on the handles or sides of the machine for stability.","Push one foot against the foot platform, extending your leg until it is almost fully straight.","Pause for a moment, then slowly bend your leg and return to the starting position.","Repeat with the other leg.","Continue alternating legs for the desired number of repetitions."],"img":"2287-V07qpXy.jpg","gif":"2287-V07qpXy.gif"},{"id":"0571","n":"lever alternating narrow grip seated row","bp":"back","eq":"leverage machine","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Adjust the seat height and footplate position to ensure proper alignment.","Sit on the machine with your back straight and feet flat on the footplate.","Grasp the handles with a narrow grip, palms facing each other.","Keep your chest up and shoulders back throughout the exercise.","Pull one handle towards your torso while keeping the other handle stationary.","Squeeze your shoulder blades together at the end of the movement.","Slowly return the handle to the starting position and repeat with the other side.","Continue alternating sides for the desired number of repetitions."],"img":"0571-w2oRpuH.jpg","gif":"0571-w2oRpuH.gif"},{"id":"0572","n":"lever assisted chin-up","bp":"back","eq":"leverage machine","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Adjust the leverage machine to your desired resistance level.","Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart.","Hang with your arms fully extended, keeping your body straight.","Engage your back muscles and pull your body up towards the handles, leading with your chest.","Continue pulling until your chin is above the handles.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0572-MaMuGH6.jpg","gif":"0572-MaMuGH6.gif"},{"id":"0573","n":"lever back extension","bp":"back","eq":"leverage machine","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Adjust the machine to fit your body size and range of motion.","Sit on the machine with your back against the pad and your feet secured.","Place your hands on the handles or grip bars.","Engage your core and slowly lean forward, allowing your back to round slightly.","Pause for a moment at the bottom position, feeling a stretch in your lower back.","Using your back muscles, slowly raise your torso back to the starting position.","Repeat for the desired number of repetitions."],"img":"0573-rUXfn3R.jpg","gif":"0573-rUXfn3R.gif"},{"id":"0574","n":"lever bent over row","bp":"back","eq":"barbell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend forward at the hips, keeping your back straight and chest up.","Pull the barbell towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"0574-X3cqyXz.jpg","gif":"0574-X3cqyXz.gif"},{"id":"3200","n":"lever bent-over row with v-bar","bp":"back","eq":"leverage machine","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Adjust the seat height and position yourself facing the machine.","Grasp the v-bar with an overhand grip, keeping your back straight and your knees slightly bent.","Pull the v-bar towards your abdomen, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the weight back to the starting position.","Repeat for the desired number of repetitions."],"img":"3200-LuBEORI.jpg","gif":"3200-LuBEORI.gif"},{"id":"0575","n":"lever bicep curl","bp":"upper arms","eq":"leverage machine","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles with an underhand grip, palms facing up, and keep your elbows close to your sides.","Exhale and curl the handles upward, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"0575-q6y3OhV.jpg","gif":"0575-q6y3OhV.gif"},{"id":"2289","n":"lever calf press","bp":"lower legs","eq":"leverage machine","tg":"calves","mg":"hamstrings","sm":["hamstrings"],"st":["Adjust the seat of the leverage machine so that your shoulders are aligned with the lever pad.","Place your toes on the lever pad, with your heels hanging off the edge.","Grasp the handles or side supports for stability.","Push the lever pad down by extending your ankles, contracting your calf muscles.","Pause for a moment at the bottom of the movement.","Slowly return to the starting position by allowing your heels to rise back up.","Repeat for the desired number of repetitions."],"img":"2289-7B4F5nZ.jpg","gif":"2289-7B4F5nZ.gif"},{"id":"0577","n":"lever chest press","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Adjust the seat height and position yourself on the machine with your back flat against the pad.","Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.","Push the handles forward until your arms are fully extended, exhaling during the movement.","Pause briefly at the end of the movement, then slowly return to the starting position, inhaling as you do so.","Repeat for the desired number of repetitions."],"img":"0577-T0yTjgW.jpg","gif":"0577-T0yTjgW.gif"},{"id":"0576","n":"lever chest press","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Adjust the seat height and position yourself on the machine with your back flat against the pad.","Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.","Push the handles forward until your arms are fully extended, exhaling during the movement.","Pause briefly at the end of the movement, then slowly return to the starting position, inhaling as you do so.","Repeat for the desired number of repetitions."],"img":"0576-DOoWcnA.jpg","gif":"0576-DOoWcnA.gif"},{"id":"0578","n":"lever deadlift","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Adjust the seat height and foot platform to your desired position.","Sit on the machine with your back against the pad and your feet flat on the foot platform.","Grasp the handles or the sides of the seat for stability.","Engage your glutes and hamstrings, and push through your heels to lift the weight up.","Keep your back straight and avoid rounding your shoulders.","Extend your hips fully at the top of the movement, squeezing your glutes.","Lower the weight back down in a controlled manner, keeping tension on your glutes and hamstrings.","Repeat for the desired number of repetitions."],"img":"0578-GUT8I22.jpg","gif":"0578-GUT8I22.gif"},{"id":"1300","n":"lever decline chest press","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Adjust the seat height and backrest of the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Push the handles forward and away from your body until your arms are fully extended.","Slowly lower the handles back towards your chest, keeping your elbows slightly bent.","Pause for a moment at the bottom, then push the handles back to the starting position.","Repeat for the desired number of repetitions."],"img":"1300-vsVoPHt.jpg","gif":"1300-vsVoPHt.gif"},{"id":"1253","n":"lever donkey calf raise","bp":"lower legs","eq":"leverage machine","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Adjust the leverage machine to the appropriate height for your body.","Position yourself facing the machine, with your toes on the foot platform and your heels hanging off the edge.","Place your hands on the handles or the support bars for stability.","Engage your calves and lift your heels as high as possible, using the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1253-C9LuR4A.jpg","gif":"1253-C9LuR4A.gif"},{"id":"0579","n":"lever front pulldown","bp":"back","eq":"leverage machine","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Sit upright with your chest lifted and your shoulders back, maintaining a slight arch in your lower back.","Engage your lats and pull the handles down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."],"img":"0579-7F1DVzn.jpg","gif":"0579-7F1DVzn.gif"},{"id":"0580","n":"lever gripless shrug","bp":"back","eq":"leverage machine","tg":"traps","mg":"shoulders","sm":["shoulders","forearms"],"st":["Adjust the seat height and position yourself on the leverage machine.","Grasp the handles with your palms facing inwards and your arms fully extended.","Keeping your back straight, exhale and elevate your shoulders as high as possible.","Hold the contraction for a brief moment, then inhale and slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0580-f91FwXG.jpg","gif":"0580-f91FwXG.gif"},{"id":"1439","n":"lever gripless shrug v. 2","bp":"back","eq":"leverage machine","tg":"traps","mg":"shoulders","sm":["shoulders","forearms"],"st":["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles or bars with an overhand grip, keeping your arms straight.","Keeping your back straight, lift your shoulders up towards your ears as high as possible.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1439-cbuFJrn.jpg","gif":"1439-cbuFJrn.gif"},{"id":"2288","n":"lever gripper hands","bp":"lower arms","eq":"leverage machine","tg":"forearms","mg":"biceps","sm":["biceps","triceps"],"st":["Adjust the seat height and grip the handles of the leverage machine.","Keep your back straight and your feet flat on the ground.","Exhale and squeeze the handles, contracting your forearms.","Hold the contraction for a second, then slowly release and return to the starting position.","Repeat for the desired number of repetitions."],"img":"2288-mKwcrHn.jpg","gif":"2288-mKwcrHn.gif"},{"id":"1615","n":"lever hammer grip preacher curl","bp":"upper arms","eq":"leverage machine","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Adjust the seat height and position yourself on the leverage machine.","Place your upper arms on the preacher pad, ensuring your chest is pressed against it.","Grasp the handles with a hammer grip (palms facing each other).","Keeping your upper arms stationary, exhale and curl the handles towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position.","Repeat for the desired number of repetitions."],"img":"1615-OAguZoG.jpg","gif":"1615-OAguZoG.gif"},{"id":"0581","n":"lever high row","bp":"back","eq":"leverage machine","tg":"upper back","mg":"biceps","sm":["biceps","rear deltoids"],"st":["Adjust the seat height and foot platform to a comfortable position.","Sit on the machine with your chest against the pad and your feet flat on the foot platform.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and engage your core.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."],"img":"0581-nZZZy9m.jpg","gif":"0581-nZZZy9m.gif"},{"id":"2286","n":"lever hip extension v. 2","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings"],"st":["Adjust the machine to fit your body and sit on it with your back against the backrest.","Place your feet on the footrests and grip the handles for stability.","Engage your glutes and hamstrings, then push against the footrests to extend your hips and raise your legs backward.","Pause for a moment at the top, then slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."],"img":"2286-OPqShYN.jpg","gif":"2286-OPqShYN.gif"},{"id":"2611","n":"lever horizontal one leg press","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Adjust the seat of the machine so that your knees are at a 90-degree angle when your feet are on the footplate.","Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Place your hands on the handles or sides of the machine for stability.","Push the footplate away from your body by extending your leg, keeping your back against the backrest.","Pause for a moment at the fully extended position, then slowly bend your leg to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"img":"2611-9KU9TYF.jpg","gif":"2611-9KU9TYF.gif"},{"id":"1299","n":"lever incline chest press","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Adjust the seat and backrest of the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Push the handles forward and away from your body until your arms are fully extended.","Pause for a moment, then slowly bend your elbows and lower the handles back towards your chest.","Repeat for the desired number of repetitions."],"img":"1299-jHAnWmT.jpg","gif":"1299-jHAnWmT.gif"},{"id":"1479","n":"lever incline chest press v. 2","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Adjust the seat height and backrest angle on the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Push the handles forward and away from your body until your arms are fully extended, but without locking your elbows.","Pause for a moment at the fully extended position, then slowly bend your elbows and lower the handles back towards your chest.","Repeat for the desired number of repetitions."],"img":"1479-o17Jfkt.jpg","gif":"1479-o17Jfkt.gif"},{"id":"0582","n":"lever kneeling leg curl","bp":"upper legs","eq":"leverage machine","tg":"hamstrings","mg":"glutes","sm":["glutes"],"st":["Adjust the machine to fit your body and select the desired weight.","Kneel on the machine facing downwards, with your knees resting on the pad and your feet secured under the footpads.","Grasp the handles or the sides of the machine for stability.","Keeping your upper body stationary, exhale and curl your legs up towards your glutes by flexing your knees.","Pause for a moment at the top of the movement, squeezing your hamstrings.","Inhale and slowly lower your legs back to the starting position, fully extending your knees.","Repeat for the desired number of repetitions."],"img":"0582-nnmCTLN.jpg","gif":"0582-nnmCTLN.gif"},{"id":"0583","n":"lever kneeling twist","bp":"waist","eq":"leverage machine","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Adjust the seat height and position yourself on the machine with your knees resting on the pads and your upper body facing forward.","Grasp the handles or the sides of the machine for stability.","Keeping your core engaged, twist your torso to one side as far as comfortably possible.","Pause for a moment, then slowly return to the starting position.","Repeat the twist to the opposite side.","Continue alternating sides for the desired number of repetitions."],"img":"0583-sZOR9EV.jpg","gif":"0583-sZOR9EV.gif"},{"id":"0584","n":"lever lateral raise","bp":"shoulders","eq":"leverage machine","tg":"delts","mg":"traps","sm":["traps","upper back"],"st":["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles with an overhand grip and keep your arms straight.","Exhale and raise your arms out to the sides until they are parallel to the floor.","Pause for a moment at the top, then inhale and slowly lower your arms back to the starting position.","Repeat for the desired number of repetitions."],"img":"0584-dRTfGZT.jpg","gif":"0584-dRTfGZT.gif"},{"id":"0585","n":"lever leg extension","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"hamstrings","sm":["hamstrings"],"st":["Adjust the seat height and backrest of the machine to fit your body.","Sit on the machine with your back against the backrest and your feet on the footpad.","Grasp the handles or sidebars for stability.","Extend your legs forward by straightening your knees, lifting the weight.","Pause for a moment at the top, then slowly lower the weight back to the starting position.","Repeat for the desired number of repetitions."],"img":"0585-my33uHU.jpg","gif":"0585-my33uHU.gif"},{"id":"0586","n":"lever lying leg curl","bp":"upper legs","eq":"leverage machine","tg":"hamstrings","mg":"calves","sm":["calves"],"st":["Adjust the machine to fit your body and select the desired weight.","Lie face down on the machine with your legs straight and your heels against the padded lever.","Grasp the handles or the sides of the machine for stability.","Keeping your upper body stationary, exhale and curl your legs up as far as possible without lifting your hips off the pad.","Hold the contracted position for a brief pause as you squeeze your hamstrings.","Inhale and slowly lower the lever back to the starting position.","Repeat for the desired number of repetitions."],"img":"0586-17lJ1kr.jpg","gif":"0586-17lJ1kr.gif"},{"id":"3195","n":"lever lying two-one leg curl","bp":"upper legs","eq":"leverage machine","tg":"hamstrings","mg":"glutes","sm":["glutes"],"st":["Adjust the machine to fit your body and sit on it with your back against the backrest.","Place your legs on the lever pad, just above your ankles.","Grasp the handles on the sides of the machine for support.","Keeping your upper body still, exhale and curl your legs up towards your glutes.","Pause for a moment at the top, then inhale and slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."],"img":"3195-UXpKJoq.jpg","gif":"3195-UXpKJoq.gif"},{"id":"0587","n":"lever military press","bp":"shoulders","eq":"leverage machine","tg":"delts","mg":"triceps","sm":["triceps","upper chest"],"st":["Adjust the seat height and position yourself on the machine with your back against the backrest.","Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Push the handles upward until your arms are fully extended, but do not lock your elbows.","Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0587-CggQhII.jpg","gif":"0587-CggQhII.gif"},{"id":"0588","n":"lever narrow grip seated row","bp":"back","eq":"leverage machine","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Adjust the seat height and footrests to ensure proper form.","Sit on the machine with your feet flat on the footrests and your knees slightly bent.","Grasp the handles with a narrow grip, palms facing each other.","Keep your back straight and lean slightly forward.","Pull the handles towards your torso, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement.","Slowly release the handles and return to the starting position.","Repeat for the desired number of repetitions."],"img":"0588-IGjKj1v.jpg","gif":"0588-IGjKj1v.gif"},{"id":"0589","n":"lever one arm bent over row","bp":"back","eq":"barbell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with an overhand grip.","Bend forward at the hips, keeping your back straight and your head up.","Let the barbell hang in front of you with your arms fully extended.","Pull the barbell up towards your chest, keeping your elbows close to your body.","Squeeze your shoulder blades together at the top of the movement.","Lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0589-Fhdtwf3.jpg","gif":"0589-Fhdtwf3.gif"},{"id":"1356","n":"lever one arm lateral high row","bp":"back","eq":"leverage machine","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Adjust the seat height and position yourself facing the machine.","Grasp the handle with one hand and keep your back straight.","Pull the handle towards your body, keeping your elbow close to your side.","Squeeze your back muscles at the top of the movement.","Slowly release the handle back to the starting position.","Repeat for the desired number of repetitions."],"img":"1356-OIFMAp1.jpg","gif":"1356-OIFMAp1.gif"},{"id":"1347","n":"lever one arm lateral wide pulldown","bp":"back","eq":"leverage machine","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Grasp the handle with an overhand grip and fully extend your arm, keeping a slight bend in your elbow.","Pull the handle down and across your body towards your opposite hip, squeezing your lat muscle at the bottom of the movement.","Slowly return the handle to the starting position, fully extending your arm.","Repeat for the desired number of repetitions, then switch sides."],"img":"1347-tTuZSDT.jpg","gif":"1347-tTuZSDT.gif"},{"id":"0590","n":"lever one arm shoulder press","bp":"shoulders","eq":"leverage machine","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the lever handle with one hand and position your elbow at a 90-degree angle.","Press the lever upward until your arm is fully extended overhead.","Pause for a moment at the top, then slowly lower the lever back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"img":"0590-2KGnL6M.jpg","gif":"0590-2KGnL6M.gif"},{"id":"0591","n":"lever overhand triceps dip","bp":"upper arms","eq":"leverage machine","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Adjust the machine to the appropriate height and secure your body in position.","Grasp the handles with an overhand grip and position your body so that your arms are fully extended.","Lower your body by bending your elbows, keeping your upper arms close to your sides.","Continue lowering until your upper arms are parallel to the floor.","Pause for a moment, then push yourself back up to the starting position by extending your elbows.","Repeat for the desired number of repetitions."],"img":"0591-D5yqP2p.jpg","gif":"0591-D5yqP2p.gif"},{"id":"0592","n":"lever preacher curl","bp":"upper arms","eq":"leverage machine","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Adjust the seat height and position yourself on the leverage machine.","Place your upper arms on the pad and grip the handles with an underhand grip.","Keep your back straight and your elbows positioned on the pad.","Exhale and curl your forearms towards your upper arms, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position.","Repeat for the desired number of repetitions."],"img":"0592-b6hQYMb.jpg","gif":"0592-b6hQYMb.gif"},{"id":"1614","n":"lever preacher curl v. 2","bp":"upper arms","eq":"leverage machine","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Adjust the seat height and position yourself on the machine with your upper arms resting on the pad and your chest against the support.","Grasp the handles with an underhand grip, slightly wider than shoulder-width apart.","Keep your upper arms stationary and exhale as you curl the handles towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale as you slowly lower the handles back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"1614-ye84CTU.jpg","gif":"1614-ye84CTU.gif"},{"id":"2285","n":"lever pullover","bp":"back","eq":"leverage machine","tg":"lats","mg":"triceps","sm":["triceps","shoulders"],"st":["Adjust the seat and handles of the leverage machine to a comfortable position.","Sit on the machine with your back against the pad and grasp the handles with an overhand grip.","Keep your arms slightly bent and your core engaged.","Slowly pull the handles towards your chest, squeezing your lats.","Pause for a moment at the peak contraction, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"2285-4U7iLb5.jpg","gif":"2285-4U7iLb5.gif"},{"id":"2736","n":"lever reverse grip lateral pulldown","bp":"back","eq":"leverage machine","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Sit upright with your chest out and shoulders back, maintaining a slight arch in your lower back.","Pull the handles down towards your chest, leading with your elbows and squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."],"img":"2736-ky8FLU8.jpg","gif":"2736-ky8FLU8.gif"},{"id":"1616","n":"lever reverse grip preacher curl","bp":"upper arms","eq":"leverage machine","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Adjust the seat height and position yourself on the leverage machine.","Grasp the handles with an underhand grip, palms facing up.","Rest your upper arms on the preacher pad, ensuring your elbows are fully extended.","Keeping your upper arms stationary, exhale and curl the handles towards your shoulders.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position, fully extending your elbows.","Repeat for the desired number of repetitions."],"img":"1616-kj3hy6W.jpg","gif":"1616-kj3hy6W.gif"},{"id":"1348","n":"lever reverse grip vertical row","bp":"back","eq":"leverage machine","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Adjust the seat height and footplate position to ensure proper alignment.","Sit on the machine with your chest against the pad and your feet flat on the footplate.","Grasp the handles with an underhand grip, palms facing up.","Keep your back straight and engage your core.","Pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"img":"1348-ZqNOWQ6.jpg","gif":"1348-ZqNOWQ6.gif"},{"id":"0593","n":"lever reverse hyperextension","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Adjust the leverage machine to fit your body and secure your feet in the foot pads.","Lie face down on the machine with your upper body hanging off the edge and your hips resting on the pad.","Cross your arms over your chest or place them behind your head.","Engage your glutes and hamstrings to lift your legs upward until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0593-Krmb3cB.jpg","gif":"0593-Krmb3cB.gif"},{"id":"1349","n":"lever reverse t-bar row","bp":"back","eq":"leverage machine","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Adjust the seat height and footplate position on the leverage machine.","Sit on the machine with your chest against the pad and your feet flat on the footplate.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and engage your core.","Pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"img":"1349-BgljGjd.jpg","gif":"1349-BgljGjd.gif"},{"id":"2315","n":"lever rotary calf","bp":"lower legs","eq":"leverage machine","tg":"calves","mg":"soleus","sm":["soleus","ankle stabilizers"],"st":["Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate.","Place your toes on the footplate, with your heels hanging off the edge.","Grasp the handles or the sides of the machine for stability.","Push through the balls of your feet, raising your heels as high as possible.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"img":"2315-MrgP9L6.jpg","gif":"2315-MrgP9L6.gif"},{"id":"2335","n":"lever seated calf press","bp":"lower legs","eq":"leverage machine","tg":"calves","mg":"soleus","sm":["soleus","hamstrings"],"st":["Adjust the seat of the machine so that your shoulders are aligned with the lever pad.","Place your toes on the lower portion of the platform and position your knees under the lever pad.","Grasp the handles on the sides of the seat for stability.","Press the lever pad down by extending your ankles, lifting your heels as high as possible.","Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"img":"2335-Ie9UGty.jpg","gif":"2335-Ie9UGty.gif"},{"id":"0594","n":"lever seated calf raise","bp":"lower legs","eq":"leverage machine","tg":"calves","mg":"soleus","sm":["soleus","ankle stabilizers"],"st":["Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate.","Place your toes on the footplate with your heels hanging off the edge.","Grasp the handles or the sides of the seat for stability.","Push through the balls of your feet to raise your heels as high as possible.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0594-bOOdeyc.jpg","gif":"0594-bOOdeyc.gif"},{"id":"1452","n":"lever seated crunch","bp":"waist","eq":"leverage machine","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Sit on the leverage machine with your back against the pad and your feet flat on the floor.","Grasp the handles or place your hands on the side pads for support.","Engage your abs and slowly lean back, allowing the pad to move with you.","Once your upper body is at a 45-degree angle, contract your abs and crunch forward, bringing your chest towards your knees.","Pause for a moment at the top, then slowly release and return to the starting position.","Repeat for the desired number of repetitions."],"img":"1452-Wgaz7pm.jpg","gif":"1452-Wgaz7pm.gif"},{"id":"0595","n":"lever seated crunch (chest pad)","bp":"waist","eq":"leverage machine","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Adjust the seat height and chest pad position according to your comfort.","Sit on the machine with your back against the chest pad and your feet flat on the floor.","Grasp the handles or side bars for stability.","Engage your abs and slowly lean back, allowing the chest pad to move with you.","Pause for a moment at the maximum contraction, feeling the tension in your abs.","Slowly return to the starting position by contracting your abs and pulling yourself back up.","Repeat for the desired number of repetitions."],"img":"0595-ZnJHhMk.jpg","gif":"0595-ZnJHhMk.gif"},{"id":"3760","n":"lever seated crunch v. 2","bp":"waist","eq":"leverage machine","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Sit on the leverage machine with your back against the pad and your feet secured under the footpads.","Place your hands on the handles or the sides of the seat for support.","Engage your abs and slowly crunch forward, bringing your chest towards your knees.","Pause for a moment at the top of the movement, squeezing your abs.","Slowly return to the starting position, allowing your back to round slightly.","Repeat for the desired number of repetitions."],"img":"3760-eXFXCY0.jpg","gif":"3760-eXFXCY0.gif"},{"id":"1451","n":"lever seated dip","bp":"upper arms","eq":"leverage machine","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Adjust the seat height so that your feet are flat on the ground and your knees are at a 90-degree angle.","Grasp the handles of the leverage machine with your palms facing down and your arms fully extended.","Slowly lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"img":"1451-BRImeP8.jpg","gif":"1451-BRImeP8.gif"},{"id":"0596","n":"lever seated fly","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"deltoids","sm":["deltoids","trapezius"],"st":["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles with a pronated grip and keep your elbows slightly bent.","Exhale and push the handles forward, bringing them together in front of your chest.","Pause for a moment, squeezing your chest muscles.","Inhale and slowly return to the starting position, allowing your chest muscles to stretch.","Repeat for the desired number of repetitions."],"img":"0596-v3xmPAR.jpg","gif":"0596-v3xmPAR.gif"},{"id":"3759","n":"lever seated good morning","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Adjust the seat height so that your hips are slightly higher than your knees.","Sit on the machine with your back against the pad and your feet flat on the footrests.","Grasp the handles or the sides of the seat for stability.","Keeping your back straight, slowly lean forward from your hips until your upper body is parallel to the ground.","Pause for a moment, then slowly return to the starting position by pushing through your glutes and hamstrings.","Repeat for the desired number of repetitions."],"img":"3759-XsCcxCC.jpg","gif":"3759-XsCcxCC.gif"},{"id":"0597","n":"lever seated hip abduction","bp":"upper legs","eq":"leverage machine","tg":"abductors","mg":"glutes","sm":["glutes","hamstrings"],"st":["Adjust the seat height so that your knees are at a 90-degree angle.","Sit on the machine with your back against the backrest and your feet on the footrests.","Place your hands on the side handles for stability.","Engage your abductors and slowly push your legs apart, away from the midline of your body.","Pause for a moment at the end of the movement, then slowly bring your legs back together to the starting position.","Repeat for the desired number of repetitions."],"img":"0597-CHpahtl.jpg","gif":"0597-CHpahtl.gif"},{"id":"0598","n":"lever seated hip adduction","bp":"upper legs","eq":"leverage machine","tg":"adductors","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Adjust the seat height and position yourself on the machine with your back against the backrest.","Place your feet on the footrests and grasp the handles for stability.","Engage your adductor muscles and slowly bring your legs together, squeezing your inner thighs.","Pause for a moment at the peak contraction, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"0598-oHsrypV.jpg","gif":"0598-oHsrypV.gif"},{"id":"0599","n":"lever seated leg curl","bp":"upper legs","eq":"leverage machine","tg":"hamstrings","mg":"calves","sm":["calves"],"st":["Adjust the machine to fit your body and sit on it with your back against the backrest.","Place your lower legs under the padded lever, just above your ankles.","Grasp the handles on the sides of the machine for support.","Keeping your upper legs stationary, exhale and curl your legs up as far as possible.","Hold the contracted position for a brief pause as you squeeze your hamstrings.","Inhale and slowly lower the lever back to the starting position.","Repeat for the desired number of repetitions."],"img":"0599-Zg3XY7P.jpg","gif":"0599-Zg3XY7P.gif"},{"id":"0600","n":"lever seated leg raise crunch","bp":"waist","eq":"leverage machine","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Sit on the leverage machine with your back against the backrest and your feet on the footrests.","Grasp the handles or sidebars for stability.","Engage your abs and slowly raise your legs up towards your chest, curling your torso forward at the same time.","Pause for a moment at the top, then slowly lower your legs and torso back to the starting position.","Repeat for the desired number of repetitions."],"img":"0600-PQ2AtC3.jpg","gif":"0600-PQ2AtC3.gif"},{"id":"0602","n":"lever seated reverse fly","bp":"shoulders","eq":"leverage machine","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids"],"st":["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Grasp the handles with an overhand grip and keep your arms slightly bent.","Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body.","Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"0602-myfUsKf.jpg","gif":"0602-myfUsKf.gif"},{"id":"0601","n":"lever seated reverse fly (parallel grip)","bp":"shoulders","eq":"leverage machine","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids"],"st":["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Grasp the handles with a parallel grip, palms facing each other, and keep your arms slightly bent.","Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body.","Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"0601-xiHiJcA.jpg","gif":"0601-xiHiJcA.gif"},{"id":"1350","n":"lever seated row","bp":"back","eq":"leverage machine","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Adjust the seat height and footrests to a comfortable position.","Sit on the machine with your chest against the pad and your feet on the footrests.","Grasp the handles with an overhand grip, shoulder-width apart.","Keep your back straight and your core engaged.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement.","Slowly release the handles and return to the starting position.","Repeat for the desired number of repetitions."],"img":"1350-7I6LNUG.jpg","gif":"1350-7I6LNUG.gif"},{"id":"1385","n":"lever seated squat calf raise on leg press machine","bp":"lower legs","eq":"leverage machine","tg":"calves","mg":"quadriceps","sm":["quadriceps","hamstrings","glutes"],"st":["Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the footplate.","Sit on the machine with your back against the backrest and your feet flat on the footplate, shoulder-width apart.","Place your toes and the balls of your feet on the footplate, keeping your heels off the edge.","Release the safety handles and push the footplate away from you by extending your knees.","Once your knees are fully extended, slowly lower your heels by flexing your calves.","Pause for a moment at the bottom, then push the footplate back up by extending your calves.","Repeat for the desired number of repetitions."],"img":"1385-IeDEXTe.jpg","gif":"1385-IeDEXTe.gif"},{"id":"0603","n":"lever shoulder press","bp":"shoulders","eq":"leverage machine","tg":"delts","mg":"triceps","sm":["triceps","chest"],"st":["Adjust the seat height and position yourself on the machine with your back against the backrest.","Grasp the handles with an overhand grip and position your hands at shoulder level.","Push the handles upward until your arms are fully extended, but do not lock your elbows.","Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0603-67n3r98.jpg","gif":"0603-67n3r98.gif"},{"id":"0869","n":"lever shoulder press v. 2","bp":"shoulders","eq":"leverage machine","tg":"delts","mg":"triceps","sm":["triceps","chest"],"st":["Adjust the seat height and backrest of the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles of the machine with an overhand grip, slightly wider than shoulder-width apart.","Push the handles upward and forward until your arms are fully extended, but not locked.","Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0869-vqsbmL0.jpg","gif":"0869-vqsbmL0.gif"},{"id":"2318","n":"lever shoulder press v. 3","bp":"shoulders","eq":"leverage machine","tg":"delts","mg":"triceps","sm":["triceps","chest"],"st":["Adjust the seat height and backrest of the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles of the machine with an overhand grip, slightly wider than shoulder-width apart.","Push the handles upward and forward until your arms are fully extended, but not locked.","Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Repeat for the desired number of repetitions."],"img":"2318-dNFYIU1.jpg","gif":"2318-dNFYIU1.gif"},{"id":"0604","n":"lever shrug","bp":"back","eq":"leverage machine","tg":"traps","mg":"shoulders","sm":["shoulders"],"st":["Adjust the seat height and position yourself on the leverage machine with your back against the pad.","Grasp the handles with an overhand grip and keep your arms straight.","Keeping your back straight, lift your shoulders up towards your ears as high as possible.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0604-ZZKbeMw.jpg","gif":"0604-ZZKbeMw.gif"},{"id":"0605","n":"lever standing calf raise","bp":"lower legs","eq":"leverage machine","tg":"calves","mg":"soleus","sm":["soleus","ankle stabilizers"],"st":["Adjust the machine to your height and stand with your feet shoulder-width apart.","Place your shoulders under the pads and hold onto the handles for stability.","Raise your heels as high as possible by extending your ankles.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0605-ykUOVze.jpg","gif":"0605-ykUOVze.gif"},{"id":"3758","n":"lever standing chest press","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Adjust the seat height and position yourself on the machine with your feet flat on the ground.","Grasp the handles with an overhand grip and position your hands at chest level.","Push the handles forward until your arms are fully extended, keeping your elbows slightly bent.","Pause for a moment, then slowly bring the handles back towards your chest, maintaining control throughout the movement.","Repeat for the desired number of repetitions."],"img":"3758-WbNq5Xu.jpg","gif":"3758-WbNq5Xu.gif"},{"id":"0606","n":"lever t bar row","bp":"back","eq":"leverage machine","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Adjust the seat height and footplate position to ensure proper alignment.","Sit on the machine with your chest against the pad and your feet flat on the footplate.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and engage your core.","Pull the handles towards your torso, squeezing your shoulder blades together.","Pause for a moment at the peak contraction, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."],"img":"0606-aaXr7ld.jpg","gif":"0606-aaXr7ld.gif"},{"id":"1351","n":"lever t-bar reverse grip row","bp":"back","eq":"leverage machine","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and engage your core.","Pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"img":"1351-FVM1AUZ.jpg","gif":"1351-FVM1AUZ.gif"},{"id":"0607","n":"lever triceps extension","bp":"upper arms","eq":"leverage machine","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles with an overhand grip and fully extend your arms in front of you.","Keeping your upper arms stationary, slowly lower the handles towards your forehead by bending your elbows.","Pause for a moment at the bottom, then push the handles back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."],"img":"0607-Ser9eQp.jpg","gif":"0607-Ser9eQp.gif"},{"id":"1313","n":"lever unilateral row","bp":"back","eq":"leverage machine","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Adjust the seat height and position yourself facing the machine.","Grasp the handles with an overhand grip and keep your back straight.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"img":"1313-oROuvrX.jpg","gif":"1313-oROuvrX.gif"},{"id":"0609","n":"london bridge","bp":"back","eq":"rope","tg":"upper back","mg":"shoulders","sm":["shoulders","biceps","forearms"],"st":["Attach the rope to a high anchor point.","Stand facing away from the anchor point with your feet shoulder-width apart.","Grasp the rope with an overhand grip, palms facing down.","Lean forward slightly, keeping your back straight and core engaged.","Pull the rope towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"img":"0609-bLyQokI.jpg","gif":"0609-bLyQokI.gif","ty":"rin"},{"id":"3013","n":"low glute bridge on floor","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your arms by your sides, palms facing down.","Engage your glutes and core, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, squeezing your glutes.","Slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"img":"3013-u0cNiij.jpg","gif":"3013-u0cNiij.gif","ty":"rin"},{"id":"1352","n":"lower back curl","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Lie flat on your stomach with your legs extended and your arms by your sides.","Engage your glutes and hamstrings, and slowly lift your upper body off the ground, curling your back upwards.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1352-ANbbry2.jpg","gif":"1352-ANbbry2.gif"},{"id":"3582","n":"lunge with jump","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Start by standing with your feet shoulder-width apart.","Take a step forward with your right foot, lowering your body into a lunge position.","Push off with your right foot and jump into the air, switching the position of your feet mid-air.","Land softly with your left foot forward and immediately lower your body into a lunge position.","Continue alternating between lunges and jumps for the desired number of repetitions."],"img":"3582-PM1PZjg.jpg","gif":"3582-PM1PZjg.gif","ty":"atl"},{"id":"1688","n":"lunge with twist","bp":"waist","eq":"body weight","tg":"abs","mg":"quadriceps","sm":["quadriceps","glutes","hamstrings"],"st":["Start by standing with your feet shoulder-width apart.","Take a step forward with your right foot, lowering your body into a lunge position.","As you lunge, twist your torso to the right, bringing your left elbow towards your right knee.","Pause for a moment, then return to the starting position.","Repeat on the other side, stepping forward with your left foot and twisting your torso to the left.","Continue alternating sides for the desired number of repetitions."],"img":"1688-K9VL0Jq.jpg","gif":"1688-K9VL0Jq.gif"},{"id":"0613","n":"lying (side) quads stretch","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hamstrings","sm":["hamstrings"],"st":["Lie on your side with your legs straight.","Bend your top leg and grab your ankle or foot with your hand.","Gently pull your ankle or foot towards your glutes until you feel a stretch in your quads.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat on the other side."],"img":"0613-BWnJR72.jpg","gif":"0613-BWnJR72.gif","ty":"stretch","kind":"time"},{"id":"2312","n":"lying elbow to knee","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee.","At the same time, extend your right leg straight out and lift it off the ground.","Pause for a moment, then return to the starting position.","Repeat the movement, this time bringing your left elbow towards your right knee and extending your left leg.","Continue alternating sides for the desired number of repetitions."],"img":"2312-AQIhRjM.jpg","gif":"2312-AQIhRjM.gif"},{"id":"0620","n":"lying leg raise flat bench","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Lie flat on a flat bench with your back pressed against it.","Place your hands under your glutes for support.","Keep your legs straight and together, and lift them up towards the ceiling.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0620-WhuFnR7.jpg","gif":"0620-WhuFnR7.gif"},{"id":"0865","n":"lying leg-hip raise","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your core and lift your legs off the ground, raising them towards the ceiling.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0865-9IxJdtC.jpg","gif":"0865-9IxJdtC.gif"},{"id":"1301","n":"machine inner chest press","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Adjust the seat height and position yourself on the machine with your back flat against the pad.","Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.","Push the handles forward until your arms are fully extended, exhaling during the movement.","Pause for a moment at the end of the movement, then slowly return to the starting position, inhaling as you do so.","Repeat for the desired number of repetitions."],"img":"1301-wDN97Ca.jpg","gif":"1301-wDN97Ca.gif"},{"id":"0624","n":"march sit (wall)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your back against a wall and your feet hip-width apart.","Slowly slide your back down the wall until your knees are bent at a 90-degree angle.","Lift your right foot off the ground and bring your knee towards your chest.","Lower your right foot back down and lift your left foot off the ground, bringing your knee towards your chest.","Continue alternating between lifting your right and left foot for the desired number of repetitions."],"img":"0624-sVQCCeG.jpg","gif":"0624-sVQCCeG.gif"},{"id":"1353","n":"medicine ball catch and overhead throw","bp":"back","eq":"medicine ball","tg":"lats","mg":"shoulders","sm":["shoulders","core"],"st":["Stand with your feet shoulder-width apart, holding a medicine ball in both hands at chest level.","Bend your knees slightly and engage your core.","Lower your body into a squat position, keeping your back straight and chest up.","Explosively extend your hips and legs, while simultaneously throwing the medicine ball overhead.","Release the ball at the top of the movement and catch it on the way down.","Lower your body back into the squat position and repeat for the desired number of repetitions."],"img":"1353-PsVS1QP.jpg","gif":"1353-PsVS1QP.gif"},{"id":"1302","n":"medicine ball chest pass","bp":"chest","eq":"medicine ball","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Stand with your feet shoulder-width apart, holding the medicine ball at chest level.","Extend your arms forward, pushing the medicine ball away from your chest with force.","As you release the ball, follow through with your arms and torso, transferring your weight from your back foot to your front foot.","Catch the ball as it rebounds off the wall or partner, and immediately repeat the movement.","Continue for the desired number of repetitions."],"img":"1302-aDoFKrE.jpg","gif":"1302-aDoFKrE.gif"},{"id":"1303","n":"medicine ball chest push from 3 point stance","bp":"chest","eq":"medicine ball","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Start in a 3 point stance with one hand on the medicine ball and the other hand on the ground.","Extend your legs and position your body in a straight line.","Lower your chest towards the ground while keeping your back straight.","Push the medicine ball away from your body, extending your arm fully.","Return to the starting position and repeat for the desired number of repetitions."],"img":"1303-dCJnuVq.jpg","gif":"1303-dCJnuVq.gif"},{"id":"1304","n":"medicine ball chest push multiple response","bp":"chest","eq":"medicine ball","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Stand with your feet shoulder-width apart, holding a medicine ball at chest level.","Extend your arms forward, pushing the medicine ball away from your chest.","Pause for a moment, then slowly bring the medicine ball back to your chest.","Repeat for the desired number of repetitions."],"img":"1304-7aolH9D.jpg","gif":"1304-7aolH9D.gif"},{"id":"1305","n":"medicine ball chest push single response","bp":"chest","eq":"medicine ball","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Stand with your feet shoulder-width apart, holding the medicine ball at chest level.","Extend your arms forward, pushing the medicine ball away from your chest.","Pause for a moment, then slowly bring the medicine ball back to your chest.","Repeat for the desired number of repetitions."],"img":"1305-jeHtrlO.jpg","gif":"1305-jeHtrlO.gif"},{"id":"1312","n":"medicine ball chest push with run release","bp":"chest","eq":"medicine ball","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Stand with your feet shoulder-width apart, holding a medicine ball at chest level.","Step forward with your right foot and simultaneously push the medicine ball forward, extending your arms fully.","As you push the ball forward, release it and let it roll forward.","Quickly run forward and catch the ball before it hits the ground.","Once you catch the ball, bring it back to your chest and repeat the movement with your left foot forward.","Continue alternating legs and repeating the exercise for the desired number of repetitions."],"img":"1312-pX9Elbe.jpg","gif":"1312-pX9Elbe.gif"},{"id":"1701","n":"medicine ball close grip push up","bp":"upper arms","eq":"medicine ball","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Start in a high plank position with your hands on the medicine ball, shoulder-width apart.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","Push back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"1701-8K7m2SS.jpg","gif":"1701-8K7m2SS.gif"},{"id":"1354","n":"medicine ball overhead slam","bp":"back","eq":"medicine ball","tg":"upper back","mg":"shoulders","sm":["shoulders","core"],"st":["Stand with your feet shoulder-width apart, holding a medicine ball with both hands above your head.","Engage your core and keep your back straight.","Bend your knees slightly and forcefully slam the medicine ball down to the ground in front of you.","As you slam the ball down, use your entire body to generate power, including your shoulders and core.","Catch the ball on the bounce and repeat for the desired number of repetitions."],"img":"1354-oHg8eop.jpg","gif":"1354-oHg8eop.gif"},{"id":"1750","n":"medicine ball supine chest throw","bp":"upper arms","eq":"medicine ball","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Lie flat on your back on a bench with your knees bent and feet flat on the ground.","Hold the medicine ball with both hands, extending your arms straight up above your chest.","Lower the medicine ball towards your chest, keeping your elbows close to your body.","Explosively push the medicine ball upwards, extending your arms fully and throwing the ball as high as possible.","Catch the medicine ball and repeat for the desired number of repetitions."],"img":"1750-Al3tP0D.jpg","gif":"1750-Al3tP0D.gif"},{"id":"0627","n":"mixed grip chin-up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Grab the pull-up bar with an underhand grip (palms facing towards you) and your hands slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position with control.","Repeat for the desired number of repetitions."],"img":"0627-T8UpLkb.jpg","gif":"0627-T8UpLkb.gif"},{"id":"3217","n":"modified hindu push-up (male)","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet hip-width apart.","Lower your body towards the ground, bending your elbows and keeping your core engaged.","As you lower your body, shift your weight back and lift your hips up towards the ceiling, creating an inverted V shape with your body.","Continue to lower your body until your chest is just above the ground, then reverse the movement, pushing your hips back down and extending your arms to return to the starting position.","Repeat for the desired number of repetitions."],"img":"3217-epOSYUZ.jpg","gif":"3217-epOSYUZ.gif"},{"id":"1421","n":"modified push up to lower arms","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"triceps","sm":["triceps","chest","shoulders"],"st":["Start in a push-up position with your hands directly under your shoulders and your body in a straight line.","Lower your body down towards the ground by bending your elbows, keeping them close to your sides.","Once your elbows are at a 90-degree angle, lower your forearms to the ground, keeping your elbows directly under your shoulders.","Pause for a moment, then push through your palms to lift your forearms back up to the starting position.","Repeat for the desired number of repetitions."],"img":"1421-arvaszz.jpg","gif":"1421-arvaszz.gif"},{"id":"0628","n":"monster walk","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Place a resistance band around your ankles.","Stand with your feet shoulder-width apart and slightly bend your knees.","Take a step to the side with your right foot, maintaining tension on the resistance band.","Follow with your left foot, stepping to the side to return to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"0628-O95afRA.jpg","gif":"0628-O95afRA.gif"},{"id":"0630","n":"mountain climber","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"core","sm":["core","shoulders","triceps"],"st":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Engage your core and bring your right knee towards your chest, then quickly switch and bring your left knee towards your chest.","Continue alternating legs in a running motion, keeping your hips low and your core engaged.","Maintain a steady pace and breathe evenly throughout the exercise.","Repeat for the desired number of repetitions."],"img":"0630-RJgzwny.jpg","gif":"0630-RJgzwny.gif"},{"id":"0631","n":"muscle up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","triceps","shoulders","chest"],"st":["Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended.","Engage your core and pull your body up towards the bar, leading with your chest.","As you reach the top of the movement, transition your grip so that your palms are facing towards you.","Continue pulling yourself up until your chest is above the bar and your arms are fully flexed.","Reverse the movement by slowly lowering yourself back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0631-yJUHKTn.jpg","gif":"0631-yJUHKTn.gif","ty":"atl"},{"id":"1401","n":"muscle-up (on vertical bar)","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","triceps","forearms"],"st":["Start by hanging from a vertical bar with your palms facing away from you and your arms fully extended.","Engage your core and pull your body up towards the bar, leading with your chest.","As you pull yourself up, lean back slightly and bring your elbows towards your sides.","Continue pulling until your chest reaches the bar and your elbows are fully bent.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1401-Af0EW2I.jpg","gif":"1401-Af0EW2I.gif"},{"id":"2328","n":"narrow push-up on exercise ball","bp":"upper arms","eq":"stability ball","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Place the stability ball on the ground and position yourself in a push-up position with your hands on the ball, slightly narrower than shoulder-width apart.","Engage your core and keep your body in a straight line from head to toe.","Lower your chest towards the ball by bending your elbows, keeping them close to your body.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"img":"2328-4cWjYEN.jpg","gif":"2328-4cWjYEN.gif"},{"id":"1403","n":"neck side stretch","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"trapezius","sm":["trapezius","sternocleidomastoid"],"st":["Stand or sit up straight with your shoulders relaxed.","Tilt your head to one side, bringing your ear towards your shoulder.","Hold the stretch for 15-30 seconds.","Repeat on the other side.","Perform 2-4 sets on each side."],"img":"1403-x2chWLO.jpg","gif":"1403-x2chWLO.gif","ty":"stretch","kind":"time"},{"id":"0634","n":"negative crunch","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0634-szIn2UK.jpg","gif":"0634-szIn2UK.gif"},{"id":"1495","n":"oblique crunch v. 2","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Lie on your back with your knees bent and feet flat on the ground.","Place your hands behind your head or cross them over your chest.","Engage your abs and lift your shoulder blades off the ground, rotating your torso to one side.","Pause for a moment, then lower your shoulder blades back down to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."],"img":"1495-cJgSTmh.jpg","gif":"1495-cJgSTmh.gif"},{"id":"0635","n":"oblique crunches floor","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Lie on your back with your knees bent and feet flat on the floor.","Place your hands behind your head or cross them over your chest.","Engage your abs and lift your shoulder blades off the floor, rotating your torso to one side.","Pause for a moment, then lower your shoulder blades back down to the floor.","Repeat on the other side, alternating sides with each repetition."],"img":"0635-QUDd8WS.jpg","gif":"0635-QUDd8WS.gif"},{"id":"0636","n":"olympic barbell hammer curl","bp":"upper arms","eq":"olympic barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up straight with your feet shoulder-width apart and hold an Olympic barbell with an overhand grip.","Let the barbell hang at arm's length in front of your thighs, with your palms facing your body.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"img":"0636-o1ntciW.jpg","gif":"0636-o1ntciW.gif"},{"id":"0637","n":"olympic barbell triceps extension","bp":"upper arms","eq":"olympic barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Start by standing with your feet shoulder-width apart and holding the barbell with an overhand grip.","Raise the barbell above your head, fully extending your arms.","Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"img":"0637-wu5LXwz.jpg","gif":"0637-wu5LXwz.gif"},{"id":"1355","n":"one arm against wall","bp":"back","eq":"body weight","tg":"lats","mg":"shoulders","sm":["shoulders","triceps"],"st":["Stand facing a wall with your feet shoulder-width apart.","Extend one arm straight out in front of you and place your palm against the wall.","Engage your core and lean your body forward, keeping your arm straight and your back flat.","Slowly push against the wall with your palm, activating your lat muscles.","Hold the position for a few seconds, then release and repeat with the other arm."],"img":"1355-ZZTGMKh.jpg","gif":"1355-ZZTGMKh.gif"},{"id":"0638","n":"one arm chin-up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Stand facing a pull-up bar with your feet shoulder-width apart.","Reach up and grab the bar with an underhand grip, with one hand gripping the bar and the other hand holding your wrist for support.","Hang from the bar with your arm fully extended, keeping your body straight and your core engaged.","Pull yourself up towards the bar by bending your elbow and squeezing your back muscles.","Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions, then switch arms and repeat."],"img":"0638-HjdqmZa.jpg","gif":"0638-HjdqmZa.gif"},{"id":"0639","n":"one arm dip","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Stand facing away from a bench or chair, with your feet shoulder-width apart.","Place one hand on the bench or chair behind you, fingers pointing towards your body.","Extend your legs out in front of you, keeping your heels on the ground.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench or chair.","Pause for a moment at the bottom, then push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions, then switch sides and repeat with the other arm."],"img":"0639-FAoIFMw.jpg","gif":"0639-FAoIFMw.gif"},{"id":"0640","n":"one arm slam (with medicine ball)","bp":"waist","eq":"medicine ball","tg":"abs","mg":"shoulders","sm":["shoulders","back"],"st":["Stand with your feet shoulder-width apart, holding the medicine ball with one hand in front of your waist.","Bend your knees slightly and engage your core.","Raise the medicine ball above your head, fully extending your arm.","Forcefully slam the medicine ball down to the ground, using your core and shoulders to generate power.","Catch the medicine ball on the bounce and repeat for the desired number of repetitions."],"img":"0640-jCrtE9b.jpg","gif":"0640-jCrtE9b.gif"},{"id":"1773","n":"one arm towel row","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand.","Bend forward at the waist, keeping your back straight and your core engaged.","Extend your arm fully, allowing the towel to hang in front of you.","Pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the towel back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"img":"1773-bKWbrTA.jpg","gif":"1773-bKWbrTA.gif"},{"id":"1386","n":"one leg donkey calf raise","bp":"lower legs","eq":"body weight","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Stand with your feet shoulder-width apart, toes pointing forward.","Place your hands on a stable surface for support, such as a wall or a bar.","Lift one leg off the ground, keeping your knee slightly bent.","Raise your heel as high as possible, using your calf muscles.","Pause for a moment at the top, then slowly lower your heel back down.","Repeat for the desired number of repetitions, then switch legs."],"img":"1386-A2upspL.jpg","gif":"1386-A2upspL.gif"},{"id":"1387","n":"one leg floor calf raise","bp":"lower legs","eq":"body weight","tg":"calves","mg":"ankles","sm":["ankles","feet"],"st":["Stand with your feet hip-width apart and place your hands on a wall or sturdy object for balance.","Lift one foot off the ground and balance on the other foot.","Slowly raise your heel off the ground, lifting your body up onto the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."],"img":"1387-0jp9Rlz.jpg","gif":"1387-0jp9Rlz.gif"},{"id":"1476","n":"one leg squat","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart.","Extend one leg forward, keeping it off the ground.","Bend your standing leg and lower your body down as if sitting back into a chair.","Keep your chest up and your back straight.","Push through your heel to return to the starting position.","Repeat with the other leg."],"img":"1476-C31LMnP.jpg","gif":"1476-C31LMnP.gif"},{"id":"0641","n":"otis up","bp":"waist","eq":"weighted","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0641-UVL20oz.jpg","gif":"0641-UVL20oz.gif"},{"id":"0642","n":"outside leg kick push-up","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged.","As you push back up, kick one leg out to the side, extending it fully and engaging your glutes.","Return your leg to the starting position and repeat the push-up, alternating legs with each repetition.","Continue alternating leg kicks and push-ups for the desired number of repetitions."],"img":"0642-jNU1gFQ.jpg","gif":"0642-jNU1gFQ.gif"},{"id":"0643","n":"overhead triceps stretch","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Stand or sit upright with your feet shoulder-width apart.","Extend one arm overhead, bending at the elbow so that your hand reaches towards the opposite shoulder blade.","With your other hand, gently pull the elbow of the extended arm towards the opposite side of your head, feeling a stretch in your triceps.","Hold the stretch for 15-30 seconds, then release.","Repeat on the other side."],"img":"0643-Z5YStHW.jpg","gif":"0643-Z5YStHW.gif","ty":"stretch","kind":"time"},{"id":"3147","n":"pelvic tilt","bp":"waist","eq":"body weight","tg":"abs","mg":"lower back","sm":["lower back"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands by your sides.","Engage your abs and tilt your pelvis upward, pressing your lower back into the ground.","Hold this position for a few seconds, focusing on contracting your abs.","Release the tilt and return to the starting position.","Repeat for the desired number of repetitions."],"img":"3147-NKJ8o6x.jpg","gif":"3147-NKJ8o6x.gif"},{"id":"1422","n":"pelvic tilt into bridge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Lie on your back with your knees bent and feet flat on the ground.","Place your arms by your sides with your palms facing down.","Engage your glutes and core muscles.","Tilt your pelvis upward, lifting your hips off the ground.","Hold the bridge position for a few seconds.","Slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1422-D9qe7CM.jpg","gif":"1422-D9qe7CM.gif","ty":"rin"},{"id":"1388","n":"peroneals stretch","bp":"lower legs","eq":"rope","tg":"calves","mg":"ankles","sm":["ankles","feet"],"st":["Sit on the ground with your legs extended in front of you.","Loop the rope around the ball of your foot and hold the ends of the rope with your hands.","Gently pull the rope towards you, flexing your foot and stretching your calf muscles.","Hold the stretch for 15-30 seconds.","Release the tension on the rope and repeat the stretch on the other leg.","Repeat for the desired number of repetitions."],"img":"1388-XhfS1DZ.jpg","gif":"1388-XhfS1DZ.gif","ty":"stretch","kind":"time"},{"id":"3662","n":"pike-to-cobra push-up","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"core","sm":["core","shoulders","triceps"],"st":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Engage your core and lift your hips up towards the ceiling, forming an inverted V shape with your body.","Lower your upper body towards the ground by bending your elbows, keeping them close to your body.","As you lower down, shift your weight forward and transition into a cobra pose by straightening your arms and lifting your chest up.","Reverse the movement by bending your elbows and lowering your chest back down towards the ground.","Push through your hands to return to the inverted V position.","Continue the movement by lowering your hips back down towards the ground, returning to the starting push-up position.","Repeat for the desired number of repetitions."],"img":"3662-XPUDTt7.jpg","gif":"3662-XPUDTt7.gif"},{"id":"1306","n":"plyo push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Start in a high plank position with your hands slightly wider than shoulder-width apart.","Lower your chest towards the ground by bending your elbows, keeping your body in a straight line.","Push explosively off the ground, using your chest muscles to propel your upper body off the ground.","Land softly with your hands back in the starting position.","Repeat for the desired number of repetitions."],"img":"1306-Snj1wSv.jpg","gif":"1306-Snj1wSv.gif"},{"id":"1687","n":"posterior step to overhead reach","bp":"waist","eq":"body weight","tg":"abs","mg":"glutes","sm":["glutes","hamstrings","quadriceps","shoulders"],"st":["Stand with your feet hip-width apart and your arms by your sides.","Take a step back with your right foot, landing on the ball of your foot.","Bend your left knee and lower your body into a lunge position.","As you lower into the lunge, simultaneously reach your arms overhead.","Pause for a moment at the bottom of the lunge, then return to the starting position by pushing through your left heel and bringing your right foot forward.","Repeat the movement on the other side, stepping back with your left foot and bending your right knee.","Continue alternating sides for the desired number of repetitions."],"img":"1687-ErqK3UL.jpg","gif":"1687-ErqK3UL.gif"},{"id":"1389","n":"posterior tibialis stretch","bp":"lower legs","eq":"rope","tg":"calves","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Sit on the ground with your legs extended in front of you.","Loop the rope around the ball of your foot and hold the ends of the rope with your hands.","Gently pull the rope towards you, flexing your foot and stretching your calf muscles.","Hold the stretch for 20-30 seconds.","Release the tension on the rope and relax your foot.","Repeat the stretch on the other leg."],"img":"1389-DEEqoI2.jpg","gif":"1389-DEEqoI2.gif","ty":"stretch","kind":"time"},{"id":"3119","n":"potty squat","bp":"waist","eq":"body weight","tg":"abs","mg":"quadriceps","sm":["quadriceps","glutes"],"st":["Stand with your feet shoulder-width apart, toes pointing slightly outward.","Lower your body down by bending your knees and pushing your hips back as if you were sitting on a chair.","Keep your chest up and your back straight throughout the movement.","Lower yourself until your thighs are parallel to the ground or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"3119-75Bgtjy.jpg","gif":"3119-75Bgtjy.gif"},{"id":"3132","n":"potty squat with support","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart, toes pointing slightly outward.","Hold onto a stable support, such as a chair or wall, for balance.","Lower your body down into a squat position by bending your knees and pushing your hips back.","Keep your chest up and your back straight throughout the movement.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"3132-b63ZzGe.jpg","gif":"3132-b63ZzGe.gif"},{"id":"0648","n":"power clean","bp":"upper legs","eq":"barbell","tg":"hamstrings","mg":"glutes","sm":["glutes","quadriceps","calves"],"st":["Start with the barbell on the ground in front of you, with your feet shoulder-width apart.","Bend down and grip the barbell with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and chest up as you lift the barbell off the ground, extending your hips and knees.","As the barbell reaches your mid-thigh, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides.","As the barbell reaches its highest point, quickly drop underneath it, rotating your elbows around and catching the barbell on your shoulders in a front squat position.","Stand up with the barbell, fully extending your hips and knees.","Lower the barbell back down to the starting position, keeping control of the weight throughout the movement.","Repeat for the desired number of repetitions."],"img":"0648-SiWCcTN.jpg","gif":"0648-SiWCcTN.gif"},{"id":"3665","n":"power point plank","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","triceps","glutes"],"st":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.","Engage your core and squeeze your glutes to maintain a stable position.","Lower your body down onto your forearms, one arm at a time, maintaining a straight line from head to toe.","Hold this position for the desired amount of time, keeping your core and glutes engaged.","To return to the starting position, push through your forearms and lift your body back up into a high plank position.","Repeat for the desired number of repetitions."],"img":"3665-hCjGsRQ.jpg","gif":"3665-hCjGsRQ.gif","ty":"rin","kind":"time"},{"id":"3203","n":"prisoner half sit-up (male)","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"3203-mgejmGP.jpg","gif":"3203-mgejmGP.gif"},{"id":"1707","n":"prone twist on stability ball","bp":"waist","eq":"stability ball","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Start by lying face down on a stability ball with your feet shoulder-width apart and your toes touching the ground.","Place your hands behind your head or cross them over your chest.","Engage your core muscles and slowly lift your upper body off the ball, keeping your back straight.","Rotate your torso to one side, bringing your shoulder towards your hip. Keep your hips and legs stable throughout the movement.","Pause for a moment, then return to the starting position.","Repeat the rotation to the other side.","Continue alternating sides for the desired number of repetitions."],"img":"1707-1IG6gVF.jpg","gif":"1707-1IG6gVF.gif"},{"id":"0651","n":"pull up (neutral grip)","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Hang from a pull-up bar with a neutral grip (palms facing each other) and your arms fully extended.","Engage your core and squeeze your shoulder blades together.","Pull your body up towards the bar by bending your elbows and driving your elbows down towards your hips.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position with control.","Repeat for the desired number of repetitions."],"img":"0651-0V2YQjW.jpg","gif":"0651-0V2YQjW.gif"},{"id":"0650","n":"pull-in (on stability ball)","bp":"waist","eq":"stability ball","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Start by sitting on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Place your hands on the sides of the stability ball for support.","Engage your abs and slowly roll your hips forward, bringing your knees towards your chest.","Pause for a moment at the top of the movement, then slowly extend your legs back to the starting position.","Repeat for the desired number of repetitions."],"img":"0650-UQr48Oi.jpg","gif":"0650-UQr48Oi.gif"},{"id":"0652","n":"pull-up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Hang from a pull-up bar with your palms facing away from you and your arms fully extended.","Engage your core and squeeze your shoulder blades together.","Pull your body up towards the bar by bending your elbows and bringing your chest towards the bar.","Pause at the top of the movement, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0652-lBDjFxJ.jpg","gif":"0652-lBDjFxJ.gif"},{"id":"1689","n":"push and pull bodyweight","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","deltoids"],"st":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your body in a straight line.","Lower your chest towards the ground by bending your elbows, keeping your body straight.","Push through your palms to extend your arms and return to the starting position.","From the push-up position, pull your chest towards the ground by bending your elbows, keeping your body straight.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."],"img":"1689-wXvUZC8.jpg","gif":"1689-wXvUZC8.gif"},{"id":"3638","n":"push to run","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Start in a push-up position with your hands shoulder-width apart and your body in a straight line.","Lower your chest towards the ground by bending your elbows, keeping your body straight.","Push through your hands to extend your arms and return to the starting position.","Quickly bring one knee towards your chest, then quickly switch and bring the other knee towards your chest.","Continue alternating knees as fast as you can while maintaining good form.","Continue for the desired duration or number of repetitions."],"img":"3638-PrQbjvB.jpg","gif":"3638-PrQbjvB.gif"},{"id":"1307","n":"push up on bosu ball","bp":"chest","eq":"bosu ball","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Place the bosu ball on the ground with the flat side facing up.","Position yourself in a push-up position with your hands on the outer edges of the bosu ball.","Engage your core and lower your body down towards the bosu ball by bending your elbows.","Push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."],"img":"1307-wVompEp.jpg","gif":"1307-wVompEp.gif"},{"id":"0662","n":"push-up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","deltoids","core"],"st":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.","Engage your core and lower your body towards the ground by bending your elbows, keeping your body in a straight line.","Pause for a moment when your chest is just above the ground, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"img":"0662-I4hDWkc.jpg","gif":"0662-I4hDWkc.gif"},{"id":"0653","n":"push-up (bosu ball)","bp":"chest","eq":"bosu ball","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Place the bosu ball on the ground with the flat side facing up.","Position yourself in a push-up position with your hands on the outer edges of the bosu ball.","Engage your core and lower your body down towards the bosu ball by bending your elbows.","Push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."],"img":"0653-2kr2lWy.jpg","gif":"0653-2kr2lWy.gif"},{"id":"0655","n":"push-up (on stability ball)","bp":"chest","eq":"stability ball","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Place the stability ball on the ground and position yourself facing down with your hands on the ball, shoulder-width apart.","Extend your legs straight out behind you, balancing on your toes.","Engage your core and lower your chest towards the ball by bending your elbows, keeping your body in a straight line.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"img":"0655-Y4BRNQF.jpg","gif":"0655-Y4BRNQF.gif"},{"id":"0656","n":"push-up (on stability ball)","bp":"chest","eq":"stability ball","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Place the stability ball on the ground and position yourself facing down with your hands on the ball, shoulder-width apart.","Extend your legs straight out behind you, balancing on your toes.","Engage your core and lower your chest towards the ball by bending your elbows, keeping your body in a straight line.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"img":"0656-tgryw5Y.jpg","gif":"0656-tgryw5Y.gif"},{"id":"0659","n":"push-up (wall)","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","deltoids"],"st":["Stand facing a wall, about arm's length away.","Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart.","Step back a few feet, keeping your body straight and your feet hip-width apart.","Bend your elbows and lower your chest towards the wall, keeping your body in a straight line.","Push back up to the starting position, straightening your arms.","Repeat for the desired number of repetitions."],"img":"0659-LEH9jxP.jpg","gif":"0659-LEH9jxP.gif"},{"id":"0658","n":"push-up (wall) v. 2","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Stand facing a wall, about arm's length away.","Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart.","Step back with your feet, keeping them hip-width apart.","Engage your core and keep your body in a straight line from head to heels.","Bend your elbows and lower your chest towards the wall, keeping your body straight.","Pause for a moment, then push yourself back to the starting position.","Repeat for the desired number of repetitions."],"img":"0658-NCmbLCw.jpg","gif":"0658-NCmbLCw.gif"},{"id":"0660","n":"push-up close-grip off dumbbell","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Start in a push-up position with your hands placed close together, directly under your shoulders.","Hold a dumbbell in each hand, resting them on the ground.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."],"img":"0660-KZXAtKQ.jpg","gif":"0660-KZXAtKQ.gif"},{"id":"0661","n":"push-up inside leg kick","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Lower your body towards the ground by bending your elbows, keeping your back straight and your core engaged.","As you push back up, lift one leg off the ground and kick it out to the side, keeping it straight.","Lower your leg back down and repeat the push-up, then switch to the other leg.","Continue alternating leg kicks with each push-up repetition."],"img":"0661-0br45wL.jpg","gif":"0661-0br45wL.gif"},{"id":"0663","n":"push-up medicine ball","bp":"chest","eq":"medicine ball","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Start in a high plank position with your hands on the medicine ball, shoulder-width apart.","Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."],"img":"0663-W8KAlkI.jpg","gif":"0663-W8KAlkI.gif"},{"id":"1467","n":"push-up on lower arms","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Start in a plank position with your forearms on the ground and elbows directly below your shoulders.","Engage your core and keep your body in a straight line from head to toe.","Lower your chest towards the ground by bending your elbows, keeping them close to your body.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"img":"1467-4Jt8QsQ.jpg","gif":"1467-4Jt8QsQ.gif"},{"id":"3145","n":"push-up plus","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","Once your chest is just above the ground, push through your hands to extend your arms and lift your upper body up.","At the top of the movement, protract your shoulder blades by pushing your upper back towards the ceiling.","Pause for a moment, then reverse the movement by retracting your shoulder blades and lowering your body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"3145-pvBMLHA.jpg","gif":"3145-pvBMLHA.gif"},{"id":"0664","n":"push-up to side plank","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","chest","triceps"],"st":["Start in a push-up position with your hands shoulder-width apart and your body in a straight line.","Lower your body towards the ground by bending your elbows, keeping your core engaged.","Push back up to the starting position.","Shift your weight onto your left hand and rotate your body to the right, lifting your right arm towards the ceiling.","Hold the side plank position for a few seconds, then return to the starting position.","Repeat the push-up and side plank on the opposite side.","Continue alternating sides for the desired number of repetitions."],"img":"0664-KhHJ338.jpg","gif":"0664-KhHJ338.gif","ty":"rin"},{"id":"3533","n":"quads","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Stand with your feet shoulder-width apart.","Lower your body by bending your knees and pushing your hips back as if sitting on a chair.","Keep your chest up and your back straight.","Lower yourself until your thighs are parallel to the ground.","Push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"3533-6YUfHPL.jpg","gif":"3533-6YUfHPL.gif"},{"id":"3201","n":"quarter sit-up","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"3201-enxnJcM.jpg","gif":"3201-enxnJcM.gif"},{"id":"3552","n":"quick feet v. 2","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","hamstrings"],"st":["Stand with your feet shoulder-width apart and your arms by your sides.","Begin by rapidly moving your feet up and down, as if you were running in place.","Keep your movements quick and light, focusing on staying on the balls of your feet.","Continue for the desired duration or number of repetitions."],"img":"3552-mweqJin.jpg","gif":"3552-mweqJin.gif"},{"id":"0666","n":"raise single arm push-up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Extend one arm straight out to the side, parallel to the ground.","Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged.","Push back up to the starting position, using your chest muscles to lift your body.","Repeat with the other arm extended."],"img":"0666-13TpY4H.jpg","gif":"0666-13TpY4H.gif"},{"id":"0668","n":"rear decline bridge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Lie on your back with your feet flat on the ground and your knees bent.","Place your arms by your sides with your palms facing down.","Engage your glutes and hamstrings, and lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Hold this position for a few seconds, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0668-UpAlold.jpg","gif":"0668-UpAlold.gif","ty":"rin"},{"id":"0669","n":"rear deltoid stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids"],"st":["Stand tall with your feet shoulder-width apart.","Extend your right arm across your chest, placing your left hand on your right elbow.","Gently pull your right arm towards your left shoulder, feeling a stretch in your right shoulder.","Hold the stretch for 15-30 seconds, then release.","Repeat on the other side."],"img":"0669-xifhB5W.jpg","gif":"0669-xifhB5W.gif","ty":"stretch","kind":"time"},{"id":"0670","n":"rear pull-up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0670-CbFSYC1.jpg","gif":"0670-CbFSYC1.gif"},{"id":"1582","n":"reclining big toe pose with rope","bp":"upper legs","eq":"rope","tg":"hamstrings","mg":"calves","sm":["calves","glutes"],"st":["Lie on your back with your legs extended and your arms by your sides.","Loop the rope around the ball of your right foot and hold the ends of the rope with your hands.","Slowly raise your right leg towards your chest, keeping your knee straight and your foot flexed.","Hold the stretch for a few seconds, then slowly lower your leg back down to the starting position.","Repeat with your left leg.","Continue alternating legs for the desired number of repetitions."],"img":"1582-K5xgdvI.jpg","gif":"1582-K5xgdvI.gif"},{"id":"3236","n":"resistance band hip thrusts on knees (female)","bp":"upper legs","eq":"resistance band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Start by kneeling on the ground with your knees hip-width apart and your feet flexed.","Wrap the resistance band around your thighs, just above your knees.","Place your hands on your hips or extend them out in front of you for balance.","Engage your glutes and core muscles.","Push your hips forward and squeeze your glutes as you lift your knees off the ground, extending your hips until your thighs are parallel to the ground.","Hold the position for a moment, then slowly lower your knees back down to the starting position.","Repeat for the desired number of repetitions."],"img":"3236-Pjbc0Kt.jpg","gif":"3236-Pjbc0Kt.gif"},{"id":"3007","n":"resistance band leg extension","bp":"upper legs","eq":"resistance band","tg":"quads","mg":"hamstrings","sm":["hamstrings"],"st":["Attach the resistance band to a sturdy anchor point and secure it around your ankle.","Stand facing the anchor point with your feet shoulder-width apart.","Keeping your core engaged and your upper body stable, extend your leg straight out in front of you.","Pause for a moment at the top, then slowly return your leg to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"img":"3007-Y1MsI1l.jpg","gif":"3007-Y1MsI1l.gif"},{"id":"3123","n":"resistance band seated biceps curl","bp":"upper arms","eq":"resistance band","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a chair or bench with your back straight and feet flat on the ground.","Hold the resistance band with an underhand grip, palms facing up, and arms extended down by your sides.","Keeping your upper arms stationary, exhale and curl the resistance band up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the resistance band back to the starting position.","Repeat for the desired number of repetitions."],"img":"3123-XFc3vpY.jpg","gif":"3123-XFc3vpY.gif"},{"id":"3124","n":"resistance band seated chest press","bp":"chest","eq":"resistance band","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Sit on a chair or bench with your back straight and feet flat on the ground.","Hold the resistance band handles in each hand, with your palms facing down and elbows bent at a 90-degree angle.","Extend your arms forward, pushing the resistance band away from your chest.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"3124-4x5Okof.jpg","gif":"3124-4x5Okof.gif"},{"id":"3006","n":"resistance band seated hip abduction","bp":"upper legs","eq":"resistance band","tg":"abductors","mg":"glutes","sm":["glutes","hamstrings"],"st":["Sit on a chair or bench with your back straight and feet flat on the ground.","Wrap the resistance band around your thighs, just above your knees.","Place your hands on the sides of the chair or bench for support.","Engage your abductors (outer thigh muscles) and slowly push your knees apart, against the resistance of the band.","Pause for a moment at the end of the movement, then slowly bring your knees back together.","Repeat for the desired number of repetitions."],"img":"3006-0xDpB4L.jpg","gif":"3006-0xDpB4L.gif"},{"id":"3122","n":"resistance band seated shoulder press","bp":"shoulders","eq":"resistance band","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Sit on a chair or bench with your back straight and feet flat on the ground.","Hold the resistance band with both hands, palms facing forward, and bring it up to shoulder level.","Press the band overhead, extending your arms fully.","Pause for a moment at the top, then slowly lower the band back down to shoulder level.","Repeat for the desired number of repetitions."],"img":"3122-S93zLTG.jpg","gif":"3122-S93zLTG.gif"},{"id":"3144","n":"resistance band seated straight back row","bp":"back","eq":"resistance band","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Sit on the floor with your legs extended and loop the resistance band around your feet.","Hold the ends of the resistance band with your hands, palms facing each other.","Keep your back straight and lean slightly back, engaging your core.","Pull the resistance band towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"img":"3144-Nu7jqFE.jpg","gif":"3144-Nu7jqFE.gif"},{"id":"0872","n":"reverse crunch","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Lie flat on your back with your arms extended along your sides.","Bend your knees and lift your feet off the ground, bringing your thighs perpendicular to the floor.","Contract your abs and curl your hips off the floor, bringing your knees towards your chest.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0872-nCU1Ekp.jpg","gif":"0872-nCU1Ekp.gif"},{"id":"0672","n":"reverse dip","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Position yourself between two parallel bars with your arms fully extended and your body straight.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"img":"0672-NZ5Qqkz.jpg","gif":"0672-NZ5Qqkz.gif"},{"id":"0673","n":"reverse grip machine lat pulldown","bp":"back","eq":"leverage machine","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.","Grasp the handles with an underhand grip, slightly wider than shoulder-width apart.","Sit upright with your chest out and shoulders back, maintaining a slight arch in your lower back.","Pull the handles down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."],"img":"0673-ecpY0rH.jpg","gif":"0673-ecpY0rH.gif"},{"id":"0674","n":"reverse grip pull-up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Grab the pull-up bar with an underhand grip, hands shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0674-YAk5dIw.jpg","gif":"0674-YAk5dIw.gif"},{"id":"0675","n":"reverse hyper extension (on stability ball)","bp":"upper legs","eq":"stability ball","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Lie face down on a stability ball with your hips resting on the ball and your legs extended straight behind you.","Place your hands on the ground in front of you for stability.","Engaging your glutes and hamstrings, lift your legs up towards the ceiling as high as you can.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0675-vM5YS2g.jpg","gif":"0675-vM5YS2g.gif"},{"id":"1423","n":"reverse hyper on flat bench","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Lie face down on a flat bench with your hips at the edge and your legs hanging off the bench.","Hold onto the bench for stability.","Keeping your legs straight, raise them up towards the ceiling as high as you can.","Squeeze your glutes at the top of the movement.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1423-OrETs32.jpg","gif":"1423-OrETs32.gif"},{"id":"3663","n":"reverse plank with leg lift","bp":"waist","eq":"body weight","tg":"abs","mg":"glutes","sm":["glutes","hamstrings","shoulders"],"st":["Sit on the ground with your legs extended in front of you and your hands resting on the ground behind you, fingers pointing towards your feet.","Press through your hands and lift your hips off the ground, coming into a reverse plank position.","Engage your core and lift one leg off the ground, extending it straight up towards the ceiling.","Hold for a moment, then lower your leg back down.","Repeat with the other leg.","Continue alternating legs for the desired number of repetitions."],"img":"3663-tFToB7l.jpg","gif":"3663-tFToB7l.gif","ty":"rin"},{"id":"0677","n":"ring dips","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Start by hanging from the rings with your arms fully extended and your body straight.","Lower your body by bending your elbows until your shoulders are below your elbows.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"img":"0677-ezTvXcr.jpg","gif":"0677-ezTvXcr.gif"},{"id":"2571","n":"rocking frog stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Start by kneeling on the ground with your knees hip-width apart.","Place your hands on the ground in front of you for support.","Slowly lean forward, shifting your weight onto your hands and extending your legs behind you.","Keep your back straight and engage your glutes as you push your hips back and up towards the ceiling.","Hold this position for a few seconds, feeling a stretch in your glutes.","Slowly return to the starting position by bending your knees and lowering your hips back down.","Repeat for the desired number of repetitions."],"img":"2571-2Dk4xQV.jpg","gif":"2571-2Dk4xQV.gif","ty":"stretch","kind":"time"},{"id":"0678","n":"rocky pull-up pulldown","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Stand in front of a pull-up bar with your feet shoulder-width apart.","Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0678-cQ19bBP.jpg","gif":"0678-cQ19bBP.gif"},{"id":"2208","n":"roller back stretch","bp":"back","eq":"roller","tg":"spine","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Start by sitting on the ground with your legs extended in front of you.","Place the roller perpendicular to your body, just below your glutes.","Slowly roll your body backwards, allowing the roller to move up your back.","Continue rolling until the roller reaches your upper back.","Pause for a moment, then slowly roll back to the starting position.","Repeat for the desired number of repetitions."],"img":"2208-isofgzg.jpg","gif":"2208-isofgzg.gif","ty":"stretch","kind":"time"},{"id":"2204","n":"roller body saw","bp":"waist","eq":"roller","tg":"abs","mg":"shoulders","sm":["shoulders","triceps","core"],"st":["Start in a plank position with your forearms on the roller and your body in a straight line.","Engage your core and slowly roll the roller forward, extending your body as far as you can while maintaining control.","Pause for a moment at the furthest point, then slowly roll the roller back towards your starting position.","Repeat for the desired number of repetitions."],"img":"2204-XeMvLgE.jpg","gif":"2204-XeMvLgE.gif"},{"id":"2205","n":"roller hip lat stretch","bp":"upper legs","eq":"roller","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Start by kneeling on the ground with the roller positioned under your hips.","Place your hands on the roller for support.","Slowly roll the roller forward, extending your hips and stretching your glutes.","Hold the stretch for a few seconds, then roll back to the starting position.","Repeat for the desired number of repetitions."],"img":"2205-0L2KwtI.jpg","gif":"2205-0L2KwtI.gif","ty":"stretch","kind":"time"},{"id":"2202","n":"roller hip stretch","bp":"upper legs","eq":"roller","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Start by sitting on the ground with your legs extended in front of you.","Place the roller under your glutes, just above your knees.","Lean back and place your hands on the ground behind you for support.","Engage your glutes and slowly roll the roller forward, bending your knees and bringing them towards your chest.","Pause for a moment at the end of the movement, feeling a stretch in your glutes.","Slowly roll the roller back to the starting position, extending your legs.","Repeat for the desired number of repetitions."],"img":"2202-oMypNrz.jpg","gif":"2202-oMypNrz.gif","ty":"stretch","kind":"time"},{"id":"2206","n":"roller reverse crunch","bp":"waist","eq":"roller","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Lie flat on your back with your arms extended straight above your head and your legs straight out in front of you.","Place the roller between your feet and grip it with your toes.","Engaging your abs, lift your legs off the ground and curl your knees towards your chest, rolling the roller towards your body.","Pause for a moment at the top, then slowly lower your legs back down to the starting position, rolling the roller away from your body.","Repeat for the desired number of repetitions."],"img":"2206-SKXQAx3.jpg","gif":"2206-SKXQAx3.gif"},{"id":"2203","n":"roller seated shoulder flexor depresor retractor","bp":"chest","eq":"roller","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Sit on a flat surface with your legs extended in front of you.","Hold the roller with both hands, palms facing down, and place it on your thighs.","Lean forward slightly and roll the roller away from your body, extending your arms straight in front of you.","Pause for a moment, then slowly roll the roller back towards your body, bending your arms and bringing the roller back to your thighs.","Repeat for the desired number of repetitions."],"img":"2203-8coXSYU.jpg","gif":"2203-8coXSYU.gif","ty":"mob"},{"id":"2209","n":"roller seated single leg shoulder flexor depresor retractor","bp":"chest","eq":"roller","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Sit on a flat surface with your legs extended in front of you.","Hold the roller with both hands, palms facing down, and place it on your thighs.","Lean back slightly and engage your core muscles.","Raise the roller up to shoulder level, keeping your arms straight.","Slowly lower the roller back down to your thighs.","Repeat for the desired number of repetitions."],"img":"2209-CjETvlw.jpg","gif":"2209-CjETvlw.gif","ty":"mob"},{"id":"2207","n":"roller side lat stretch","bp":"back","eq":"roller","tg":"lats","mg":"shoulders","sm":["shoulders","triceps"],"st":["Stand with your feet shoulder-width apart and hold the roller with both hands in front of your body.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms forward and roll the roller down towards your feet, feeling a stretch in your lats.","Hold the stretch for a few seconds, then slowly roll the roller back up to the starting position.","Repeat for the desired number of repetitions."],"img":"2207-c3Pfhti.jpg","gif":"2207-c3Pfhti.gif","ty":"stretch","kind":"time"},{"id":"0680","n":"rope climb","bp":"back","eq":"rope","tg":"upper back","mg":"forearms","sm":["forearms","biceps","shoulders"],"st":["Stand facing the rope with your feet shoulder-width apart.","Grab the rope with both hands, palms facing towards you.","Bend your knees slightly and engage your core.","Begin pulling yourself up the rope by alternating hand-over-hand movements.","Use your legs to assist in the upward movement.","Continue climbing until you reach the desired height or the top of the rope.","To descend, reverse the hand-over-hand movement while controlling your descent.","Repeat for the desired number of repetitions."],"img":"0680-yaAxcQr.jpg","gif":"0680-yaAxcQr.gif"},{"id":"0685","n":"run","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Start by standing upright with your feet hip-width apart.","Engage your core and keep your upper body relaxed.","Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet.","Maintain a steady pace and continue jogging for the desired duration or distance.","Remember to breathe deeply and maintain good posture throughout the exercise."],"img":"0685-oLrKqDH.jpg","gif":"0685-oLrKqDH.gif"},{"id":"0684","n":"run (equipment)","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Start by standing upright with your feet hip-width apart.","Engage your core and keep your upper body relaxed.","Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet.","Maintain a steady pace and continue jogging for the desired duration or distance.","Remember to breathe deeply and maintain good posture throughout the exercise."],"img":"0684-y5p0H8a.jpg","gif":"0684-y5p0H8a.gif"},{"id":"1585","n":"runners stretch","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","quadriceps"],"st":["Stand with your feet hip-width apart.","Take a step forward with your right foot, keeping your left foot planted.","Bend your right knee and lower your body down, keeping your left leg straight.","Place your hands on your right thigh for support.","Hold the stretch for 20-30 seconds, then switch sides and repeat."],"img":"1585-0mB6wHO.jpg","gif":"1585-0mB6wHO.gif","ty":"stretch","kind":"time"},{"id":"0687","n":"russian twist","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Sit on the ground with your knees bent and feet flat on the floor.","Lean back slightly while keeping your back straight and your core engaged.","Hold your hands together in front of your chest or hold a weight if desired.","Lift your feet off the ground, balancing on your sit bones.","Twist your torso to the right, bringing your hands or weight towards the right side of your body.","Pause for a moment, then twist your torso to the left, bringing your hands or weight towards the left side of your body.","Continue alternating sides for the desired number of repetitions."],"img":"0687-XVDdcoj.jpg","gif":"0687-XVDdcoj.gif"},{"id":"3012","n":"scapula dips","bp":"back","eq":"body weight","tg":"traps","mg":"rhomboids","sm":["rhomboids","deltoids"],"st":["Start by standing with your feet shoulder-width apart and your arms extended in front of you.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Lower your body by bending your elbows and retracting your shoulder blades, as if you are trying to squeeze a pencil between them.","Pause for a moment at the bottom, then push through your hands to extend your elbows and return to the starting position.","Repeat for the desired number of repetitions."],"img":"3012-7xeukSt.jpg","gif":"3012-7xeukSt.gif","ty":"rin"},{"id":"3021","n":"scapula push-up","bp":"chest","eq":"body weight","tg":"serratus anterior","mg":"triceps","sm":["triceps","shoulders"],"st":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Lower your chest towards the ground, keeping your elbows close to your body.","As you lower, squeeze your shoulder blades together and push your chest forward.","Pause for a moment at the bottom, then push back up to the starting position.","Repeat for the desired number of repetitions."],"img":"3021-jV65tKx.jpg","gif":"3021-jV65tKx.gif","ty":"rin"},{"id":"0688","n":"scapular pull-up","bp":"back","eq":"body weight","tg":"traps","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended.","Retract your shoulder blades by pulling them down and back.","Engage your back muscles and pull your body up towards the bar, focusing on squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0688-uTBt1HV.jpg","gif":"0688-uTBt1HV.gif","ty":"rin"},{"id":"3219","n":"scissor jumps (male)","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart.","Jump off the ground and simultaneously cross your right leg in front of your left leg.","As you land, quickly switch legs, crossing your left leg in front of your right leg.","Continue alternating legs and jumping as quickly as possible.","Repeat for the desired number of repetitions."],"img":"3219-Eh2v5Iu.jpg","gif":"3219-Eh2v5Iu.gif","ty":"atl"},{"id":"1390","n":"seated calf stretch (male)","bp":"lower legs","eq":"body weight","tg":"calves","mg":"hamstrings","sm":["hamstrings"],"st":["Sit on the edge of a chair or bench with your feet flat on the ground.","Extend one leg straight out in front of you, keeping your heel on the ground.","Lean forward slightly, feeling a stretch in your calf muscle.","Hold the stretch for 20-30 seconds.","Switch legs and repeat the stretch."],"img":"1390-17bqEXD.jpg","gif":"1390-17bqEXD.gif","ty":"stretch","kind":"time"},{"id":"1424","n":"seated glute stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings"],"st":["Sit on the ground with your legs extended in front of you.","Bend your right knee and cross your right ankle over your left thigh.","Place your right hand on the ground behind you for support.","With your left hand, gently press down on your right knee to deepen the stretch.","Hold the stretch for 30 seconds to 1 minute.","Switch sides and repeat."],"img":"1424-DeDThfG.jpg","gif":"1424-DeDThfG.gif","ty":"stretch","kind":"time"},{"id":"0689","n":"seated leg raise","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Sit on a flat bench with your back straight and your feet flat on the ground.","Place your hands on the sides of the bench for support.","Keeping your legs straight, slowly raise them up in front of you until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0689-Hgs6Nl1.jpg","gif":"0689-Hgs6Nl1.gif"},{"id":"0690","n":"seated lower back stretch","bp":"back","eq":"body weight","tg":"lats","mg":"glutes","sm":["glutes","hamstrings"],"st":["Sit on the edge of a chair with your feet flat on the ground.","Place your hands on your thighs or on the sides of the chair for support.","Slowly lean forward from your hips, keeping your back straight.","Feel the stretch in your lower back and hold for 20-30 seconds.","Slowly return to the starting position and repeat for the desired number of repetitions."],"img":"0690-QFmz6ch.jpg","gif":"0690-QFmz6ch.gif","ty":"stretch","kind":"time"},{"id":"2567","n":"seated piriformis stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings"],"st":["Sit on the ground with your legs extended in front of you.","Bend your right knee and place your right foot on the outside of your left knee.","Place your left elbow on the outside of your right knee and gently twist your torso to the right.","Hold the stretch for 20-30 seconds, then switch sides and repeat."],"img":"2567-QY39eBr.jpg","gif":"2567-QY39eBr.gif","ty":"stretch","kind":"time"},{"id":"0691","n":"seated side crunch (wall)","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Sit on the floor with your back against a wall and your legs extended in front of you.","Bend your knees and place your feet flat on the floor, hip-width apart.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and lean to one side, bringing your elbow towards your hip.","Pause for a moment, then return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."],"img":"0691-Y9hNPcN.jpg","gif":"0691-Y9hNPcN.gif"},{"id":"1587","n":"seated wide angle pose sequence","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"quadriceps","sm":["quadriceps","calves"],"st":["Sit on the ground with your legs extended in a wide angle.","Flex your feet and engage your quadriceps.","Place your hands on the ground behind you for support.","Keeping your back straight, lean forward from your hips.","Continue leaning forward until you feel a stretch in your hamstrings.","Hold this position for a few breaths.","Slowly release the stretch and return to the starting position.","Repeat for the desired number of repetitions."],"img":"1587-HIgYKAB.jpg","gif":"1587-HIgYKAB.gif"},{"id":"0697","n":"self assisted inverse leg curl","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","calves"],"st":["Lie flat on your back on a mat or bench with your legs extended.","Place your hands by your sides or under your glutes for support.","Bend your knees and lift your feet off the ground, bringing your thighs towards your chest.","Pause for a moment at the top, then slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."],"img":"0697-GwYwElT.jpg","gif":"0697-GwYwElT.gif"},{"id":"1766","n":"self assisted inverse leg curl","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","calves"],"st":["Lie face down on a leg curl machine with your legs extended and your ankles hooked under the padded lever.","Place your hands on the side handles of the machine for support.","Keeping your upper body stationary, exhale and curl your legs upward as far as possible.","Hold the contracted position for a brief pause as you squeeze your hamstrings.","Slowly lower your legs back to the starting position while inhaling.","Repeat for the desired number of repetitions."],"img":"1766-ZSY3MsL.jpg","gif":"1766-ZSY3MsL.gif"},{"id":"0696","n":"self assisted inverse leg curl (on floor)","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","calves"],"st":["Lie flat on your back with your legs extended and your arms by your sides.","Bend your knees and place your feet flat on the ground, hip-width apart.","Lift your hips off the ground, engaging your glutes and hamstrings.","Slowly curl your legs towards your glutes, keeping your hips lifted.","Pause for a moment at the top, then slowly extend your legs back to the starting position.","Lower your hips back down to the ground.","Repeat for the desired number of repetitions."],"img":"0696-E4PwJqI.jpg","gif":"0696-E4PwJqI.gif"},{"id":"3222","n":"semi squat jump (male)","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position.","Jump explosively, extending your hips and knees while swinging your arms for momentum.","Land softly on the balls of your feet and immediately go into the next repetition.","Repeat for the desired number of repetitions."],"img":"3222-6FMU51h.jpg","gif":"3222-6FMU51h.gif","ty":"atl"},{"id":"3656","n":"short stride run","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Find an open space or a treadmill to perform the exercise.","Stand tall with your feet hip-width apart.","Start jogging in place, lifting your knees high and pumping your arms.","After a few seconds, start taking short strides forward, maintaining a quick pace.","Continue running with short strides for the desired duration or distance."],"img":"3656-CcWEoWV.jpg","gif":"3656-CcWEoWV.gif"},{"id":"1763","n":"shoulder grip pull-up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Grab the pull-up bar with a shoulder-width grip, palms facing away from you.","Hang freely with your arms fully extended.","Engage your back muscles and pull your body up towards the bar until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1763-YtgD7Xq.jpg","gif":"1763-YtgD7Xq.gif"},{"id":"3699","n":"shoulder tap","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","triceps"],"st":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Engage your core and lift your right hand off the ground, reaching across to tap your left shoulder.","Place your right hand back on the ground and repeat with your left hand tapping your right shoulder.","Continue alternating shoulder taps while keeping your hips and torso stable.","Repeat for the desired number of repetitions."],"img":"3699-yRpV5TC.jpg","gif":"3699-yRpV5TC.gif"},{"id":"0699","n":"shoulder tap push-up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","core"],"st":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","As you push back up, lift your right hand off the ground and tap your left shoulder.","Return your right hand to the ground and repeat the push-up, this time lifting your left hand and tapping your right shoulder.","Continue alternating shoulder taps with each push-up repetition.","Maintain a stable core and avoid excessive hip rotation throughout the exercise.","Repeat for the desired number of repetitions."],"img":"0699-qEse6fe.jpg","gif":"0699-qEse6fe.gif"},{"id":"1774","n":"side bridge hip abduction","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","obliques"],"st":["Lie on your side with your legs extended and stacked on top of each other.","Prop yourself up on your forearm, keeping your elbow directly below your shoulder.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","While keeping your core engaged, lift your top leg as high as possible without rotating your hips.","Pause for a moment at the top, then lower your leg back down.","Repeat for the desired number of repetitions, then switch sides."],"img":"1774-WL4EmxJ.jpg","gif":"1774-WL4EmxJ.gif","ty":"rin"},{"id":"0705","n":"side bridge v. 2","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","glutes"],"st":["Lie on your side with your legs extended and stacked on top of each other.","Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","Hold this position for the desired amount of time.","Lower your hips back down to the starting position.","Repeat on the other side."],"img":"0705-RKjH6Lt.jpg","gif":"0705-RKjH6Lt.gif","ty":"rin"},{"id":"0709","n":"side hip (on parallel bars)","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Stand between two parallel bars with your feet shoulder-width apart.","Place your hands on the bars and lift your body off the ground, supporting your weight on your arms.","Engage your abs and slowly lift your legs to the side, keeping them straight.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0709-jTkSc6o.jpg","gif":"0709-jTkSc6o.gif"},{"id":"0710","n":"side hip abduction","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","quadriceps"],"st":["Stand with your feet shoulder-width apart and your hands on your hips.","Shift your weight to one leg and lift the opposite leg out to the side, keeping it straight.","Pause for a moment at the top, then slowly lower your leg back down to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."],"img":"0710-7WaDzyL.jpg","gif":"0710-7WaDzyL.gif"},{"id":"1358","n":"side lying floor stretch","bp":"back","eq":"body weight","tg":"lats","mg":"obliques","sm":["obliques","glutes"],"st":["Lie on your side with your legs straight and your bottom arm extended straight overhead.","Bend your top knee and place your foot on the ground in front of your bottom leg.","Reach your top arm over your head and grab onto something stable, like a wall or a piece of furniture.","Slowly lift your bottom leg off the ground, keeping it straight, until you feel a stretch in your side.","Hold the stretch for 20-30 seconds, then slowly lower your leg back down.","Repeat on the other side."],"img":"1358-jDOKRM5.jpg","gif":"1358-jDOKRM5.gif","ty":"stretch","kind":"time"},{"id":"3667","n":"side lying hip adduction (male)","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"glutes","sm":["glutes","hamstrings"],"st":["Lie on your side with your legs straight and stacked on top of each other.","Place your bottom arm under your head for support.","Engage your adductors and lift your top leg as high as possible without rotating your hips or leaning backward.","Pause for a moment at the top, then slowly lower your leg back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"3667-c8f5cSY.jpg","gif":"3667-c8f5cSY.gif"},{"id":"1775","n":"side plank hip adduction","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"obliques","sm":["obliques","glutes"],"st":["Start by lying on your side with your legs extended and stacked on top of each other.","Prop yourself up on your forearm, keeping your elbow directly below your shoulder.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","While maintaining the side plank position, lift your top leg towards the ceiling, keeping it straight.","Slowly lower your leg back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"1775-VO2qeJg.jpg","gif":"1775-VO2qeJg.gif","ty":"rin"},{"id":"0716","n":"side push neck stretch","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"trapezius","sm":["trapezius","sternocleidomastoid"],"st":["Stand or sit up straight with your shoulders relaxed.","Tilt your head to the right, bringing your right ear towards your right shoulder.","Place your right hand on the left side of your head and gently apply pressure to increase the stretch.","Hold the stretch for 15-30 seconds.","Repeat on the other side, tilting your head to the left and applying pressure with your left hand.","Repeat the stretch 2-3 times on each side."],"img":"0716-oQRJYkC.jpg","gif":"0716-oQRJYkC.gif","ty":"stretch","kind":"time"},{"id":"0717","n":"side push-up","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders","chest","core"],"st":["Start by lying on your side with your legs extended and stacked on top of each other.","Place your bottom hand on the ground directly under your shoulder, fingers pointing forward.","Press through your bottom hand to lift your body off the ground, keeping your legs straight and your core engaged.","Extend your top arm straight up towards the ceiling, creating a straight line from your head to your heels.","Lower your body back down to the starting position with control.","Repeat for the desired number of repetitions, then switch sides."],"img":"0717-wpbD28t.jpg","gif":"0717-wpbD28t.gif"},{"id":"0721","n":"side wrist pull stretch","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrists","sm":["wrists","hands"],"st":["Stand with your feet shoulder-width apart and your arms extended in front of you.","Extend your right arm out to the side, parallel to the ground, with your palm facing down.","With your left hand, grab your right hand and gently pull it towards your body, feeling a stretch in your right forearm.","Hold the stretch for 15-30 seconds, then release.","Repeat on the other side."],"img":"0721-UtmIqcI.jpg","gif":"0721-UtmIqcI.gif","ty":"stretch","kind":"time"},{"id":"0720","n":"side-to-side chin","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body relaxed.","Pull yourself up by bending your elbows and bringing your chin towards the bar, while keeping your body straight.","Once your chin is above the bar, lower yourself back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0720-isAAZWA.jpg","gif":"0720-isAAZWA.gif"},{"id":"3213","n":"side-to-side toe touch (male)","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Stand with your feet shoulder-width apart and your arms extended to the sides.","Bend at the waist to the right, reaching your right hand towards your right foot while keeping your left hand extended to the side.","Return to the starting position and then bend at the waist to the left, reaching your left hand towards your left foot while keeping your right hand extended to the side.","Repeat the side-to-side bending motion for the desired number of repetitions."],"img":"3213-WCAvOfC.jpg","gif":"3213-WCAvOfC.gif"},{"id":"0725","n":"single arm push-up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Start in a push-up position with your hands shoulder-width apart and one hand placed slightly wider than the other.","Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight.","As you lower yourself, shift your weight to one side and lift the opposite arm off the ground, extending it straight out to the side.","Push through your chest and triceps to raise your body back up to the starting position, while simultaneously lowering your extended arm back to the ground.","Repeat the movement, alternating the arm you extend with each repetition."],"img":"0725-MUic5zN.jpg","gif":"0725-MUic5zN.gif"},{"id":"3645","n":"single leg bridge with outstretched leg","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Lie on your back with your knees bent and feet flat on the ground.","Extend one leg straight out in front of you.","Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.","Hold for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"img":"3645-rmEukuS.jpg","gif":"3645-rmEukuS.gif","ty":"rin"},{"id":"0727","n":"single leg calf raise (on a dumbbell)","bp":"lower legs","eq":"dumbbell","tg":"calves","mg":"ankles","sm":["ankles","feet"],"st":["Stand with your feet hip-width apart and hold a dumbbell in one hand.","Lift one foot off the ground and balance on the other foot.","Slowly raise your heel as high as possible, using your calf muscles.","Pause for a moment at the top, then slowly lower your heel back down.","Repeat for the desired number of repetitions, then switch to the other leg."],"img":"0727-fKZgDEO.jpg","gif":"0727-fKZgDEO.gif"},{"id":"0730","n":"single leg platform slide","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","quadriceps"],"st":["Start by standing with one foot on a platform or slide board.","Bend your knee slightly and slide the foot on the platform backward, extending your leg.","Keep your core engaged and maintain a straight posture throughout the movement.","Slowly return to the starting position by sliding your foot back to the initial position.","Repeat the movement for the desired number of repetitions, then switch legs."],"img":"0730-LNE3wfo.jpg","gif":"0730-LNE3wfo.gif"},{"id":"1759","n":"single leg squat (pistol) male","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart and arms extended in front of you.","Lift your right foot off the ground and extend it forward.","Slowly lower your body down by bending your left knee and pushing your hips back.","Keep your chest up and your back straight as you lower yourself down.","Lower until your left thigh is parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your left heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"img":"1759-nqs5HGV.jpg","gif":"1759-nqs5HGV.gif","ty":"atl"},{"id":"1489","n":"sissy squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","glutes"],"st":["Stand with your feet shoulder-width apart and your toes pointing slightly outward.","Hold onto a stable object for balance if needed.","Slowly lower your body by bending your knees and leaning back, keeping your torso upright.","Continue lowering until your thighs are parallel to the ground or as far as you can comfortably go.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"1489-xdYPUtE.jpg","gif":"1489-xdYPUtE.gif"},{"id":"0735","n":"sit-up v. 2","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0735-Bn6TXyO.jpg","gif":"0735-Bn6TXyO.gif"},{"id":"3679","n":"sit-up with arms on chest","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Cross your arms over your chest.","Engaging your abs, lift your upper body off the ground towards your knees.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"3679-6ZCiYWQ.jpg","gif":"3679-6ZCiYWQ.gif"},{"id":"3361","n":"skater hops","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","glutes","calves"],"st":["Stand with your feet shoulder-width apart.","Bend your knees slightly and jump to the right, landing on your right foot.","As you land, swing your left leg behind your right leg and tap the ground with your left toes.","Immediately jump to the left, landing on your left foot.","As you land, swing your right leg behind your left leg and tap the ground with your right toes.","Continue alternating sides, jumping and tapping the ground with each leg.","Repeat for the desired number of repetitions."],"img":"3361-zfNHMN9.jpg","gif":"3361-zfNHMN9.gif","ty":"atl"},{"id":"2142","n":"ski ergometer","bp":"upper arms","eq":"skierg machine","tg":"triceps","mg":"shoulders","sm":["shoulders","forearms"],"st":["Adjust the seat height and footrests to a comfortable position.","Grasp the handles with an overhand grip, palms facing down.","Sit up straight with your feet flat on the footrests.","Extend your arms straight out in front of you, keeping your elbows slightly bent.","Engage your triceps and push the handles down towards your thighs.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"2142-vpQaQkH.jpg","gif":"2142-vpQaQkH.gif"},{"id":"3671","n":"ski step","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","glutes","calves"],"st":["Stand with your feet shoulder-width apart.","Bend your knees slightly and keep your back straight.","Jump to the right, landing on your right foot while swinging your left leg behind your right leg.","Immediately jump to the left, landing on your left foot while swinging your right leg behind your left leg.","Continue alternating jumps from side to side, mimicking a skiing motion.","Repeat for the desired number of repetitions."],"img":"3671-5MRH8H2.jpg","gif":"3671-5MRH8H2.gif"},{"id":"3304","n":"skin the cat","bp":"back","eq":"body weight","tg":"upper back","mg":"shoulders","sm":["shoulders","core"],"st":["Start by hanging from a bar with your arms fully extended and your body relaxed.","Engage your core and lift your legs up, bringing your knees towards your chest.","Continue to lift your legs up and over your head, allowing your body to pass through the arms.","Once your legs are fully extended over your head, begin to lower them back down towards the starting position.","As you lower your legs, allow your body to pass back through the arms until you are hanging with your arms fully extended again.","Repeat for the desired number of repetitions."],"img":"3304-MSfvriJ.jpg","gif":"3304-MSfvriJ.gif"},{"id":"1425","n":"sled 45 degrees one leg press","bp":"upper legs","eq":"sled machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Adjust the sled machine to a 45-degree angle.","Sit on the sled machine with your back against the pad and your feet on the footplate.","Place one foot on the footplate and extend your leg, pushing the sled away from you.","Slowly bend your knee and lower the sled back to the starting position.","Repeat with the other leg.","Continue alternating legs for the desired number of repetitions."],"img":"1425-WWD6FzI.jpg","gif":"1425-WWD6FzI.gif"},{"id":"0738","n":"sled 45° calf press","bp":"lower legs","eq":"sled machine","tg":"calves","mg":"hamstrings","sm":["hamstrings"],"st":["Adjust the sled machine to a 45-degree angle.","Place your feet on the sled platform with your toes pointing forward.","Push the sled platform away from you by extending your ankles and calves.","Pause for a moment at the top, then slowly lower the sled platform back to the starting position.","Repeat for the desired number of repetitions."],"img":"0738-qCNVnaU.jpg","gif":"0738-qCNVnaU.gif"},{"id":"0739","n":"sled 45° leg press","bp":"upper legs","eq":"sled machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Adjust the seat and footplate of the sled machine to a comfortable position.","Sit on the sled machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Grip the handles on the sides of the seat for stability.","Push the footplate away from your body by extending your legs, keeping your heels on the footplate.","Continue pushing until your legs are almost fully extended, but without locking your knees.","Pause for a moment at the top of the movement, then slowly lower the footplate back towards your body by bending your knees.","Repeat for the desired number of repetitions."],"img":"0739-10Z2DXU.jpg","gif":"0739-10Z2DXU.gif"},{"id":"1464","n":"sled 45° leg press (back pov)","bp":"upper legs","eq":"sled machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Adjust the seat of the sled machine so that your knees are at a 45-degree angle.","Sit on the sled machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Grip the handles on the sides of the seat for stability.","Push the footplate away from your body by extending your legs, keeping your heels on the footplate.","Pause for a moment at the fully extended position.","Slowly bend your knees and lower the footplate back towards your body, controlling the movement.","Repeat for the desired number of repetitions."],"img":"1464-yn2lLSI.jpg","gif":"1464-yn2lLSI.gif"},{"id":"1463","n":"sled 45° leg press (side pov)","bp":"upper legs","eq":"sled machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Adjust the seat of the sled machine so that your knees are at a 90-degree angle when your feet are on the footplate.","Sit on the sled machine with your back flat against the backrest and your feet shoulder-width apart on the footplate.","Grip the handles on the sides of the seat for stability.","Push against the footplate to extend your legs, straightening them completely.","Pause for a moment at the top, then slowly bend your knees to lower the footplate back to the starting position.","Repeat for the desired number of repetitions."],"img":"1463-2Qh2J1e.jpg","gif":"1463-2Qh2J1e.gif"},{"id":"0740","n":"sled 45° leg wide press","bp":"upper legs","eq":"sled machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Adjust the sled machine to a 45-degree angle.","Sit on the sled machine with your back against the pad and your feet on the foot platform.","Position your feet wider than shoulder-width apart.","Push against the foot platform to extend your legs and straighten your knees.","Pause for a moment at the end of the movement, then slowly bend your knees to return to the starting position.","Repeat for the desired number of repetitions."],"img":"0740-tj41Nu6.jpg","gif":"0740-tj41Nu6.gif"},{"id":"1391","n":"sled calf press on leg press","bp":"lower legs","eq":"sled machine","tg":"calves","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled.","Place your feet shoulder-width apart on the sled, with your toes pointing forward.","Release the safety handles and push the sled away from you by extending your knees and ankles.","Pause for a moment at the top of the movement, then slowly lower the sled back down by bending your knees and ankles.","Repeat for the desired number of repetitions."],"img":"1391-ykHcWme.jpg","gif":"1391-ykHcWme.gif"},{"id":"0741","n":"sled closer hack squat","bp":"upper legs","eq":"sled machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Adjust the sled machine to a comfortable weight and position yourself with your back against the pad.","Place your feet shoulder-width apart on the platform, toes slightly pointed outwards.","Grip the handles on the sides of the machine for stability.","Engage your core and slowly lower your body by bending your knees and hips, keeping your back straight.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment at the bottom, then push through your heels to extend your legs and return to the starting position.","Repeat for the desired number of repetitions."],"img":"0741-gf3ZjB9.jpg","gif":"0741-gf3ZjB9.gif"},{"id":"0742","n":"sled forward angled calf raise","bp":"lower legs","eq":"sled machine","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Adjust the sled machine to a comfortable weight and position yourself on the machine with your toes on the platform and your heels hanging off.","Place your hands on the handles or the sides of the machine for support.","Engage your calves and slowly raise your heels as high as possible, pushing against the resistance of the sled.","Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0742-XDOiFns.jpg","gif":"0742-XDOiFns.gif"},{"id":"0743","n":"sled hack squat","bp":"upper legs","eq":"sled machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Adjust the sled machine to a comfortable position for your height.","Stand with your feet shoulder-width apart on the platform, toes slightly pointed outwards.","Hold onto the handles or bars for stability.","Lower your body by bending your knees and hips, keeping your back straight and chest up.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment, then push through your heels to raise your body back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0743-Qa55kX1.jpg","gif":"0743-Qa55kX1.gif"},{"id":"2334","n":"sled lying calf press","bp":"lower legs","eq":"sled machine","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Adjust the sled machine to a comfortable weight.","Sit on the sled machine with your back against the pad and your feet on the platform.","Place your toes and the balls of your feet on the edge of the platform, with your heels hanging off.","Push the platform away from you by extending your ankles, keeping your knees slightly bent.","Continue pushing until your calves are fully contracted.","Hold the contraction for a moment, then slowly lower the platform back to the starting position.","Repeat for the desired number of repetitions."],"img":"2334-g376LuL.jpg","gif":"2334-g376LuL.gif"},{"id":"0744","n":"sled lying squat","bp":"upper legs","eq":"sled machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Adjust the sled machine to a comfortable weight.","Lie on your back on the sled machine with your feet on the footplate.","Position your feet shoulder-width apart and slightly angled outwards.","Grip the handles of the sled machine for stability.","Engage your glutes and core muscles.","Push through your heels and extend your legs to lift the sled.","Lower the sled back down by bending your knees and hips.","Repeat for the desired number of repetitions."],"img":"0744-9n2149Z.jpg","gif":"0744-9n2149Z.gif"},{"id":"1392","n":"sled one leg calf press on leg press","bp":"lower legs","eq":"sled machine","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled.","Sit on the machine with your back against the backrest and your feet on the sled, shoulder-width apart.","Place your toes and the balls of your feet on the sled, keeping your heels off.","Push the sled forward by extending your ankles, keeping your knees slightly bent.","Pause for a moment at the top, then slowly lower the sled back down by flexing your ankles.","Repeat for the desired number of repetitions."],"img":"1392-u0pLNgz.jpg","gif":"1392-u0pLNgz.gif"},{"id":"1496","n":"sledge hammer","bp":"waist","eq":"hammer","tg":"abs","mg":"forearms","sm":["forearms","shoulders"],"st":["Stand with your feet shoulder-width apart and hold the sledge hammer with both hands.","Engage your core and keep your back straight.","Swing the sledge hammer down towards the ground, using your core and upper body strength.","As you swing down, pivot your hips and transfer the force to the hammer.","Repeat for the desired number of repetitions."],"img":"1496-REXmfVC.jpg","gif":"1496-REXmfVC.gif"},{"id":"0746","n":"smith back shrug","bp":"back","eq":"smith machine","tg":"traps","mg":"shoulders","sm":["shoulders"],"st":["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your arms straight and allow the barbell to hang in front of your thighs.","Lift your shoulders straight up towards your ears, squeezing your traps at the top.","Hold for a moment, then lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0746-MzNnwx9.jpg","gif":"0746-MzNnwx9.gif"},{"id":"0747","n":"smith behind neck press","bp":"shoulders","eq":"smith machine","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Adjust the seat height of the smith machine so that the bar is at shoulder level.","Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Lift the bar off the rack and step back, maintaining a stable stance.","Lower the bar down to the back of your neck, keeping your elbows pointing forward.","Press the bar up overhead until your arms are fully extended.","Pause for a moment at the top, then slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0747-Gpn4ADc.jpg","gif":"0747-Gpn4ADc.gif"},{"id":"0748","n":"smith bench press","bp":"chest","eq":"smith machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Adjust the height of the smith machine bar to chest level.","Lie flat on the bench with your feet firmly planted on the ground.","Grip the bar with an overhand grip slightly wider than shoulder-width apart.","Unrack the bar and lower it towards your chest, keeping your elbows tucked in.","Pause for a moment when the bar touches your chest.","Push the bar back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"0748-trqKQv2.jpg","gif":"0748-trqKQv2.gif"},{"id":"0749","n":"smith bent knee good morning","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Start by standing with your feet shoulder-width apart, toes pointing forward.","Place the barbell across your upper back, resting it on your traps.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Engage your glutes and hamstrings to raise your torso back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0749-1bQkKZK.jpg","gif":"0749-1bQkKZK.gif"},{"id":"1359","n":"smith bent over row","bp":"back","eq":"smith machine","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Set up the smith machine with the bar at hip height.","Stand facing the bar with your feet shoulder-width apart.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Pull the bar towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1359-ZX9UZmj.jpg","gif":"1359-ZX9UZmj.gif"},{"id":"0750","n":"smith chair squat","bp":"upper legs","eq":"smith machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Adjust the height of the smith machine bar to a comfortable position.","Stand with your feet shoulder-width apart, toes slightly turned out.","Place the barbell across your upper back, resting it on your traps.","Engage your core and keep your chest up as you slowly lower your body by bending your knees and hips.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"0750-Gu2rNJd.jpg","gif":"0750-Gu2rNJd.gif"},{"id":"0751","n":"smith close-grip bench press","bp":"upper arms","eq":"smith machine","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Adjust the seat height and position yourself on the bench with your feet flat on the ground.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Lower the barbell towards your chest, keeping your elbows close to your body.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0751-WcHl7ru.jpg","gif":"0751-WcHl7ru.gif"},{"id":"0752","n":"smith deadlift","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","lower back"],"st":["Set up the smith machine with the bar at hip height.","Stand with your feet shoulder-width apart, toes pointing slightly outward.","Bend at the hips and knees, keeping your back straight and chest up, and grip the bar with an overhand grip slightly wider than shoulder-width apart.","Engage your core and lift the bar by extending your hips and knees, keeping the bar close to your body.","Stand up straight, fully extending your hips and knees.","Lower the bar back down by bending at the hips and knees, maintaining control and keeping your back straight.","Repeat for the desired number of repetitions."],"img":"0752-UfePqpx.jpg","gif":"0752-UfePqpx.gif"},{"id":"0753","n":"smith decline bench press","bp":"chest","eq":"smith machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Adjust the decline bench to the desired angle.","Lie down on the bench with your feet secured under the foot pads.","Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0753-ETZfAbZ.jpg","gif":"0753-ETZfAbZ.gif"},{"id":"0754","n":"smith decline reverse-grip press","bp":"chest","eq":"smith machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Adjust the smith machine to a decline position.","Lie down on the bench with your feet secured under the foot pads.","Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.","Unrack the barbell and lower it towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0754-MY9P1WA.jpg","gif":"0754-MY9P1WA.gif"},{"id":"1433","n":"smith front squat (clean grip)","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Set up the smith machine with the barbell at shoulder height.","Stand facing the barbell with your feet shoulder-width apart.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Step back and position the barbell on your front shoulders, resting it on your collarbone and deltoids.","Keep your chest up, back straight, and core engaged.","Lower your body by bending at the knees and hips, as if sitting back into a chair.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"1433-lFhb2Rw.jpg","gif":"1433-lFhb2Rw.gif"},{"id":"3281","n":"smith full squat","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Set up the smith machine with the barbell at shoulder height.","Stand with your feet shoulder-width apart, toes slightly turned out.","Step under the bar and position it across your upper back, resting on your traps.","Grip the bar with your hands slightly wider than shoulder-width apart.","Unrack the bar and take a step back, maintaining a stable stance.","Keeping your chest up and core engaged, initiate the squat by pushing your hips back and bending your knees.","Lower your body until your thighs are parallel to the ground, or as low as your flexibility allows.","Pause for a moment at the bottom, then drive through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"3281-NNoHCEA.jpg","gif":"3281-NNoHCEA.gif"},{"id":"0755","n":"smith hack squat","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Adjust the barbell on the smith machine to an appropriate height for your body.","Stand with your feet shoulder-width apart, toes slightly pointed outwards.","Position yourself under the barbell, resting it on your upper traps and shoulders.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Engage your core and keep your chest up as you unrack the barbell.","Take a step back and position your feet slightly wider than shoulder-width apart.","Bend your knees and lower your body down, keeping your chest up and back straight.","Continue descending until your thighs are parallel to the ground or slightly below.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"0755-ZuPXtCK.jpg","gif":"0755-ZuPXtCK.gif"},{"id":"0756","n":"smith hip raise","bp":"waist","eq":"smith machine","tg":"abs","mg":"glutes","sm":["glutes","hamstrings"],"st":["Position yourself on the smith machine with your back against the pad and your feet shoulder-width apart.","Place your hands on the barbell, slightly wider than shoulder-width apart.","Engage your core and glutes, then push through your heels to raise your hips off the ground.","Continue lifting until your body forms a straight line from your knees to your shoulders.","Hold for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0756-CqhoytW.jpg","gif":"0756-CqhoytW.gif"},{"id":"0757","n":"smith incline bench press","bp":"chest","eq":"smith machine","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Adjust the bench to a 30-45 degree incline.","Sit on the bench with your back flat against the pad and feet firmly on the ground.","Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your upper chest, keeping your elbows slightly tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"0757-5v7KYld.jpg","gif":"0757-5v7KYld.gif"},{"id":"0758","n":"smith incline reverse-grip press","bp":"chest","eq":"smith machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Adjust the seat of the smith machine to a comfortable incline angle.","Sit on the machine with your back against the pad and your feet flat on the ground.","Grasp the bar with an overhand grip that is slightly wider than shoulder-width apart.","Unrack the bar and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment when the bar is just above your chest.","Push the bar back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"0758-78VqWQK.jpg","gif":"0758-78VqWQK.gif"},{"id":"0759","n":"smith incline shoulder raises","bp":"chest","eq":"smith machine","tg":"serratus anterior","mg":"deltoids","sm":["deltoids","trapezius"],"st":["Adjust the smith machine to an incline position.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and core engaged.","Raise the barbell up towards the ceiling, leading with your elbows.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0759-ayAHcEm.jpg","gif":"0759-ayAHcEm.gif"},{"id":"0760","n":"smith leg press","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Adjust the seat and footplate of the smith machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Grasp the handles or sides of the machine for stability.","Push the footplate away from you by extending your legs, keeping your back against the backrest.","Pause for a moment at the fully extended position.","Slowly bend your knees and lower the footplate back towards you, returning to the starting position.","Repeat for the desired number of repetitions."],"img":"0760-7zdxRTl.jpg","gif":"0760-7zdxRTl.gif"},{"id":"1434","n":"smith low bar squat","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Set up the smith machine with the barbell at a height that allows you to comfortably rest it on your upper back.","Stand with your feet shoulder-width apart, toes slightly turned outwards.","Step under the bar and position it across your upper back, resting it on your traps.","Grip the bar with your hands slightly wider than shoulder-width apart.","Unrack the bar by straightening your legs and stepping back from the rack.","Take a deep breath and brace your core.","Initiate the squat by pushing your hips back and bending your knees.","Lower your body until your thighs are parallel to the ground or slightly below.","Keep your chest up and your back straight throughout the movement.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."],"img":"1434-RGLscZM.jpg","gif":"1434-RGLscZM.gif"},{"id":"1683","n":"smith machine bicep curl","bp":"upper arms","eq":"smith machine","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Adjust the height of the smith machine bar to be at waist level.","Stand facing the smith machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, hands slightly wider than shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and curl the bar up towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1683-zILLZ98.jpg","gif":"1683-zILLZ98.gif"},{"id":"1625","n":"smith machine decline close grip bench press","bp":"upper arms","eq":"smith machine","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Adjust the bench on the smith machine to a decline position.","Lie down on the bench with your feet firmly planted on the ground.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell is just above your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"1625-yB9SvIF.jpg","gif":"1625-yB9SvIF.gif"},{"id":"1752","n":"smith machine incline tricep extension","bp":"upper arms","eq":"smith machine","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Adjust the seat of the smith machine so that the bar is at shoulder height.","Sit on the bench with your back against the pad and your feet flat on the ground.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Extend your arms fully, lifting the bar off the rack and holding it directly above your chest.","Lower the bar slowly towards your forehead, keeping your elbows close to your head.","Pause for a moment at the bottom, then push the bar back up to the starting position.","Repeat for the desired number of repetitions."],"img":"1752-o8aOcrz.jpg","gif":"1752-o8aOcrz.gif"},{"id":"1626","n":"smith machine reverse decline close grip bench press","bp":"chest","eq":"smith machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Adjust the smith machine to a decline position.","Lie down on the bench with your feet secured under the foot pads.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."],"img":"1626-QyO6Uma.jpg","gif":"1626-QyO6Uma.gif"},{"id":"0761","n":"smith narrow row","bp":"back","eq":"smith machine","tg":"upper back","mg":"biceps","sm":["biceps","rear deltoids"],"st":["Adjust the seat height and position yourself on the machine with your feet flat on the floor.","Grasp the handles with an overhand grip, slightly narrower than shoulder-width apart.","Keep your back straight and your chest up as you pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."],"img":"0761-JGKowMS.jpg","gif":"0761-JGKowMS.gif"},{"id":"1360","n":"smith one arm row","bp":"back","eq":"smith machine","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Adjust the height of the smith machine bar to waist level.","Stand facing the smith machine with your feet shoulder-width apart.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Grasp the bar with one hand using an overhand grip, with your palm facing down.","Keep your elbow close to your body and pull the bar towards your waist, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly lower the bar back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"img":"1360-Q4DSJPC.jpg","gif":"1360-Q4DSJPC.gif"},{"id":"1393","n":"smith one leg floor calf raise","bp":"lower legs","eq":"smith machine","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Position yourself on the floor under the smith machine bar, facing away from the machine.","Place the balls of your feet on a raised surface, such as a weight plate or block.","Position the smith machine bar across your lower legs, just above your ankles.","Hold onto the bar with your hands for stability.","Raise your heels off the ground by extending your ankles, lifting your body up.","Pause at the top of the movement, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1393-9GXrTE6.jpg","gif":"1393-9GXrTE6.gif"},{"id":"0762","n":"smith rear delt row","bp":"shoulders","eq":"smith machine","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids","biceps"],"st":["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the ground.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and your core engaged as you pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."],"img":"0762-nFUwqG6.jpg","gif":"0762-nFUwqG6.gif"},{"id":"0763","n":"smith reverse calf raises","bp":"lower legs","eq":"smith machine","tg":"calves","mg":"hamstrings","sm":["hamstrings"],"st":["Adjust the smith machine bar to a height just below your shoulders.","Stand facing the bar with your feet hip-width apart and toes pointing forward.","Place the balls of your feet on the edge of a step or platform, with your heels hanging off.","Hold onto the bar for support, keeping your back straight and core engaged.","Raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0763-ywaNfuh.jpg","gif":"0763-ywaNfuh.gif"},{"id":"1394","n":"smith reverse calf raises","bp":"lower legs","eq":"smith machine","tg":"calves","mg":"hamstrings","sm":["hamstrings"],"st":["Adjust the smith machine bar to a height just below your shoulders.","Stand facing the bar with your feet hip-width apart and toes pointing forward.","Place the balls of your feet on the edge of a step or platform, with your heels hanging off.","Hold onto the bar for support.","Raise your heels as high as possible, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1394-Lsqrgh4.jpg","gif":"1394-Lsqrgh4.gif"},{"id":"1361","n":"smith reverse grip bent over row","bp":"back","eq":"smith machine","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Set up the smith machine with the bar at hip height.","Stand facing the bar with your feet shoulder-width apart.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Pull the bar towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1361-aaxA3cm.jpg","gif":"1361-aaxA3cm.gif"},{"id":"0764","n":"smith reverse-grip press","bp":"chest","eq":"smith machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Adjust the height of the smith machine bar to chest level.","Stand facing the bar with your feet shoulder-width apart.","Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Step back and position yourself with a slight bend in your knees.","Keep your chest up and core engaged throughout the exercise.","Lower the bar towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the bar back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0764-zK8Fu1W.jpg","gif":"0764-zK8Fu1W.gif"},{"id":"1395","n":"smith seated one leg calf raise","bp":"lower legs","eq":"smith machine","tg":"calves","mg":"hamstrings","sm":["hamstrings"],"st":["Sit on the machine with your back against the pad and your feet on the footrest.","Place one leg on the footrest and keep the other leg off the footrest.","Using your calf muscles, raise your heel as high as possible.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."],"img":"1395-0S75mYG.jpg","gif":"1395-0S75mYG.gif"},{"id":"0765","n":"smith seated shoulder press","bp":"shoulders","eq":"smith machine","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Adjust the seat height so that the handles are at shoulder level.","Sit on the machine with your back against the pad and your feet flat on the floor.","Grasp the handles with an overhand grip and lift them off the supports, extending your arms fully.","Lower the handles down to shoulder level, keeping your elbows slightly bent.","Press the handles up overhead until your arms are fully extended.","Pause for a moment at the top, then slowly lower the handles back down to shoulder level.","Repeat for the desired number of repetitions."],"img":"0765-xUwnBMT.jpg","gif":"0765-xUwnBMT.gif"},{"id":"1426","n":"smith seated wrist curl","bp":"lower arms","eq":"smith machine","tg":"forearms","mg":"biceps","sm":["biceps","brachialis"],"st":["Sit on a bench in front of a Smith machine with your feet flat on the ground.","Grasp the barbell with an underhand grip, hands shoulder-width apart.","Rest your forearms on your thighs, allowing your wrists to hang off.","Slowly curl your wrists upward, bringing the barbell towards your forearms.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1426-B6dAO1t.jpg","gif":"1426-B6dAO1t.gif"},{"id":"0766","n":"smith shoulder press","bp":"shoulders","eq":"smith machine","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Adjust the seat height and position yourself on the smith machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Lift the bar off the rack and position it at shoulder level, with your elbows bent and palms facing forward.","Press the bar upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the bar back down to shoulder level.","Repeat for the desired number of repetitions."],"img":"0766-903mzG8.jpg","gif":"0766-903mzG8.gif"},{"id":"0767","n":"smith shrug","bp":"back","eq":"smith machine","tg":"traps","mg":"shoulders","sm":["shoulders"],"st":["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your arms straight and your shoulders relaxed.","Lift your shoulders up towards your ears, squeezing your traps at the top.","Hold for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0767-OUQ0ZyW.jpg","gif":"0767-OUQ0ZyW.gif"},{"id":"0768","n":"smith single leg split squat","bp":"upper legs","eq":"smith machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings"],"st":["Stand in front of the smith machine with your feet shoulder-width apart.","Place one foot behind you on a bench or step, with your toes pointing forward.","Hold onto the smith machine bar for stability.","Bend your front knee and lower your body down into a lunge position, keeping your back straight.","Pause for a moment at the bottom, then push through your front heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"img":"0768-wWFspEi.jpg","gif":"0768-wWFspEi.gif"},{"id":"0769","n":"smith sprint lunge","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Set up the smith machine with the barbell at hip height.","Stand facing away from the machine with your feet shoulder-width apart.","Step back with your right foot and place it on the barbell, resting the top of your foot on the bar.","Bend your left knee and lower your body into a lunge position, keeping your back straight.","Push through your left heel to return to the starting position.","Repeat on the other side, stepping back with your left foot.","Continue alternating sides for the desired number of repetitions."],"img":"0769-HsjbB1z.jpg","gif":"0769-HsjbB1z.gif"},{"id":"0770","n":"smith squat","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Set up the smith machine with the barbell at an appropriate height for your squat.","Stand with your feet shoulder-width apart, toes slightly turned out.","Position yourself under the barbell, resting it on your upper traps and shoulders.","Grip the barbell with a wide grip, slightly wider than shoulder-width apart.","Engage your core and unrack the barbell, stepping back to clear the rack.","Keeping your chest up and back straight, initiate the squat by bending at the hips and knees.","Lower your body until your thighs are parallel to the ground or slightly below.","Pause for a moment at the bottom, then drive through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"0770-jFtipLl.jpg","gif":"0770-jFtipLl.gif"},{"id":"0771","n":"smith standing back wrist curl","bp":"lower arms","eq":"smith machine","tg":"forearms","mg":"biceps","sm":["biceps","triceps"],"st":["Stand facing the smith machine with your feet shoulder-width apart.","Grasp the barbell with an overhand grip, hands shoulder-width apart.","Keep your back straight and your elbows close to your body.","Slowly curl your wrists upwards, bringing the barbell towards your body.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0771-hfmQ0Tz.jpg","gif":"0771-hfmQ0Tz.gif"},{"id":"0772","n":"smith standing behind head military press","bp":"shoulders","eq":"smith machine","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Adjust the seat height of the smith machine so that the bar is at shoulder level.","Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Lift the bar off the rack and step back, maintaining a stable stance.","Position the bar behind your head, resting on your upper traps.","Keep your core engaged and your chest lifted throughout the exercise.","Press the bar overhead by extending your arms, fully straightening them.","Pause briefly at the top of the movement, then slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0772-ht8xDrP.jpg","gif":"0772-ht8xDrP.gif"},{"id":"0773","n":"smith standing leg calf raise","bp":"lower legs","eq":"smith machine","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Adjust the smith machine bar to a height that allows you to stand with your feet flat on the ground and your shoulders under the bar.","Position yourself under the bar with your feet shoulder-width apart and your toes pointing forward.","Place your hands on the bar for stability.","Engage your calves and slowly raise your heels off the ground, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0773-6MaEjVA.jpg","gif":"0773-6MaEjVA.gif"},{"id":"0774","n":"smith standing military press","bp":"shoulders","eq":"smith machine","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and bring it down to shoulder level, with your palms facing forward.","Press the barbell upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the barbell back down to shoulder level.","Repeat for the desired number of repetitions."],"img":"0774-jjUPrze.jpg","gif":"0774-jjUPrze.gif"},{"id":"3142","n":"smith sumo squat","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Set up the smith machine with the barbell at hip height.","Stand with your feet wider than shoulder-width apart, toes pointing outwards.","Position yourself under the barbell, resting it on your upper back and shoulders.","Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.","Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"3142-dzz6BiV.jpg","gif":"3142-dzz6BiV.gif"},{"id":"1396","n":"smith toe raise","bp":"lower legs","eq":"smith machine","tg":"calves","mg":"ankles","sm":["ankles","shins"],"st":["Adjust the smith machine bar to a height that allows you to comfortably stand with your feet flat on the ground.","Position yourself under the bar with your shoulders directly below it and your feet shoulder-width apart.","Place the balls of your feet on a raised platform or weight plates, with your heels hanging off the edge.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Engage your core and keep your back straight throughout the exercise.","Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1396-Y4QlY8z.jpg","gif":"1396-Y4QlY8z.gif"},{"id":"0775","n":"smith upright row","bp":"shoulders","eq":"smith machine","tg":"delts","mg":"traps","sm":["traps","biceps"],"st":["Stand with your feet shoulder-width apart, facing the smith machine.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your back straight and your core engaged.","Pull the barbell up towards your chin, leading with your elbows.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0775-1DN3iz4.jpg","gif":"0775-1DN3iz4.gif"},{"id":"1308","n":"smith wide grip bench press","bp":"chest","eq":"smith machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Adjust the bench to a comfortable position on the smith machine.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows out to the sides.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"1308-zoOvPcx.jpg","gif":"1308-zoOvPcx.gif"},{"id":"1309","n":"smith wide grip decline bench press","bp":"chest","eq":"smith machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Adjust the decline bench to the desired angle.","Lie down on the bench with your feet secured under the foot pads.","Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows pointed outwards.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"1309-wi2H9QX.jpg","gif":"1309-wi2H9QX.gif"},{"id":"0776","n":"snatch pull","bp":"upper legs","eq":"barbell","tg":"quads","mg":"hamstrings","sm":["hamstrings","glutes","calves"],"st":["Stand with your feet shoulder-width apart and the barbell on the ground in front of you.","Bend your knees and hinge at the hips to lower into a squat position, gripping the barbell with an overhand grip.","Keep your back straight and chest up as you drive through your heels to lift the barbell off the ground, extending your hips and knees.","As the barbell reaches hip level, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides.","As the barbell reaches its highest point, quickly drop underneath it, pulling yourself into a deep squat position.","Catch the barbell overhead with your arms fully extended and your knees bent.","Stand up by extending your hips and knees, keeping the barbell overhead.","Lower the barbell back down to the starting position by reversing the movement.","Repeat for the desired number of repetitions."],"img":"0776-dG5Smob.jpg","gif":"0776-dG5Smob.gif"},{"id":"0777","n":"spell caster","bp":"waist","eq":"dumbbell","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Stand with your feet shoulder-width apart and hold a dumbbell in one hand.","Bend your knees slightly and hinge forward at the waist, keeping your back straight.","Extend your arm with the dumbbell towards the opposite foot, rotating your torso as you do so.","Return to the starting position and repeat on the other side.","Continue alternating sides for the desired number of repetitions."],"img":"0777-p9cCe2r.jpg","gif":"0777-p9cCe2r.gif"},{"id":"1362","n":"sphinx","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Lie face down on the ground with your forearms flat on the floor, elbows directly under your shoulders.","Engage your core and lift your chest off the ground, keeping your forearms and toes on the floor.","Hold this position for a few seconds, making sure to keep your neck in a neutral position.","Slowly lower your chest back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1362-DIVyqrU.jpg","gif":"1362-DIVyqrU.gif"},{"id":"0778","n":"spider crawl push up","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"core","sm":["core","chest","shoulders"],"st":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Bring your right knee towards your right elbow, keeping it off the ground.","As you bring your right knee back, simultaneously lower your body towards the ground by bending your elbows.","Push back up to the starting position and repeat with your left knee towards your left elbow.","Continue alternating sides for the desired number of repetitions."],"img":"0778-P9GFBME.jpg","gif":"0778-P9GFBME.gif"},{"id":"1363","n":"spine stretch","bp":"back","eq":"body weight","tg":"spine","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Sit on the ground with your legs extended in front of you.","Place your hands on the ground behind you, fingers pointing towards your body.","Engage your core and slowly lean back, keeping your back straight.","Continue leaning back until you feel a stretch in your spine.","Hold the stretch for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"1363-JbC2iaV.jpg","gif":"1363-JbC2iaV.gif","ty":"stretch","kind":"time"},{"id":"2329","n":"spine twist","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Sit on the ground with your legs extended in front of you.","Bend your knees and place your feet flat on the ground, hip-width apart.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and slowly twist your torso to the right, bringing your right elbow towards your left knee.","Pause for a moment at the end of the twist, then slowly return to the starting position.","Repeat the twist to the left side, bringing your left elbow towards your right knee.","Continue alternating sides for the desired number of repetitions."],"img":"2329-2jl9K55.jpg","gif":"2329-2jl9K55.gif"},{"id":"2368","n":"split squats","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart.","Take a step forward with one foot and place it about two feet in front of the other foot.","Lower your body by bending your knees and hips, keeping your back straight.","Continue lowering until your front thigh is parallel to the ground, and your back knee is hovering just above the ground.","Pause for a moment, then push through your front heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."],"img":"2368-9E25EOx.jpg","gif":"2368-9E25EOx.gif"},{"id":"0786","n":"squat jerk","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","core"],"st":["Start with the barbell resting on your shoulders, with your feet shoulder-width apart.","Lower your body into a squat position, keeping your chest up and your knees tracking over your toes.","As you reach the bottom of the squat, explosively drive through your legs and push the barbell overhead.","As the barbell reaches its peak, quickly drop into a split position, with one foot forward and one foot back.","Catch the barbell overhead with your arms fully extended and your back knee slightly touching the ground.","Stand up from the split position, bringing your feet back together.","Lower the barbell back to your shoulders and repeat for the desired number of repetitions."],"img":"0786-IMRsOCn.jpg","gif":"0786-IMRsOCn.gif"},{"id":"1705","n":"squat on bosu ball","bp":"upper legs","eq":"bosu ball","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Place the bosu ball on the ground with the flat side up.","Stand with your feet shoulder-width apart and position yourself on top of the bosu ball.","Lower your body down by bending your knees and hips, as if sitting back into a chair.","Keep your chest up and your weight on your heels.","Lower yourself until your thighs are parallel to the ground.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"1705-T2fA5Ir.jpg","gif":"1705-T2fA5Ir.gif"},{"id":"1685","n":"squat to overhead reach","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Stand with your feet shoulder-width apart and toes slightly turned out.","Lower your body down into a squat position by bending your knees and pushing your hips back.","As you come up from the squat, extend your arms overhead, reaching towards the ceiling.","Return to the starting position by lowering your arms and bending your knees to squat down again.","Repeat for the desired number of repetitions."],"img":"1685-QChZi3x.jpg","gif":"1685-QChZi3x.gif"},{"id":"1686","n":"squat to overhead reach with twist","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Stand with your feet shoulder-width apart and toes slightly turned out.","Lower your body into a squat position by bending your knees and pushing your hips back.","As you come up from the squat, raise your arms overhead and twist your torso to one side.","Return to the starting position and repeat the squat, this time twisting your torso to the opposite side.","Continue alternating sides with each squat repetition."],"img":"1686-5BZHW9s.jpg","gif":"1686-5BZHW9s.gif"},{"id":"2297","n":"stability ball crunch (full range hands behind head)","bp":"waist","eq":"stability ball","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly curl your upper body forward, bringing your chest towards your knees.","Pause for a moment at the top, then slowly lower your upper body back to the starting position.","Repeat for the desired number of repetitions."],"img":"2297-Gn5FwYT.jpg","gif":"2297-Gn5FwYT.gif"},{"id":"3291","n":"stalder press","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Start by standing with your feet shoulder-width apart and your arms extended overhead.","Bend your knees slightly and engage your core.","Lower your body down into a squat position while keeping your arms extended overhead.","As you squat down, press your arms down towards the ground, engaging your triceps.","Pause for a moment at the bottom of the squat, then push through your heels to stand back up while simultaneously raising your arms back overhead.","Repeat for the desired number of repetitions."],"img":"3291-zd4P4B2.jpg","gif":"3291-zd4P4B2.gif"},{"id":"3669","n":"standing archer","bp":"back","eq":"body weight","tg":"upper back","mg":"shoulders","sm":["shoulders","biceps","forearms"],"st":["Stand with your feet shoulder-width apart and your knees slightly bent.","Extend your arms straight out in front of you at shoulder height, parallel to the ground.","Rotate your torso to the right, keeping your arms extended and your back straight.","As you rotate, extend your right arm forward and your left arm back, mimicking the motion of drawing a bowstring.","Hold the position for a moment, then return to the starting position.","Repeat the motion, this time rotating your torso to the left and extending your left arm forward and your right arm back.","Continue alternating sides for the desired number of repetitions."],"img":"3669-JF8AkMX.jpg","gif":"3669-JF8AkMX.gif"},{"id":"0788","n":"standing behind neck press","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Stand with your feet shoulder-width apart and hold the barbell behind your neck with an overhand grip.","Keep your back straight and core engaged.","Press the barbell overhead by extending your arms, fully extending your elbows.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0788-xDh0lJr.jpg","gif":"0788-xDh0lJr.gif"},{"id":"1490","n":"standing calf raise (on a staircase)","bp":"lower legs","eq":"body weight","tg":"calves","mg":"ankles","sm":["ankles","feet"],"st":["Stand on the edge of a step or a sturdy platform with your heels hanging off and your toes on the step.","Hold onto a railing or wall for balance if needed.","Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1490-6HmFgmx.jpg","gif":"1490-6HmFgmx.gif"},{"id":"1397","n":"standing calves","bp":"lower legs","eq":"body weight","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Stand with your feet shoulder-width apart, toes pointing forward.","Raise your heels off the ground as high as possible, standing on your toes.","Hold the position for a moment, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1397-XIHEoCG.jpg","gif":"1397-XIHEoCG.gif"},{"id":"1398","n":"standing calves calf stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Stand facing a wall or sturdy object, about an arm's length away.","Place your hands on the wall or object at shoulder height.","Step back with one foot, keeping your heel flat on the ground.","Bend your front knee slightly and lean forward, keeping your back leg straight.","You should feel a stretch in your calf muscle.","Hold the stretch for 20-30 seconds.","Repeat on the other leg."],"img":"1398-qOKcgVP.jpg","gif":"1398-qOKcgVP.gif","ty":"stretch","kind":"time"},{"id":"1599","n":"standing hamstring and calf stretch with strap","bp":"upper legs","eq":"rope","tg":"hamstrings","mg":"calves","sm":["calves"],"st":["Stand upright with your feet shoulder-width apart.","Hold the strap with both hands and place it around the ball of your foot.","Keep your leg straight and slowly lean forward from your hips, keeping your back straight.","Feel the stretch in your hamstring and calf muscles.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat with the other leg.","Repeat for the desired number of repetitions."],"img":"1599-xTjr103.jpg","gif":"1599-xTjr103.gif","ty":"stretch","kind":"time"},{"id":"0794","n":"standing lateral stretch","bp":"back","eq":"body weight","tg":"lats","mg":"shoulders","sm":["shoulders","obliques"],"st":["Stand with your feet shoulder-width apart and your knees slightly bent.","Extend your arms straight out to the sides, parallel to the ground.","Slowly lean your upper body to one side, feeling a stretch in your side and lats.","Hold the stretch for 15-30 seconds.","Return to the starting position and repeat on the other side.","Repeat for the desired number of repetitions."],"img":"0794-1jXLYEw.jpg","gif":"0794-1jXLYEw.gif","ty":"stretch","kind":"time"},{"id":"1364","n":"standing pelvic tilt","bp":"back","eq":"body weight","tg":"spine","mg":"abdominals","sm":["abdominals"],"st":["Stand with your feet shoulder-width apart and your knees slightly bent.","Place your hands on your hips or let them hang by your sides.","Engage your core muscles and tilt your pelvis forward, pushing your lower back towards the wall behind you.","Hold the position for a few seconds, then release and return to the starting position.","Repeat for the desired number of repetitions."],"img":"1364-cuKYxhu.jpg","gif":"1364-cuKYxhu.gif"},{"id":"0795","n":"standing single leg curl","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes"],"st":["Stand with your feet hip-width apart and your hands on your hips.","Shift your weight onto your left leg and lift your right foot off the ground, bending your knee.","Slowly curl your right heel towards your glutes, squeezing your hamstring.","Pause for a moment at the top, then slowly lower your right foot back down to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"img":"0795-C5jncD2.jpg","gif":"0795-C5jncD2.gif"},{"id":"0796","n":"standing wheel rollerout","bp":"waist","eq":"wheel roller","tg":"abs","mg":"lower back","sm":["lower back","shoulders"],"st":["Start by standing tall with your feet shoulder-width apart and the wheel roller in front of you.","Bend at your waist and slowly roll the wheel forward, keeping your back straight and your core engaged.","Continue rolling forward until you feel a stretch in your abs and your body is extended as far as possible.","Pause for a moment, then slowly roll the wheel back towards your body, returning to the starting position.","Repeat for the desired number of repetitions."],"img":"0796-KtRomty.jpg","gif":"0796-KtRomty.gif"},{"id":"3223","n":"star jump (male)","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart and your arms by your sides.","Bend your knees slightly and jump up explosively.","As you jump, spread your legs and extend your arms out to the sides, forming a star shape with your body.","Land softly on the balls of your feet with your knees slightly bent.","Repeat for the desired number of repetitions."],"img":"3223-HtfCpfi.jpg","gif":"3223-HtfCpfi.gif","ty":"atl"},{"id":"2138","n":"stationary bike run v. 3","bp":"cardio","eq":"stationary bike","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Adjust the seat height and position to ensure proper alignment.","Place your feet on the pedals and secure them with the straps if available.","Start pedaling at a comfortable pace.","Maintain a steady rhythm and increase the resistance as desired.","Engage your core muscles to maintain stability and proper posture.","Continue pedaling for the desired duration of your workout.","Gradually decrease the resistance and slow down before coming to a complete stop.","Stretch your legs and cool down after the workout."],"img":"2138-H1PESYI.jpg","gif":"2138-H1PESYI.gif"},{"id":"0798","n":"stationary bike walk","bp":"cardio","eq":"leverage machine","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Adjust the seat height and position on the stationary bike to ensure proper alignment.","Place your feet on the pedals and secure them with the straps if available.","Start pedaling at a comfortable pace, keeping your back straight and core engaged.","Maintain a steady rhythm and increase the resistance level if desired.","Continue pedaling for the desired duration of your cardio workout.","Cool down by gradually reducing your pace and resistance level.","Stretch your leg muscles after the workout to prevent tightness and promote recovery."],"img":"0798-a8VDgLw.jpg","gif":"0798-a8VDgLw.gif"},{"id":"3314","n":"straddle maltese","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","chest"],"st":["Start by hanging from a pair of rings with your arms fully extended and your body in a straight line.","Spread your legs wide apart, forming a straddle position.","Engage your core and slowly lower your body until your arms are parallel to the ground.","Hold this position for a few seconds, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"img":"3314-HfqciZF.jpg","gif":"3314-HfqciZF.gif"},{"id":"3298","n":"straddle planche","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","triceps","chest"],"st":["Start in a push-up position with your hands shoulder-width apart and your feet spread wide apart.","Engage your core and slowly shift your weight forward, bringing your shoulders over your hands.","Bend your elbows and lower your body towards the ground, keeping your elbows close to your sides.","Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position.","Repeat for the desired number of repetitions."],"img":"3298-BL3GHeY.jpg","gif":"3298-BL3GHeY.gif"},{"id":"1427","n":"straight leg outer hip abductor","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","hamstrings"],"st":["Lie on your side with your legs straight and stacked on top of each other.","Place your bottom arm under your head for support.","Engage your core and lift your top leg as high as possible without rotating your hips or leaning backward.","Pause for a moment at the top, then slowly lower your leg back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"1427-mQ1tBXn.jpg","gif":"1427-mQ1tBXn.gif"},{"id":"0803","n":"superman push-up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"core","sm":["core","shoulders"],"st":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.","Engage your core and lower your body towards the ground, keeping your elbows close to your sides.","As you lower your body, simultaneously lift your right arm and left leg off the ground, extending them straight out.","Pause for a moment at the top, then lower your arm and leg back down while pushing yourself back up to the starting position.","Repeat the movement, this time lifting your left arm and right leg.","Continue alternating sides for the desired number of repetitions."],"img":"0803-4GqRrAk.jpg","gif":"0803-4GqRrAk.gif"},{"id":"0805","n":"suspended abdominal fallout","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Attach a suspension trainer to a high anchor point and adjust the straps to waist height.","Stand facing away from the anchor point and hold the handles with your arms extended in front of you.","Lean forward at the waist, keeping your body straight and your core engaged.","Lower your body as far as you can while maintaining control and tension in your abs.","Pause for a moment at the bottom, then slowly raise your body back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0805-X3TCNEU.jpg","gif":"0805-X3TCNEU.gif"},{"id":"0806","n":"suspended push-up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Find a suspension trainer and adjust it to an appropriate height.","Stand facing away from the anchor point and hold the handles with an overhand grip.","Walk your feet forward, leaning your body forward until your weight is supported by the suspension trainer.","Keep your body straight from head to heels, engage your core, and lower your chest towards the handles.","Push through your chest and arms to return to the starting position.","Repeat for the desired number of repetitions."],"img":"0806-IaGQCrC.jpg","gif":"0806-IaGQCrC.gif"},{"id":"0807","n":"suspended reverse crunch","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your knees up towards your chest, curling your pelvis towards your ribcage.","Pause for a moment at the top, then slowly lower your knees back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0807-R1WYG5D.jpg","gif":"0807-R1WYG5D.gif"},{"id":"0808","n":"suspended row","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Set up a suspension trainer at an appropriate height.","Stand facing the anchor point with your feet shoulder-width apart.","Hold the handles with an overhand grip, palms facing each other.","Lean back, keeping your body straight and your heels on the ground.","Pull your chest towards the handles, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower yourself back to the starting position.","Repeat for the desired number of repetitions."],"img":"0808-4OaumBr.jpg","gif":"0808-4OaumBr.gif"},{"id":"0809","n":"suspended split squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand facing away from a suspension trainer with your feet shoulder-width apart.","Extend one leg forward and place the top of your foot in the foot cradle of the suspension trainer.","Bend your standing leg and lower your body down into a lunge position, keeping your chest up and your knee in line with your toes.","Push through your heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"img":"0809-QpXqiq8.jpg","gif":"0809-QpXqiq8.gif"},{"id":"3433","n":"swimmer kicks v. 2 (male)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","calves"],"st":["Lie face down on a mat with your arms extended overhead.","Engage your core and lift your chest and legs off the ground simultaneously.","Kick your legs up and down in a fluttering motion, as if you were swimming.","Continue kicking for the desired number of repetitions.","Lower your chest and legs back down to the starting position."],"img":"3433-SP3hUez.jpg","gif":"3433-SP3hUez.gif"},{"id":"3318","n":"swing 360","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"shoulders","sm":["shoulders","core"],"st":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold your arms straight out in front of you, parallel to the ground.","Engage your core and swing your arms in a circular motion, rotating your torso as you do so.","Continue the circular motion, swinging your arms and rotating your torso for the desired number of repetitions.","Remember to breathe throughout the exercise."],"img":"3318-tnaj0mT.jpg","gif":"3318-tnaj0mT.gif"},{"id":"1753","n":"three bench dip","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Sit on a bench with your hands gripping the edge, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Bend your elbows and lower your body until your upper arms are parallel to the ground.","Push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"img":"1753-DQ0cqkT.jpg","gif":"1753-DQ0cqkT.gif"},{"id":"2459","n":"tire flip","bp":"upper legs","eq":"tire","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","core"],"st":["Stand with your feet shoulder-width apart, facing the tire.","Bend your knees and hinge at the hips, lowering into a squat position.","Reach down and grab the bottom edge of the tire with both hands, fingers facing towards you.","Engage your glutes and leg muscles, and explosively drive through your legs to lift the tire off the ground.","As the tire flips over, use your upper body strength to guide it and maintain control.","Once the tire is fully flipped, quickly step back and reset your stance.","Repeat for the desired number of repetitions."],"img":"2459-oZjMu1t.jpg","gif":"2459-oZjMu1t.gif"},{"id":"0811","n":"trap bar deadlift","bp":"upper legs","eq":"trap bar","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","lower back"],"st":["Stand with your feet shoulder-width apart and the trap bar on the ground in front of you.","Bend at the hips and knees to lower yourself down and grip the handles of the trap bar with an overhand grip.","Keep your back straight and chest up as you begin to lift the trap bar off the ground by extending your hips and knees.","As you lift, focus on driving through your heels and squeezing your glutes at the top of the movement.","Lower the trap bar back down to the ground by bending at the hips and knees, keeping your back straight throughout the movement.","Repeat for the desired number of repetitions."],"img":"0811-jQGwmxN.jpg","gif":"0811-jQGwmxN.gif"},{"id":"0814","n":"triceps dip","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0814-X6C6i5Y.jpg","gif":"0814-X6C6i5Y.gif"},{"id":"0812","n":"triceps dip (bench leg)","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward.","Walk your feet forward, sliding your butt off the bench, and straighten your arms.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."],"img":"0812-VuoerH0.jpg","gif":"0812-VuoerH0.gif"},{"id":"0813","n":"triceps dip (between benches)","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Sit on a bench with your hands gripping the edge of the bench, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0813-Wgbn9qo.jpg","gif":"0813-Wgbn9qo.gif"},{"id":"0815","n":"triceps dips floor","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Sit on the edge of a chair or bench with your hands next to your hips, fingers pointing forward.","Slide your butt off the front of the chair with your legs extended in front of you.","Straighten your arms, keeping a little bend in your elbows to keep tension on your triceps and off your elbow joints.","Slowly bend your elbows to lower your body toward the floor until your elbows are at about a 90-degree angle.","Once you reach the bottom of the movement, press down into the chair to straighten your elbows, returning to the starting position.","Repeat for the desired number of repetitions."],"img":"0815-7aVz15j.jpg","gif":"0815-7aVz15j.gif"},{"id":"0816","n":"triceps press","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Stand with your feet shoulder-width apart and your knees slightly bent.","Extend your arms straight out in front of you, parallel to the ground.","Bend your elbows and lower your body towards the ground, keeping your upper arms close to your sides.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"img":"0816-fSrPP6B.jpg","gif":"0816-fSrPP6B.gif"},{"id":"0817","n":"triceps stretch","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Stand or sit upright with your back straight.","Extend one arm overhead, bending it at the elbow.","Place your opposite hand on the bent elbow and gently pull it towards your head.","Hold the stretch for 15-30 seconds, feeling a gentle stretch in your triceps.","Release the stretch and repeat on the other arm."],"img":"0817-uOV3Itw.jpg","gif":"0817-uOV3Itw.gif","ty":"stretch","kind":"time"},{"id":"0871","n":"tuck crunch","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your shoulder blades off the ground and bring your knees towards your chest, simultaneously curling your upper body towards your knees.","Pause for a moment at the top, then slowly lower your shoulder blades and extend your legs back to the starting position.","Repeat for the desired number of repetitions."],"img":"0871-BMMolZ3.jpg","gif":"0871-BMMolZ3.gif"},{"id":"0818","n":"twin handle parallel grip lat pulldown","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Adjust the seat height and position yourself facing the cable machine.","Grasp the handles with an overhand grip, hands shoulder-width apart.","Sit down and position your thighs under the thigh pads, keeping your feet flat on the floor.","Lean back slightly and keep your chest up, maintaining a neutral spine.","Pull the handles down towards your upper chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, feeling the contraction in your lats.","Slowly release the handles and return to the starting position.","Repeat for the desired number of repetitions."],"img":"0818-rkg41Fb.jpg","gif":"0818-rkg41Fb.gif"},{"id":"1466","n":"twist hip lift","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"obliques","sm":["obliques","hamstrings"],"st":["Lie on your back with your knees bent and feet flat on the ground.","Place your hands by your sides for support.","Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.","While keeping your hips lifted, twist your lower body to the right side, bringing your knees towards the ground.","Return to the starting position and repeat the twist to the left side.","Continue alternating twists for the desired number of repetitions."],"img":"1466-AX1kB0o.jpg","gif":"1466-AX1kB0o.gif"},{"id":"2802","n":"twisted leg raise","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your abs and lift both legs off the ground, keeping them straight.","As you lift your legs, twist your hips to one side, bringing your legs towards your opposite shoulder.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat the movement, this time twisting your hips to the other side.","Continue alternating sides for the desired number of repetitions."],"img":"2802-C0eCeEt.jpg","gif":"2802-C0eCeEt.gif"},{"id":"2801","n":"twisted leg raise (female)","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Lie flat on your back with your legs extended and your arms by your sides.","Bend your knees and lift your legs off the ground, bringing them towards your chest.","As you lift your legs, twist your hips to one side, bringing your knees towards your opposite shoulder.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat the movement, this time twisting your hips to the other side.","Continue alternating sides for the desired number of repetitions."],"img":"2801-yT9tk17.jpg","gif":"2801-yT9tk17.gif"},{"id":"3231","n":"two toe touch (male)","bp":"back","eq":"body weight","tg":"spine","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Stand with your feet shoulder-width apart and your arms extended out to the sides.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Reach down towards your toes with both hands, keeping your legs straight.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"img":"3231-p195zsJ.jpg","gif":"3231-p195zsJ.gif"},{"id":"1365","n":"upper back stretch","bp":"back","eq":"body weight","tg":"upper back","mg":"shoulders","sm":["shoulders"],"st":["Stand up straight with your feet shoulder-width apart.","Extend your arms straight in front of you, parallel to the ground.","Interlace your fingers and rotate your palms away from your body.","Slowly raise your arms overhead, keeping them straight and parallel to each other.","As you raise your arms, squeeze your shoulder blades together.","Hold the stretch for 15-30 seconds, then release and repeat."],"img":"1365-GSDioYu.jpg","gif":"1365-GSDioYu.gif","ty":"stretch","kind":"time"},{"id":"1366","n":"upward facing dog","bp":"back","eq":"body weight","tg":"spine","mg":"shoulders","sm":["shoulders","chest"],"st":["Lie face down on the floor with your legs extended behind you.","Place your hands on the floor next to your lower ribs, fingers pointing forward.","Press your hands firmly into the floor and straighten your arms, lifting your torso and thighs off the ground.","Roll your shoulders back and down, opening your chest and lifting your gaze towards the ceiling.","Hold this position for a few breaths, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1366-01qpYSe.jpg","gif":"1366-01qpYSe.gif"},{"id":"3420","n":"v-sit on floor","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Sit on the floor with your legs extended in front of you.","Lean back slightly and lift your legs off the ground, keeping them straight.","Simultaneously, lift your upper body off the ground and reach your arms towards your legs.","Hold this position for a few seconds, then slowly lower your upper body and legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"3420-ZuXu4Eq.jpg","gif":"3420-ZuXu4Eq.gif"},{"id":"0826","n":"vertical leg raise (on parallel bars)","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Hang from the parallel bars with your arms fully extended and your body straight.","Engage your core and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or slightly higher.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0826-ZNgOYQU.jpg","gif":"0826-ZNgOYQU.gif"},{"id":"2141","n":"walk elliptical cross trainer","bp":"cardio","eq":"elliptical machine","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","glutes","calves"],"st":["Adjust the resistance level and incline of the elliptical machine to your desired settings.","Step onto the pedals of the machine and grip the handles lightly.","Begin by pushing down with your feet and pulling the handles towards your body.","Continue this motion, alternating between pushing and pulling, to simulate a walking or running motion.","Maintain a steady pace and keep your core engaged throughout the exercise.","Continue for the desired duration of your cardio workout.","Gradually decrease the intensity and speed of the machine before stepping off."],"img":"2141-rjtuP6X.jpg","gif":"2141-rjtuP6X.gif"},{"id":"3655","n":"walking high knees lunge","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","glutes","calves"],"st":["Stand with your feet hip-width apart.","Lift your right knee up towards your chest as high as you can while balancing on your left leg.","Step forward with your right foot and lower your body into a lunge position, bending both knees to a 90-degree angle.","Push off with your right foot and bring your left knee up towards your chest.","Step forward with your left foot and lower your body into a lunge position.","Continue alternating legs and lunging forward, keeping your core engaged and maintaining a steady pace.","Repeat for the desired number of repetitions."],"img":"3655-J9zIWig.jpg","gif":"3655-J9zIWig.gif"},{"id":"1460","n":"walking lunge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart.","Take a step forward with your right leg, lowering your body into a lunge position.","Keep your torso upright and your front knee aligned with your ankle.","Push off with your right foot and bring your left foot forward, stepping into a lunge position with your left leg.","Continue alternating legs and walking forward, maintaining a controlled and steady pace.","Repeat for the desired number of repetitions."],"img":"1460-IZVHb27.jpg","gif":"1460-IZVHb27.gif"},{"id":"3666","n":"walking on incline treadmill","bp":"cardio","eq":"leverage machine","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Adjust the incline level on the treadmill to your desired intensity.","Stand on the treadmill with your feet shoulder-width apart.","Start walking at a comfortable pace, ensuring that you maintain proper form.","Engage your core muscles and keep your back straight throughout the exercise.","Continue walking on the incline treadmill for the desired duration of your cardio workout.","Gradually decrease the incline and speed of the treadmill to cool down before stopping."],"img":"3666-rjiM4L3.jpg","gif":"3666-rjiM4L3.gif"},{"id":"2311","n":"walking on stepmill","bp":"cardio","eq":"stepmill machine","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","glutes","calves"],"st":["Adjust the stepmill machine to a comfortable level.","Step onto the machine and place your hands on the handrails for support.","Start walking by placing one foot on a step and then the other, alternating between legs.","Maintain an upright posture and engage your core muscles.","Continue walking for the desired duration or distance.","Gradually increase the intensity or speed as you become more comfortable with the exercise.","Remember to cool down and stretch after completing the exercise."],"img":"2311-j9Q5crt.jpg","gif":"2311-j9Q5crt.gif"},{"id":"0830","n":"weighted bench dip","bp":"upper arms","eq":"weighted","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Sit on a bench with your hands gripping the edge, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"img":"0830-MU9HnE7.jpg","gif":"0830-MU9HnE7.gif"},{"id":"2987","n":"weighted close grip chin-up on dip cage","bp":"back","eq":"weighted","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Stand in front of the dip cage and grab the parallel bars with an underhand grip, hands shoulder-width apart.","Hang from the bars with your arms fully extended, feet off the ground, and body straight.","Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your sides.","Continue pulling until your chin is above the bars, then pause for a moment.","Slowly lower your body back down to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"img":"2987-Gk1r408.jpg","gif":"2987-Gk1r408.gif"},{"id":"3643","n":"weighted cossack squats (male)","bp":"upper legs","eq":"weighted","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet wider than shoulder-width apart and toes pointing slightly outward.","Hold a weight in front of your chest with both hands.","Shift your weight to one side and lower your body by bending the knee of the side you shifted towards, while keeping the other leg straight.","Go as low as you can while maintaining balance and keeping your chest up.","Push through the heel of the bent leg to return to the starting position.","Repeat on the other side, alternating between legs."],"img":"3643-GWoKnIm.jpg","gif":"3643-GWoKnIm.gif"},{"id":"0832","n":"weighted crunch","bp":"waist","eq":"weighted","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Lie flat on your back with your knees bent and feet flat on the ground.","Hold a weight plate or dumbbell on your chest.","Engage your abs and lift your upper body off the ground, curling forward until your shoulder blades are off the ground.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0832-s8nrDXF.jpg","gif":"0832-s8nrDXF.gif"},{"id":"3670","n":"weighted decline sit-up","bp":"waist","eq":"weighted","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Lie flat on a decline bench with your feet secured under the foot pads.","Place your hands behind your head or across your chest.","Engage your abs and slowly lift your upper body off the bench, curling forward until your torso is perpendicular to the ground.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"3670-EZeDVzO.jpg","gif":"3670-EZeDVzO.gif"},{"id":"0833","n":"weighted donkey calf raise","bp":"lower legs","eq":"weighted","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Stand on a raised platform with your toes on the edge and your heels hanging off.","Hold onto a stable object for support.","Raise your heels as high as possible by extending your ankles.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0833-LmaFNZS.jpg","gif":"0833-LmaFNZS.gif"},{"id":"1310","n":"weighted drop push up","bp":"chest","eq":"weighted","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.","Lower your chest towards the ground, keeping your elbows close to your body.","Once your chest is just above the ground, explosively push yourself up, lifting your hands off the ground.","As you push up, quickly move your hands out to the sides and slightly forward, allowing your body to drop down towards the ground.","Catch yourself with your hands in the wider position and immediately lower your chest towards the ground again.","Repeat the push-up motion, dropping down and catching yourself with your hands in the narrower position.","Continue alternating between the wider and narrower hand positions for the desired number of repetitions."],"img":"1310-PSlvNMs.jpg","gif":"1310-PSlvNMs.gif"},{"id":"2135","n":"weighted front plank","bp":"waist","eq":"weighted","tg":"abs","mg":"shoulders","sm":["shoulders","lower back"],"st":["Start by lying face down on the floor.","Place your forearms on the ground, with your elbows directly under your shoulders.","Extend your legs straight out behind you, with your toes on the ground.","Engage your core and lift your body off the ground, balancing on your forearms and toes.","Keep your body in a straight line from your head to your heels.","Hold this position for the desired amount of time.","Lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"2135-VBAWRPG.jpg","gif":"2135-VBAWRPG.gif","ty":"rin","kind":"time"},{"id":"0834","n":"weighted front raise","bp":"shoulders","eq":"weighted","tg":"delts","mg":"biceps","sm":["biceps","forearms"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.","Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0834-e4aFmFY.jpg","gif":"0834-e4aFmFY.gif"},{"id":"0866","n":"weighted hanging leg-hip raise","bp":"waist","eq":"weighted","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or slightly higher.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0866-QOA0FD0.jpg","gif":"0866-QOA0FD0.gif"},{"id":"0835","n":"weighted hyperextension (on stability ball)","bp":"back","eq":"weighted","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Position yourself face down on a stability ball with your hips resting on the ball and your feet against a wall for stability.","Place your hands behind your head or cross them over your chest.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0835-8urJS9b.jpg","gif":"0835-8urJS9b.gif"},{"id":"3641","n":"weighted kneeling step with swing","bp":"shoulders","eq":"weighted","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Start in a kneeling position with your knees hip-width apart and your back straight.","Hold a weight in each hand, with your arms extended straight down in front of you.","Engage your core and swing the weights up and overhead, keeping your arms straight.","Lower the weights back down to the starting position and repeat for the desired number of repetitions."],"img":"3641-7uFJuXp.jpg","gif":"3641-7uFJuXp.gif"},{"id":"3644","n":"weighted lunge with swing","bp":"upper legs","eq":"weighted","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart, holding a weight in each hand.","Take a step forward with your right foot, lowering your body into a lunge position.","As you lunge forward, swing the weights forward and upward, keeping your arms straight.","Push off with your right foot and return to the starting position, swinging the weights back down.","Repeat with your left foot and continue alternating legs for the desired number of repetitions."],"img":"3644-5WiFcYk.jpg","gif":"3644-5WiFcYk.gif"},{"id":"3286","n":"weighted muscle up","bp":"back","eq":"weighted","tg":"lats","mg":"biceps","sm":["biceps","triceps","shoulders","chest"],"st":["Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart.","Engage your core and pull your body up towards the bar, leading with your chest.","As you reach the top of the movement, transition your grip so that your palms are facing towards you.","Continue pulling yourself up until your chest reaches the bar, then pause for a moment.","Slowly lower yourself back down to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions."],"img":"3286-JsOV1SU.jpg","gif":"3286-JsOV1SU.gif","ty":"atl"},{"id":"3312","n":"weighted muscle up (on bar)","bp":"back","eq":"weighted","tg":"lats","mg":"biceps","sm":["biceps","triceps","shoulders","forearms"],"st":["Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","Bend your elbows and pull your chest towards the bar, keeping your body straight.","Once your chest reaches the bar, push down with your hands and drive your elbows back, lifting your body above the bar.","Pause at the top of the movement, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."],"img":"3312-MCkqdKE.jpg","gif":"3312-MCkqdKE.gif","ty":"atl"},{"id":"3290","n":"weighted one hand pull up","bp":"back","eq":"weighted","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arm fully extended and your body straight.","Engage your core and pull your body up towards the bar by bending your elbow and squeezing your back muscles.","Continue pulling until your chin is above the bar.","Lower your body back down to the starting position with control.","Repeat for the desired number of repetitions."],"img":"3290-fXfqg1E.jpg","gif":"3290-fXfqg1E.gif"},{"id":"0840","n":"weighted overhead crunch (on stability ball)","bp":"waist","eq":"weighted","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a weight plate or dumbbell with both hands and extend your arms overhead.","Engage your abs and slowly curl your torso forward, bringing your chest towards your knees.","Pause for a moment at the top, then slowly lower your torso back to the starting position.","Repeat for the desired number of repetitions."],"img":"0840-xmM75XG.jpg","gif":"0840-xmM75XG.gif"},{"id":"0841","n":"weighted pull-up","bp":"back","eq":"weighted","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0841-HMzLjXx.jpg","gif":"0841-HMzLjXx.gif"},{"id":"0844","n":"weighted round arm","bp":"shoulders","eq":"weighted","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise your arms out to the sides, keeping a slight bend in your elbows.","Continue lifting your arms until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0844-VLYXo8S.jpg","gif":"0844-VLYXo8S.gif"},{"id":"0846","n":"weighted russian twist","bp":"waist","eq":"weighted","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Sit on the ground with your knees bent and your feet flat on the floor.","Hold a weight or medicine ball with both hands in front of your chest.","Lean back slightly, keeping your back straight and your core engaged.","Slowly twist your torso to the right, bringing the weight or medicine ball towards the floor on your right side.","Pause for a moment, then twist your torso to the left, bringing the weight or medicine ball towards the floor on your left side.","Continue alternating sides for the desired number of repetitions."],"img":"0846-fZFZ704.jpg","gif":"0846-fZFZ704.gif"},{"id":"0845","n":"weighted russian twist (legs up)","bp":"waist","eq":"weighted","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Sit on the ground with your knees bent and feet lifted off the ground, keeping your legs together.","Hold the weight with both hands in front of your chest, keeping your elbows slightly bent.","Lean back slightly to engage your core muscles.","Twist your torso to the right, bringing the weight towards the ground on your right side.","Pause for a moment, then twist your torso to the left, bringing the weight towards the ground on your left side.","Continue alternating sides for the desired number of repetitions."],"img":"0845-WU9BLIs.jpg","gif":"0845-WU9BLIs.gif"},{"id":"2371","n":"weighted russian twist v. 2","bp":"waist","eq":"weighted","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Sit on the ground with your knees bent and feet flat on the floor.","Hold the weight with both hands in front of your chest.","Lean back slightly to engage your core muscles.","Twist your torso to the right, bringing the weight towards the right side of your body.","Pause for a moment, then twist your torso to the left, bringing the weight towards the left side of your body.","Continue alternating sides for the desired number of repetitions."],"img":"2371-YIUAtYf.jpg","gif":"2371-YIUAtYf.gif"},{"id":"0847","n":"weighted seated bicep curl (on stability ball)","bp":"upper arms","eq":"medicine ball","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a medicine ball with an underhand grip, palms facing up, and let your arms hang down by your sides.","Keeping your upper arms stationary, exhale and curl the medicine ball up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the medicine ball back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0847-b4b6afT.jpg","gif":"0847-b4b6afT.gif"},{"id":"0849","n":"weighted seated twist (on stability ball)","bp":"waist","eq":"weighted","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a weight plate or dumbbell with both hands close to your chest.","Engage your core and slowly rotate your torso to one side, keeping your hips stable.","Pause for a moment at the end of the rotation, then slowly return to the starting position.","Repeat the rotation to the other side.","Continue alternating sides for the desired number of repetitions."],"img":"0849-s34Y4LR.jpg","gif":"0849-s34Y4LR.gif"},{"id":"0850","n":"weighted side bend (on stability ball)","bp":"waist","eq":"weighted","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Sit on a stability ball with your feet shoulder-width apart and flat on the ground.","Hold a weight in one hand and place your other hand on your hip.","Engage your core and slowly bend sideways towards the weighted side, keeping your back straight.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"img":"0850-6bOA1Oi.jpg","gif":"0850-6bOA1Oi.gif"},{"id":"0851","n":"weighted sissy squat","bp":"upper legs","eq":"weighted","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart and your toes pointing slightly outward.","Hold a weight in front of your chest with both hands, or place a barbell across your upper back.","Keeping your chest up and your core engaged, slowly lower your body down by bending at the knees and hips.","Continue lowering until your thighs are parallel to the ground or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"img":"0851-0lQnxMZ.jpg","gif":"0851-0lQnxMZ.gif"},{"id":"0852","n":"weighted squat","bp":"upper legs","eq":"weighted","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart, toes pointing slightly outward.","Hold a weight in front of your chest or on your shoulders.","Engage your core and keep your chest up as you lower your hips down and back, as if sitting into a chair.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Push through your heels to stand back up, squeezing your glutes at the top.","Repeat for the desired number of repetitions."],"img":"0852-JZuApnB.jpg","gif":"0852-JZuApnB.gif"},{"id":"0853","n":"weighted standing curl","bp":"upper arms","eq":"weighted","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Keep your elbows close to your torso and exhale as you curl the weights up to shoulder level.","Pause for a moment at the top, then inhale as you slowly lower the weights back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0853-M5Y7GPg.jpg","gif":"0853-M5Y7GPg.gif"},{"id":"0854","n":"weighted standing hand squeeze","bp":"lower arms","eq":"weighted","tg":"forearms","mg":"biceps","sm":["biceps","triceps"],"st":["Stand with your feet shoulder-width apart and hold a weight in each hand.","Extend your arms straight in front of you, palms facing each other.","Squeeze your hands together as hard as you can, engaging your forearms.","Hold the squeeze for a few seconds, then release.","Repeat for the desired number of repetitions."],"img":"0854-bjqbauy.jpg","gif":"0854-bjqbauy.gif"},{"id":"3313","n":"weighted straight bar dip","bp":"chest","eq":"weighted","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Position yourself between parallel bars with your arms fully extended and your body straight.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"img":"3313-Ff18ItA.jpg","gif":"3313-Ff18ItA.gif"},{"id":"3642","n":"weighted stretch lunge","bp":"upper legs","eq":"weighted","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart.","Take a step forward with your right foot, keeping your back straight.","Lower your body by bending your knees until your right thigh is parallel to the ground.","Push through your right heel to return to the starting position.","Repeat with your left leg.","Continue alternating legs for the desired number of repetitions."],"img":"3642-13VW2VO.jpg","gif":"3642-13VW2VO.gif","ty":"mob"},{"id":"0856","n":"weighted svend press","bp":"chest","eq":"weighted","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Stand with your feet shoulder-width apart and hold a weight plate in front of your chest with both hands.","Keep your elbows slightly bent and your palms facing each other.","Press the weight plate straight out in front of you, fully extending your arms.","Pause for a moment at the end of the movement, then slowly bring the weight plate back to the starting position.","Repeat for the desired number of repetitions."],"img":"0856-I1OBLnn.jpg","gif":"0856-I1OBLnn.gif"},{"id":"1754","n":"weighted three bench dips","bp":"upper arms","eq":"weighted","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward.","Walk your feet forward, sliding your butt off the bench and supporting your weight with your arms.","Lower your body by bending your elbows, keeping your back close to the bench.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"img":"1754-gtO1ErP.jpg","gif":"1754-gtO1ErP.gif"},{"id":"1755","n":"weighted tricep dips","bp":"upper arms","eq":"weighted","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.","Slide your butt off the front of the bench with your legs extended in front of you.","Keep your back close to the bench and your elbows slightly bent.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"img":"1755-bZq4bwK.jpg","gif":"1755-bZq4bwK.gif"},{"id":"1767","n":"weighted triceps dip on high parallel bars","bp":"upper arms","eq":"weighted","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Position yourself between two parallel bars with your hands gripping the bars and your arms fully extended.","Bend your elbows and lower your body until your upper arms are parallel to the ground.","Pause for a moment, then push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."],"img":"1767-K1vlode.jpg","gif":"1767-K1vlode.gif"},{"id":"0857","n":"wheel rollerout","bp":"waist","eq":"wheel roller","tg":"abs","mg":"lower back","sm":["lower back"],"st":["Kneel on the floor and place the wheel roller in front of you.","Place your hands on the handles of the wheel roller and extend your arms straight out in front of you.","Engage your core muscles and slowly roll the wheel forward, keeping your back straight and your abs tight.","Continue rolling forward until your body is fully extended and your arms are overhead.","Pause for a moment, then slowly roll the wheel back towards your knees, maintaining control and keeping your abs engaged.","Repeat for the desired number of repetitions."],"img":"0857-NAgVB3t.jpg","gif":"0857-NAgVB3t.gif"},{"id":"3637","n":"wheel run","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Start in a plank position with your hands on the wheel and your body straight.","Engage your core and start rolling the wheel forward by extending your arms.","Continue rolling until your body is fully extended and your arms are overhead.","Reverse the movement by pulling the wheel back towards your body, using your core and arms.","Repeat for the desired number of repetitions."],"img":"3637-km2Ljzj.jpg","gif":"3637-km2Ljzj.gif"},{"id":"1429","n":"wide grip pull-up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Hang from a pull-up bar with your palms facing away from you and your hands wider than shoulder-width apart.","Engage your core and squeeze your shoulder blades together.","Pull your body up towards the bar until your chin is above the bar.","Lower your body back down to the starting position with control.","Repeat for the desired number of repetitions."],"img":"1429-Qqi7bko.jpg","gif":"1429-Qqi7bko.gif"},{"id":"1367","n":"wide grip rear pull-up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Grab the pull-up bar with a wide overhand grip, hands slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"img":"1367-OYFhXVD.jpg","gif":"1367-OYFhXVD.gif"},{"id":"1311","n":"wide hand push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Start in a high plank position with your hands wider than shoulder-width apart.","Keep your body in a straight line from head to toe.","Lower your chest towards the ground by bending your elbows, keeping them close to your sides.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."],"img":"1311-JmMVpR3.jpg","gif":"1311-JmMVpR3.gif"},{"id":"2363","n":"wide-grip chest dip on high parallel bars","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Position yourself on the parallel bars with your arms fully extended and your body suspended in the air.","Lean forward slightly and lower your body by bending your elbows until your chest is just above the bars.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"img":"2363-O2K9Vb5.jpg","gif":"2363-O2K9Vb5.gif"},{"id":"0858","n":"wind sprints","bp":"waist","eq":"body weight","tg":"abs","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Find an open space or a track to perform the exercise.","Start by standing with your feet shoulder-width apart.","Begin running as fast as you can, pumping your arms and driving your knees up.","Continue sprinting for a specific distance or time period.","Rest and repeat for the desired number of repetitions."],"img":"0858-Qoujh3Q.jpg","gif":"0858-Qoujh3Q.gif","ty":"atl"},{"id":"1604","n":"world greatest stretch","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","quadriceps","calves"],"st":["Start in a lunge position with your right foot forward and your left foot back.","Place your hands on the ground on either side of your right foot.","Lower your left knee to the ground and extend your right leg, keeping your right foot flat on the ground.","Rotate your torso to the right, reaching your right arm up towards the ceiling.","Hold this position for a few seconds, then return to the starting position.","Switch sides and repeat the stretch with your left foot forward."],"img":"1604-DFGXwZr.jpg","gif":"1604-DFGXwZr.gif","ty":"stretch","kind":"time"},{"id":"1428","n":"wrist circles","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"hands","sm":["hands","wrists"],"st":["Extend your arms straight out in front of you.","Make a fist with both hands.","Rotate your wrists in a circular motion, keeping your arms still.","Continue the wrist circles for the desired number of repetitions."],"img":"1428-2zNKRUB.jpg","gif":"1428-2zNKRUB.gif","ty":"mob"},{"id":"0859","n":"wrist rollerer","bp":"lower arms","eq":"weighted","tg":"forearms","mg":"biceps","sm":["biceps","triceps"],"st":["Attach a weight to one end of a rope or bar.","Hold the other end of the rope or bar with both hands, palms facing down.","Stand with your feet shoulder-width apart and your arms fully extended in front of you.","Slowly roll the weight up towards your hands by flexing your wrists.","Pause for a moment at the top, then slowly lower the weight back down to the starting position.","Repeat for the desired number of repetitions."],"img":"0859-bd5b860.jpg","gif":"0859-bd5b860.gif"},{"id":"fe-90_90_Hamstring","n":"90/90 hamstring","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves"],"st":["Lie on your back, with one leg extended straight out.","With the other leg, bend the hip and knee to 90 degrees. You may brace your leg with your hands if necessary. This will be your starting position.","Extend your leg straight into the air, pausing briefly at the top. Return the leg to the starting position.","Repeat for 10-20 repetitions, and then switch to the other leg."],"img":"fe-90_90_Hamstring.jpg","ty":"stretch","kind":"time"},{"id":"fe-Adductor","n":"adductor","bp":"upper legs","eq":"roller","tg":"adductors","mg":"","sm":[],"st":["Lie face down with one leg on a foam roll.","Rotate the leg so that the foam roll contacts against your inner thigh. Shift as much weight onto the foam roll as can be tolerated.","While trying to relax the muscles if the inner thigh, roll over the foam between your hip and knee, holding points of tension for 10-30 seconds. Repeat with the other leg."],"img":"fe-Adductor.jpg","ty":"stretch","kind":"time"},{"id":"fe-Adductor_Groin","n":"adductor/groin","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"","sm":[],"st":["Lie on your back with your feet raised towards the ceiling.","Have your partner hold your feet or ankles. Abduct your legs as far as you can. This will be your starting position.","Attempt to squeeze your legs together for 10 or more seconds, while your partner prevents you from doing so.","Now, relax the muscles in your legs as your partner pushes your feet apart, stretching as far as is comfortable for you. Be sure to let your partner know when the stretch is adequate to prevent overstretching or injury."],"img":"fe-Adductor_Groin.jpg","ty":"stretch","kind":"time"},{"id":"fe-Advanced_Kettlebell_Windmill","n":"advanced kettlebell windmill","bp":"waist","eq":"kettlebell","tg":"abs","mg":"glutes","sm":["glutes","hamstrings","shoulders"],"st":["Clean and press a kettlebell overhead with one arm.","Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Keep the non-working arm behind your back and turn your feet out at a forty-five degree angle from the arm with the kettlebell.","Lower yourself as far as possible.","Pause for a second and reverse the motion back to the starting position."],"img":"fe-Advanced_Kettlebell_Windmill.jpg","ty":"atl"},{"id":"fe-All_Fours_Quad_Stretch","n":"all fours quad stretch","bp":"upper legs","eq":"body weight","tg":"quads","mg":"quadriceps","sm":["quadriceps"],"st":["Start off on your hands and knees, then lift your leg off the floor and hold the foot with your hand.","Use your hand to hold the foot or ankle, keeping the knee fully flexed, stretching the quadriceps and hip flexors.","Focus on extending your hips, thrusting them towards the floor. Hold for 10-20 seconds and then switch sides."],"img":"fe-All_Fours_Quad_Stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-Alternate_Leg_Diagonal_Bound","n":"alternate leg diagonal bound","bp":"upper legs","eq":"body weight","tg":"quads","mg":"abductors","sm":["abductors","adductors","calves","glutes","hamstrings"],"st":["Assume a comfortable stance with one foot slightly in front of the other.","Begin by pushing off with the front leg, driving the opposite knee forward and as high as possible before landing. Attempt to cover as much distance to each side with each bound.","It may help to use a line on the ground to guage distance from side to side.","Repeat the sequence with the other leg."],"img":"fe-Alternate_Leg_Diagonal_Bound.jpg","ty":"atl"},{"id":"fe-Alternating_Floor_Press","n":"alternating floor press","bp":"chest","eq":"kettlebell","tg":"pectorals","mg":"abdominals","sm":["abdominals","shoulders","triceps"],"st":["Lie on the floor with two kettlebells next to your shoulders.","Position one in place on your chest and then the other, gripping the kettlebells on the handle with the palms facing forward.","Extend both arms, so that the kettlebells are being held above your chest. Lower one kettlebell, bringing it to your chest and turn the wrist in the direction of the locked out kettlebell.","Raise the kettlebell and repeat on the opposite side."],"img":"fe-Alternating_Floor_Press.jpg","ty":"atl"},{"id":"fe-Alternating_Hang_Clean","n":"alternating hang clean","bp":"upper legs","eq":"kettlebell","tg":"hamstrings","mg":"biceps","sm":["biceps","calves","forearms","glutes","lower back","traps"],"st":["Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.","Clean one kettlebell to your shoulder and hold on to the other kettlebell in a hanging position. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so.","Lower the cleaned kettlebell to a hanging position and clean the alternate kettlebell. Repeat."],"img":"fe-Alternating_Hang_Clean.jpg","ty":"atl"},{"id":"fe-Alternating_Kettlebell_Press","n":"alternating kettlebell press","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps"],"st":["Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so.","Press one directly overhead by extending through the elbow, turning it so the palm faces forward while holding the other kettlebell stationary .","Lower the pressed kettlebell to the starting position and immediately press with your other arm."],"img":"fe-Alternating_Kettlebell_Press.jpg","ty":"atl"},{"id":"fe-Alternating_Kettlebell_Row","n":"alternating kettlebell row","bp":"back","eq":"kettlebell","tg":"upper back","mg":"biceps","sm":["biceps","lats"],"st":["Place two kettlebells in front of your feet. Bend your knees slightly and push your butt out as much as possible. As you bend over to get into the starting position grab both kettlebells by the handles.","Pull one kettlebell off of the floor while holding on to the other kettlebell. Retract the shoulder blade of the working side, as you flex the elbow, drawing the kettlebell towards your stomach or rib cage.","Lower the kettlebell in the working arm and repeat with your other arm."],"img":"fe-Alternating_Kettlebell_Row.jpg","ty":"atl"},{"id":"fe-Alternating_Renegade_Row","n":"alternating renegade row","bp":"back","eq":"kettlebell","tg":"upper back","mg":"abdominals","sm":["abdominals","biceps","chest","lats","triceps"],"st":["Place two kettlebells on the floor about shoulder width apart. Position yourself on your toes and your hands as though you were doing a pushup, with the body straight and extended. Use the handles of the kettlebells to support your upper body. You may need to position your feet wide for support.","Push one kettlebell into the floor and row the other kettlebell, retracting the shoulder blade of the working side as you flex the elbow, pulling it to your side.","Then lower the kettlebell to the floor and begin the kettlebell in the opposite hand. Repeat for several reps."],"img":"fe-Alternating_Renegade_Row.jpg","ty":"atl"},{"id":"fe-Ankle_On_The_Knee","n":"ankle on the knee","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"","sm":[],"st":["From a lying position, bend your knees and keep your feet on the floor.","Place your ankle of one foot on your opposite knee.","Grasp the thigh or knee of the bottom leg and pull both of your legs into the chest. Relax your neck and shoulders. Hold for 10-20 seconds and then switch sides."],"img":"fe-Ankle_On_The_Knee.jpg","ty":"stretch","kind":"time"},{"id":"fe-Anterior_Tibialis-SMR","n":"anterior tibialis-smr","bp":"lower legs","eq":"body weight","tg":"calves","mg":"","sm":[],"st":["Begin seated on the ground with your legs bent and your feet on the floor.","Using a Muscle Roller or a rolling pin, apply pressure to the muscles on the outside of your shins. Work from just below the knee to above the ankle, pausing at points of tension for 10-30 seconds. Repeat on the other leg."],"img":"fe-Anterior_Tibialis-SMR.jpg","ty":"mob"},{"id":"fe-Arm_Circles","n":"arm circles","bp":"shoulders","eq":"body weight","tg":"delts","mg":"traps","sm":["traps"],"st":["Stand up and extend your arms straight out by the sides. The arms should be parallel to the floor and perpendicular (90-degree angle) to your torso. This will be your starting position.","Slowly start to make circles of about 1 foot in diameter with each outstretched arm. Breathe normally as you perform the movement.","Continue the circular motion of the outstretched arms for about ten seconds. Then reverse the movement, going the opposite direction."],"img":"fe-Arm_Circles.jpg","ty":"mob"},{"id":"fe-Back_Flyes_-_With_Bands","n":"back flyes - with bands","bp":"shoulders","eq":"band","tg":"delts","mg":"middle back","sm":["middle back","triceps"],"st":["Run a band around a stationary post like that of a squat rack.","Grab the band by the handles and stand back so that the tension in the band rises.","Extend and lift the arms straight in front of you. Tip: Your arms should be straight and parallel to the floor while perpendicular to your torso. Your feet should be firmly planted on the floor spread at shoulder width. This will be your starting position.","As you exhale, move your arms to the sides and back. Keep your arms extended and parallel to the floor. Continue the movement until the arms are extended to your sides.","After a pause, go back to the original position as you inhale.","Repeat for the recommended amount of repetitions."],"img":"fe-Back_Flyes_-_With_Bands.jpg","ty":"rin"},{"id":"fe-Backward_Medicine_Ball_Throw","n":"backward medicine ball throw","bp":"shoulders","eq":"medicine ball","tg":"delts","mg":"","sm":[],"st":["This exercise is best done with a partner. If you lack a partner, the ball can be thrown and retrieved or thrown against a wall.","Begin standing a few meters in front of your partner, both facing the same direction. Begin holding the ball between your legs.","Squat down and then forcefully reverse direction, coming to full extension and you toss the ball over your head to your partner.","Your partner can then roll the ball back to you. Repeat for the desired number of repetitions."],"img":"fe-Backward_Medicine_Ball_Throw.jpg","ty":"atl"},{"id":"fe-Band_Hip_Adductions","n":"band hip adductions","bp":"upper legs","eq":"band","tg":"adductors","mg":"","sm":[],"st":["Anchor a band around a solid post or other object.","Stand with your left side to the post, and put your right foot through the band, getting it around the ankle.","Stand up straight and hold onto the post if needed. This will be your starting position.","Keeping the knee straight, raise your right legs out to the side as far as you can.","Return to the starting position and repeat for the desired rep count.","Switch sides."],"img":"fe-Band_Hip_Adductions.jpg","ty":"rin"},{"id":"fe-Band_Pull_Apart","n":"band pull apart","bp":"shoulders","eq":"band","tg":"delts","mg":"middle back","sm":["middle back","traps"],"st":["Begin with your arms extended straight out in front of you, holding the band with both hands.","Initiate the movement by performing a reverse fly motion, moving your hands out laterally to your sides.","Keep your elbows extended as you perform the movement, bringing the band to your chest. Ensure that you keep your shoulders back during the exercise.","Pause as you complete the movement, returning to the starting position under control."],"img":"fe-Band_Pull_Apart.jpg","ty":"rin"},{"id":"fe-Band_Skull_Crusher","n":"band skull crusher","bp":"upper arms","eq":"band","tg":"triceps","mg":"","sm":[],"st":["Secure a band to the base of a rack or the bench. Lay on the bench so that the band is lined up with your head.","Take hold of the band, raising your elbows so that the upper arm is perpendicular to the floor. With the elbow flexed, the band should be above your head. This will be your starting position.","Extend through the elbow to straighten your arm, keeping your upper arm in place. Pause at the top of the motion, and return to the starting position."],"img":"fe-Band_Skull_Crusher.jpg","ty":"rin"},{"id":"fe-Bench_Dips","n":"bench dips","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["For this exercise you will need to place a bench behind your back. With the bench perpendicular to your body, and while looking away from it, hold on to the bench on its edge with the hands fully extended, separated at shoulder width. The legs will be extended forward, bent at the waist and perpendicular to your torso. This will be your starting position.","Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.","Using your triceps to bring your torso up again, lift yourself back to the starting position.","Repeat for the recommended amount of repetitions."],"img":"fe-Bench_Dips.jpg","ty":"atl"},{"id":"fe-Bench_Jump","n":"bench jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings"],"st":["Begin with a box or bench 1-2 feet in front of you. Stand with your feet shoulder width apart. This will be your starting position.","Perform a short squat in preparation for the jump; swing your arms behind you.","Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up.","Jump over the bench, landing with the knees bent, absorbing the impact through the legs.","Turn around and face the opposite direction, then jump back over the bench."],"img":"fe-Bench_Jump.jpg","ty":"atl"},{"id":"fe-Bench_Press_-_With_Bands","n":"bench press - with bands","bp":"chest","eq":"band","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Using a flat bench secure a band under the leg of the bench that is nearest to your head.","Once the band is secure, grab it by both handles and lie down on the bench.","Extend your arms so that you are holding the band handles in front of you at shoulder width.","Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.","Bring down the handles slowly until your elbow forms a 90 degree angle. Keep full control at all times.","As you breathe out, bring the handles up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions of your training program."],"img":"fe-Bench_Press_-_With_Bands.jpg","ty":"rin"},{"id":"fe-Bench_Sprint","n":"bench sprint","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings"],"st":["Stand on the ground with one foot resting on a bench or box with your heel close to the edge.","Push off with your foot on top of the bench, extending through the hip and knee.","Land with the opposite foot on top of the box, returning your other foot back to the start position.","Continue alternating from one foot to another to complete the set."],"img":"fe-Bench_Sprint.jpg","ty":"atl"},{"id":"fe-Bent-Knee_Hip_Raise","n":"bent-knee hip raise","bp":"waist","eq":"body weight","tg":"abs","mg":"","sm":[],"st":["Lay flat on the floor with your arms next to your sides.","Now bend your knees at around a 75 degree angle and lift your feet off the floor by around 2 inches.","Using your lower abs, bring your knees in towards you as you maintain the 75 degree angle bend in your legs. Continue this movement until you raise your hips off of the floor by rolling your pelvis backward. Breathe out as you perform this portion of the movement. Tip: At the end of the movement your knees will be over your chest.","Squeeze your abs at the top of the movement for a second and then return to the starting position slowly as you breathe in. Tip: Maintain a controlled motion at all times.","Repeat for the recommended amount of repetitions."],"img":"fe-Bent-Knee_Hip_Raise.jpg","ty":"atl"},{"id":"fe-Bent_Press","n":"bent press","bp":"waist","eq":"kettlebell","tg":"abs","mg":"glutes","sm":["glutes","hamstrings","lower back","quadriceps","shoulders","triceps"],"st":["Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so. This will be your starting position.","Begin my leaning to the side opposite the kettlebell, continuing until you are able to touch the ground with your free hand, keeping your eyes on the kettlebell. As you do so, press the weight vertically be extending through the elbow, keeping your arm perpendicular to the ground.","Return to an upright position, with the kettlebell above your head. Return the kettlebell to the shoulder and repeat for the desired number of repetitions."],"img":"fe-Bent_Press.jpg","ty":"atl"},{"id":"fe-Body_Tricep_Press","n":"body tricep press","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"","sm":[],"st":["Position a bar in a rack at chest height.","Standing, take a shoulder width grip on the bar and step a yard or two back, feet together and arms extended so that you are leaning on the bar. This will be your starting position.","Begin by flexing the elbow, lowering yourself towards the bar.","Pause, and then reverse the motion by extending the elbows.","Progress from bodyweight by adding chains over your shoulders."],"img":"fe-Body_Tricep_Press.jpg","ty":"atl"},{"id":"fe-Bodyweight_Squat","n":"bodyweight squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings"],"st":["Stand with your feet shoulder width apart. You can place your hands behind your head. This will be your starting position.","Begin the movement by flexing your knees and hips, sitting back with your hips.","Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out."],"img":"fe-Bodyweight_Squat.jpg","ty":"atl"},{"id":"fe-Bottoms-Up_Clean_From_The_Hang_Position","n":"bottoms-up clean from the hang position","bp":"lower arms","eq":"kettlebell","tg":"forearms","mg":"biceps","sm":["biceps","shoulders"],"st":["Initiate the exercise by standing upright with a kettlebell in one hand.","Swing the kettlebell back forcefully and then reverse the motion forcefully. Crush the kettlebell handle as hard as possible and raise the kettlebell to your shoulder."],"img":"fe-Bottoms-Up_Clean_From_The_Hang_Position.jpg","ty":"atl"},{"id":"fe-Box_Jump_Multiple_Response","n":"box jump (multiple response)","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"abductors","sm":["abductors","adductors","calves","glutes","quadriceps"],"st":["Assume a relaxed stance facing the box or platform approximately an arm's length away. Arms should be down at the sides and legs slightly bent.","Using the arms to aid in the initial burst, jump upward and forward, landing with feet simultaneously on top of the box or platform.","Immediately drop or jump back down to the original starting place; then repeat the sequence."],"img":"fe-Box_Jump_Multiple_Response.jpg","ty":"atl"},{"id":"fe-Box_Skip","n":"box skip","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"abductors","sm":["abductors","adductors","calves","glutes","quadriceps"],"st":["You will need several boxes lined up about 8 feet apart.","Begin facing the first box with one leg slightly behind the other.","Drive off the back leg, attempting to gain as much height with the hips as possible.","Immediately upon landing on the box, drive the other leg forward and upward to gain height and distance, leaping from the box. Land between the first two boxes with the same leg that landed on the first box.","Then, step to the next box and repeat."],"img":"fe-Box_Skip.jpg","ty":"atl"},{"id":"fe-Brachialis-SMR","n":"brachialis-smr","bp":"upper arms","eq":"roller","tg":"biceps","mg":"","sm":[],"st":["Lie on your side, with your upper arm against the foam roller. The upper arm should be more or less aligned with your body, with the outside of the bicep pressed against the foam roller.","Raise your hips off of the floor, supporting your weight on your arm and on your feet. Hold for 10-30 seconds, and then switch sides."],"img":"fe-Brachialis-SMR.jpg","ty":"mob"},{"id":"fe-Butt_Lift_Bridge","n":"butt lift (bridge)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings"],"st":["Lie flat on the floor on your back with the hands by your side and your knees bent. Your feet should be placed around shoulder width. This will be your starting position.","Pushing mainly with your heels, lift your hips off the floor while keeping your back straight. Breathe out as you perform this part of the motion and hold at the top for a second.","Slowly go back to the starting position as you breathe in."],"img":"fe-Butt_Lift_Bridge.jpg","ty":"atl"},{"id":"fe-Calf_Raises_-_With_Bands","n":"calf raises - with bands","bp":"lower legs","eq":"band","tg":"calves","mg":"","sm":[],"st":["Grab an exercise band and stand on it with your toes making sure that the length of the band between the foot and the arms is the same for both sides.","While holding the handles of the band, raise the arms to the side of your head as if you were getting ready to perform a shoulder press. The palms should be facing forward with the elbows bent and to the sides. This movement will create tension on the band. This will be your starting position.","Keeping the hands by your shoulder, stand up on your toes as you exhale and contract the calves hard at the top of the movement.","After a one second contraction, slowly go back down to the starting position.","Repeat for the recommended amount of repetitions."],"img":"fe-Calf_Raises_-_With_Bands.jpg","ty":"rin"},{"id":"fe-Calf_Stretch_Elbows_Against_Wall","n":"calf stretch elbows against wall","bp":"lower legs","eq":"body weight","tg":"calves","mg":"","sm":[],"st":["Stand facing a wall from a couple feet away.","Lean against the wall, placing your weight on your forearms.","Attempt to keep your heels on the ground. Hold for 10-20 seconds. You may move further or closer the wall, making it more or less difficult, respectively."],"img":"fe-Calf_Stretch_Elbows_Against_Wall.jpg","ty":"stretch","kind":"time"},{"id":"fe-Calf_Stretch_Hands_Against_Wall","n":"calf stretch hands against wall","bp":"lower legs","eq":"body weight","tg":"calves","mg":"","sm":[],"st":["Stand facing a wall from several feet away. Stagger your stance, placing one foot forward.","Lean forward and rest your hands on the wall, keeping your heel, hip and head in a straight line.","Attempt to keep your heel on the ground. Hold for 10-20 seconds and then switch sides."],"img":"fe-Calf_Stretch_Hands_Against_Wall.jpg","ty":"stretch","kind":"time"},{"id":"fe-Calves-SMR","n":"calves-smr","bp":"lower legs","eq":"roller","tg":"calves","mg":"","sm":[],"st":["Begin seated on the floor. Place a foam roller underneath your lower leg. Your other leg can either be crossed over the opposite or be placed on the floor, supporting some of your weight. This will be your starting position.","Place your hands to your side or just behind you, and press down to raise your hips off of the floor, placing much of your weight against your calf muscle. Roll from below the knee to above the ankle, pausing at points of tension for 10-30 seconds. Repeat for the other leg."],"img":"fe-Calves-SMR.jpg","ty":"mob"},{"id":"fe-Carioca_Quick_Step","n":"carioca quick step","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"abdominals","sm":["abdominals","abductors","calves","glutes","hamstrings","quadriceps"],"st":["Begin with your feet a few inches apart and your left arm up in a relaxed, athletic position.","With your right foot, quick step behind and pull the knee up.","Fire your arms back up when you pull the right knee, being sure that your knee goes straight up and down. Avoid turning your feet as you move and continue to look forward as you move to the side."],"img":"fe-Carioca_Quick_Step.jpg","ty":"atl"},{"id":"fe-Cat_Stretch","n":"cat stretch","bp":"back","eq":"body weight","tg":"spine","mg":"middle back","sm":["middle back","traps"],"st":["Position yourself on the floor on your hands and knees.","Pull your belly in and round your spine, lower back, shoulders, and neck, letting your head drop.","Hold for 15 seconds."],"img":"fe-Cat_Stretch.jpg","ty":"mob"},{"id":"fe-Catch_and_Overhead_Throw","n":"catch and overhead throw","bp":"back","eq":"medicine ball","tg":"lats","mg":"abdominals","sm":["abdominals","chest","shoulders"],"st":["Begin standing while facing a wall or a partner.","Using both hands, position the ball behind your head, stretching as much as possible, and forcefully throw the ball forward.","Ensure that you follow your throw through, being prepared to receive your rebound from your throw. If you are throwing against the wall, make sure that you stand close enough to the wall to receive the rebound, and aim a little higher than you would with a partner."],"img":"fe-Catch_and_Overhead_Throw.jpg","ty":"atl"},{"id":"fe-Chair_Lower_Back_Stretch","n":"chair lower back stretch","bp":"back","eq":"body weight","tg":"lats","mg":"lower back","sm":["lower back"],"st":["Sit upright on a chair.","Bend to one side with your arm over your head. You can hold onto the chair with your free hand.","Hold for 10 seconds, and repeat for your other side."],"img":"fe-Chair_Lower_Back_Stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-Chair_Upper_Body_Stretch","n":"chair upper body stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"biceps","sm":["biceps","chest"],"st":["Sit on the edge of a chair, gripping the back of it.","Straighten your arms, keeping your back straight, and pull your upper body forward so you feel a stretch. Hold for 20-30 seconds."],"img":"fe-Chair_Upper_Body_Stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-Chest_Push_from_3_point_stance","n":"chest push from 3 point stance","bp":"chest","eq":"medicine ball","tg":"pectorals","mg":"abdominals","sm":["abdominals","shoulders","triceps"],"st":["Begin in a three point stance, squatted down with your back flat and one hand on the ground. Place the medicine ball directly in front of you.","To begin, take your first step as you pull the ball to your chest, positioning both hands to prepare for the throw.","As you execute the second step, explosively release the ball forward as hard as possible."],"img":"fe-Chest_Push_from_3_point_stance.jpg","ty":"atl"},{"id":"fe-Chest_Push_multiple_response","n":"chest push (multiple response)","bp":"chest","eq":"medicine ball","tg":"pectorals","mg":"abdominals","sm":["abdominals","shoulders","triceps"],"st":["Begin in a kneeling position facing a wall or utilize a partner. Hold the ball with both hands tight into the chest.","Execute the pass by exploding forward and outward with the hips while pushing the ball as hard as possible.","Follow through by falling forward, catching yourself with your hands.","Immediately return to an upright position. Repeat for the desired number of repetitions."],"img":"fe-Chest_Push_multiple_response.jpg","ty":"atl"},{"id":"fe-Chest_Push_single_response","n":"chest push (single response)","bp":"chest","eq":"medicine ball","tg":"pectorals","mg":"abdominals","sm":["abdominals","shoulders","triceps"],"st":["Begin in a kneeling position holding the medicine ball with both hands tightly into the chest.","Execute the pass by exploding forward and outward with the hips while pushing the ball as far as possible.","Follow through by falling forward, catching yourself with your hands."],"img":"fe-Chest_Push_single_response.jpg","ty":"atl"},{"id":"fe-Chest_Push_with_Run_Release","n":"chest push with run release","bp":"chest","eq":"medicine ball","tg":"pectorals","mg":"abdominals","sm":["abdominals","shoulders","triceps"],"st":["Begin in an athletic stance with the knees bent, hips back, and back flat. Hold the medicine ball near your legs. This will be your starting position.","While taking your first step draw the medicine ball into your chest.","As you take the second step, explosively push the ball forward, immediately sprinting for 10 yards after the release. If you are really fast, you can catch your own pass!"],"img":"fe-Chest_Push_with_Run_Release.jpg","ty":"atl"},{"id":"fe-Chest_Stretch_on_Stability_Ball","n":"chest stretch on stability ball","bp":"chest","eq":"stability ball","tg":"pectorals","mg":"","sm":[],"st":["Get on your hands and knees next to an exercise ball.","Place your elbows on top of the ball, keeping your arm out to your side. This will be your starting position.","Lower your torso towards the floor, keeping your elbow on top of the ball. Hold the stretch for 20-30 seconds, and repeat with the other arm."],"img":"fe-Chest_Stretch_on_Stability_Ball.jpg","ty":"stretch","kind":"time"},{"id":"fe-Childs_Pose","n":"child's pose","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","middle back"],"st":["Get on your hands and knees, walk your hands in front of you.","Lower your buttocks down to sit on your heels. Let your arms drag along the floor as you sit back to stretch your entire spine.","Once you settle onto your heels, bring your hands next to your feet and relax. \"breathe\" into your back. Rest your forehead on the floor. Avoid this position if you have knee problems."],"img":"fe-Childs_Pose.jpg","ty":"stretch","kind":"time"},{"id":"fe-Chin_To_Chest_Stretch","n":"chin to chest stretch","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"traps","sm":["traps"],"st":["Get into a seated position on the floor.","Place both hands at the rear of your head, fingers interlocked, thumbs pointing down and elbows pointing straight ahead. Slowly pull your head down to your chest. Hold for 20-30 seconds."],"img":"fe-Chin_To_Chest_Stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-Close-Grip_Push-Up_off_of_a_Dumbbell","n":"close-grip push-up off of a dumbbell","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"abdominals","sm":["abdominals","chest","shoulders"],"st":["Lie on the floor and place your hands on an upright dumbbell. Supporting your weight on your toes and hands, keep your torso rigid and your elbows in with your arms straight. This will be your starting position.","Lower your body, allowing the elbows to flex while you inhale. Keep your body straight, not allowing your hips to rise or sag.","Press yourself back up to the starting position by extending the elbows. Breathe out as you perform this step.","After a pause at the contracted position, repeat the movement for the prescribed amount of repetitions."],"img":"fe-Close-Grip_Push-Up_off_of_a_Dumbbell.jpg","ty":"atl"},{"id":"fe-Cross_Over_-_With_Bands","n":"cross over - with bands","bp":"chest","eq":"band","tg":"pectorals","mg":"biceps","sm":["biceps","shoulders"],"st":["Secure an exercise band around a stationary post.","While facing away from the post, grab the handles on both ends of the band and step forward enough to create tension on the band.","Raise your arms to the sides, parallel to the floor, perpendicular to your torso (your torso and the arms should resemble the letter \"T\") and with the palms facing forward. Have them extended with a slight bend at the elbows. This will be your starting position.","While keeping your arms straight, bring them across your chest in a semicircular motion to the front as you exhale and flex your pecs. Hold the contraction for a second.","Slowly return to the starting position as you inhale.","Perform for the recommended amount of repetitions."],"img":"fe-Cross_Over_-_With_Bands.jpg","ty":"rin"},{"id":"fe-Crossover_Reverse_Lunge","n":"crossover reverse lunge","bp":"back","eq":"body weight","tg":"spine","mg":"abdominals","sm":["abdominals","abductors","glutes","hamstrings","quadriceps"],"st":["Stand with your feet shoulder width apart. This will be your starting position.","Perform a rear lunge by stepping back with one foot and flexing the hips and front knee. As you do so, rotate your torso across the front leg.","After a brief pause, return to the starting position and repeat on the other side, continuing in an alternating fashion."],"img":"fe-Crossover_Reverse_Lunge.jpg","ty":"mob"},{"id":"fe-Crunch_-_Legs_On_Exercise_Ball","n":"crunch - legs on exercise ball","bp":"waist","eq":"body weight","tg":"abs","mg":"","sm":[],"st":["Lie flat on your back with your feet resting on an exercise ball and your knees bent at a 90 degree angle.","Place your feet three to four inches apart and point your toes inward so they touch.","Place your hands lightly on either side of your head keeping your elbows in. Tip: Don't lock your fingers behind your head.","Push the small of your back down in the floor in order to better isolate your abdominal muscles. This will be your starting position.","Begin to roll your shoulders off the floor and continue to push down as hard as you can with your lower back. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. Breathe out as you execute this portion of the movement. Squeeze your abdominals hard at the top of the contraction and hold for a second. Tip: Focus on a slow, controlled movement. Refrain from using momentum at any time.","Slowly go back down to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"img":"fe-Crunch_-_Legs_On_Exercise_Ball.jpg","ty":"atl"},{"id":"fe-Crunches","n":"crunches","bp":"waist","eq":"body weight","tg":"abs","mg":"","sm":[],"st":["Lie flat on your back with your feet flat on the ground, or resting on a bench with your knees bent at a 90 degree angle. If you are resting your feet on a bench, place them three to four inches apart and point your toes inward so they touch.","Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don't lock your fingers behind your head.","While pushing the small of your back down in the floor to better isolate your abdominal muscles, begin to roll your shoulders off the floor.","Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don't cheat yourself by using momentum.","After the one second contraction, begin to come down slowly again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"img":"fe-Crunches.jpg","ty":"atl"},{"id":"fe-Dancers_Stretch","n":"dancer's stretch","bp":"back","eq":"body weight","tg":"spine","mg":"abductors","sm":["abductors","glutes"],"st":["Sit up on the floor.","Cross your right leg over your left, keeping the knee bent. Your left leg is straight and down on the floor.","Place your left arm on your right leg and your right hand on the floor.","Rotate your upper body to the right, and hold for 10-20 seconds. Switch sides."],"img":"fe-Dancers_Stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-Decline_Oblique_Crunch","n":"decline oblique crunch","bp":"waist","eq":"body weight","tg":"abs","mg":"","sm":[],"st":["Secure your legs at the end of the decline bench and slowly lay down on the bench.","Raise your upper body off the bench until your torso is about 35-45 degrees if measured from the floor.","Put one hand beside your head and the other on your thigh. This will be your starting position.","Raise your upper body slowly from the starting position while turning your torso to the left. Continue crunching up as you exhale until your right elbow touches your left knee. Hold this contracted position for a second. Tip: Focus on keeping your abs tight and keeping the movement slow and controlled.","Lower your body back down slowly to the starting position as you inhale.","After completing one set on the right for the recommended amount of repetitions, switch to your left side. Tip: Focus on really twisting your torso and feeling the contraction when you are in the up position."],"img":"fe-Decline_Oblique_Crunch.jpg","ty":"atl"},{"id":"fe-Decline_Reverse_Crunch","n":"decline reverse crunch","bp":"waist","eq":"body weight","tg":"abs","mg":"","sm":[],"st":["Lie on your back on a decline bench and hold on to the top of the bench with both hands. Don't let your body slip down from this position.","Hold your legs parallel to the floor using your abs to hold them there while keeping your knees and feet together. Tip: Your legs should be fully extended with a slight bend on the knee. This will be your starting position.","While exhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the bench. At the end of this movement your knees will be touching your chest.","Hold the contraction for a second and move your legs back to the starting position while inhaling.","Repeat for the recommended amount of repetitions."],"img":"fe-Decline_Reverse_Crunch.jpg","ty":"atl"},{"id":"fe-Depth_Jump_Leap","n":"depth jump leap","bp":"upper legs","eq":"body weight","tg":"quads","mg":"abductors","sm":["abductors","adductors","calves","glutes","hamstrings"],"st":["For this drill you will need two boxes or benches, one 12 to 16 inches high and the other 22 to 26 inches high.","Stand on one of the two boxes with arms at the sides; feet should be together and slightly off the edge as in the depth jump. Place the other box approximately two or three feet in front of and facing the performer.","Begin by dropping off the initial box, landing and simultaneously taking off with both feet.","Rebound by driving upward and outward as intensely as possible, using the arms and full extension of the body to jump onto the higher box. Again, allow the legs to absorb the impact."],"img":"fe-Depth_Jump_Leap.jpg","ty":"atl"},{"id":"fe-Dips_-_Triceps_Version","n":"dips - triceps version","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["To get into the starting position, hold your body at arm's length with your arms nearly locked above the bars.","Now, inhale and slowly lower yourself downward. Your torso should remain upright and your elbows should stay close to your body. This helps to better focus on tricep involvement. Lower yourself until there is a 90 degree angle formed between the upper arm and forearm.","Then, exhale and push your torso back up using your triceps to bring your body back to the starting position.","Repeat the movement for the prescribed amount of repetitions."],"img":"fe-Dips_-_Triceps_Version.jpg","ty":"atl"},{"id":"fe-Double_Kettlebell_Alternating_Hang_Clean","n":"double kettlebell alternating hang clean","bp":"upper legs","eq":"kettlebell","tg":"hamstrings","mg":"biceps","sm":["biceps","calves","forearms","glutes","lower back","quadriceps","traps"],"st":["Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.","Clean one kettlebell to your shoulder and hold on to the other kettlebell.","With a fluid motion, lower the top kettlebell while driving the bottom kettlebell up."],"img":"fe-Double_Kettlebell_Alternating_Hang_Clean.jpg","ty":"atl"},{"id":"fe-Double_Kettlebell_Jerk","n":"double kettlebell jerk","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"calves","sm":["calves","quadriceps","triceps"],"st":["Hold a kettlebell by the handle in each hand.","Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward. This will be your starting position.","Dip your body by bending the knees, keeping your torso upright.","Immediately reverse direction, driving through the heels, in essence jumping to create momentum.","As you do so, press the kettlebells overhead to lockout by extending the arms, using your body's momentum to move the weights.","Return your feet to the ground in a split fashion, with one foot forward and one foot back.","Keeping the weights overhead, return to a standing position, bringing your feet together. Lower the weights to perform the next repetition."],"img":"fe-Double_Kettlebell_Jerk.jpg","ty":"atl"},{"id":"fe-Double_Kettlebell_Push_Press","n":"double kettlebell push press","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"calves","sm":["calves","quadriceps","triceps"],"st":["Clean two kettlebells to your shoulders.","Squat down a few inches and reverse the motion rapidly. Use the momentum from the legs to drive the kettlebells overhead.","Once the kettlebells are locked out, lower the kettlebells to your shoulders and repeat."],"img":"fe-Double_Kettlebell_Push_Press.jpg","ty":"atl"},{"id":"fe-Double_Kettlebell_Snatch","n":"double kettlebell snatch","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"glutes","sm":["glutes","hamstrings","quadriceps"],"st":["Place two kettlebells behind your feet. Bend your knees and sit back to pick up the kettlebells.","Swing the kettlebells between your legs forcefully and reverse the direction.","Drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion."],"img":"fe-Double_Kettlebell_Snatch.jpg","ty":"atl"},{"id":"fe-Double_Kettlebell_Windmill","n":"double kettlebell windmill","bp":"waist","eq":"kettlebell","tg":"abs","mg":"glutes","sm":["glutes","hamstrings","shoulders","triceps"],"st":["Place a kettlebell in front of your front foot and clean and press a kettlebell overhead with your opposite arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so, so that the palm faces forward.","Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Turn your feet out at a forty-five degree angle from the arm with the locked out kettlebell.","Bending at the hip to one side, sticking your butt out, slowly lean until you can retrieve the kettlebell from the floor. Keep your eyes on the kettlebell that you hold over your head at all times.","Pause for a second after retrieving the kettlebell from the ground and reverse the motion back to the starting position."],"img":"fe-Double_Kettlebell_Windmill.jpg","ty":"atl"},{"id":"fe-Double_Leg_Butt_Kick","n":"double leg butt kick","bp":"upper legs","eq":"body weight","tg":"quads","mg":"abductors","sm":["abductors","adductors","calves","glutes","hamstrings"],"st":["Begin standing with your knees slightly bent.","Quickly squat a short distance, flexing the hips and knees, and immediately extend to jump for maximum vertical height.","As you go up, tuck your heels by flexing the knees, attempting to touch the buttocks.","Finish the motion by landing with the knees only partially bent, using your legs to absorb the impact."],"img":"fe-Double_Leg_Butt_Kick.jpg","ty":"atl"},{"id":"fe-Drop_Push","n":"drop push","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Position low boxes or other platforms 2-3 feet apart.","Move to a pushup position between them, supporting yourself by placing your hands on the boxes.","With good posture, drop from the platforms by pressing up and moving your hands to shoulder width, cushioning your landing by absorbing the impact through the arm."],"img":"fe-Drop_Push.jpg","ty":"atl"},{"id":"fe-Dumbbell_Seated_Box_Jump","n":"dumbbell seated box jump","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings"],"st":["Position a box a couple feet to the side of a bench. Hold a dumbbell to your chest with both hands and seat yourself on the bench facing the box. This will be your starting position.","Plant your feet firmly on the ground as you lean forward, extending through the hips and knees to jump up and forward.","Land on the box with both feet, absorbing the impact by allowing the hips and knees to bend.","Step down and return to the starting position."],"img":"fe-Dumbbell_Seated_Box_Jump.jpg","ty":"atl"},{"id":"fe-Dynamic_Back_Stretch","n":"dynamic back stretch","bp":"back","eq":"body weight","tg":"lats","mg":"","sm":[],"st":["Stand with your feet shoulder width apart. This will be your starting position.","Keeping your arms straight, swing them straight up in front of you 5-10 times, increasing the range of motion each time until your arms are above your head."],"img":"fe-Dynamic_Back_Stretch.jpg","ty":"mob"},{"id":"fe-Dynamic_Chest_Stretch","n":"dynamic chest stretch","bp":"chest","eq":"body weight","tg":"pectorals","mg":"middle back","sm":["middle back"],"st":["Stand with your hands together, arms extended directly in front of you. This will be your starting position.","Keeping your arms straight, quickly move your arms back as far as possible and back in again, similar to an exaggerated clapping motion. Repeat 5-10 times, increasing speed as you do so."],"img":"fe-Dynamic_Chest_Stretch.jpg","ty":"mob"},{"id":"fe-Elbow_Circles","n":"elbow circles","bp":"shoulders","eq":"body weight","tg":"delts","mg":"traps","sm":["traps"],"st":["Sit or stand with your feet slightly apart.","Place your hands on your shoulders with your elbows at shoulder level and pointing out.","Slowly make a circle with your elbows. Breathe out as you start the circle and breathe in as you complete the circle."],"img":"fe-Elbow_Circles.jpg","ty":"mob"},{"id":"fe-Elbows_Back","n":"elbows back","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders"],"st":["Stand up straight.","Place both hands on your lower back, fingers pointing downward and elbows out.","Then gently pull your elbows back aiming to touch them together."],"img":"fe-Elbows_Back.jpg","ty":"mob"},{"id":"fe-Extended_Range_One-Arm_Kettlebell_Floor_Press","n":"extended range one-arm kettlebell floor press","bp":"chest","eq":"kettlebell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Lie on the floor and position a kettlebell for one arm to press. The kettlebell should be held by the handle. The leg on the same side that you are pressing should be bent, with the knee crossing over the midline of the body.","Press the kettlebell by extending the elbow and adducting the arm, pressing it above your body. Return to the starting position."],"img":"fe-Extended_Range_One-Arm_Kettlebell_Floor_Press.jpg","ty":"atl"},{"id":"fe-External_Rotation_with_Band","n":"external rotation with band","bp":"shoulders","eq":"band","tg":"delts","mg":"","sm":[],"st":["Choke the band around a post. The band should be at the same height as your elbow. Stand with your left side to the band a couple of feet away.","Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.","With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting position.","Execute the movement by rotating your arm in a backhand motion, keeping your elbow in place.","Continue as far as you are able, pause, and then return to the starting position."],"img":"fe-External_Rotation_with_Band.jpg","ty":"rin"},{"id":"fe-Fast_Skipping","n":"fast skipping","bp":"upper legs","eq":"body weight","tg":"quads","mg":"abductors","sm":["abductors","adductors","calves","glutes","hamstrings"],"st":["Start in a relaxed position with one leg slightly forward. This will be your starting position.","Skip by executing a step-hop pattern of right-right-step to left-left-step, and so on, alternating back and forth.","Perform fast skips by maintaining close contact with the ground and reduce air time, moving as quickly as possible."],"img":"fe-Fast_Skipping.jpg","ty":"atl"},{"id":"fe-Flat_Bench_Leg_Pull-In","n":"flat bench leg pull-in","bp":"waist","eq":"body weight","tg":"abs","mg":"","sm":[],"st":["Lie on an exercise mat or a flat bench with your legs off the end.","Place your hands either under your glutes with your palms down or by the sides holding on to the bench (or with palms down by the side on an exercise mat). Also extend your legs straight out. This will be your starting position.","Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue this movement until your knees are near your chest. Hold the contracted position for a second.","As you breathe in, slowly return to the starting position.","Repeat for the recommended amount of repetitions."],"img":"fe-Flat_Bench_Leg_Pull-In.jpg","ty":"atl"},{"id":"fe-Flat_Bench_Lying_Leg_Raise","n":"flat bench lying leg raise","bp":"waist","eq":"body weight","tg":"abs","mg":"","sm":[],"st":["Lie with your back flat on a bench and your legs extended in front of you off the end.","Place your hands either under your glutes with your palms down or by the sides holding on to the bench. This will be your starting position.","As you keep your legs extended, straight as possible with your knees slightly bent but locked raise your legs until they make a 90-degree angle with the floor. Exhale as you perform this portion of the movement and hold the contraction at the top for a second.","Now, as you inhale, slowly lower your legs back down to the starting position."],"img":"fe-Flat_Bench_Lying_Leg_Raise.jpg","ty":"atl"},{"id":"fe-Foot-SMR","n":"foot-smr","bp":"lower legs","eq":"body weight","tg":"calves","mg":"","sm":[],"st":["This exercise stretches the fascia of the muscles in the feet. Start off seated with your shoes removed. Using a foot roller or a similar object, such as a small section of pvc pipe, place your foot against the roller across the arch of your foot. This will be your starting position.","Press down firmly, rolling across the arch of your foot. Hold for 10-30 seconds, and then switch feet."],"img":"fe-Foot-SMR.jpg","ty":"mob"},{"id":"fe-Freehand_Jump_Squat","n":"freehand jump squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings"],"st":["Cross your arms over your chest.","With your head up and your back straight, position your feet at shoulder width.","Keeping your back straight and chest up, squat down as you inhale until your upper thighs are parallel, or lower, to the floor.","Now pressing mainly with the ball of your feet, jump straight up in the air as high as possible, using the thighs like springs. Exhale during this portion of the movement.","When you touch the floor again, immediately squat down and jump again.","Repeat for the recommended amount of repetitions."],"img":"fe-Freehand_Jump_Squat.jpg","ty":"atl"},{"id":"fe-Frog_Hops","n":"frog hops","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings"],"st":["Stand with your hands behind your head, and squat down keeping your torso upright and your head up. This will be your starting position.","Jump forward several feet, avoiding jumping unnecessarily high. As your feet contact the ground, absorb the impact through your legs, and jump again. Repeat this action 5-10 times."],"img":"fe-Frog_Hops.jpg","ty":"mob"},{"id":"fe-Frog_Sit-Ups","n":"frog sit-ups","bp":"waist","eq":"body weight","tg":"abs","mg":"","sm":[],"st":["Lie with your back flat on the floor (or exercise mat) and your legs extended in front of you.","Now bend at the knees and place your outer thighs by the floor (or mat) as you make the soles of your feet touch each other.","Now try pushing both soles and bringing them up as near you as possible while you keep the outer thighs on the floor (or at least almost touching it). Tip: In this position your legs should create a diamond shape.","Now, cross your arms in front of you by touching the opposite shoulders. This will be your starting position.","As you exhale flatten your lower back to the floor while curling the torso upwards. Tip: This will be like performing the first 1/4 movement of a sit up. Hold at the top position for a second.","As you inhale, slowly lower back to the starting position.","Repeat for the recommended amount of repetitions."],"img":"fe-Frog_Sit-Ups.jpg","ty":"atl"},{"id":"fe-Front_Box_Jump","n":"front box jump","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"abductors","sm":["abductors","adductors","calves","glutes","quadriceps"],"st":["Begin with a box of an appropriate height 1-2 feet in front of you. Stand with your feet should width apart. This will be your starting position.","Perform a short squat in preparation for jumping, swinging your arms behind you.","Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up.","Land on the box with the knees bent, absorbing the impact through the legs. You can jump from the box back to the ground, or preferably step down one leg at a time."],"img":"fe-Front_Box_Jump.jpg","ty":"atl"},{"id":"fe-Front_Cone_Hops_or_hurdle_hops","n":"front cone hops (or hurdle hops)","bp":"upper legs","eq":"body weight","tg":"quads","mg":"abductors","sm":["abductors","adductors","calves","glutes","hamstrings"],"st":["Set up a row of cones or other small barriers, placing them a few feet apart.","Stand in front of the first cone with your feet shoulder width apart. This will be your starting position.","Begin by jumping with both feet over the first cone, swinging both arms as you jump.","Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next cone.","Continue until you have jumped over all of the cones."],"img":"fe-Front_Cone_Hops_or_hurdle_hops.jpg","ty":"atl"},{"id":"fe-Front_Leg_Raises","n":"front leg raises","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"","sm":[],"st":["Stand next to a chair or other support, holding on with one hand.","Swing your leg forward, keeping the leg straight. Continue with a downward swing, bringing the leg as far back as your flexibility allows. Repeat 5-10 times, and then switch legs."],"img":"fe-Front_Leg_Raises.jpg","ty":"mob"},{"id":"fe-Front_Squats_With_Two_Kettlebells","n":"front squats with two kettlebells","bp":"upper legs","eq":"kettlebell","tg":"quads","mg":"calves","sm":["calves","glutes"],"st":["Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so.","Looking straight ahead at all times, squat as low as you can and pause at the bottom. As you squat down, push your knees out. You should squat between your legs, keeping an upright torso, with your head and chest up.","Rise back up by driving through your heels and repeat."],"img":"fe-Front_Squats_With_Two_Kettlebells.jpg","ty":"atl"},{"id":"fe-Glute_Kickback","n":"glute kickback","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings"],"st":["Kneel on the floor or an exercise mat and bend at the waist with your arms extended in front of you (perpendicular to the torso) in order to get into a kneeling push-up position but with the arms spaced at shoulder width. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.","As you exhale, lift up your right leg until the hamstrings are in line with the back while maintaining the 90-degree angle bend. Contract the glutes throughout this movement and hold the contraction at the top for a second. Tip: At the end of the movement the upper leg should be parallel to the floor while the calf should be perpendicular to it.","Go back to the initial position as you inhale and now repeat with the left leg.","Continue to alternate legs until all of the recommended repetitions have been performed."],"img":"fe-Glute_Kickback.jpg","ty":"atl"},{"id":"fe-Goblet_Squat","n":"goblet squat","bp":"upper legs","eq":"kettlebell","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings","shoulders"],"st":["Stand holding a light kettlebell by the horns close to your chest. This will be your starting position.","Squat down between your legs until your hamstrings are on your calves. Keep your chest and head up and your back straight.","At the bottom position, pause and use your elbows to push your knees out. Return to the starting position, and repeat for 10-20 repetitions."],"img":"fe-Goblet_Squat.jpg","ty":"atl"},{"id":"fe-Gorilla_Chin_Crunch","n":"gorilla chin/crunch","bp":"waist","eq":"body weight","tg":"abs","mg":"biceps","sm":["biceps","lats"],"st":["Hang from a chin-up bar using an underhand grip (palms facing you) that is slightly wider than shoulder width.","Now bend your knees at a 90 degree angle so that the calves are parallel to the floor while the thighs remain perpendicular to it. This will be your starting position.","As you exhale, pull yourself up while crunching your knees up at the same time until your knees are at chest level. You will stop going up as soon as your nose is at the same level as the bar. Tip: When you get to this point you should also be finishing the crunch at the same time.","Slowly start to inhale as you return to the starting position.","Repeat for the recommended amount of repetitions."],"img":"fe-Gorilla_Chin_Crunch.jpg","ty":"atl"},{"id":"fe-Groin_and_Back_Stretch","n":"groin and back stretch","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"","sm":[],"st":["Sit on the floor with your knees bent and feet together.","Interlock your fingers behind your head. This will be your starting position.","Curl downwards, bringing your elbows to the inside of your thighs. After a brief pause, return to the starting position with your head up and your back straight. Repeat for 10-20 repetitions."],"img":"fe-Groin_and_Back_Stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-Groiners","n":"groiners","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"","sm":[],"st":["Begin in a pushup position on the floor. This will be your starting position.","Using both legs, jump forward landing with your feet next to your hands. Keep your head up as you do so.","Return to the starting position and immediately repeat the movement, continuing for 10-20 repetitions."],"img":"fe-Groiners.jpg","ty":"mob"},{"id":"fe-Hamstring-SMR","n":"hamstring-smr","bp":"upper legs","eq":"roller","tg":"hamstrings","mg":"","sm":[],"st":["In a seated position, extend your legs over a foam roll so that it is position on the back of the upper legs. Place your hands to the side or behind you to help support your weight. This will be your starting position.","Using your hands, lift your hips off of the floor and shift your weight on the foam roll to one leg. Relax the hamstrings of the leg you are stretching.","Roll over the foam from below the hip to above the back of the knee, pausing at points of tension for 10-30 seconds. Repeat for the other leg."],"img":"fe-Hamstring-SMR.jpg","ty":"mob"},{"id":"fe-Handstand_Push-Ups","n":"handstand push-ups","bp":"shoulders","eq":"body weight","tg":"delts","mg":"triceps","sm":["triceps"],"st":["With your back to the wall bend at the waist and place both hands on the floor at shoulder width.","Kick yourself up against the wall with your arms straight. Your body should be upside down with the arms and legs fully extended. Keep your whole body as straight as possible. Tip: If doing this for the first time, have a spotter help you. Also, make sure that you keep facing the wall with your head, rather than looking down.","Slowly lower yourself to the ground as you inhale until your head almost touches the floor. Tip: It is of utmost importance that you come down slow in order to avoid head injury.","Push yourself back up slowly as you exhale until your elbows are nearly locked.","Repeat for the recommended amount of repetitions."],"img":"fe-Handstand_Push-Ups.jpg","ty":"atl"},{"id":"fe-Heavy_Bag_Thrust","n":"heavy bag thrust","bp":"chest","eq":"body weight","tg":"pectorals","mg":"abdominals","sm":["abdominals","shoulders","triceps"],"st":["Utilize a heavy bag for this exercise. Assume an upright stance next to the bag, with your feet staggered, fairly wide apart. Place your hand on the bag at about chest height. This will be your starting position.","Begin by twisting at the waist, pushing the bag forward as hard as possible. Perform this move quickly, pushing the bag away from your body.","Receive the bag as it swings back by reversing these steps."],"img":"fe-Heavy_Bag_Thrust.jpg","ty":"atl"},{"id":"fe-Hip_Circles_prone","n":"hip circles (prone)","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"adductors","sm":["adductors"],"st":["Position yourself on your hands and knees on the ground. Maintaining good posture, raise one bent knee off of the ground. This will be your starting position.","Keeping the knee in a bent position, rotate the femur in an arc, attempting to make a big circle with your knee.","Perform this slowly for a number of repetitions, and repeat on the other side."],"img":"fe-Hip_Circles_prone.jpg","ty":"mob"},{"id":"fe-Hip_Extension_with_Bands","n":"hip extension with bands","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings"],"st":["Secure one end of the band to the lower portion of a post and attach the other to one ankle.","Facing the attachment point of the band, hold on to the column to stabilize yourself.","Keeping your head and your chest up, move the resisted leg back as far as you can while keeping the knee straight.","Return the leg to the starting position."],"img":"fe-Hip_Extension_with_Bands.jpg","ty":"rin"},{"id":"fe-Hip_Flexion_with_Band","n":"hip flexion with band","bp":"upper legs","eq":"band","tg":"quads","mg":"","sm":[],"st":["Secure one end of the band to the lower portion of a post and attach the other to one ankle.","Face away from the attachment point of the band.","Keeping your head and your chest up, raise your knee up to 90 degrees and pause.","Return the leg to the starting position."],"img":"fe-Hip_Flexion_with_Band.jpg","ty":"rin"},{"id":"fe-Hug_A_Ball","n":"hug a ball","bp":"back","eq":"stability ball","tg":"spine","mg":"calves","sm":["calves","glutes"],"st":["Seat yourself on the floor.","Straddle an exercise ball between both legs and lower your hips down toward the floor.","Hug your arms around the ball to support your body. Adjust your legs so that your feet are flat on the floor and your knees line up over your ankles. Keep a good grip on the ball so it doesn't roll away from you and send you back onto your buttocks."],"img":"fe-Hug_A_Ball.jpg","ty":"mob"},{"id":"fe-Hug_Knees_To_Chest","n":"hug knees to chest","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes"],"st":["Lie down on your back and pull both knees up to your chest.","Hold your arms under the knees, not over (that would put to much pressure on your knee joints).","Slowly pull the knees toward your shoulders. This also stretches your buttocks muscles."],"img":"fe-Hug_Knees_To_Chest.jpg","ty":"stretch","kind":"time"},{"id":"fe-Hurdle_Hops","n":"hurdle hops","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"abductors","sm":["abductors","adductors","calves","glutes","hamstrings"],"st":["Set up a row of hurdles or other small barriers, placing them a few feet apart.","Stand in front of the first hurdle with your feet shoulder width apart. This will be your starting position.","Begin by jumping with both feet over the first hurdle, swinging both arms as you jump.","Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next hurdle. Continue until you have jumped over all of the hurdles."],"img":"fe-Hurdle_Hops.jpg","ty":"atl"},{"id":"fe-Hyperextensions_With_No_Hyperextension_Bench","n":"hyperextensions with no hyperextension bench","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["With someone holding down your legs, slide yourself down to the edge a flat bench until your hips hang off the end of the bench. Tip: Your entire upper body should be hanging down towards the floor. Also, you will be in the same position as if you were on a hyperextension bench but the range of motion will be shorter due to the height of the flat bench vs. that of the hyperextension bench.","With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.","Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you almost touch the floor or you feel a nice stretch on the hamstrings (whichever comes first). Tip: Never round the back as you perform this exercise.","Slowly raise your torso back to the initial position as you exhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury.","Repeat for the recommended amount of repetitions."],"img":"fe-Hyperextensions_With_No_Hyperextension_Bench.jpg","ty":"atl"},{"id":"fe-IT_Band_and_Glute_Stretch","n":"it band and glute stretch","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"","sm":[],"st":["Loop a belt, rope, or band around one of your feet, and swing that leg across your body to the opposite side, keeping the leg extended as you lay on the ground. This will be your starting position.","Keeping your foot off of the floor, pull on the belt, using the tension to pull the toes up. Hold for 10-20 seconds, and repeat on the other side."],"img":"fe-IT_Band_and_Glute_Stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-Iliotibial_Tract-SMR","n":"iliotibial tract-smr","bp":"upper legs","eq":"roller","tg":"abductors","mg":"","sm":[],"st":["Lay on your side, with the bottom leg placed onto a foam roller between the hip and the knee. The other leg can be crossed in front of you.","Place as much of your weight as is tolerable onto your bottom leg; there is no need to keep your bottom leg in contact with the ground. Be sure to relax the muscles of the leg you are stretching.","Roll your leg over the foam from you hip to your knee, pausing for 10-30 seconds at points of tension. Repeat with the opposite leg."],"img":"fe-Iliotibial_Tract-SMR.jpg","ty":"mob"},{"id":"fe-Incline_Push-Up_Close-Grip","n":"incline push-up close-grip","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.","Place your hands next to one another on the bar.","Position your feet back from the bar with arms and body straight. This will be your starting position.","Keeping your body straight, lower your chest to the bar by bending the arms.","Return to the starting position by extending the elbows, pressing yourself back up."],"img":"fe-Incline_Push-Up_Close-Grip.jpg","ty":"atl"},{"id":"fe-Incline_Push-Up_Medium","n":"incline push-up medium","bp":"chest","eq":"body weight","tg":"pectorals","mg":"abdominals","sm":["abdominals","shoulders","triceps"],"st":["Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.","Place your hands on the bar, with your hands about shoulder width apart.","Position your feet back from the bar with arms and body straight. This will be your starting position.","Keeping your body straight, lower your chest to the bar by bending the arms.","Return to the starting position by extending the elbows, pressing yourself back up."],"img":"fe-Incline_Push-Up_Medium.jpg","ty":"atl"},{"id":"fe-Incline_Push-Up_Reverse_Grip","n":"incline push-up reverse grip","bp":"chest","eq":"body weight","tg":"pectorals","mg":"abdominals","sm":["abdominals","shoulders","triceps"],"st":["Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.","Place your hands on the bar palms up, with your hands about shoulder width apart.","Position your feet back from the bar with arms and body straight. This will be your starting position.","Keeping your body straight, lower your chest to the bar by bending the arms.","Return to the starting position by extending the elbows, pressing yourself back up."],"img":"fe-Incline_Push-Up_Reverse_Grip.jpg","ty":"atl"},{"id":"fe-Incline_Push-Up_Wide","n":"incline push-up wide","bp":"chest","eq":"body weight","tg":"pectorals","mg":"abdominals","sm":["abdominals","shoulders","triceps"],"st":["Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.","Place your hands on the bar, with your hands wider than shoulder width.","Position your feet back from the bar with arms and body straight. Your arms should be perpendicular to the body. This will be your starting position.","Keeping your body straight, lower your chest to the bar by bending the arms.","Return to the starting position by extending the elbows, pressing yourself back up."],"img":"fe-Incline_Push-Up_Wide.jpg","ty":"atl"},{"id":"fe-Intermediate_Groin_Stretch","n":"intermediate groin stretch","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"","sm":[],"st":["Lie on your back with your legs extended. Loop a belt, rope, or band around one of your feet, and swing that leg as far to the side as you can. This will be your starting position.","Pull gently on the belt to create tension in your groin and hamstring muscles. Hold for 10-20 seconds, and repeat on the other side."],"img":"fe-Intermediate_Groin_Stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-Internal_Rotation_with_Band","n":"internal rotation with band","bp":"shoulders","eq":"band","tg":"delts","mg":"","sm":[],"st":["Choke the band around a post. The band should be at the same height as your elbow. Stand with your right side to the band a couple of feet away.","Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.","With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching away from your torso. This will be your starting position.","Execute the movement by rotating your arm in a forehand motion, keeping your elbow in place.","Continue as far as you are able, pause, and then return to the starting position."],"img":"fe-Internal_Rotation_with_Band.jpg","ty":"rin"},{"id":"fe-Iron_Crosses_stretch","n":"iron crosses (stretch)","bp":"upper legs","eq":"body weight","tg":"quads","mg":"","sm":[],"st":["Lie face down on the floor, with your arms extended out to your side, palms pressed to the floor. This will be your starting position.","To begin, flex one knee and bring that leg across the back of your body, attempting to touch it to the ground near the opposite hand.","Promptly return the leg to the starting postion, and quickly repeat with the other leg. Continue alternating for 10-20 repetitions."],"img":"fe-Iron_Crosses_stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-Isometric_Chest_Squeezes","n":"isometric chest squeezes","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["While either seating or standing, bend your arms at a 90-degree angle and place the palms of your hands together in front of your chest. Tip: Your hands should be open with the palms together and fingers facing forward (perpendicular to your torso).","Push both hands against each other as you contract your chest. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.","Hold for the recommended number of seconds.","Now release the tension slowly.","Rest for the recommended amount of time and repeat."],"img":"fe-Isometric_Chest_Squeezes.jpg","ty":"atl"},{"id":"fe-Isometric_Neck_Exercise_-_Front_And_Back","n":"isometric neck exercise - front and back","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"","sm":[],"st":["With your head and neck in a neutral position (normal position with head erect facing forward), place both of your hands on the front side of your head.","Now gently push forward as you contract the neck muscles but resisting any movement of your head. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.","Hold for the recommended number of seconds.","Now release the tension slowly.","Rest for the recommended amount of time and repeat with your hands placed on the back side of your head."],"img":"fe-Isometric_Neck_Exercise_-_Front_And_Back.jpg","ty":"atl"},{"id":"fe-Isometric_Neck_Exercise_-_Sides","n":"isometric neck exercise - sides","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"","sm":[],"st":["With your head and neck in a neutral position (normal position with head erect facing forward), place your left hand on the left side of your head.","Now gently push towards the left as you contract the left neck muscles but resisting any movement of your head. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.","Hold for the recommended number of seconds.","Now release the tension slowly.","Rest for the recommended amount of time and repeat with your right hand placed on the right side of your head."],"img":"fe-Isometric_Neck_Exercise_-_Sides.jpg","ty":"atl"},{"id":"fe-Kettlebell_Dead_Clean","n":"kettlebell dead clean","bp":"upper legs","eq":"kettlebell","tg":"hamstrings","mg":"calves","sm":["calves","glutes","lower back","quadriceps","traps"],"st":["Place kettlebell between your feet. To get in the starting position, push your butt back and look straight ahead.","Clean the kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so.","Lower the kettlebell, keeping the hamstrings loaded by keeping your back straight and your butt out."],"img":"fe-Kettlebell_Dead_Clean.jpg","ty":"atl"},{"id":"fe-Kettlebell_One-Legged_Deadlift","n":"kettlebell one-legged deadlift","bp":"upper legs","eq":"kettlebell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back"],"st":["Hold a kettlebell by the handle in one hand. Stand on one leg, on the same side that you hold the kettlebell.","Keeping that knee slightly bent, perform a stiff legged deadlift by bending at the hip, extending your free leg behind you for balance.","Continue lowering the kettlebell until you are parallel to the ground, and then return to the upright position."],"img":"fe-Kettlebell_One-Legged_Deadlift.jpg","ty":"atl"},{"id":"fe-Kettlebell_Pass_Between_The_Legs","n":"kettlebell pass between the legs","bp":"waist","eq":"kettlebell","tg":"abs","mg":"glutes","sm":["glutes","hamstrings","shoulders"],"st":["Place one kettlebell between your legs and take a comfortable stance. Bend over by pushing your butt out and keeping your back flat.","Pick up a kettlebell and pass it to your other hand between your legs, in the fashion of a \"W\". Go back and forth for several repetitions."],"img":"fe-Kettlebell_Pass_Between_The_Legs.jpg","ty":"atl"},{"id":"fe-Kettlebell_Pirate_Ships","n":"kettlebell pirate ships","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"abdominals","sm":["abdominals"],"st":["With a wide stance, hold a kettlebell with both hands. Allow it to hang at waist level with your arms extended. This will be your starting position.","Initiate the movement by turning to one side, swinging the kettlebell to head height. Briefly pause at the top of the motion.","Allow the bell to drop as you rotate to the opposite side, again raising the kettlebell to head height.","Repeat for the desired amount of repetitions."],"img":"fe-Kettlebell_Pirate_Ships.jpg","ty":"atl"},{"id":"fe-Kettlebell_Turkish_Get-Up_Lunge_style","n":"kettlebell turkish get-up (lunge style)","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"abdominals","sm":["abdominals","hamstrings","quadriceps","triceps"],"st":["Lie on your back on the floor and press a kettlebell to the top position by extending the elbow. Bend the knee on the same side as the kettlebell.","Keeping the kettlebell locked out at all times, pivot to the opposite side and use your non- working arm to assist you in driving forward to the lunge position. Using your free hand, push yourself to a seated position, then progressing to one knee.","While looking up at the kettlebell, slowly stand up. Reverse the motion back to the starting position and repeat."],"img":"fe-Kettlebell_Turkish_Get-Up_Lunge_style.jpg","ty":"atl"},{"id":"fe-Knee_Across_The_Body","n":"knee across the body","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"abductors","sm":["abductors","lower back"],"st":["Lie down on the floor with your right leg straight. Bend your left leg and lower it across your body, holding the knee down toward the floor with your right hand. (The knee doesn't need to touch the floor if you're tight.)","Place your left arm comfortably beside you and turn your head to the left. Imagine you have a weight tied to your tailbone. let your tailbone fall back toward the floor as your chest reaches in the opposite direction to stretch your lower back. Switch sides."],"img":"fe-Knee_Across_The_Body.jpg","ty":"mob"},{"id":"fe-Knee_Circles","n":"knee circles","bp":"lower legs","eq":"body weight","tg":"calves","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Stand with your legs together and hands by your waist.","Now move your knees in a circular motion as you breathe normally.","Repeat for the recommended amount of repetitions."],"img":"fe-Knee_Circles.jpg","ty":"mob"},{"id":"fe-Knee_Tuck_Jump","n":"knee tuck jump","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"abductors","sm":["abductors","adductors","calves","glutes","quadriceps"],"st":["Begin in a comfortable standing position with your knees slightly bent. Hold your hands in front of you, palms down with your fingertips together at chest height. This will be your starting position.","Rapidly dip down into a quarter squat and immediately explode upward. Drive the knees towards the chest, attempting to touch them to the palms of the hands.","Jump as high as you can, raising your knees up, and then ensure a good land be re-extending your legs, absorbing impact through be allowing the knees to rebend."],"img":"fe-Knee_Tuck_Jump.jpg","ty":"atl"},{"id":"fe-Kneeling_Arm_Drill","n":"kneeling arm drill","bp":"shoulders","eq":"body weight","tg":"delts","mg":"abdominals","sm":["abdominals"],"st":["This drill helps increase arm efficiency during the run. Begin kneeling, left foot in front, right knee down. Apply pressure through the front heel to keep your glutes and hamstrings activated.","Begin by blocking the arms in long, pendulum like swings. Close the arm angle, blocking with the arms as you would when jogging, progressing to a run and finally a sprint.","As soon as your hands pass the hip, accelerate them forward during the sprinting motion to move them as quickly as possible.","Switch knees and repeat."],"img":"fe-Kneeling_Arm_Drill.jpg","ty":"atl"},{"id":"fe-Kneeling_Forearm_Stretch","n":"kneeling forearm stretch","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"","sm":[],"st":["Start by kneeling on a mat with your palms flat and your fingers pointing back toward your knees.","Slowly lean back keeping your palms flat on the floor until you feel a stretch in your wrists and forearms. Hold for 20-30 seconds."],"img":"fe-Kneeling_Forearm_Stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-Kneeling_Hip_Flexor","n":"kneeling hip flexor","bp":"upper legs","eq":"body weight","tg":"quads","mg":"quadriceps","sm":["quadriceps"],"st":["Kneel on a mat and bring your right knee up so the bottom of your foot is on the floor and extend your left leg out behind you so the top of your foot is on the floor.","Shift your weight forward until you feel a stretch in your hip. Hold for 15 seconds, then repeat for your other side."],"img":"fe-Kneeling_Hip_Flexor.jpg","ty":"stretch","kind":"time"},{"id":"fe-Lateral_Bound","n":"lateral bound","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"abductors","sm":["abductors","calves","glutes","hamstrings","quadriceps"],"st":["Assume a half squat position facing 90 degrees from your direction of travel. This will be your starting position.","Allow your lead leg to do a countermovement inward as you shift your weight to the outside leg.","Immediately push off and extend, attempting to bound to the side as far as possible.","Upon landing, immediately push off in the opposite direction, returning to your original start position.","Continue back and forth for several repetitions."],"img":"fe-Lateral_Bound.jpg","ty":"atl"},{"id":"fe-Lateral_Box_Jump","n":"lateral box jump","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"abductors","sm":["abductors","calves","glutes","hamstrings","quadriceps"],"st":["Assume a comfortable standing position, with a short box positioned next to you. This will be your starting position.","Quickly dip into a quarter squat to initiate the stretch reflex, and immediately reverse direction to jump up and to the side.","Bring your knees high enough to ensure your feet have good clearance over the box.","Land on the center of the box, using your legs to absorb the impact.","Carefully jump down to the other side of the box, and continue going back and forth for several repetitions."],"img":"fe-Lateral_Box_Jump.jpg","ty":"atl"},{"id":"fe-Lateral_Cone_Hops","n":"lateral cone hops","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"abductors","sm":["abductors","calves","glutes","hamstrings","quadriceps"],"st":["Position a number of cones in a row several feet apart.","Stand next to the end of the cones, facing 90 degrees to the direction of travel. This will be your starting position.","Begin the jump by dipping with the knees to initiate a stretch reflex, and immediately reverse direction to push off the ground, jumping up and sideways over the cone.","Use your legs to absorb impact upon landing, and rebound into the next jump, continuing down the row of cones."],"img":"fe-Lateral_Cone_Hops.jpg","ty":"atl"},{"id":"fe-Lateral_Raise_-_With_Bands","n":"lateral raise - with bands","bp":"shoulders","eq":"band","tg":"delts","mg":"","sm":[],"st":["To begin, stand on an exercise band so that tension begins at arm's length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on the sides of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.","Use your side shoulders to lift the handles to the sides as you exhale. Continue to lift the handles until they are slightly above parallel. Tip: As you lift the handles, slightly tilt the hand as if you were pouring water and keep your arms extended. Also, keep your torso stationary and pause for a second at the top of the movement.","Lower the handles back down slowly to the starting position. Inhale as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."],"img":"fe-Lateral_Raise_-_With_Bands.jpg","ty":"rin"},{"id":"fe-Latissimus_Dorsi-SMR","n":"latissimus dorsi-smr","bp":"back","eq":"roller","tg":"lats","mg":"","sm":[],"st":["While lying on the floor, place a foam roll under your back and to one side, just behind your arm pit. This will be your starting position.","Keep the arm of the side being stretched behind and to the side of you as you shift your weight onto your lats, keeping your upper body off of the ground. Hold for 10-30 seconds, and switch sides."],"img":"fe-Latissimus_Dorsi-SMR.jpg","ty":"mob"},{"id":"fe-Leg-Over_Floor_Press","n":"leg-over floor press","bp":"chest","eq":"kettlebell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Lie on the floor with one kettlebell in place on your chest, holding it by the handle. Extend leg on working side over leg on non-working side.Your free arm can be extended out to your side for support.","Press the kettlebll into a locked out position.","Lower the weight until the elbow touches the ground, keeping the kettlebell above the elbow. Repeat for the desired number of repetitions."],"img":"fe-Leg-Over_Floor_Press.jpg","ty":"atl"},{"id":"fe-Leg_Lift","n":"leg lift","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings"],"st":["While standing up straight with both feet next to each other at around shoulder width, grab a sturdy surface such as the sides of a squat rack or the top of a chair to brace yourself and keep balance.","With or without an ankle weight, lift one leg behind you as if performing a leg curl but standing up while keeping the other leg straight. Breathe out as you perform this movement.","Slowly bring the raised leg back to the floor as you breathe in.","Repeat for the recommended amount of repetitions.","Repeat the movement with the opposite leg."],"img":"fe-Leg_Lift.jpg","ty":"atl"},{"id":"fe-Leg_Pull-In","n":"leg pull-in","bp":"waist","eq":"body weight","tg":"abs","mg":"","sm":[],"st":["Lie on an exercise mat with your legs extended and your hands either palms facing down next to you or under your glutes. Tip: My preference is with the hands next to me. This will be your starting position.","Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue the motion until your knees are around chest level. Contract your abs as you execute this movement and hold for a second at the top. Tip: As you perform the motion, the lower legs (calves) should always remain parallel to the floor.","Return to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"img":"fe-Leg_Pull-In.jpg","ty":"atl"},{"id":"fe-Linear_3-Part_Start_Technique","n":"linear 3-part start technique","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","quadriceps"],"st":["This drill helps you accelerate as quickly as possible into a sprint from a dead stop. It helps to use a line to start from. Begin with two feet on the line. Place your left foot with the toe next to your right ankle. Place your right foot 4-6 inches behind the left.","Place your right hand onto the line, and thing bring your nose close to your left knee.","Squat down as you lean foward, your head being lower than your hips and your weight loaded onto the left leg. This will be your starting position.","Take your left hand up so that it is parallel to the ground, pointing behind you, and explode out when ready."],"img":"fe-Linear_3-Part_Start_Technique.jpg","ty":"atl"},{"id":"fe-Linear_Acceleration_Wall_Drill","n":"linear acceleration wall drill","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","glutes","quadriceps"],"st":["Lean at around 45 degrees against a wall. Your feet should be together, glutes contracted.","Begin by lifting your right knee quickly, pausing, and then driving it straight down into the ground.","Switch legs, raising the opposite knee, and then attacking the ground straight down.","Repeat once more with your right leg, and as soon as the right foot strikes the ground hammer them out rapidly, alternating left and right as fast as you can."],"img":"fe-Linear_Acceleration_Wall_Drill.jpg","ty":"atl"},{"id":"fe-Linear_Depth_Jump","n":"linear depth jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings"],"st":["You will need two boxes or benches spaced a few feet away from each other. Begin by standing on one box facing towards the other platform.","To initiate the movement, gently drop down to the ground between your platforms, allowing the knees and hips to flex.","Reverse the motion by exploding, extending through the hips, knees, and ankles to jump onto the other platform.","Land softly, asborbing the impact through the legs."],"img":"fe-Linear_Depth_Jump.jpg","ty":"atl"},{"id":"fe-Looking_At_Ceiling","n":"looking at ceiling","bp":"upper legs","eq":"body weight","tg":"quads","mg":"","sm":[],"st":["Kneel on the floor, holding your heels with both hands.","Lift your buttocks up and forward while bringing your head back to look up at the ceiling, to give an arch in your back."],"img":"fe-Looking_At_Ceiling.jpg","ty":"mob"},{"id":"fe-Lower_Back-SMR","n":"lower back-smr","bp":"back","eq":"roller","tg":"spine","mg":"","sm":[],"st":["In a seated position, place a foam roll under your lower back. Cross your arms in front of you and protract your shoulders. This will be your starting position.","Raise your hips off of the floor and lean back, keeping your weight on your lower back. Now shift your weight slightly to one side, keeping your weight off of the spine and on the muscles to the side of it. Roll over your lower back, holding points of tension for 10-30 seconds. Repeat on the other side."],"img":"fe-Lower_Back-SMR.jpg","ty":"mob"},{"id":"fe-Lunge_Pass_Through","n":"lunge pass through","bp":"upper legs","eq":"kettlebell","tg":"hamstrings","mg":"calves","sm":["calves","glutes","quadriceps"],"st":["Stand with your torso upright holding a kettlebell in your right hand. This will be your starting position.","Step forward with your left foot and lower your upper body down by flexing the hip and the knee, keeping the torso upright. Lower your back knee until it nearly touches the ground.","As you lunge, pass the kettlebell under your front leg to your opposite hand.","Pressing through the heel of your foot, return to the starting position.","Repeat the movement for the recommended amount of repetitions, alternating legs."],"img":"fe-Lunge_Pass_Through.jpg","ty":"atl"},{"id":"fe-Lying_Bent_Leg_Groin","n":"lying bent leg groin","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"","sm":[],"st":["Lie on your back with your knees bent and the soles of the feet pressed together. Have your partner hold your knees. This will be your starting position.","Attempt to squeeze your knees together, while your partner prevents any movement from occurring.","After 10-20 seconds, relax your muscles as your partner gently pushes your knees towards the floor. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching."],"img":"fe-Lying_Bent_Leg_Groin.jpg","ty":"stretch","kind":"time"},{"id":"fe-Lying_Crossover","n":"lying crossover","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"","sm":[],"st":["Lie on your back with your legs extended.","Cross one leg over your body with the knee bent, attempting to touch the knee to the ground. Your partner should kneel beside you, holding your shoulder down with one hand and controlling the crossed leg with the other. this will be your starting position.","Attempt to raise the bent knee off of the ground as your partner prevents any actual movement.","After 10-20 seconds, relax the leg as your partner gently presses the knee towards the floor. Repeat with the other side."],"img":"fe-Lying_Crossover.jpg","ty":"mob"},{"id":"fe-Lying_Glute","n":"lying glute","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"abductors","sm":["abductors"],"st":["Lie on your back with your partner kneeling beside you.","Flex the hip of one leg, raising it off of the floor. Rotate the leg so the foot is over the opposite hip, the lower leg perpendicular to your body. Your partner should hold the knee and ankle in place. This will be your starting position.","Attempt to push your leg towards your partner, who should be preventing any actual movement of the leg.","After 10-20 seconds, completely relax as your partner gently pushes the ankle and knee towards your chest. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching."],"img":"fe-Lying_Glute.jpg","ty":"stretch","kind":"time"},{"id":"fe-Lying_Hamstring","n":"lying hamstring","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves"],"st":["Lie on your back with your legs extended. Your partner should be kneeling beside you. Raise one leg up towards the ceiling and have your partner hold the ankle. Your partner can use their shoulder to brace your leg if necessary. This will be your starting position.","With your partner holding your leg in place, attempt to flex the knee, contracting the hamstrings for 10-20 seconds.","Then relax your leg, allowing your partner to gently push the leg towards your head. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching. Switch sides once complete."],"img":"fe-Lying_Hamstring.jpg","ty":"stretch","kind":"time"},{"id":"fe-Lying_Prone_Quadriceps","n":"lying prone quadriceps","bp":"upper legs","eq":"body weight","tg":"quads","mg":"","sm":[],"st":["Lay face down on the floor with your partner kneeling beside you. Flex one knee and raise that leg off the ground, attempting to touch your glutes with your foot. Your partner should hold the knee and ankle. This will be your starting position.","Attempt to extend your knee while your partner prevents any actual movement.","After 10-20 seconds, relax your muscles as your partner gently pushes the foot towards your glutes, further stretching the quadriceps and hip flexors.","After 10-20 seconds, switch sides."],"img":"fe-Lying_Prone_Quadriceps.jpg","ty":"stretch","kind":"time"},{"id":"fe-Medicine_Ball_Full_Twist","n":"medicine ball full twist","bp":"waist","eq":"medicine ball","tg":"abs","mg":"shoulders","sm":["shoulders"],"st":["For this exercise you will need a medicine ball and a partner. Stand back to back with your partner, spaced 2-3 feet apart. This will be your starting position.","Hold the ball in front of the trunk. Open the hips and turn the shoulders at the same time as your partner.","For full rotation, you and your partner should twist in the same direction, i.e. counter-clockwise.","Pass the ball to your partner, and both of you can now twist in the opposite direction to repeat the procedure."],"img":"fe-Medicine_Ball_Full_Twist.jpg","ty":"atl"},{"id":"fe-Medicine_Ball_Scoop_Throw","n":"medicine ball scoop throw","bp":"shoulders","eq":"medicine ball","tg":"delts","mg":"abdominals","sm":["abdominals","hamstrings","quadriceps"],"st":["Assume a semisquat stance with a medicine ball in your hands. Your arms should hang so the ball is near your feet.","Begin by thrusting the hips forward as you extend through the legs, jumping up.","As you do, swing your arms up and over your head, keeping them extended, releasing the ball at the peak of your movement. The goal is to throw the ball the greatest distance behind you."],"img":"fe-Medicine_Ball_Scoop_Throw.jpg","ty":"atl"},{"id":"fe-Middle_Back_Stretch","n":"middle back stretch","bp":"back","eq":"body weight","tg":"upper back","mg":"abdominals","sm":["abdominals","lats","lower back"],"st":["Stand so your feet are shoulder width apart and your hands are on your hips.","Twist at your waist until you feel a stretch. Hold for 10 to 15 seconds, then twist to the other side."],"img":"fe-Middle_Back_Stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-Mountain_Climbers","n":"mountain climbers","bp":"upper legs","eq":"body weight","tg":"quads","mg":"chest","sm":["chest","hamstrings","shoulders"],"st":["Begin in a pushup position, with your weight supported by your hands and toes. Flexing the knee and hip, bring one leg until the knee is approximately under the hip. This will be your starting position.","Explosively reverse the positions of your legs, extending the bent leg until the leg is straight and supported by the toe, and bringing the other foot up with the hip and knee flexed. Repeat in an alternating fashion for 20-30 seconds."],"img":"fe-Mountain_Climbers.jpg","ty":"atl"},{"id":"fe-Moving_Claw_Series","n":"moving claw series","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","quadriceps"],"st":["This move helps prepare your running form to help you excel at sprinting. As you run, be sure to flex the knee, aiming to kick your glutes as the hip extends.","Reload the quad as the leg moves back forward, attacking the ground on the next step.","Ensure that as you run, you block with the arms, punching through in a rapid 1-2 motion."],"img":"fe-Moving_Claw_Series.jpg","ty":"atl"},{"id":"fe-Natural_Glute_Ham_Raise","n":"natural glute ham raise","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","glutes","lower back"],"st":["Using the leg pad of a lat pulldown machine or a preacher bench, position yourself so that your ankles are under the pads, knees on the seat, and you are facing away from the machine. You should be upright and maintaining good posture.","This will be your starting position. Lower yourself under control until your knees are almost completely straight.","Remaining in control, raise yourself back up to the starting position.","If you are unable to complete a rep, use a band, a partner, or push off of a box to aid in completing a repetition."],"img":"fe-Natural_Glute_Ham_Raise.jpg","ty":"atl"},{"id":"fe-Neck-SMR","n":"neck-smr","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"","sm":[],"st":["Using a muscle roller or a rolling pin, place the roller behind your head and against your neck. Make sure that you do not place the roller directly against the spine, but turned slightly so that the roller is pressed against the muscles to either side of the spine. This will be your starting position.","Starting at the top of your neck, slowly roll down the muscles of your neck, pausing at points of tension for 10-30 seconds."],"img":"fe-Neck-SMR.jpg","ty":"mob"},{"id":"fe-Oblique_Crunches","n":"oblique crunches","bp":"waist","eq":"body weight","tg":"abs","mg":"","sm":[],"st":["Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put one hand beside your head and the other to the side against the floor.","Make sure your feet are elevated and resting on a flat surface.","Now lift the shoulder in which your hand is touching your head.","Simply elevate your shoulder and body upward until you touch your knee. For example, if you have your right hand besides your head, then you want to elevate your body upwards until your right elbow touches your left knee. The same variation can be applied doing the inverse and using your left elbow to touch your right knee.","After your knee touches your elbow, lower your body until you have reached the starting position.","Remember to breathe in during the eccentric (lowering) part of the exercise and to breathe out during the concentric (upward) part of the exercise.","Continue alternating in this manner until all of the recommended repetitions for each side have been completed."],"img":"fe-Oblique_Crunches.jpg","ty":"atl"},{"id":"fe-Oblique_Crunches_-_On_The_Floor","n":"oblique crunches - on the floor","bp":"waist","eq":"body weight","tg":"abs","mg":"","sm":[],"st":["Start out by lying on your right side with your legs lying on top of each other. Make sure your knees are bent a little bit.","Place your left hand behind your head.","Once you are in this set position, begin by moving your left elbow up as you would perform a normal crunch except this time the main emphasis is on your obliques.","Crunch as high as you can, hold the contraction for a second and then slowly drop back down into the starting position.","Remember to breathe in during the eccentric (lowering) part of the exercise and to breathe out during the concentric (elevation) part of the exercise."],"img":"fe-Oblique_Crunches_-_On_The_Floor.jpg","ty":"atl"},{"id":"fe-On-Your-Back_Quad_Stretch","n":"on-your-back quad stretch","bp":"upper legs","eq":"body weight","tg":"quads","mg":"","sm":[],"st":["Lie on a flat bench or step, and hang one leg and arm over the side.","Bend the knee and hold the top of the foot. As you do this, be careful not to arch your lower back.","Pull the belly button to the spine to stay in neutral. Press your foot down and into your hand. To add the hip stretch, lift the hip of the leg you're holding up toward the ceiling.","Switch sides."],"img":"fe-On-Your-Back_Quad_Stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-On_Your_Side_Quad_Stretch","n":"on your side quad stretch","bp":"upper legs","eq":"body weight","tg":"quads","mg":"","sm":[],"st":["Start off by lying on your right side, with your right knee bent at a 90-degree angle resting on the floor in front of you (this stabilizes the torso).","Bend your left knee behind you and hold your left foot with your left hand. To stretch your hip flexor, press your left hip forward as you push your left foot back into your hand. Switch sides."],"img":"fe-On_Your_Side_Quad_Stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-One-Arm_Kettlebell_Clean","n":"one-arm kettlebell clean","bp":"upper legs","eq":"kettlebell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","shoulders","traps"],"st":["Place a kettlebell between your feet. As you bend down to grab the kettlebell, push your butt back and keep your eyes looking forward.","Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so.","Return the weight to the starting position."],"img":"fe-One-Arm_Kettlebell_Clean.jpg","ty":"atl"},{"id":"fe-One-Arm_Kettlebell_Clean_and_Jerk","n":"one-arm kettlebell clean and jerk","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"","sm":[],"st":["Hold a kettlebell by the handle.","Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward.","Dip your body by bending the knees, keeping your torso upright.","Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body's momentum to move the weight.","Receive the weight overhead by returning to a squat position underneath the weight.","Keeping the weight overhead, return to a standing position. Lower the weight to the floor to perform the next repetition."],"img":"fe-One-Arm_Kettlebell_Clean_and_Jerk.jpg","ty":"atl"},{"id":"fe-One-Arm_Kettlebell_Floor_Press","n":"one-arm kettlebell floor press","bp":"chest","eq":"kettlebell","tg":"pectorals","mg":"triceps","sm":["triceps"],"st":["Lie on the floor holding a kettlebell with one hand, with your upper arm supported by the floor. The palm should be facing in.","Press the kettlebell straight up toward the ceiling, rotating your wrist.","Lower the kettlebell back to the starting position and repeat."],"img":"fe-One-Arm_Kettlebell_Floor_Press.jpg","ty":"atl"},{"id":"fe-One-Arm_Kettlebell_Jerk","n":"one-arm kettlebell jerk","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"calves","sm":["calves","quadriceps","triceps"],"st":["Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.","Dip your body by bending the knees, keeping your torso upright.","Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body's momentum to move the weight. Receive the weight overhead by returning to a squat position underneath the weight. Keeping the weight overhead, return to a standing position.","Lower the weight to perform the next repetition."],"img":"fe-One-Arm_Kettlebell_Jerk.jpg","ty":"atl"},{"id":"fe-One-Arm_Kettlebell_Military_Press_To_The_Side","n":"one-arm kettlebell military press to the side","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps"],"st":["Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces inward. This will be your starting position.","Look at the kettlebell and press it up and out until it is locked out overhead.","Lower the kettlebell back to your shoulder under control and repeat. Make sure to contract your lat, butt, and stomach forcefully for added stability and strength."],"img":"fe-One-Arm_Kettlebell_Military_Press_To_The_Side.jpg","ty":"atl"},{"id":"fe-One-Arm_Kettlebell_Para_Press","n":"one-arm kettlebell para press","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps"],"st":["Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.","Hold the kettlebell with the elbow out to the side, and press it up and out until it is locked out overhead.","Lower the kettlebell back to your shoulder under control and repeat. Make sure to contract your lat, butt, and stomach forcefully for added stability and strength."],"img":"fe-One-Arm_Kettlebell_Para_Press.jpg","ty":"atl"},{"id":"fe-One-Arm_Kettlebell_Push_Press","n":"one-arm kettlebell push press","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"calves","sm":["calves","quadriceps","triceps"],"st":["Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.","Dip your body by bending the knees, keeping your torso upright.","Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body's momentum to move the weight. Lower the weight to perform the next repetition."],"img":"fe-One-Arm_Kettlebell_Push_Press.jpg","ty":"atl"},{"id":"fe-One-Arm_Kettlebell_Row","n":"one-arm kettlebell row","bp":"back","eq":"kettlebell","tg":"upper back","mg":"biceps","sm":["biceps","lats"],"st":["Place a kettlebell in front of your feet. Bend your knees slightly and then push your butt out as much as possible as you bend over to get in the starting position. Grab the kettlebell and pull it to your stomach, retracting your shoulder blade and flexing the elbow. Keep your back straight. Lower and repeat."],"img":"fe-One-Arm_Kettlebell_Row.jpg","ty":"atl"},{"id":"fe-One-Arm_Kettlebell_Snatch","n":"one-arm kettlebell snatch","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"calves","sm":["calves","glutes","hamstrings","lower back","traps","triceps"],"st":["Place a kettlebell between your feet. Bend your knees and push your butt back to get in the proper starting position.","Look straight ahead and swing the kettlebell back between your legs.","Immediately reverse the direction and drive through with your hips and knees, accelerating the kettlebell upward. As the kettlebell rises to your shoulder rotate your hand and punch straight up, using momentum to receive the weight locked out overhead."],"img":"fe-One-Arm_Kettlebell_Snatch.jpg","ty":"atl"},{"id":"fe-One-Arm_Kettlebell_Split_Jerk","n":"one-arm kettlebell split jerk","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"glutes","sm":["glutes","hamstrings","quadriceps","triceps"],"st":["Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.","Dip your body by bending the knees, keeping your torso upright.","Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body's momentum to move the weight.","Receive the weight overhead by returning to a squat position underneath the weight, positioning one leg in front of you and one leg behind you.","Keeping the weight overhead, return to a standing position and bring your feet together. Lower the weight to perform the next repetition."],"img":"fe-One-Arm_Kettlebell_Split_Jerk.jpg","ty":"atl"},{"id":"fe-One-Arm_Kettlebell_Split_Snatch","n":"one-arm kettlebell split snatch","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Hold a kettlebell in one hand by the handle.","Squat towards the floor, and then reverse the motion, extending the hips, knees, and finally the ankles, to raise the kettlebell overhead.","After fully extending the body, descend into a lunge position to receive the weights overhead, one leg forward and one leg back. Ensure you drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion.","Return to a standing position, holding the weight overhead, and bring the feet together. Lower the weight to return to the starting position."],"img":"fe-One-Arm_Kettlebell_Split_Snatch.jpg","ty":"atl"},{"id":"fe-One-Arm_Kettlebell_Swings","n":"one-arm kettlebell swings","bp":"upper legs","eq":"kettlebell","tg":"hamstrings","mg":"calves","sm":["calves","glutes","lower back","shoulders"],"st":[],"img":"fe-One-Arm_Kettlebell_Swings.jpg","ty":"atl"},{"id":"fe-One-Arm_Medicine_Ball_Slam","n":"one-arm medicine ball slam","bp":"waist","eq":"medicine ball","tg":"abs","mg":"lats","sm":["lats","shoulders"],"st":["Start in a standing position with a staggered, athletic stance. Hold a medicine ball in one hand, on the same side as your back leg. This will be your starting position.","Begin by winding the arm, raising the medicine ball above your head. As you do so, extend through the hips, knees, and ankles to load up for the slam.","At peak extension, flex the shoulders, spine, and hips to throw the ball hard into the ground directly in front of you.","Catch the ball on the bounce and continue for the desired number of repetitions."],"img":"fe-One-Arm_Medicine_Ball_Slam.jpg","ty":"atl"},{"id":"fe-One-Arm_Open_Palm_Kettlebell_Clean","n":"one-arm open palm kettlebell clean","bp":"upper legs","eq":"kettlebell","tg":"hamstrings","mg":"forearms","sm":["forearms","glutes","lower back","quadriceps","shoulders"],"st":["Place one kettlebell between your feet.","Grab the handle with one hand and raise the kettlebell rapidly, let it flip so that the ball of the kettlebell lands in the palm of your hand.","Throw the kettlebell out in front of you and catch the handle with one hand.","Take the kettlebell to the floor and repeat. Make sure to work both arms."],"img":"fe-One-Arm_Open_Palm_Kettlebell_Clean.jpg","ty":"atl"},{"id":"fe-One-Arm_Overhead_Kettlebell_Squats","n":"one-arm overhead kettlebell squats","bp":"upper legs","eq":"kettlebell","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings","shoulders"],"st":["Clean and press a kettlebell with one arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so. Press the weight overhead by extending through the elbow.This will be your starting position.","Looking straight ahead and keeping a kettlebell locked out above you, flex the knees and hips and lower your torso between your legs, keeping your head and chest up.","Pause at the bottom position for a second before rising back to the top, driving through the heels of your feet."],"img":"fe-One-Arm_Overhead_Kettlebell_Squats.jpg","ty":"atl"},{"id":"fe-One_Half_Locust","n":"one half locust","bp":"upper legs","eq":"body weight","tg":"quads","mg":"abdominals","sm":["abdominals","biceps","chest"],"st":["Lie facedown on the floor.","Put your left hand under your left hipbone to pad your hip and pubic bone.","Bend your right knee so you can hold the foot in your right hand.","Lift the foot in the air and simultaneously lift your shoulders off the floor. This also stretches the right hip flexor and the chest and shoulders. Switch sides. If it doesn't bother your back, you can try it with both arms and legs at the same time."],"img":"fe-One_Half_Locust.jpg","ty":"stretch","kind":"time"},{"id":"fe-One_Handed_Hang","n":"one handed hang","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps"],"st":["Grab onto a chinup bar with one hand, using a pronated grip. Keep your feet on the floor or a step. Allow the majority of your weight to hang from that hand, while keeping your feet on the ground. Hold for 10-20 seconds and switch sides."],"img":"fe-One_Handed_Hang.jpg","ty":"stretch","kind":"time"},{"id":"fe-One_Knee_To_Chest","n":"one knee to chest","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Start off by lying on the floor.","Extend one leg straight and pull the other knee to your chest. Hold under the knee joint to protect the kneecap.","Gently tug that knee toward your nose.","Switch sides. This stretches the buttocks and lower back of the bent leg and the hip flexor of the straight leg."],"img":"fe-One_Knee_To_Chest.jpg","ty":"stretch","kind":"time"},{"id":"fe-Open_Palm_Kettlebell_Clean","n":"open palm kettlebell clean","bp":"upper legs","eq":"kettlebell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","quadriceps","shoulders"],"st":["Place one kettlebell between your feet. Clean the kettlebell by extending through the legs and hips as you raise the kettlebell towards your shoulders.","Release the kettlebell as it comes up, and let it flip so that the ball of the kettlebell lands in the palms of your hands.","Release the kettlebell out in front of you and catch the handle with both hands. Lower the kettlebell to the starting position and repeat."],"img":"fe-Open_Palm_Kettlebell_Clean.jpg","ty":"atl"},{"id":"fe-Overhead_Lat","n":"overhead lat","bp":"back","eq":"body weight","tg":"lats","mg":"triceps","sm":["triceps"],"st":["Sit upright on the floor with your partner behind you. Raise one arm straight up, and flex the elbow, attempting to touch your hand to your back. Your parner should hold your tricep and wrist. This will be your starting position.","Attempt to pull your upper arm to your side as your partner prevents you from doing actually doing so.","After 10-20 seconds, relax the arm and allow your partner to further stretch the lat by applying gentle pressure to the tricep. Hold for 10-20 seconds, and then switch sides."],"img":"fe-Overhead_Lat.jpg","ty":"stretch","kind":"time"},{"id":"fe-Overhead_Slam","n":"overhead slam","bp":"back","eq":"medicine ball","tg":"lats","mg":"","sm":[],"st":["Hold a medine ball with both hands and stand with your feet at shoulder width. This will be your starting position.","Initiate the countermovement by raising the ball above your head and fully extending your body.","Reverse the motion, slamming the ball into the ground directly in front of you as hard as you can.","Receive the ball with both hands on the bounce and repeat the movement."],"img":"fe-Overhead_Slam.jpg","ty":"atl"},{"id":"fe-Overhead_Stretch","n":"overhead stretch","bp":"waist","eq":"body weight","tg":"abs","mg":"chest","sm":["chest","forearms","lats","triceps"],"st":["Standing straight up, lace your fingers together and open your palms to the ceiling. Keep your shoulders down as you extend your arms up.","To create a full torso stretch, pull your tailbone down and stabilize your torso as you do this. Stretch the muscles on both the front and the back of the torso."],"img":"fe-Overhead_Stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-Overhead_Triceps","n":"overhead triceps","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"lats","sm":["lats"],"st":["Sit upright on the floor with your partner behind you. Raise one arm straight up, and flex the elbow, attempting to touch your hand to your back. Your parner should hold your elbow and wrist. This will be your starting position.","Attempt to extend the arm straight into the air as your partner prevents you from doing actually doing so.","After 10-20 seconds, relax the arm and allow your partner to further stretch the tricep by applying gentle pressure to the wrist. Hold for 10-20 seconds, and then switch sides."],"img":"fe-Overhead_Triceps.jpg","ty":"stretch","kind":"time"},{"id":"fe-Peroneals-SMR","n":"peroneals-smr","bp":"lower legs","eq":"roller","tg":"calves","mg":"","sm":[],"st":["Lay on your side, supporting your weight on your forearm and on a foam roller placed on the outside of your lower leg. Your upper leg can either be on top of your lower leg, or you can cross it in front of you. This will be your starting position.","Raise your hips off of the ground and begin to roll from below the knee to above the ankle on the side of your leg, pausing at points of tension for 10-30 seconds. Repeat on the other leg."],"img":"fe-Peroneals-SMR.jpg","ty":"mob"},{"id":"fe-Piriformis-SMR","n":"piriformis-smr","bp":"upper legs","eq":"roller","tg":"glutes","mg":"","sm":[],"st":["Sit with your buttocks on top of a foam roll. Bend your knees, and then cross one leg so that the ankle is over the knee. This will be your starting position.","Shift your weight to the side of the crossed leg, rolling over the buttocks until you feel tension in your upper glute. You may assist the stretch by using one hand to pull the bent knee towards your chest. Hold this position for 10-30 seconds, and then switch sides."],"img":"fe-Piriformis-SMR.jpg","ty":"mob"},{"id":"fe-Plank","n":"plank","bp":"waist","eq":"body weight","tg":"abs","mg":"","sm":[],"st":["Get into a prone position on the floor, supporting your weight on your toes and your forearms. Your arms are bent and directly below the shoulder.","Keep your body straight at all times, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised."],"img":"fe-Plank.jpg","ty":"atl"},{"id":"fe-Plyo_Kettlebell_Pushups","n":"plyo kettlebell pushups","bp":"chest","eq":"kettlebell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Place a kettlebell on the floor. Place yourself in a pushup position, on your toes with one hand on the ground and one hand holding the kettlebell, with your elbows extended. This will be your starting position.","Begin by lowering yourself as low as you can, keeping your back straight.","Quickly and forcefully reverse direction, pushing yourself up to the other side of the kettlebell, switching hands as you do so. Continue the movement by descending and repeating the movement back and forth."],"img":"fe-Plyo_Kettlebell_Pushups.jpg","ty":"atl"},{"id":"fe-Pullups","n":"pullups","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","middle back"],"st":["Grab the pull-up bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.","As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.","After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.","Repeat this motion for the prescribed amount of repetitions."],"img":"fe-Pullups.jpg","ty":"atl"},{"id":"fe-Push-Up_Wide","n":"push-up wide","bp":"chest","eq":"body weight","tg":"pectorals","mg":"abdominals","sm":["abdominals","shoulders","triceps"],"st":["With your hands wide apart, support your body on your toes and hands in a plank position. Your elbows should be extended and your body straight. Do not allow your hips to sag. This will be your starting position.","To begin, allow the elbows to flex, lowering your chest to the floor as you inhale.","Using your pectoral muscles, press your upper body back up to the starting position by extending the elbows. Exhale as you perform this step.","After pausing at the contracted position, repeat the movement for the prescribed amount of repetitions."],"img":"fe-Push-Up_Wide.jpg","ty":"atl"},{"id":"fe-Push-Ups_-_Close_Triceps_Position","n":"push-ups - close triceps position","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Lie on the floor face down and place your hands closer than shoulder width for a close hand position. Make sure that you are holding your torso up at arms' length.","Lower yourself until your chest almost touches the floor as you inhale.","Using your triceps and some of your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.","After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."],"img":"fe-Push-Ups_-_Close_Triceps_Position.jpg","ty":"atl"},{"id":"fe-Push-Ups_With_Feet_Elevated","n":"push-ups with feet elevated","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Lie on the floor face down and place your hands about 36 inches apart from each other holding your torso up at arms length.","Place your toes on top of a flat bench. This will allow your body to be elevated. Note: The higher the elevation of the flat bench, the higher the resistance of the exercise is.","Lower yourself until your chest almost touches the floor as you inhale.","Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.","After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."],"img":"fe-Push-Ups_With_Feet_Elevated.jpg","ty":"atl"},{"id":"fe-Pushups","n":"pushups","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length.","Next, lower yourself downward until your chest almost touches the floor as you inhale.","Now breathe out and press your upper body back up to the starting position while squeezing your chest.","After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed."],"img":"fe-Pushups.jpg","ty":"atl"},{"id":"fe-Pushups_Close_and_Wide_Hand_Positions","n":"pushups (close and wide hand positions)","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Lie on the floor face down and body straight with your toes on the floor and the hands wider than shoulder width for a wide hand position and closer than shoulder width for a close hand position. Make sure you are holding your torso up at arms length.","Lower yourself until your chest almost touches the floor as you inhale.","Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.","After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."],"img":"fe-Pushups_Close_and_Wide_Hand_Positions.jpg","ty":"atl"},{"id":"fe-Pyramid","n":"pyramid","bp":"back","eq":"stability ball","tg":"spine","mg":"shoulders","sm":["shoulders"],"st":["Start off by rolling your torso forward onto the ball so your hips rest on top of the ball and become the highest point of your body.","Rest your hands and feet on the floor. Your arms and legs can be slightly bent or straight, depending on the size of the ball, your flexibility, and the length of your limbs. This also helps develop stabilizing strength in your torso and shoulders."],"img":"fe-Pyramid.jpg","ty":"stretch","kind":"time"},{"id":"fe-Quad_Stretch","n":"quad stretch","bp":"upper legs","eq":"body weight","tg":"quads","mg":"","sm":[],"st":["Lay on your side. Loop a belt, rope, or band around your top foot. Flex the knee and extend your hip, attempting to touch your glutes with your foot, and holding the belt with your hands. This will be your starting position.","With the belt being held over the shoulder or overhead, gently pull to increase the stretch in the quadriceps. Hold for 10-20 seconds, and then switch sides."],"img":"fe-Quad_Stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-Quadriceps-SMR","n":"quadriceps-smr","bp":"upper legs","eq":"roller","tg":"quads","mg":"","sm":[],"st":["Lay facedown on the floor with your weight supported by your hands or forearms. Place a foam roll underneath one leg on the quadriceps, and keep the foot off of the ground. Make sure to relax the leg as much as possible. This will be your starting position.","Shifting as much weight onto the leg to be stretched as is tolerable, roll over the foam from above the knee to below the hip, holding points of tension for 10-30 seconds. Switch sides."],"img":"fe-Quadriceps-SMR.jpg","ty":"mob"},{"id":"fe-Quick_Leap","n":"quick leap","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","hamstrings"],"st":["You will need a box for this exerise.","Begin facing the box standing 1-2 feet from its edge.","By utilizing your hips, hop onto the box, landing on both legs. Ensure that you land with your legs bent and your feet flat.","Immediately upon landing, fully extend through the entire body and swing your arms overhead to explode off of the box. Use your legs to absorb the impact of landing."],"img":"fe-Quick_Leap.jpg","ty":"atl"},{"id":"fe-Rear_Leg_Raises","n":"rear leg raises","bp":"upper legs","eq":"body weight","tg":"quads","mg":"","sm":[],"st":["Place yourself on your hands knees on an exercise mat. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.","Extend one leg up and behind you. The knee and hip should both extend. Repeat for 5-10 repetitions, and then switch sides."],"img":"fe-Rear_Leg_Raises.jpg","ty":"mob"},{"id":"fe-Return_Push_from_Stance","n":"return push from stance","bp":"shoulders","eq":"medicine ball","tg":"delts","mg":"chest","sm":["chest","triceps"],"st":["You will need a partner for this drill.","Begin in an athletic 2 or 3 point stance.","At the signal, move into a position to receive the pass from your partner.","Catch the medicine ball with both hands and immediately throw it back to your partner.","You can modify this drill by running different routes."],"img":"fe-Return_Push_from_Stance.jpg","ty":"atl"},{"id":"fe-Rhomboids-SMR","n":"rhomboids-smr","bp":"back","eq":"roller","tg":"upper back","mg":"traps","sm":["traps"],"st":["Lay down with your back on the floor. Place a foam roll underneath your upper back, and cross your arms in front of you, protracting your shoulders. This will be your starting position.","Raise your hips off of the ground, placing your weight onto the foam roll. Shift your weight to one side at a time, rolling over your middle and upper back. Pause at points of tension for 10-30 seconds."],"img":"fe-Rhomboids-SMR.jpg","ty":"mob"},{"id":"fe-Rocket_Jump","n":"rocket jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","hamstrings"],"st":["Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body.","To initiate the move, squat down halfway and explode back up as high as possible.","Fully extend your entire body, reaching overhead as far as possible. As you land, absorb your impact through the legs."],"img":"fe-Rocket_Jump.jpg","ty":"atl"},{"id":"fe-Round_The_World_Shoulder_Stretch","n":"round the world shoulder stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"biceps","sm":["biceps","chest"],"st":["Stand up straight with your legs together, holding a bodybar or broomstick.","Hold the pole behind your hips with a wider than shoulder width grip. Your palms should be down and your thumbs facing out.","Slowly lift your arms up behind your head. Don't force it if it gets hard to lift further."],"img":"fe-Round_The_World_Shoulder_Stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-Scissor_Kick","n":"scissor kick","bp":"waist","eq":"body weight","tg":"abs","mg":"","sm":[],"st":["To begin, lie down with your back pressed against the floor or on an exercise mat (optional). Your arms should be fully extended to the sides with your palms facing down. Note: The arms should be stationary the entire time.","With a slight bend at the knees, lift your legs up so that your heels are about 6 inches off the ground. This is the starting position.","Now lift your left leg up to about a 45 degree angle while your right leg is lowered until the heel is about 2-3 inches from the ground.","Switch movements by raising your right leg up and lowering your left leg. Remember to breathe while performing this exercise.","Repeat for the recommended amount of repetitions."],"img":"fe-Scissor_Kick.jpg","ty":"mob"},{"id":"fe-Scissors_Jump","n":"scissors jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings"],"st":["Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground.","Ensure that the front knee is over the midline of the foot. Extending through both legs, jump as high as possible, swinging your arms to gain lift.","As you jump as high as you can, switch the position of your legs, moving your front leg to the back and the rear leg to the front.","As you land, absorb the impact through the legs by adopting the lunge position, and repeat."],"img":"fe-Scissors_Jump.jpg","ty":"atl"},{"id":"fe-Seated_Biceps","n":"seated biceps","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"chest","sm":["chest","shoulders"],"st":["Sit on the floor with your knees bent and your partner standing behind you. Extend your arms straight behind you with your palms facing each other. Your partner will hold your wrists for you. This will be the starting position.","Attempt to flex your elbows, while your partner prevents any actual movement.","After 10-20 seconds, relax your arms while your partner gently pulls your wrists up to stretch your biceps. Be sure to let your partner know when the stretch is appropriate to prevent injury or overstretching."],"img":"fe-Seated_Biceps.jpg","ty":"stretch","kind":"time"},{"id":"fe-Seated_Calf_Stretch","n":"seated calf stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Sit up straight on an exercise mat.","Bend one knee and put that foot on the floor to stabilize the torso.","Straighten your other leg and flex your ankle.","Using a band, towel, or your hand if you can reach, pull the toes toward you. Hold for 10 to 20 seconds, then switch sides."],"img":"fe-Seated_Calf_Stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-Seated_Flat_Bench_Leg_Pull-In","n":"seated flat bench leg pull-in","bp":"waist","eq":"body weight","tg":"abs","mg":"","sm":[],"st":["Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench. Your torso should be leaning backwards around a 45-degree angle from the bench. This will be your starting position.","Bring the knees in toward you as you move your torso closer to them at the same time. Breathe out as you perform this movement.","After a second pause, go back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"img":"fe-Seated_Flat_Bench_Leg_Pull-In.jpg","ty":"atl"},{"id":"fe-Seated_Floor_Hamstring_Stretch","n":"seated floor hamstring stretch","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves"],"st":["Sit on a mat with your right leg extended in front of you and your left leg bent with your foot against your right inner thigh.","Lean forward from your hips and reach for your ankle until you feel a stretch in your hamstring. Hold for 15 seconds, then repeat for your other side."],"img":"fe-Seated_Floor_Hamstring_Stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-Seated_Front_Deltoid","n":"seated front deltoid","bp":"shoulders","eq":"body weight","tg":"delts","mg":"chest","sm":["chest"],"st":["Sit upright on the floor with your legs bent, your partner standing behind you. Stick your arms straight out to your sides, with your palms facing the ground. Attempt to move them as far behind you as possible, as your assistant holds your wrists. This will be your starting position.","Keeping your elbows straight, attempt to move your arms to the front, with your partner gently restraining you to prevent any actual movement for 10-20 seconds.","Now, relax your muscles and allow your partner to gently increase the stretch on the shoulders and chest. Hold for 10 to 20 seconds."],"img":"fe-Seated_Front_Deltoid.jpg","ty":"stretch","kind":"time"},{"id":"fe-Seated_Glute","n":"seated glute","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"adductors","sm":["adductors"],"st":["In a seated position with your knees bent, cross one ankle over the opposite knee. Your partner will stand behind you. Now, lean forward as your partner braces your shoulders with their hands. This will be your starting position.","Attempt to push your torso back for 10-20 seconds, as your partner prevents any actual movement of your torso.","Now relax your muscles as your partner increases the stretch by gently pushing your torso forward for 10-20 seconds."],"img":"fe-Seated_Glute.jpg","ty":"stretch","kind":"time"},{"id":"fe-Seated_Hamstring","n":"seated hamstring","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves"],"st":["In a seated position with your legs extended, have your partner stand behind you. Now, lean forward as your partner braces your shoulders with their hands. This will be your starting position.","Attempt to push your torso back for 10-20 seconds, as your partner prevents any actual movement of your torso.","Now relax your muscles as your partner increases the stretch by gently pushing your torso forward for 10-20 seconds."],"img":"fe-Seated_Hamstring.jpg","ty":"stretch","kind":"time"},{"id":"fe-Seated_Hamstring_and_Calf_Stretch","n":"seated hamstring and calf stretch","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves"],"st":["Loop a belt, rope, or band around one foot. Sit down with both legs extended . This will be your starting position.","Leaning forward slightly, pull on the belt to draw the toes of your foot back. Hold this position for 10-20 seconds and then repeat with the other leg."],"img":"fe-Seated_Hamstring_and_Calf_Stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-Seated_Leg_Tucks","n":"seated leg tucks","bp":"waist","eq":"body weight","tg":"abs","mg":"","sm":[],"st":["Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench. Your torso should be leaning backwards around a 45-degree angle from the bench. This will be your starting position.","Bring the knees in toward you as you move your torso closer to them at the same time. Breathe out as you perform this movement.","After a second pause, go back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"img":"fe-Seated_Leg_Tucks.jpg","ty":"atl"},{"id":"fe-Seated_Overhead_Stretch","n":"seated overhead stretch","bp":"waist","eq":"body weight","tg":"abs","mg":"","sm":[],"st":["Sit up straight on an exercise mat.","Touch the soles of your feet together with your feet six to eight inches in front of your hips.","Place one hand on the floor beside you and your other hand behind your head.","Lift your elbow to the ceiling as you incline your torso to the other side. Hold for 10 to 20 seconds, then switch sides."],"img":"fe-Seated_Overhead_Stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-Shoulder_Circles","n":"shoulder circles","bp":"shoulders","eq":"body weight","tg":"delts","mg":"traps","sm":["traps"],"st":["With shoulders relaxed and arms resting loosely at your sides (or in your lap if you're seated), gently roll your shoulders forward, up, back, and down.","Reverse direction. You can do this exercise alternating shoulders or both at the same time."],"img":"fe-Shoulder_Circles.jpg","ty":"mob"},{"id":"fe-Shoulder_Press_-_With_Bands","n":"shoulder press - with bands","bp":"shoulders","eq":"band","tg":"delts","mg":"triceps","sm":["triceps"],"st":["To begin, stand on an exercise band so that tension begins at arm's length. Grasp the handles and lift them so that the hands are at shoulder height at each side.","Rotate the wrists so that the palms of your hands are facing forward. Your elbows should be bent, with the upper arms and forearms in line to the torso. This is your starting position.","As you exhale, lift the handles up until your arms are fully extended overhead."],"img":"fe-Shoulder_Press_-_With_Bands.jpg","ty":"rin"},{"id":"fe-Shoulder_Raise","n":"shoulder raise","bp":"shoulders","eq":"body weight","tg":"delts","mg":"lats","sm":["lats"],"st":["Relax your arms to your sides and raise your shoulders up toward your ears, then back down."],"img":"fe-Shoulder_Raise.jpg","ty":"mob"},{"id":"fe-Shoulder_Stretch","n":"shoulder stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"","sm":[],"st":["Reach your left arm across your body and hold it straight."],"img":"fe-Shoulder_Stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-Side_Bridge","n":"side bridge","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders"],"st":[],"img":"fe-Side_Bridge.jpg","ty":"atl"},{"id":"fe-Side_Hop-Sprint","n":"side hop-sprint","bp":"upper legs","eq":"body weight","tg":"quads","mg":"abductors","sm":["abductors","adductors","calves","hamstrings"],"st":["Stand to the side of a cone or hurdle.","Begin this drill by hopping sideways over the obstacle, rebounding out of your landing to hop back to where you started.","Hop for a prescribed number or repetitions as quickly as possible, and finish this drill by sprinting a short distance upon landing the last hop."],"img":"fe-Side_Hop-Sprint.jpg","ty":"atl"},{"id":"fe-Side_Jackknife","n":"side jackknife","bp":"waist","eq":"body weight","tg":"abs","mg":"","sm":[],"st":[],"img":"fe-Side_Jackknife.jpg","ty":"atl"},{"id":"fe-Side_Leg_Raises","n":"side leg raises","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"","sm":[],"st":["Stand next to a chair, which you may hold onto as a support. Stand on one leg. This will be your starting position.","Keeping your leg straight, raise it as far out to the side as possible, and swing it back down, allowing it to cross the opposite leg.","Repeat this swinging motion 5-10 times, increasing the range of motion as you do so."],"img":"fe-Side_Leg_Raises.jpg","ty":"mob"},{"id":"fe-Side_Lying_Groin_Stretch","n":"side lying groin stretch","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"hamstrings","sm":["hamstrings"],"st":["Start off by lying on your right side and bend your right knee in front of you to stabilize the torso.","Rest your head on your right hand or shoulder. Lift your left leg upward and hold it by the back of the knee (easier) or the foot (harder).","Pull your left knee in toward your left shoulder and simultaneously press your foot or knee down to the floor. To intensify this stretch, straighten your left leg. Switch sides."],"img":"fe-Side_Lying_Groin_Stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-Side_Neck_Stretch","n":"side neck stretch","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"","sm":[],"st":["Start with your shoulders relaxed, gently tilt your head towards your shoulder.","Assist stretch with a gentle pull on the side of the head."],"img":"fe-Side_Neck_Stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-Side_Standing_Long_Jump","n":"side standing long jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings"],"st":["Begin standing with your feet hip width apart in an athletic stance. Your head and chest should be up, knees and hips slightly bent. This will be your starting position.","Leaning to your right, extend through your hips, knees, and ankles to jump into the air. Block with the arms to lead the movement, jumping as far to your right as you can.","Land facing the same direction with your feet hip width apart, absorbing the impact through your lower body."],"img":"fe-Side_Standing_Long_Jump.jpg","ty":"atl"},{"id":"fe-Side_Wrist_Pull","n":"side wrist pull","bp":"shoulders","eq":"body weight","tg":"delts","mg":"forearms","sm":["forearms","lats"],"st":["This stretch works best standing. Cross your left arm over the midline of your body and hold the left wrist in your right hand down at the level of your hips. Start the stretch with a bent left arm.","Slowly straighten, pull, and lift it up to shoulder height, as pictured. Feel this stretch originate in your back, not your shoulders, and don't pull too hard on the shoulders joint. Switch sides."],"img":"fe-Side_Wrist_Pull.jpg","ty":"stretch","kind":"time"},{"id":"fe-Side_to_Side_Box_Shuffle","n":"side to side box shuffle","bp":"upper legs","eq":"body weight","tg":"quads","mg":"abductors","sm":["abductors","adductors","calves","hamstrings"],"st":["Stand to one side of the box with your left foot resting on the middle of it.","To begin, jump up and over to the other side of the box, landing with your right foot on top of the box and your left foot on the floor. Swing your arms to aid your movement.","Continue shuffling back and forth across the box."],"img":"fe-Side_to_Side_Box_Shuffle.jpg","ty":"atl"},{"id":"fe-Single-Cone_Sprint_Drill","n":"single-cone sprint drill","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings"],"st":["This drill teaches quick foot action. You need a single cone. Begin standing next to the cone with one arm back and one arm forward.","Chop the feet as quickly as possible, blocking with the arms. Circle the cone, keep your knees up, with violent foot action.","Rest after three trips around the cone."],"img":"fe-Single-Cone_Sprint_Drill.jpg","ty":"atl"},{"id":"fe-Single-Leg_Hop_Progression","n":"single-leg hop progression","bp":"upper legs","eq":"body weight","tg":"quads","mg":"abductors","sm":["abductors","adductors","calves","hamstrings"],"st":["Arrange a line of cones in front of you. Assume a relaxed standing position, balanced on one leg. Raise the knee of your opposite leg. This will be your starting position.","Hop forward, jumping and landing with the same leg over the cone.","Use a countermovement jump to hop from cone to cone.","At the end, turn around and go back on the other leg."],"img":"fe-Single-Leg_Hop_Progression.jpg","ty":"atl"},{"id":"fe-Single-Leg_Lateral_Hop","n":"single-leg lateral hop","bp":"upper legs","eq":"body weight","tg":"quads","mg":"abductors","sm":["abductors","adductors","calves","hamstrings"],"st":["Stand to the side of a cone or hurdle. To get into the start position, stand on one leg with your knee slightly bent.","To begin, execute a counterjump to hop sideways over the cone.","Land on your jumping leg, and immediately rebound out of it by jumping back to the start position.","Continue hopping back and forth."],"img":"fe-Single-Leg_Lateral_Hop.jpg","ty":"atl"},{"id":"fe-Single-Leg_Stride_Jump","n":"single-leg stride jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"abductors","sm":["abductors","adductors","calves","hamstrings"],"st":["Stand to the side of a box with your inside foot on top of it, close to the edge.","Begin by swinging the arms upward as you push through the top leg, jumping upward as high as possible. Attempt to drive the opposite knee upward.","Land in the same position that you started, using your inside leg to decelerate the impact."],"img":"fe-Single-Leg_Stride_Jump.jpg","ty":"atl"},{"id":"fe-Single_Leg_Butt_Kick","n":"single leg butt kick","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","hamstrings"],"st":["Begin by standing on one leg, with the bent knee raised. This will be your start position.","Using a countermovement jump, take off upward by extending the hip, knee, and ankle of the grounded leg.","Immediately flex the knee and attempt to touch your butt with the heel of your jumping leg.","Return the leg to a partially bent position underneath the hips and land. Your opposite leg should stay in relatively the same position throughout the drill."],"img":"fe-Single_Leg_Butt_Kick.jpg","ty":"atl"},{"id":"fe-Single_Leg_Glute_Bridge","n":"single leg glute bridge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings"],"st":["Lay on the floor with your feet flat and knees bent.","Raise one leg off of the ground, pulling the knee to your chest. This will be your starting position.","Execute the movement by driving through the heel, extending your hip upward and raising your glutes off of the ground.","Extend as far as possible, pause and then return to the starting position."],"img":"fe-Single_Leg_Glute_Bridge.jpg","ty":"atl"},{"id":"fe-Single_Leg_Push-off","n":"single leg push-off","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","hamstrings"],"st":["Stand on the ground with one foot resting on the box, heel close to the edge.","Push off with your foot on top of the box, trying to gain as much height as possible by extending through the hip and knee.","Land with the same foot on top of the box, returning your other foot back to the start position."],"img":"fe-Single_Leg_Push-off.jpg","ty":"atl"},{"id":"fe-Sit-Up","n":"sit-up","bp":"waist","eq":"body weight","tg":"abs","mg":"","sm":[],"st":["Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.","Place your hands behind your head and lock them together by clasping your fingers. This is the starting position.","Elevate your upper body so that it creates an imaginary V-shape with your thighs. Breathe out when performing this part of the exercise.","Once you feel the contraction for a second, lower your upper body back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions."],"img":"fe-Sit-Up.jpg","ty":"atl"},{"id":"fe-Sit_Squats","n":"sit squats","bp":"upper legs","eq":"body weight","tg":"quads","mg":"abductors","sm":["abductors","glutes","hamstrings"],"st":["Stand with your feet shoulder width apart. This will be your starting position.","Begin the movement by flexing your knees and hips, sitting back with your hips.","Continue until you have squatted a portion of the way down, but are above parallel, and quickly reverse the motion until you return to the starting position. Repeat for 5-10 repetitions."],"img":"fe-Sit_Squats.jpg","ty":"mob"},{"id":"fe-Sledgehammer_Swings","n":"sledgehammer swings","bp":"waist","eq":"body weight","tg":"abs","mg":"calves","sm":["calves","forearms","lats","middle back","shoulders"],"st":["You will need a tire and a sledgehammer for this exercise. Stand in front of the tire about two feet away from it with a staggered stance. Grip the sledgehammer.","If you are right handed, your left hand should be at the bottom of the handle, and your right hand should be choking up closer to the head.","As you bring the sledge up, your right hand slides toward the head; as you swing down, your right hand will slide down to join your left hand. Slam it down as hard as you can against the tire. Control the bounce of the hammer off of the tire.","Repeat on the other side."],"img":"fe-Sledgehammer_Swings.jpg","ty":"atl"},{"id":"fe-Speed_Band_Overhead_Triceps","n":"speed band overhead triceps","bp":"upper arms","eq":"band","tg":"triceps","mg":"","sm":[],"st":["For this exercise anchor a band to the ground. We used an incline bench and anchored the band to the base, standing over the bench. Alternatively, this could be performed standing on the band.","To begin, pull the band behind your head, holding it with a pronated grip and your elbows up. This will be your starting position.","To perform the movement, extend through the elbow to to straighten your arms, ensuring that you keep your upper arm in place.","Pause, and then return to the starting position."],"img":"fe-Speed_Band_Overhead_Triceps.jpg","ty":"rin"},{"id":"fe-Spider_Crawl","n":"spider crawl","bp":"waist","eq":"body weight","tg":"abs","mg":"chest","sm":["chest","shoulders","triceps"],"st":["Begin in a prone position on the floor. Support your weight on your hands and toes, with your feet together and your body straight. Your arms should be bent to 90 degrees. This will be your starting position.","Initiate the movement by raising one foot off of the ground. Externally rotate the leg and bring the knee toward your elbow, as far forward as possible.","Return this leg to the starting position and repeat on the opposite side."],"img":"fe-Spider_Crawl.jpg","ty":"atl"},{"id":"fe-Spinal_Stretch","n":"spinal stretch","bp":"back","eq":"body weight","tg":"upper back","mg":"lats","sm":["lats","lower back","neck","traps"],"st":["Sit in a chair so your back is straight and your feet planted on the floor.","Interlace your fingers behind your head, elbows out and your chin down.","Twist your upper body to one side about 3 times as far as you can. Then lean forward and twist your torso to reach your elbow to the floor on the inside of your knee.","Return to upright position and then repeat for your other side."],"img":"fe-Spinal_Stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-Split_Jump","n":"split jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings"],"st":["Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground.","Ensure that the front knee is over the midline of the foot.","Extending through both legs, jump as high as possible, swinging your arms to gain lift.","As you jump, bring your feet together, and move them back to their initial positions as you land.","Absorb the impact by reverting back to the starting position."],"img":"fe-Split_Jump.jpg","ty":"atl"},{"id":"fe-Squats_-_With_Bands","n":"squats - with bands","bp":"upper legs","eq":"band","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings","lower back"],"st":["To start out, make sure that the exercise band is at an even split between both the left and right side of the body. To do this, use your hands to grab both sides of the band and place both feet in the middle of the band. Your feet should be shoulder width apart from each other.","When holding the bands, they should be the same height on each side. You should be using a pronated grip (palms facing forward) and have the handles of the bands next to your face for this exercise. This is the starting position.","Slowly start to bend the knees and lower the legs so that your thighs are parallel to the floor while exhaling.","Use the heel of your feet to push your body up to the starting position as you exhale.","Repeat for the recommended amount of repetitions."],"img":"fe-Squats_-_With_Bands.jpg","ty":"rin"},{"id":"fe-Standing_Biceps_Stretch","n":"standing biceps stretch","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"chest","sm":["chest","shoulders"],"st":["Clasp your hands behind your back with your palms together, straighten arms and then rotate them so your palms face downward.","Raise your arms up and hold until you feel a stretch in your biceps."],"img":"fe-Standing_Biceps_Stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-Standing_Elevated_Quad_Stretch","n":"standing elevated quad stretch","bp":"upper legs","eq":"body weight","tg":"quads","mg":"","sm":[],"st":["Start by standing with your back about two to three feet away from a bench or step.","Lift one leg behind you and rest your foot on the step,either on your instep or the ball of your foot, whichever you find most comfortable.","Keep your supporting knee slightly bent and avoid letting that knee extend out beyond your toes. Switch sides."],"img":"fe-Standing_Elevated_Quad_Stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-Standing_Gastrocnemius_Calf_Stretch","n":"standing gastrocnemius calf stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"hamstrings","sm":["hamstrings"],"st":["Place your right heel on a step with your knee extended and lean forward to grab your right toe with your right hand. Your left knee should be slightly bent and your back should be straight.","Support your weight on your left leg and place your left hand on your left thigh.","Pull your right toes toward your knee until you feel a stretch in your calf."],"img":"fe-Standing_Gastrocnemius_Calf_Stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-Standing_Hamstring_and_Calf_Stretch","n":"standing hamstring and calf stretch","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"","sm":[],"st":["Being by looping a belt, band, or rope around one foot. While standing, place that foot forward.","Bend your back leg, while keeping the front one straight. Now raise the toes of your front foot off of the ground and lean forward.","Using the belt, pull on the top of the foot to increase the stretch in the calf. Hold for 10-20 seconds and repeat with the other foot."],"img":"fe-Standing_Hamstring_and_Calf_Stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-Standing_Hip_Circles","n":"standing hip circles","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"adductors","sm":["adductors"],"st":["Begin standing on one leg, holding to a vertical support.","Raise the unsupported knee to 90 degrees. This will be your starting position.","Open the hip as far as possible, attempting to make a big circle with your knee.","Perform this movement slowly for a number of repetitions, and repeat on the other side."],"img":"fe-Standing_Hip_Circles.jpg","ty":"mob"},{"id":"fe-Standing_Hip_Flexors","n":"standing hip flexors","bp":"upper legs","eq":"body weight","tg":"quads","mg":"","sm":[],"st":["Stand up straight with the spine vertical, the left foot slightly in front of the right.","Bend both knees and lift the back heel off the floor as you press the right hip forward. You can't get a thorough, deep stretch in this position, however, because it's hard to relax the hip flexor and stand on it at the same time. Switch sides."],"img":"fe-Standing_Hip_Flexors.jpg","ty":"stretch","kind":"time"},{"id":"fe-Standing_Long_Jump","n":"standing long jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings"],"st":["This drill is best done in sand or other soft landing surface. Ensure that you are able to measure distance. Stand in a partial squat stance with feet shoulder width apart.","Utilizing a big arm swing and a countermovement of the legs, jump forward as far as you can.","Attempt to land with your feet out in front you, reaching as far as possible with your legs.","Measure the distance from your landing point to the starting point and track results."],"img":"fe-Standing_Long_Jump.jpg","ty":"atl"},{"id":"fe-Standing_Soleus_And_Achilles_Stretch","n":"standing soleus and achilles stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"","sm":[],"st":["Stand with your feet hip-distance apart, one foot slightly in front of the other.","Bend both knees, keeping your back heel on the floor. Switch sides."],"img":"fe-Standing_Soleus_And_Achilles_Stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-Standing_Toe_Touches","n":"standing toe touches","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves"],"st":["Stand with some space in front and behind you.","Bend at the waist, keeping your legs straight, until you can relax and let your upper body hang down in front of you. Let your arms and hands hang down naturally. Hold for 10 to 20 seconds."],"img":"fe-Standing_Toe_Touches.jpg","ty":"stretch","kind":"time"},{"id":"fe-Standing_Towel_Triceps_Extension","n":"standing towel triceps extension","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"","sm":[],"st":["To begin, stand up with both arms fully extended above the head holding one end of a towel with both hands. Your elbows should be in and the arms perpendicular to the floor with the palms facing each other while your feet should be shoulder width apart from each other. This is the starting position.","Now communicate with your partner so that he/she can grip the other side of the towel to apply resistance. Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.","Go back to the starting position by using the triceps to raise the towel. Breathe out as you perform this step.","Repeat for the recommended amount of repetitions."],"img":"fe-Standing_Towel_Triceps_Extension.jpg","ty":"atl"},{"id":"fe-Standing_Two-Arm_Overhead_Throw","n":"standing two-arm overhead throw","bp":"shoulders","eq":"medicine ball","tg":"delts","mg":"chest","sm":["chest","lats"],"st":["Stand with your feet shoulder width apart holding a medicine ball in both hands. To begin, reach the medicine ball deep behind your head as you bend the knees slightly and lean back.","Violently throw the ball forward, flexing at the hip and using your whole body to complete the movement.","The medicine ball can be thrown to a partner or to a wall, receiving it as it bounces back."],"img":"fe-Standing_Two-Arm_Overhead_Throw.jpg","ty":"atl"},{"id":"fe-Star_Jump","n":"star jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings","shoulders"],"st":["Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body.","To initiate the move, squat down halfway and explode back up as high as possible. Fully extend your entire body, spreading your legs and arms away from the body.","As you land, bring your limbs back in and absorb your impact through the legs."],"img":"fe-Star_Jump.jpg","ty":"atl"},{"id":"fe-Step-up_with_Knee_Raise","n":"step-up with knee raise","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Stand facing a box or bench of an appropriate height with your feet together. This will be your starting position.","Begin the movement by stepping up, putting your left foot on the top of the bench. Extend through the hip and knee of your front leg to stand up on the box. As you stand on the box with your left leg, flex your right knee and hip, bringing your knee as high as you can.","Reverse this motion to step down off the box, and then repeat the sequence on the opposite leg."],"img":"fe-Step-up_with_Knee_Raise.jpg","ty":"atl"},{"id":"fe-Stomach_Vacuum","n":"stomach vacuum","bp":"waist","eq":"body weight","tg":"abs","mg":"","sm":[],"st":["To begin, stand straight with your feet shoulder width apart from each other. Place your hands on your hips. This is the starting position.","Now slowly inhale as much air as possible and then start to exhale as much as possible while bringing your stomach in as much as possible and hold this position. Try to visualize your navel touching your backbone.","One isometric contraction is around 20 seconds. During the 20 second hold, try to breathe normally. Then inhale and bring your stomach back to the starting position.","Once you have practiced this exercise, try to perform this exercise for longer than 20 seconds. Tip: You can work your way up to 40-60 seconds.","Repeat for the recommended amount of sets."],"img":"fe-Stomach_Vacuum.jpg","ty":"mob"},{"id":"fe-Stride_Jump_Crossover","n":"stride jump crossover","bp":"upper legs","eq":"body weight","tg":"quads","mg":"abductors","sm":["abductors","adductors","calves","hamstrings"],"st":["Stand to the side of a box with your inside foot on top of it, close to the edge.","Begin by swinging the arms upward as you push through the top leg, jumping upward as high as possible. Attempt to drive the opposite knee upward.","Land in the opposite position that you started, on the opposite side of the box. The foot that was initially on the box will now be on the ground, with the opposite foot now on the box.","Repeat the movement, crossing back over to the other side."],"img":"fe-Stride_Jump_Crossover.jpg","ty":"atl"},{"id":"fe-Superman","n":"superman","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["To begin, lie straight and face down on the floor or exercise mat. Your arms should be fully extended in front of you. This is the starting position.","Simultaneously raise your arms, legs, and chest off of the floor and hold this contraction for 2 seconds. Tip: Squeeze your lower back to get the best results from this exercise. Remember to exhale during this movement. Note: When holding the contracted position, you should look like superman when he is flying.","Slowly begin to lower your arms, legs and chest back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions prescribed in your program."],"img":"fe-Superman.jpg","ty":"mob"},{"id":"fe-Supine_Chest_Throw","n":"supine chest throw","bp":"upper arms","eq":"medicine ball","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["This drill is great for chest passes when you lack a partner or a wall of sufficient strength. Lay on the ground on your back with your knees bent.","Begin with the ball on your chest, held with both hands on the bottom.","Explode up, extending through the elbow to throw the ball directly above you as high as possible.","Catch the ball with both hands as it comes down."],"img":"fe-Supine_Chest_Throw.jpg","ty":"atl"},{"id":"fe-Supine_One-Arm_Overhead_Throw","n":"supine one-arm overhead throw","bp":"waist","eq":"medicine ball","tg":"abs","mg":"chest","sm":["chest","lats","shoulders"],"st":["Lay on the ground on your back with your knees bent. Hold the ball with one hand, extending the arm fully behind your head. This will be your starting position.","Initiate the movement at the shoulder, throwing the ball directly forward of you as you sit up, attempting to go for maximum distance.","The ball can be thrown to a partner or bounced off of a wall."],"img":"fe-Supine_One-Arm_Overhead_Throw.jpg","ty":"atl"},{"id":"fe-Supine_Two-Arm_Overhead_Throw","n":"supine two-arm overhead throw","bp":"waist","eq":"medicine ball","tg":"abs","mg":"chest","sm":["chest","lats","shoulders"],"st":["Lay on the ground on your back with your knees bent.","Hold the ball with both hands, extending the arms fully behind your head. This will be your starting position.","Initiate the movement at the shoulder, throwing the ball directly forward of you as you sit up, attempting to go for maximum distance.","The ball can be thrown to a partner or bounced off of a wall."],"img":"fe-Supine_Two-Arm_Overhead_Throw.jpg","ty":"atl"},{"id":"fe-The_Straddle","n":"the straddle","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"adductors","sm":["adductors","calves"],"st":["Begin in a seated, upright position. Start by extending your legs in front of you in a V.","With your hands on the floor, lean forward as far as possible. Hold for 10 to 20 seconds."],"img":"fe-The_Straddle.jpg","ty":"stretch","kind":"time"},{"id":"fe-Toe_Touchers","n":"toe touchers","bp":"waist","eq":"body weight","tg":"abs","mg":"","sm":[],"st":["To begin, lie down on the floor or an exercise mat with your back pressed against the floor. Your arms should be lying across your sides with the palms facing down.","Your legs should be touching each other. Slowly elevate your legs up in the air until they are almost perpendicular to the floor with a slight bend at the knees. Your feet should be parallel to the floor.","Move your arms so that they are fully extended at a 45 degree angle from the floor. This is the starting position.","While keeping your lower back pressed against the floor, slowly lift your torso and use your hands to try and touch your toes. Remember to exhale while perform this part of the exercise.","Slowly begin to lower your torso and arms back down to the starting position while inhaling. Remember to keep your arms straight out pointing towards your toes.","Repeat for the recommended amount of repetitions."],"img":"fe-Toe_Touchers.jpg","ty":"mob"},{"id":"fe-Torso_Rotation","n":"torso rotation","bp":"waist","eq":"stability ball","tg":"abs","mg":"","sm":[],"st":["Stand upright holding an exercise ball with both hands. Extend your arms so the ball is straight out in front of you. This will be your starting position.","Rotate your torso to one side, keeping your eyes on the ball as you move. Now, rotate back to the opposite direction. Repeat for 10-20 repetitions."],"img":"fe-Torso_Rotation.jpg","ty":"mob"},{"id":"fe-Tricep_Side_Stretch","n":"tricep side stretch","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Bring right arm across your body and over your left shoulder, holding your elbow with your left hand, until you feel a stretch in your tricep. Then repeat for your other arm."],"img":"fe-Tricep_Side_Stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-Two-Arm_Kettlebell_Clean","n":"two-arm kettlebell clean","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"calves","sm":["calves","glutes","hamstrings","lower back","traps"],"st":["Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.","Clean the kettlebells to your shoulders by extending through the legs and hips as you raise the kettlebells towards your shoulders. Rotate your wrists as you do so.","Lower the kettlebells back to the starting position and repeat."],"img":"fe-Two-Arm_Kettlebell_Clean.jpg","ty":"atl"},{"id":"fe-Two-Arm_Kettlebell_Jerk","n":"two-arm kettlebell jerk","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"calves","sm":["calves","quadriceps","triceps"],"st":["Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you swing the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward. Squat down a few inches and reverse the motion rapidly driving both kettlebells overhead. Immediately after the initial push, squat down again and get under the kettlebells. Once the kettlebells are locked out, stand upright to complete the exercise."],"img":"fe-Two-Arm_Kettlebell_Jerk.jpg","ty":"atl"},{"id":"fe-Two-Arm_Kettlebell_Military_Press","n":"two-arm kettlebell military press","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps"],"st":["Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you swing the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward.","Press the kettlebells up and out. As the kettlebells pass your head, lean into the weights so that the kettlebells are racked behind your head. Make sure to contract your lats, butt, and stomach for added stability."],"img":"fe-Two-Arm_Kettlebell_Military_Press.jpg","ty":"atl"},{"id":"fe-Two-Arm_Kettlebell_Row","n":"two-arm kettlebell row","bp":"back","eq":"kettlebell","tg":"upper back","mg":"biceps","sm":["biceps","lats"],"st":["Place two kettlebells in front of your feet. Bend your knees slightly and then push your butt out as much as possible as you bend over to get in the starting position.","Grab both kettlebells and pull them to your stomach, retracting your shoulder blades and flexing the elbows. Keep your back straight. Lower and repeat."],"img":"fe-Two-Arm_Kettlebell_Row.jpg","ty":"atl"},{"id":"fe-Upper_Back-Leg_Grab","n":"upper back-leg grab","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"lower back","sm":["lower back","middle back"],"st":["While seated, bend forward to hug your thighs from underneath with both arms.","Keep your knees together and your legs extended out as you bring your chest down to your knees. You can also stretch your middle back by pulling your back away from your knees as your hugging them."],"img":"fe-Upper_Back-Leg_Grab.jpg","ty":"stretch","kind":"time"},{"id":"fe-Upright_Row_-_With_Bands","n":"upright row - with bands","bp":"back","eq":"band","tg":"traps","mg":"shoulders","sm":["shoulders"],"st":["To begin, stand on an exercise band so that tension begins at arm's length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.","Use your side shoulders to lift the handles as you exhale. The handles should be close to the body as you move them up. Continue to lift the handles until they nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the handles, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.","Lower the handles back down slowly to the starting position. Inhale as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."],"img":"fe-Upright_Row_-_With_Bands.jpg","ty":"rin"},{"id":"fe-Upward_Stretch","n":"upward stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"chest","sm":["chest","lats"],"st":["Extend both hands straight above your head, palms touching.","Slowly push your hands up and back, keeping your back straight."],"img":"fe-Upward_Stretch.jpg","ty":"stretch","kind":"time"},{"id":"fe-V-Bar_Pullup","n":"v-bar pullup","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","middle back","shoulders"],"st":["Start by placing the middle of the V-bar in the middle of the pull-up bar (assuming that the pull-up station you are using does not have neutral grip handles). The V-Bar handles will be facing down so that you can hang from the pull-up bar through the use of the handles.","Once you securely place the V-bar, take a hold of the bar from each side and hang from it. Stick your chest out and lean yourself back slightly in order to better engage the lats. This will be your starting position.","Using your lats, pull your torso up while leaning your head back slightly so that you do not hit yourself with the chin-up bar. Continue until your chest nearly touches the V-bar. Exhale as you execute this motion.","After a second hold on the contracted position, slowly lower your body back to the starting position as you breathe in.","Repeat for the prescribed number of repetitions."],"img":"fe-V-Bar_Pullup.jpg","ty":"atl"},{"id":"fe-Vertical_Swing","n":"vertical swing","bp":"upper legs","eq":"dumbbell","tg":"hamstrings","mg":"glutes","sm":["glutes","quadriceps","shoulders"],"st":["Allow the dumbbell to hang at arms length between your legs, holding it with both hands. Keep your back straight and your head up.","Swing the dumbbell between your legs, flexing at the hips and bending the knees slightly.","Powerfully reverse the motion by extending at the hips, knees, and ankles to propel yourself upward, swinging the dumbell over your head.","As you land, absorb the impact through your legs and draw the dumbbell to your torso before the next repetition."],"img":"fe-Vertical_Swing.jpg","ty":"atl"},{"id":"fe-Weighted_Crunches","n":"weighted crunches","bp":"waist","eq":"medicine ball","tg":"abs","mg":"","sm":[],"st":["Lie flat on your back with your feet flat on the ground or resting on a bench with your knees bent at a 90 degree angle.","Hold a weight to your chest, or you may hold it extended above your torso. This will be your starting position.","Now, exhale and slowly begin to roll your shoulders off the floor. Your shoulders should come up off the floor about 4 inches while your lower back remains on the floor.","At the top of the movement, flex your abdominals and hold for a brief pause.","Then inhale and slowly lower yourself back down to the starting position."],"img":"fe-Weighted_Crunches.jpg","ty":"atl"},{"id":"fe-Windmills","n":"windmills","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","hamstrings","lower back"],"st":["Lie on your back with your arms extended out to the sides and your legs straight. This will be your starting position.","Lift one leg and quickly cross it over your body, attempting to touch the ground near the opposite hand.","Return to the starting position, and repeat with the opposite leg. Continue to alternate for 10-20 repetitions."],"img":"fe-Windmills.jpg","ty":"mob"},{"id":"fe-Worlds_Greatest_Stretch","n":"world's greatest stretch","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","glutes","quadriceps"],"st":["This is a three-part stretch. Begin by lunging forward, with your front foot flat on the ground and on the toes of your back foot. With your knees bent, squat down until your knee is almost touching the ground. Keep your torso erect, and hold this position for 10-20 seconds.","Now, place the arm on the same side as your front leg on the ground, with the elbow next to the foot. Your other hand should be placed on the ground, parallel to your lead leg, to help support you during this portion of the stretch.","After 10-20 seconds, place your hands on either side of your front foot. Raise the toes of the front foot off of the ground, and straighten your leg. You may need to reposition your rear leg to do so. Hold for 10-20 seconds, and then repeat the entire sequence for the other side."],"img":"fe-Worlds_Greatest_Stretch.jpg","ty":"mob"},{"id":"rh-01","n":"spanish squat","bp":"upper legs","eq":"band","tg":"quads","mg":"","sm":[],"st":["Loop a heavy band around a post at knee height and step into it so it sits behind both knees.","Walk back until the band is tight, feet hip-width, shins vertical.","Sit back into a squat to about 60-90 degrees of knee bend, keeping the shins upright against the band.","Hold the position with steady breathing; the effort should be felt in the front of the thighs and the patellar tendon, without sharp pain."],"kind":"time","ty":"rin","img":"rh-01.jpg"},{"id":"rh-02","n":"wall sit","bp":"upper legs","eq":"body weight","tg":"quads","mg":"","sm":[],"st":["Stand with your back against a wall, feet about two feet in front of you.","Slide down until the knees are bent to roughly 90 degrees, knees over the ankles.","Keep the lower back flat on the wall and the weight in the heels.","Hold for the set time, then slide back up."],"kind":"time","ty":"rin","img":"rh-02.jpg"},{"id":"rh-03","n":"copenhagen plank","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"","sm":[],"st":["Lie on your side with the forearm under the shoulder and the top leg resting on a bench (knee on the bench for the easier version, ankle for the harder one).","Lift the hips until the body is in a straight line, the bottom leg hanging or lifted under the bench.","Squeeze the inner thigh of the top leg to hold the position.","Hold, then repeat on the other side."],"kind":"time","ty":"rin","img":"rh-03.jpg"},{"id":"rh-04","n":"nordic hamstring curl","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"","sm":[],"st":["Kneel on a pad with your ankles anchored under a bar, bench or held by a partner.","Keep hips extended and the body straight from knees to head.","Lower your body toward the floor as slowly as you can, resisting with the hamstrings.","Catch yourself with your hands at the bottom and push back up just enough to return to the start."],"ty":"rin","img":"rh-04.jpg"},{"id":"rh-05","n":"reverse nordic","bp":"upper legs","eq":"body weight","tg":"quads","mg":"","sm":[],"st":["Kneel upright on a pad with knees hip-width and the body straight from knees to head.","Lean the whole body back slowly, keeping hips extended, until you feel strong tension in the front of the thighs.","Go only as far as you can control without pain.","Return to upright by squeezing the quads."],"ty":"rin","img":"rh-05.jpg"},{"id":"rh-06","n":"tibialis raise","bp":"lower legs","eq":"body weight","tg":"calves","mg":"","sm":[],"st":["Lean your back against a wall with your heels about one foot away from it.","Keeping the legs straight, lift the toes and the front of the feet as high as possible.","Pause at the top, then lower slowly.","Move the feet further from the wall to make it harder."],"ty":"rin","img":"rh-06.jpg"},{"id":"rh-07","n":"eccentric step-down","bp":"upper legs","eq":"body weight","tg":"quads","mg":"","sm":[],"st":["Stand on one leg on a step, the other leg hanging off the side.","Slowly bend the standing knee and lower the free heel toward the floor, taking 3-4 seconds.","Keep the knee in line with the second toe and the pelvis level.","Lightly touch the floor with the heel, then push back up."],"ty":"rin","img":"rh-07.jpg"},{"id":"rh-08","n":"peterson step-up","bp":"upper legs","eq":"body weight","tg":"quads","mg":"","sm":[],"st":["Stand on a low step with one foot, heel raised so you are on the ball of the foot.","Keep the knee forward over the toes and the other foot hanging off the step.","Straighten the knee by squeezing the inner quad while the heel stays raised.","Lower under control and repeat."],"ty":"rin","img":"rh-08.jpg"},{"id":"rh-09","n":"band terminal knee extension","bp":"upper legs","eq":"band","tg":"quads","mg":"","sm":[],"st":["Anchor a band at knee height and loop it behind one knee, facing the anchor.","Step back until there is tension with the knee slightly bent.","Straighten the knee fully against the band, squeezing the thigh.","Hold for a second, then let the knee bend slightly again."],"ty":"rin","img":"rh-09.jpg"},{"id":"rh-10","n":"eccentric heel drop","bp":"lower legs","eq":"body weight","tg":"calves","mg":"","sm":[],"st":["Stand on the edge of a step on the balls of both feet, holding a rail for balance.","Rise up on both feet, then shift the weight onto one foot.","Lower that heel slowly below the step over 3-4 seconds.","Use both feet to come back up and repeat. Do it with the knee straight and with the knee bent."],"ty":"rin","img":"rh-10.jpg"},{"id":"rh-11","n":"bird dog","bp":"waist","eq":"body weight","tg":"abs","mg":"","sm":[],"st":["Kneel on all fours with hands under shoulders and knees under hips, back flat.","Brace the abs and reach one arm forward and the opposite leg back until both are level with the body.","Keep the hips square and the lower back still; do not arch.","Hold for a few seconds, return, then switch sides."],"ty":"rin","img":"rh-11.jpg"},{"id":"rh-12","n":"hollow body hold","bp":"waist","eq":"body weight","tg":"abs","mg":"","sm":[],"st":["Lie on your back, arms overhead and legs straight.","Press the lower back into the floor and lift the shoulders and legs a few inches off the ground.","Keep the lower back glued to the floor; bend the knees or bring the arms forward to make it easier.","Hold the banana shape for the set time."],"kind":"time","ty":"rin","img":"rh-12.jpg"},{"id":"rh-13","n":"wall slide","bp":"shoulders","eq":"body weight","tg":"delts","mg":"","sm":[],"st":["Stand with your back and head against a wall, feet a little away from it.","Place your arms against the wall in a W shape, elbows bent at 90 degrees.","Slide the arms up the wall as far as you can while keeping the lower back, elbows and wrists in contact.","Slide back down, pulling the shoulder blades down and together."],"ty":"rin","img":"rh-13.jpg"},{"id":"rh-14","n":"prone y-t-w raise","bp":"back","eq":"body weight","tg":"upper back","mg":"","sm":[],"st":["Lie face down on the floor or an incline bench, arms hanging, thumbs up.","Raise the arms forward into a Y, pause, and lower.","Raise them out to the sides into a T, pause, and lower.","Bend the elbows and pull them back into a W, squeezing the shoulder blades. Use no weight or very light weights."],"ty":"rin","img":"rh-14.jpg"},{"id":"rh-15","n":"sleeper stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"","sm":[],"st":["Lie on your side with the bottom arm in front of you, elbow bent 90 degrees at shoulder height.","Use the top hand to gently push the bottom forearm toward the floor.","Stop when you feel a stretch at the back of the shoulder, without pain.","Hold, then switch sides."],"kind":"time","ty":"stretch","img":"rh-15.jpg"},{"id":"rh-16","n":"doorway pec stretch","bp":"chest","eq":"body weight","tg":"pectorals","mg":"","sm":[],"st":["Stand in a doorway with the forearms on the frame, elbows at shoulder height.","Step one foot through and lean forward gently.","Feel the stretch across the chest and front of the shoulders; keep the ribs down.","Hold, then try with the elbows slightly higher or lower."],"kind":"time","ty":"stretch","img":"rh-16.jpg"},{"id":"rh-17","n":"dead hang","bp":"back","eq":"body weight","tg":"lats","mg":"","sm":[],"st":["Grab a pull-up bar with an overhand grip, hands shoulder-width.","Hang with arms straight and feet off the floor, letting the shoulders rise toward the ears.","Breathe and relax the body; keep a firm grip.","Hold for the set time, then step down."],"kind":"time","ty":"rin","img":"rh-17.jpg"},{"id":"rh-18","n":"band external rotation","bp":"shoulders","eq":"band","tg":"delts","mg":"","sm":[],"st":["Anchor a band at elbow height and stand side-on to it.","Hold the band with the outside hand, elbow bent 90 degrees and tucked to your side (a towel under the elbow helps).","Rotate the forearm outward away from the body, keeping the elbow in place.","Return slowly and repeat, then switch sides."],"ty":"rin","img":"rh-18.jpg"},{"id":"rh-19","n":"band face pull","bp":"shoulders","eq":"band","tg":"delts","mg":"","sm":[],"st":["Anchor a band at head height and hold it with both hands, palms down.","Step back until there is tension, arms straight in front.","Pull the band toward your face, elbows high, rotating the hands back so they end beside the ears.","Squeeze the shoulder blades, then return slowly."],"ty":"rin","img":"rh-19.jpg"},{"id":"rh-20","n":"shoulder cars","bp":"shoulders","eq":"body weight","tg":"delts","mg":"","sm":[],"st":["Stand tall and brace the core so the trunk does not move.","Raise one straight arm forward and up overhead as far as you can.","Rotate it back and down behind you in the largest circle you can control.","Move slowly, then reverse the direction and switch arms."],"ty":"mob","img":"rh-20.jpg"},{"id":"rh-21","n":"prone swimmer","bp":"back","eq":"body weight","tg":"upper back","mg":"","sm":[],"st":["Lie face down with arms overhead, forehead on the floor or a towel.","Lift the arms just off the floor.","Sweep them out to the sides and down behind the back, rotating the palms up, then bring the hands to the lower back.","Reverse the path back overhead, keeping the arms off the floor."],"ty":"mob","img":"rh-21.jpg"},{"id":"rh-22","n":"thoracic open book","bp":"back","eq":"body weight","tg":"upper back","mg":"","sm":[],"st":["Lie on your side with the knees bent to 90 degrees and the arms straight in front of you, palms together.","Keep the knees together and on the floor.","Open the top arm up and over toward the floor behind you, rotating the upper back and following the hand with your eyes.","Hold briefly, then close the book. Do all reps, then switch sides."],"ty":"mob","img":"rh-22.jpg"},{"id":"rh-23","n":"thread the needle","bp":"back","eq":"body weight","tg":"upper back","mg":"","sm":[],"st":["Start on all fours with hands under shoulders and knees under hips.","Reach one arm up toward the ceiling, rotating the upper back.","Then thread that arm under the other arm, bringing the shoulder and side of the head toward the floor.","Pause, return, and repeat, then switch sides."],"ty":"mob","img":"rh-23.jpg"},{"id":"rh-24","n":"foam roller thoracic extension","bp":"back","eq":"roller","tg":"upper back","mg":"","sm":[],"st":["Sit on the floor with a foam roller behind you across the upper back, knees bent.","Support the head with the hands and lift the hips slightly or keep them on the floor.","Extend the upper back over the roller, then come back up.","Move the roller a few inches and repeat; avoid rolling the lower back."],"ty":"mob","img":"rh-24.jpg"},{"id":"rh-25","n":"wrist extensor isometric","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"","sm":[],"st":["Sit with the forearm on your thigh or a table, palm facing down and the wrist just past the edge.","Hold a light dumbbell or push the back of the hand up against the other hand.","Keep the wrist level and hold the contraction without moving.","The effort should feel strong but not painful at the elbow."],"kind":"time","ty":"rin","img":"rh-25.jpg"},{"id":"rh-26","n":"eccentric wrist extension","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"","sm":[],"st":["Sit with the forearm on your thigh, palm facing down, holding a light dumbbell.","Use the other hand to help lift the wrist up.","Lower the weight slowly with the working wrist over 3-4 seconds.","Help it back up with the other hand and repeat."],"ty":"rin","img":"rh-26.jpg"},{"id":"rh-27","n":"eccentric wrist flexion","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"","sm":[],"st":["Sit with the forearm on your thigh, palm facing up, holding a light dumbbell.","Use the other hand to help curl the wrist up.","Lower the weight slowly with the working wrist over 3-4 seconds.","Help it back up and repeat."],"ty":"rin","img":"rh-27.jpg"},{"id":"rh-28","n":"90/90 hip switch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"","sm":[],"st":["Sit on the floor with both knees bent at 90 degrees, one leg in front and one to the side.","Keep the chest tall, hands on the floor behind you if needed.","Lift both knees and rotate them to the other side, ending in the mirrored 90/90 position.","Move slowly and switch side to side."],"ty":"mob","img":"rh-28.jpg"},{"id":"rh-29","n":"couch stretch","bp":"upper legs","eq":"body weight","tg":"quads","mg":"","sm":[],"st":["Kneel with the back knee close to a wall or couch and the shin and top of the foot up against it.","Place the other foot forward in a lunge position.","Squeeze the glute of the back leg and lift the chest tall.","Hold the stretch in the front of the hip and thigh, then switch sides."],"kind":"time","ty":"stretch","img":"rh-29.jpg"},{"id":"rh-30","n":"hip cars","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"","sm":[],"st":["Stand holding a wall or support, or start on all fours.","Lift one knee forward, open it out to the side, rotate it back and behind you, then bring it down.","Make the largest circle you can control while keeping the trunk still.","Reverse the direction and switch legs."],"ty":"mob","img":"rh-30.jpg"},{"id":"rh-31","n":"pigeon stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"","sm":[],"st":["From all fours, bring one knee forward behind the wrist with the shin angled across the body.","Extend the other leg straight back.","Keep the hips square and lower the chest toward the floor.","Hold the stretch in the outer hip, then switch sides."],"kind":"time","ty":"stretch","img":"rh-31.jpg"},{"id":"rh-32","n":"adductor rock back","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"","sm":[],"st":["Start on all fours and extend one leg straight out to the side, foot flat.","Keep the back flat and rock the hips back toward the heel.","Feel the stretch along the inner thigh of the straight leg.","Rock forward and back, then switch sides."],"ty":"mob"},{"id":"rh-33","n":"deep squat hold","bp":"upper legs","eq":"body weight","tg":"quads","mg":"","sm":[],"st":["Stand with feet a bit wider than hip-width, toes slightly out.","Sink into the deepest squat you can with the heels on the floor.","Keep the chest up, using the elbows to gently push the knees out.","Hold, holding a support if needed."],"kind":"time","ty":"mob","img":"rh-33.jpg"},{"id":"rh-34","n":"broad jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"","sm":[],"st":["Stand with feet hip-width apart.","Swing the arms back and dip into a quarter squat.","Explode forward, swinging the arms and jumping as far as possible.","Land softly on both feet with bent knees, stick the landing, then reset."],"ty":"atl","img":"rh-34.jpg"},{"id":"rh-35","n":"a-skip","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"","sm":[],"st":["Stand tall and start skipping forward.","Drive one knee up to hip height while the opposite arm swings forward.","Strike the ground under the hips with the ball of the foot.","Keep a quick, rhythmic contact and alternate legs."],"ty":"atl","img":"rh-35.jpg"},{"id":"rh-36","n":"side plank","bp":"waist","eq":"body weight","tg":"abs","mg":"","sm":[],"st":["Lie on your side with the forearm under the shoulder and the legs stacked.","Lift the hips until the body is in a straight line from head to feet.","Keep the hips forward and do not let them sag.","Hold, then switch sides. Bend the knees to make it easier."],"kind":"time","ty":"rin","img":"rh-36.jpg"},{"id":"rh-37","n":"glute bridge hold","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"","sm":[],"st":["Lie on your back with knees bent and feet flat, hip-width apart.","Press through the heels and lift the hips until the body is in a straight line from shoulders to knees.","Squeeze the glutes and keep the ribs down so the lower back does not arch.","Hold for the set time."],"kind":"time","ty":"rin","img":"rh-37.jpg"},{"id":"rh-38","n":"isometric calf raise hold","bp":"lower legs","eq":"body weight","tg":"calves","mg":"","sm":[],"st":["Stand on one leg on the edge of a step, holding a support.","Rise up onto the ball of the foot until about halfway up.","Hold the position without moving.","Switch legs. Add weight in the hand to progress."],"kind":"time","ty":"rin","img":"rh-38.jpg"}];
